window.CS={"groups": [{"name": "Start here", "ids": ["approach", "vitals"]}, {"name": "Core systems", "ids": ["resp", "cardiac", "pv", "abdo", "headneck", "lymph", "volume", "renal"]}, {"name": "Endocrine & breast", "ids": ["thyroid", "diabetes", "adrenal", "breast"]}, {"name": "Neuro & mental status", "ids": ["neuro", "mse", "eye"]}, {"name": "Musculoskeletal", "ids": ["gals", "shoulder", "elbow", "hand", "back", "hip", "knee", "ankle"]}], "exams": {"approach": {"title": "Before any exam", "pg": [37, 43], "notes": [], "steps": [{"sec": "Opening the exam", "name": "Introduce Yourself and Wash Hands", "phase": null, "tags": [], "pg": 36, "do": ["• Knock on door and ask for permission to enter the clinical interview space (respecting privacy)", "• Share your name and role in patient care (if not already done earlier during the assessment)", "◦ Example: My name is X, and I am a medical student working with Dr. Z in the clinic today.", "• Wash hands: Recall the 4 moments of hand hygiene:", "(1) before initial patient/patient environment contact (e.g. use hand sanitizer while walking into room) (2) before aseptic procedure (if applicable) (3) after body fluid exposure risk (if applicable) (4) after patient/patient environment contact"], "imgs": []}, {"sec": "Opening the exam", "name": "Patient Introduction", "phase": null, "tags": [], "pg": 36, "do": ["• Ask the patient how they would like to be addressed. Reflect their name and pronouns during the visit.", "◦ Example 1: How would you like to be addressed?1", "◦ Example 2: What would you like to be called today?", "◦ Example follow-up question: If you feel comfortable, could you share what pronouns you use?", "• Note: Not all patients, including trans and non-binary patients, may be comfortable sharing their pronouns. If the patient is uncomfortable when asked their pronouns, clarify your goal is to ask patients’ pronouns routinely to create a welcoming space. Be accepting if the patient declines to share pronouns.", "• Tip: If you make a mistake, apologize, use the correct pronouns, and move on. Example: “The patient reports he – I’m sorry I used the wrong pronoun. The patient reports she is experiencing dyspnea.”"], "imgs": []}, {"sec": "Opening the exam", "name": "Set An Agenda", "phase": null, "tags": [], "pg": 36, "do": ["• Explain what exam is being proposed and why. Ask for consent to allow clinician to proceed.", "◦ Example: “I’d like to transition to the physical exam. We will be doing a pulmonary exam today, so I will be listening to the lungs. This exam should take about 5 minutes. How does that sound to you?”"], "imgs": []}, {"sec": "Opening the exam", "name": "Make it Standard", "phase": null, "tags": [], "pg": 36, "do": ["• Example: “This is something we do with all of our patients who come in with symptoms of shortness of breath.”"], "imgs": []}, {"sec": "Opening the exam", "name": "Identify Concerns", "phase": null, "tags": [], "pg": 36, "do": ["• Example: “What questions do you have before the exam?”"], "imgs": []}, {"sec": "Opening the exam", "name": "Ask About Comfort", "phase": null, "tags": [], "pg": 36, "do": ["• Example: “Is there anything we can do to make you more comfortable during the exam? Please tell me if you feel uncomfortable or want to stop or pause the exam. You are in control of what we do here today.”"], "imgs": []}, {"sec": "Opening the exam", "name": "Offer Support Person", "phase": null, "tags": [], "pg": 36, "do": ["• Example: “Would you like anyone else to be present for the exam?”", "◦ Example – Support Person (e.g. friend, family): There to support patient.", "◦ Example – Chaperone (e.g. nurse, preceptor): There to support patient and for medico-legal protection.", "◦ See above re. CPSO Policy on Third-Party Attendance at Intimate Examinations. Helpful practice to offer a support person for each physical exam. This is aligned with principles of trauma-informed care (e.g. safety – remember that safety is defined by those we serve)."], "imgs": []}, {"sec": "Opening the exam", "name": "Patient Terms", "phase": null, "tags": [], "pg": 36, "do": ["• Ask patients about the terms they would like used for their anatomy (e.g. terms to describe their genitals or chest, if pertinent for the exam being performed) and then use those terms during the assessment."], "imgs": []}, {"sec": "During the exam", "name": "Approach to Draping", "phase": null, "tags": [], "pg": 37, "do": ["• Helpful Video on Draping - Proper Adjustment of Patient Attire during the Physical Exam (JoVE Science Education video, available at: https://library.mcmaster.ca/databases/jove-science-education).", "• If the patient has limited mobility, ask if they would like assistance in changing into a gown. Clinicians should not provide this assistance unless the patient requires and requests assistance.", "• Provide instructions on what to do with the gown (what the patient wears) and drape (sheet covering their person), including that it be kept open at the back, and what clothing can be removed or left on.", "• For a limited exam, consider asking patient to move their clothing rather than disrobing (e.g. patient lifts back of shirt up to reveal low back skin lesion).", "• Leave the patient’s room or use curtains and screens to allow the patient to undress and gown up privately. Check that curtains adequately block visibility.", "• Let them know when you’ll return (e.g. in 5 minutes).", "• Knock and ask patient if OK to come back into the exam room space.", "• Communicate to the patient about what is about to be done before moving a gown or drape. Check-in – remember that consent is an ongoing process.", "• Don’t reach under a gown, drape or clothing to examine a patient.", "• Enlist the patient’s help in moving the gown or drape throughout the exam, as this allows the patient to maintain some control over the degree of exposure. Only assist patients with the adjustment or removal of clothing or draping if the patient agrees or requests the physician to do so.", "• Do not assume patients with male gender expression are comfortable baring a full chest.", "• Only expose the area of the body being directly examined. When you complete the examination of an exposed area, replace the gown or drape.", "• Limit the exposure times for sensitive areas (e.g., anterior chest, inguinal region) but do not compromise the exam to do this.", "• If you have untied the gown during the exam, retie it before asking patient to step down from the table."], "imgs": []}, {"sec": "During the exam", "name": "Introduce Components, Explain Why", "phase": null, "tags": [], "pg": 37, "do": ["• Example: “I am now going to listen to the lungs, using my stethoscope. This is important because we need to see if you have pneumonia, which is a lung infection.”"], "imgs": []}, {"sec": "During the exam", "name": "Ask Permission", "phase": null, "tags": [], "pg": 37, "do": ["Allowing the patient to be in control wherever possible.", "• Example: “May I open the gown from the back slightly, to get a better listen to the lungs?”"], "imgs": []}, {"sec": "During the exam", "name": "Respect Personal Space", "phase": null, "tags": [], "pg": 37, "do": ["• Be mindful of your position in clinical space relative to the patient and the door – context dependent.", "◦ Why this is context dependent: For example, in managing a patient with agitation, for safety of healthcare providers we remember “never let the patient get between you and the door.” This same approach could be traumatizing in other scenarios e.g. when performing sensitive examinations, a trauma-informed approach would be to ensure the patient has clear access to the door in exam rooms and can easily exit if choosing to do so.", "• Stay with eyesight, positioned to gather physical exam data, and also giving patient sense of ease and control (e.g. “I’m going to stand at your side.”)"], "imgs": []}, {"sec": "During the exam", "name": "Use Professional Touch", "phase": null, "tags": [], "pg": 37, "do": ["• Prepare patients for different sensations (e.g. “this is a tuning fork that will feel like a vibration”; “the speculum may feel cold”; “you’re going to feel my hand on the abdomen”)", "• Use gloves: Particularly important when performing sensitive exams."], "imgs": []}, {"sec": "During the exam", "name": "Use Simple, Clinical Language", "phase": null, "tags": [], "pg": 37, "do": ["• Key Idea: Word choice is professional, not personal; easy to understand; cautious with imagery; avoiding any possible sexual connotation. Use patient language for their anatomy.", "◦ Refer to anatomy as “the” instead of “your” to make your language more clinical and professional, less personal (e.g. “the breast” vs. “your breast”)", "◦ Refer to equipment in clinical terms e.g. “exam table” vs. “bed”", "◦ Refer to passive physical exam tests in clinical terms e.g. “examine” vs. “feel”, “inspect” vs. “look at”", "◦ Refer to physical exam tests requiring patient action in terms of the action itself e.g. “resist this motion” vs. “don’t let me”", "◦ Avoid phrases which enhance power differential e.g. “I’m going to place my hands on the neck to examine the thyroid. When you can, please swallow” vs. “swallow for me” – Avoid phrase “for me”", "◦ Use non-normative terminology e.g. “healthy” vs. “normal”"], "imgs": []}, {"sec": "During the exam", "name": "Check-In and Monitor for Signs of Discomfort", "phase": null, "tags": [], "pg": 37, "do": ["• Check-In: “How are you doing?”", "• Watch for discomfort or distress (e.g. tensing muscles, fidgeting, breathing quickly, appearing distracted, crying) and stop the exam immediately if the patient is in distress: Check-in in an open, non- judgmental way, and let the patient know they are in control."], "imgs": []}, {"sec": "During the exam", "name": "Approach to Draping", "phase": null, "tags": [], "pg": 38, "do": ["• Allow the patient to dress before finishing the appointment: Leave the room so patient can dress. Return and review when they say they are ready."], "imgs": []}, {"sec": "Closing the exam", "name": "Express Thanks", "phase": null, "tags": [], "pg": 38, "do": ["• Example: “Thanks very much for coming to this appointment and for helping me perform a thorough physical exam.”"], "imgs": []}, {"sec": "Closing the exam", "name": "Discuss Results", "phase": null, "tags": [], "pg": 38, "do": ["• Note – as you learn new clinical skills, you may not be at a developmental stage to interpret findings in terms of pathophysiology or generate a differential diagnosis. It is helpful to skip this step in these cases (e.g. to defer until after reviewing with your preceptor).", "• Example: “The lungs sound clear which is good. You do not need a chest x-ray, and don’t have pneumonia.”"], "imgs": []}, {"sec": "Closing the exam", "name": "Provide opportunity for questions", "phase": null, "tags": [], "pg": 38, "do": ["• Do not leave the patient with unanswered questions – even if findings on exam are “normal”. As you learn new clinical skills, you may not be at a developmental stage to answer all patient questions. In these cases, it is helpful to acknowledge the question and that you will ask your preceptor.", "• Example: “What questions do you have?”"], "imgs": []}, {"sec": "Closing the exam", "name": "Make a Plan for Follow-Up", "phase": null, "tags": [], "pg": 38, "do": ["• As a medical student, the next step may be for you to step out to review with your preceptor, then come back to discuss next steps."], "imgs": []}, {"sec": "Closing the exam", "name": "Wash Hands", "phase": null, "tags": [], "pg": 38, "do": ["Wash hands: Recall the 4 moments of hand hygiene: (1) before initial patient/patient environment contact (e.g. use hand sanitizer while walking into room) → (2) before aseptic procedure (if applicable) → (3) after body fluid exposure risk (if applicable) → (4) after patient/patient environment contact"], "imgs": []}]}, "vitals": {"title": "Vital signs", "pg": [37, 43], "notes": ["1. When seeing an inpatient, note vitals (may be charted at bedside), current meds (e.g. Medical Administration Record = MAR), and lines (e.g. IVs, catheters, O2 –what lines are running and their settings e.g. IV CC’s per hour, O2 Litres per minute).", "2. Apparent State of Health: Being able to “eyeball patients” as well, ill acute or ill chronic takes time & practice – if you have any suspicion a patient you are sent to see is acutely ill, call a senior member of the team prior to your assessment! - [4, 4]"], "steps": [{"sec": "Before measuring", "name": "Focused History Before Vitals Assessment", "phase": null, "tags": [], "pg": 38, "do": ["• Have you had any caffeine or cigarettes in the last 30 mins? Have you done any vigorous exercise in the last hour? Have you taken any medications today?", "• Have you had any surgeries in either arm? Any recent stress? History of white coat syndrome (change in blood pressure due to presence of healthcare professional)?", "• Ensure patient has been seated at rest for at least 5 minutes before vitals assessment", "◦ Modification for patients who are deconditioned: Ensure patient seated for 15 mins prior to measuring vitals, otherwise values (e.g. BP, HR) may be falsely elevated with mild exertion (applies to all patients regardless of body habitus)"], "imgs": []}, {"sec": "Before measuring", "name": "Patient-Centred Weight Discussion", "phase": null, "tags": [], "pg": 38, "do": ["• Sample Questions to Begin Conversation with Adults about Weight:", "◦ Would it be alright if we discussed your weight?", "◦ Are you concerned about your weight?", "◦ Would you be interested in addressing your weight at this time?", "• Adult Weight Hx (If Patient gives Permission to Discuss):", "◦ Onset: Weight during childhood and adolescence", "◦ History of Patterns and Triggers of Weight Gain (e.g. life events – marriage, job, pregnancy, trauma, menopause, etc.)", "◦ History of Patterns of Weight Loss: Previous attempts, strategies", "◦ Current Patterns: Eating, exercise, sleep, stress and time management", "◦ Readiness Ruler: Assessing patient’s current self-assessment for behavior change, on a scale of 1-10 for importance, readiness, confidence, and confidence with supports. (See Appendix 1)", "• Barriers: Explore barriers to weight loss, factors contributing to weight gain. Note – Permission to Discuss Weight: Weight is a sensitive issue. Be non-judgmentally curious when opening a conversation about weight. If patients are not ready to discuss their weight, at end of visit consider asking if you can speak with them about their weight again in the future.7 In discussing weight, focus on improving healthy habits and quality of life, rather than weight loss. Weight is not a behavior and should not be a target for behavior change. Redefine success as healthy behavior change, regardless of body size or weight. A patient’s “best weight” is the weight at which the body stabilizes when engaging in healthy behaviors. Remember: People can be healthy in lots of different shapes and sizes8, 9."], "imgs": []}, {"sec": "Measuring vitals", "name": "Waist Circum, Waist-Height Ratio, Waist-Hip Ratio and BMI - Adult", "phase": "vitals", "tags": [], "pg": 39, "say": ["Would it be alright if we measure your height, weight, hip circumference and waist circumference today? Set-Up: Ask permission before weighing someone, and never weigh a patient in front of others. Weighing scales should be placed in private areas in clinical spaces."], "do": ["1. Ask patient to remove shoes.", "2. Requires a weight scale, a method of measuring height, and a tape measure.", "3. Measure the patient’s weight and height using appropriate scales.", "4. For waist circumference, measure circumference at a level midway between the Iliac Crest and last palpable rib (WHO guidelines)", "5. For hip circumference, measure at the level with the widest portion of the buttocks.", "6. Using these measurements, calculate BMI (kg /m2), Waist-Height Ratio, and Waist-Hip Ratio."], "report": ["The height and weight we measured today were _____, with a BMI of ______."], "why": ["Waist-Height Ratio and Waist-Hip ratio are objective measures of central (abdominal) obesity associated with ↑ cardiovascular risk. These calculated measures, including BMI, are imperfect, but clinically useful to monitor individual patients over time. Differential diagnoses for weight changes include Nutritional state, malignancy, chronic illness, eating disorders, hyper/hypothyroidism, hyper/hypo-cortisolism, etc. WHO Classification of Weight Status:", "Weight Status Under- Normal Range Overweight Class I Class II Class III Weight Obesity Obesity Obesity BMI (kg/m2) < 18.5", "18.5 – 24.9 25 – 29.9 30 – 34.9 35 – 39.9 ≥ 40 Edmonton Obesity Staging System (EOSS)11: Staging according to obesity-related risk factors, physical symptoms, psychological symptoms, and functional impairment. Overall stage determined by highest component (e.g. pt with Stage 3 Physical Symptoms, Stage 1 otherwise is considered EOSS Stage 3 Overall) EOSS Obesity-Related Risk Physical Symptoms Psychological Functional Stage Factors Symptoms Impairment Stage 0 None None None None Stage 1 Stage 1 Subclinical Risk Factors Mild Not Requiring Medical Mild Mild Mild (Quality of Life not impacted) Mild (Quality of (Borderline Intervention (e.g. moderate Life not Hypertension, Impaired exertional dyspnea; impacted) fasting glucose, occasional aches/pains; elevated liver enzymes) fatigue) Stage 2 Obesity-Related Comorbidities Requiring Medical Intervention (HTN, T2DM, OSA, PCOS, OA, GERD) Obesity-Related Comorbidities Requiring Medical Moderate (e.g. Moderate (QoL Intervention (HTN, T2DM, OSA, PCOS, OA, GERD) Depression, Eating beginning to be D/O, Anxiety D/O) impacted) Stage 3 Significant Obesity-Related End-Organ Damage (MI, HF, Diabetes Complications, Incapacitating OA) Significant (e.g. Significant (QoL Major Depression, significantly Suicidal Ideation) impacted) Stage 4 Severe (Potentially End-Stage) Obesity-Related End- Severe disabling Severe Organ Damage symptoms limitations Modification for Patients with Limited Mobility:", "• Height: Can be measured using the demi-span (distance from mid-sternal notch to the end of the middle finger in the coronal plane) and then calculated with the following formulas:", "◦ For female patients: Height (cm) = (1.35 x Demi-span) + 60.1", "◦ For male patients: Height (cm) = (1.40 x Demi-span) + 57.8", "• Weight: The patient’s estimate of their own weight is more accurate than the physician’s. If the patient is unable to give an estimation, body weight can be estimated using body height, and hip and waist circumference. Modification for Patients who are Transgender:", "• Transmasculine Patients (FTM): Patients on masculinizing hormone therapy may have body fat redistribution and/or increased muscle mass.", "• Transfeminine Patients (MTF): Patients on feminizing hormone therapy may have body fat redistribution and/or decreased muscle pass."], "imgs": []}, {"sec": "Measuring vitals", "name": "Heart Rate (HR) & Respiratory Rate (RR) (measure together)", "phase": "vitals", "tags": [], "pg": 40, "say": ["I will now measure the heart rate."], "do": ["1. Find patient’s radial pulse by palpation, have watch handy.", "2. Measure HR first 15-30s (or full minute if irregular), pretend to continue, in last 15-30s, watch RR.", "3. When patients know they are being observed for Resp rate, you can get altered RR values as patient adjusts in response to being observed. To avoid this, measure RR while you’re measuring HR"], "report": ["The heart rate we measured today is __ bpm, and respiratory rate we measured is __ breaths/minute. If you can please lie down on the exam table, I will measure the heart rate again in this position. What Is Normal HR? 60-100 bpm (trained athletes can run physiologic bradycardia; peds physiologically ↑) What is Normal RR? 12 -20 breaths/minute (peds physiologically higher) What does Supine Tachycardia tell you? Specific for volume loss Modification for Patients with Obesity: Use a handheld Doppler Ultrasound to locate pulses if they are difficult to feel by palpation. In this population, a handheld doppler may be more sensitive than palpation."], "imgs": []}, {"sec": "Measuring vitals", "name": "Blood Pressure (BP)", "phase": "vitals", "tags": [], "pg": 40, "say": ["I will now measure the blood pressure."], "do": ["1. Patient sitting quietly and relaxed, feet uncrossed and flat on ground, ideally after resting 5 minutes before measurement.", "2. Elevate patient’s arm to level of heart – either use table/pillows, or support patient’s arm with one arm.", "3. Make sure you’re using the right cuff size (see figure)", "4. Position cuff 2-3cm above the crease of the elbow, with the “Artery” marker line aligned with brachial pulse.", "5. Palpate the radial pulse.", "6. While palpating the radial pulse, inflate cuff to 70 mmHg, then by 10 mmHg increments until pulse disappears – this is estimate of systolic blood pressure (SBP).", "7. Place your stethoscope under cuff at brachial artery. Inflate the cuff above estimate (+30 mmHg), slowly let out (2 mmHg/second) until first sound comes back (SBP). Continue to deflate cuff until you hear last sounds in series (Diastolic Blood Pressure – DBP). These are called Korotkoff sounds. Keep deflating slowly for another 10 mmHg to make sure these sounds don’t appear and disappear again, then rapidly drop the pressure all the way to zero. May remeasure after 2 mins to get average readings."], "report": ["The blood pressure in the right arm was (SBP/DBP) mmHg. I will now measure blood pressure in the other arm and check for signs of hypertensive end-organ damage (eyes, heart, peripheral vascular, kidneys)."], "normal": ["120/80. The method described above is Office Blood Pressure Measurement (OBPM) – a BP measurement with a healthcare provider in the room. While this is a foundational clinical skill particularly in settings where automated BP measurement devices are not available, these in-office measurements may be artificially elevated (whitecoat hypertension) or decreased (masked hypertension). In clinical practice, recommended methods for measuring Blood Pressures include10:", "• In-Office (e.g. clinic): Recommend Automated Office Blood Pressure (AOBP) – automated device takes 3-6 measurements without patient unattended in private room.", "◦ Alternative In-Office method: Office Blood Pressure Measurement (OBPM – described above)", "• Out-Of-Office (e.g. in community): Recommend Ambulatory Blood Pressure Monitoring (ABPM) – automated device patient wears for 24-hour period with measurements taken at 20-30 minute intervals.", "◦ Alternative Out-Of-Office method: Home Blood Pressure Monitoring (HBPM) – patient self-monitors and measures BP twice for each morning and evening at home (i.e. 4 measurements/day) for 7 days."], "why": ["• Hypertension Diagnosis: Students encouraged to read CHEP Guidelines2 to learn more.", "◦ In-Office Measurement: Mean Office BP ≥ 180/110 = diagnosis of HTN", "▪ AOBP: BP ≥ 135/85 = probable HTN (need out-of-office measurement to confirm)", "▪ OBPM with Diabetes: BP ≥ 130/80 for ≥ 3 measurements on different days = probable HTN (consider out-of-office measurement to confirm)", "▪ OBPM without Diabetes: BP ≥ 140/90 = probable HTN (need out-of-office measurement to confirm)", "◦ Out-Of-Office Measurement (rules out white-coat hypertension):", "▪ ABPM: Daytime mean ≥ 135/85 or 24-hour mean ≥ 130/80 = diagnosis of HTN", "▪ HBPM: Series mean ≥ 135/85", "• Hypotension: Systolic BP < 90 mmHg associated with increased mortality in ICU patients; Systolic BP < 80 associated with increased mortality in patients with Myocardial Infarction."], "imgs": ["vitals-0.webp"]}, {"sec": "Measuring vitals", "name": "Orthostatic Vitals", "phase": "vitals", "tags": [], "pg": 41, "say": ["I will now measure the blood pressure and heart rate when standing up. Before starting, do you feel dizzy?"], "do": ["1. Ensure you have the patient’s supine measurements for BP and HR", "2. Have patient stand with back facing exam table for safety in case they experience syncope with standing.", "3. Wait 1 minute then measure HR, then after an additional 1 minute, measure BP"], "report": ["The blood pressure and heart rate changes are reassuring with no evidence of orthostatic hypotension."], "normal": ["HR ↑ 10, SBP ↓ 5, DBP ↓3.5"], "why": ["Orthostatic hypotension occurs due to changes in venous return with standing, in combination with insufficient counter-regulatory mechanisms (e.g. volume depletion; autonomic dysfunction or medication adverse effects causing lack of appropriate reflex tachycardia or vasoconstriction responses). Orthostatic hypotension is a common cause of pre-syncopal symptoms and falls in elderly patients. Threshold for Orthostatic Hypotension = 30-20-10 rule: 30 HR ↑; 20 SBP ↓; 10 DBP ↓ - or if patient becomes dizzy. HR ↑ 30 is most sensitive sign of orthostatic hypotension. Notes:", "• Keep in mind dizziness could be due to inner ear vertigo, ask whether common for patient. See Chapter 7 – Head and Neck Exam – MF1 for more information about dizziness.", "• 30-20-10 rule doesn’t work as well for elderly patients due to Autonomic Nervous System’s ↓ Agility. Modification for Patients with Obesity: see above tips for Blood Pressure and Heart Rate"], "imgs": []}, {"sec": "Measuring vitals", "name": "Oxygen Saturation (O2 Sat, SaO2)", "phase": "vitals", "tags": [], "pg": 41, "say": ["I will now be measuring the oxygen levels using a pulse oximeter."], "do": ["1. Place the pulse oximeter on a digit on the opposite hand from the blood pressure cuff (can give erroneous readings if blood pressure cuff inflated).", "2. Place pulse oximeter on a digit free of nail polish if possible (can give falsely low readings).", "3. Monitor waveform (synchronized with heart rate), wait for oxygen saturation readouts.", "4. If waveform is poor, the result may be unreliable – switch to a different digit"], "report": ["The oxygen saturations measured today are 98%, which is normal."], "why": ["Pulse oximetry is a rapid, non-invasive tool to clinically detect hypoxemia, by measuring peripheral arterial oxygen saturation (SpO2) as a surrogate marker for tissue arterial oxygenation (SaO2). SaO2 indicates the degree of O2 saturation of hemoglobin (a percentage value) and is not impacted by hemoglobin concentration."], "normal": ["Normal → >96%; Patients who are CO2 Retainers → 88-92%", "• About CO2 Retainer Mechanism: Some patients (e.g. with COPD, OSA, obesity) retain CO2 chronically (initially detected on arterial/venous blood gases) where their “normal” O2 saturation is lower (88-92%). There are three hypotheses describing why their SaO2 is kept between 88-92%:", "1. Hypoxic drive to breathe hypothesis: In healthy individuals, CO2 provides the drive to breath rather than O2. However, CO2 retainers are desensitized to CO2 and depend on O2 saturation for their drive to breath. Saturating them >92% decreases their hypoxic drive to breathe.", "2. Haldane effect hypothesis: Deoxygenated hemoglobin binds CO2 with greater affinity than oxygenated hemoglobin (Haldane effect). Thus, saturating >92% increases oxygen and shifts the CO2 dissociation curve to the right, offloading more CO2 and increasing PaCO2.", "3. V/Q mismatch hypothesis: In COPD patients for example, ventilation and gas exchange is optimized by hypoxic vasoconstriction, in an attempt to resolve the existing V/Q mismatch. Saturating >92% reduces hypoxic vasoconstriction and leads to more shunting of deoxygenated blood. Exceptions in SaO2: SaO2 can be misleading in cases of carboxyhemoglobinemia (CO poisoning) or methemoglobinemia (Fe3+ heme iron instead of normal Fe2+) as hemoglobin appears occupied and saturated with typical O2 saturation probes."], "imgs": []}, {"sec": "Measuring vitals", "name": "Temperature", "phase": "vitals", "tags": [], "pg": 41, "do": ["Rectal, Tympanic, Oral, Axillary – depends on equipment availability and patient preference"], "normal": ["Normal temperature value depends on method of measurement, as follows:", "Method Rectal (gold standard) Oral Tympanic Axillary Normal (oC)", "36.6-38", "35.5-37.5", "35.8-38", "36.5-37.5"], "imgs": []}]}, "resp": {"title": "Respiratory", "pg": [44, 55], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Patient Positioning during Respiratory exam: After taking vitals, patient should be seated, arms at side and legs uncrossed", "• Draping: In both Respiratory and Cardiac examinations, draping important especially for females. Advise minimal exposure."], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 46, "do": ["• Check for abnormal respiratory rate, tachycardia and O2 saturation in particular", "• CURB-65 score for pneumonia: 1 point each for Confusion, Urea >7, RR ≥30, BP <90/60, Age >65. If CURB-65 Score >2, recommend admit to inpatient.", "• Pulsus Paradoxus (drop in BP during inspiration) >25mmHg greatly ↑ likelihood of severe asthma (LR+", "22.6, LR- 0.8) – Differential diagnosis includes cardiac tamponade – see Chapter 6 – Cardiac Exam"], "imgs": []}, {"sec": "Inspection", "name": "Work of Breathing", "phase": "inspect", "tags": [], "pg": 47, "say": ["If you can breathe normally, I will examine the face and torso for signs of work of breathing."], "do": ["1. Look for signs of increased work of breathing: tripod position, pursed lips, nasal flaring, accessory muscle use (sternocleidomastoid, scalene, trapezius, internal intercostal, or abdominal muscles), paradoxical breathing (Hoover’s sign), tracheal tug (abnormal downward movement of trachea during inspiration), suprasternal indrawing, intercostal indrawing, supraclavicular retraction, grunting (pediatrics).", "2. Observe if patient can finish complete sentences (not interrupted by work of breathing)."], "report": ["There are no signs of increased work of breathing (comment on all the above out loud as you observe on inspection). You are speaking in complete sentences which is reassuring as well."], "why": ["Important in assessing dyspneic patients and assessing if a patient is in respiratory distress. The inability to speak in complete sentences demonstrates a higher degree of respiratory distress."], "imgs": []}, {"sec": "Inspection", "name": "Rhythm of Breathing", "phase": "inspect", "tags": [], "pg": 47, "say": ["If you can breathe normally, I will examine the face and torso for rhythm of breathing."], "do": ["Look at the rate, rhythm and depth of inspiratory and expiratory phases of breathing. Look for signs of dyspnea (laboured breathing) or apnea (absent breathing) in each cycle. Look for abnormal breathing patterns:", "1. Cheyne Stokes Breathing: Periodic breathing – deep breathing gradually becoming shallower with a period of apnea subsequent → CHF, ↑ Intracranial Pressure (ICP) Carbon Monoxide Poisoning", "2. Kussmaul Breathing: Rapid, deep laboured breathing → Metabolic Acidosis (e.g. Diabetic Ketoacidosis)", "3. Shallow breathing: Inhibited breaths → Pleuritic Chest Pain (e.g. PE, pericarditis, pneumonia, rib fracture)", "4. Cushing’s Triad: Suggests ↑ Intracranial pressure (ICP) → Irregular respirations, bradycardia, and widened pulse pressure (↑ Systolic BP, ↓ Diastolic BP)"], "report": ["You have a regular rhythm of breathing which is reassuring."], "why": ["Specific breathing patterns and rhythms can help in diagnosing particular etiologies."], "imgs": []}, {"sec": "Inspection", "name": "Assistive Equipment", "phase": "inspect", "tags": [], "pg": 47, "say": ["I will now inspect for any assistive equipment such as oxygen and IV lines."], "do": ["Look for any supplemental oxygen; look at any peripheral lines (e.g. IV, Foley i.e. Urinary Catheter) etc."], "report": ["You are on 2 litres of oxygen through nasal prongs. I don’t notice any other IV lines or catheters."], "why": ["More complete assessment in an inpatient setting"], "imgs": []}, {"sec": "Inspection", "name": "Scars & Medical Devices", "phase": "inspect", "tags": [], "pg": 47, "say": ["I will now inspect for any signs of scars or medical implants"], "do": ["Look for evidence of surgical scars or medical implants (e.g. pacemaker)"], "report": ["I note no surgical scars or medical implants."], "why": ["Provides evidence for past medical and surgical history"], "imgs": []}, {"sec": "Inspection", "name": "Cachexia/ Sarcopenia", "phase": "inspect", "tags": [], "pg": 47, "say": ["I will now inspect the torso for muscle and subcutaneous tissue wasting."], "do": ["Looking for signs of wasting/muscle atrophy, as well as subcutaneous tissue wasting – inspect clavicle (muscle– protrusion/prominence), shoulders (muscle– square look, protruding acromion process), scapula (muscle– bony prominences, depressions), and ribs (muscle, subcutaneous fat–bony prominences, indentation)"], "report": ["I note no signs of cachexia on inspection of the chest"], "why": ["Cachexia is a process of fat and muscle wasting; Sarcopenia is specifically a process of muscle wasting. Cachexia is important to assess for, where early intervention (e.g. nutrition, referral to dietitian) is critical. Pulmonary cachexia can occur in advanced lung disease – e.g. in COPD or Interstitial Lung Disease (ILD) such as Idiopathic Pulmonary Fibrosis (IPF) and is associated with accelerated functional decline and increased mortality. This is explored further in Chapter 41 – Adult Palliative Care Assessment (Integration Foundation)"], "imgs": []}, {"sec": "Inspection", "name": "Barrel Chest, Flail Chest", "phase": "inspect", "tags": [], "pg": 47, "say": ["If you can breathe in and out, I will assess how the rib cage moves for changes in shape."], "do": ["Look for signs of barrel chest (broad and deep chest), flail chest (section of chest moving in opposite direction of rest of chest), or any bruises of the chest wall."], "report": ["I note no signs of bruising, barrel chest or flail chest."], "why": ["Barrel chest is associated with hyperinflation (e.g. emphysema re. pink puffers); Flail chest is when rib fractures at two points compromising chest wall rigidity – a life-threatening condition that can alter breathing mechanics, and increase risk of pneumothorax, etc."], "imgs": []}, {"sec": "Inspection", "name": "Pectus Excavatum & Carinatum", "phase": "inspect", "tags": [], "pg": 47, "say": ["I will now inspect the chest for sternal and chest wall deformities."], "do": ["Assess from anterior aspect, looking for any abnormal concave (pectus excavatum) or convex (pectus carinatum) presentation"], "report": ["I note no pectus excavatum or carinatum on inspection."], "why": ["Severe pectus excavatum or carinatum can impair both cardiac and respiratory function, painful"], "imgs": ["resp-1.webp", "resp-2.webp"]}, {"sec": "Inspection", "name": "Scoliosis & Kyphosis", "phase": "inspect", "tags": [], "pg": 48, "say": ["I will now inspect the back for spinal deformities."], "do": ["1. Assess from posterior aspect while patient standing.", "2. Look for abnormal lordosis (inward curvature), kyphosis (outward curvature) to spine or scoliosis (lateral curvature, common deformity).", "3. If you suspect scoliosis, have the patient bend forward until their spine is horizontal as this will allow for more accurate assessment of Scoliosis. This maneuver is called the Adam’s Forward Bend Test (Will learn in MF4 Ch 29 – Back Exam)."], "report": ["I note no scoliosis or kyphosis on inspection."], "normal": ["Cervical spine physiologically lordotic; Thoracic spine physiologically kyphotic; Lumbar spine physiologically lordotic; Sacral spine physiologically kyphotic. Excessive spinal curvature is not normal (explored in detail in MF4)"], "why": ["Severe scoliosis can lead to reduced lung capacity (When Scoliosis > 50° curvature)"], "imgs": ["resp-3.webp"]}, {"sec": "Inspection", "name": "Central Cyanosis", "phase": "inspect", "tags": [], "pg": 48, "say": ["I will now inspect under the tongue for signs of low oxygen levels. Can you briefly open the mouth, and lift the tongue up?"], "do": ["Inspect under the tongue for central cyanosis"], "report": ["I note no signs of central cyanosis; I note the tongue appears proper size, free in motion, slightly red in colour and with thin white coating layer."], "why": ["Central cyanosis indicates poor oxygenation in the lungs (specifically PaO2 <50mmHg given an Hb of 140-160g/L; PaO2 45mmHg if Hb 120 g/L). Images show tongue colouration changes before and after resolution of central cyanosis4."], "imgs": ["resp-4.webp", "resp-5.webp"]}, {"sec": "Inspection", "name": "Peripheral Cyanosis", "phase": "inspect", "tags": [], "pg": 48, "say": ["I will now inspect the hands for signs of changes in circulation. Can you show the hands with palms up? And now with palms down?"], "do": ["Hold hands lightly and inspect for peripheral cyanosis"], "report": ["I note no signs of peripheral cyanosis."], "why": ["Peripheral cyanosis indicates inadequate circulation, as shown in image affecting digits5."], "imgs": ["resp-6.webp"]}, {"sec": "Inspection", "name": "Clubbing (Schamroth Sign)", "phase": "inspect", "tags": [], "pg": 48, "say": ["I will now inspect the fingers for signs of low oxygen levels. Can you hold the index finger nails together like this? (See picture, model for patient)"], "do": ["Model with your own hands. Look for a visible gap between the two nail beds.", "• If arthritic changes, check for a concave bump between base of nail bed and finger"], "report": ["Schamroth’s sign is negative, with no evidence of clubbing."], "why": ["Associated with chronic hypoxia, cyanotic heart disease, lung cancer, interstitial lung disease"], "imgs": ["resp-7.webp"]}, {"sec": "Inspection", "name": "Tar Staining of Fingers", "phase": "inspect", "tags": [], "pg": 48, "say": ["I will now inspect the hands for signs of abnormal staining. Can you show the hands with palms up? And now with palms down?"], "do": ["Look for tar stains on fingers (nicotine)"], "report": ["I do not note any nicotine staining on fingers."], "why": ["If you’re concerned the patient was not being forthright about smoking"], "imgs": []}, {"sec": "Palpation", "name": "General", "phase": "palpate", "tags": [], "pg": 48, "say": ["I will now palpate the chest anteriorly and posteriorly for masses; please tell me if you are in discomfort."], "do": ["Palpate quickly around the chest area anteriorly and posteriorly; look at patient for signs of discomfort and stop the exam if the patient is in distress."], "report": ["I note no masses or tenderness in the chest area anteriorly or posteriorly"], "why": ["Important general physical examination maneuvers, with potential for assessing mechanical causes of chest pain e.g. rib fractures, costochondritis, etc."], "imgs": []}, {"sec": "Palpation", "name": "Tracheal Deviation", "phase": "palpate", "tags": [], "pg": 49, "say": ["I will now palpate the trachea with two fingers for signs of movement with breathing (point on yourself to where you will palpate). I will ask you to breathe in and out. Please tell me if you are in discomfort."], "do": ["Make V shape with index and middle finger, above sternal notch. Instruct to breathe in, then breathe out. Look at patient for signs of discomfort and stop the exam if the patient is in distress."], "report": ["The trachea remains midline on inspiration and is mobile in all 4 directions."], "why": ["Tracheal deviation occurs when a pressure differential exists between Left and Right pleural cavities. It will shift away from pathology increasing pressure on one side (unilateral tension pneumothorax or pleural effusion); or towards a pathology decreasing pressure on one side (e.g. atelectasis/lung collapse).", "• Can’t Miss Diagnosis: Tension pneumothorax is an emergency where a one-way valve is created, where air can get in but not out, increasing intrapleural pressure. Look for dyspnea, deviated trachea, Jugular Venous Distension, unilateral absent breath sounds, unilateral hyperresonance to percussion, and trauma. A tension pneumothorax requires emergent needle decompression (in 2nd intercostal space at Mid-clavicular line) or chest tube placement (in 5th intercostal space just anterior to mid-axillary line), often at bedside even before imaging can be completed."], "imgs": []}, {"sec": "Palpation", "name": "Laryngeal Height (Tracheal Descent)", "phase": "palpate", "tags": [], "pg": 49, "say": ["I will now palpate the thyroid cartilage to measure movement with normal breathing (point on yourself to where you will palpate)."], "do": ["As patient reaches end-expiration, record maximum distance between thyroid cartilage and suprasternal notch. This is the maximum laryngeal height. Look at patient for signs of painful discomfort and stop the exam if the patient is in distress."], "report": ["The maximum laryngeal height is more than 4cm, a normal value."], "why": ["Maximum laryngeal height occurs at the end of expiration, while minimum height occurs at the end of inspiration. A maximum laryngeal height <4cm indicates hyperinflation and significant obstruction, affecting this rise in height during expiration. Important finding for obstructive airway disease."], "imgs": ["resp-8.webp"]}, {"sec": "Palpation", "name": "Bilateral Chest Expansion", "phase": "palpate", "tags": [], "pg": 49, "say": ["If you can sit up and turn to the side of the exam table, I will palpate the back for chest expansion with breathing."], "do": ["1. Place hands at 10th rib, press together.", "2. Ask patient to breathe out fully, then position hands.", "3. Have patient take a deep breath.", "4. Hands should move equidistant on each side with ≥4cm deviation bilaterally Alternative Method: Measure horizontally with measuring tape around patient at level of the xiphisternum."], "more": ["Note: takes longer, can comment that you would measure only if there was time in an OSCE scenario."], "report": ["The chest shows chest expansion of 4 cm with bilateral symmetry, a normal value."], "why": ["Bilateral ↓ expansion can occur in asthma and COPD, as well as Thoracic Scoliosis and Ankylosing Spondylitis (See Chapter 29 – Back Exam – MF4); unilateral ↓ expansion seen in pleural effusion (LR+ 8.1, LR-", "0.29), pneumothorax, etc. on the affected side."], "imgs": ["resp-9.webp"]}, {"sec": "Palpation", "name": "Tactile Fremitus", "phase": "palpate", "tags": [], "pg": 49, "say": ["I will now palpate the back for air entry on each side. When you feel my hands, say “toy boat.”"], "do": ["1. Patient crosses their arms to displace scapulae. Place medial edges of hands horizontally on the back.", "2. Start superiorly and move inferiorly. At each stage, assess vibration level and any differences bilaterally.", "3. Also, switch anteriorly and continue, to inspect upper lobes bilaterally."], "report": ["The chest shows bilateral resonance throughout all lung fields."], "why": ["Vibrations increased over areas of consolidation, reduced over areas of pleural effusion (LR+ 5.7, LR- 0.21) or pneumothorax (consider the mediums the sound produced is being conducted through)"], "imgs": []}, {"sec": "Percussion", "name": "Intercostal", "phase": "percuss", "tags": [], "pg": 49, "say": ["I will assess for dull sounds along the back & chest. Please tell me if you are in discomfort."], "setup": ["Patient crosses their arms to displace scapulae."], "do": ["Using wrist drop technique, move side to side beginning superiorly and progressing inferiorly to assess for bilateral resonance. Look at patient for signs of discomfort and stop the exam if the patient is in distress."], "report": ["The chest shows equal resonance bilaterally on percussion."], "why": ["Dullness to percussion increases likelihood of suspected consolidation (LR+ 3.0 for pneumonia) or pleural effusion (LR+ 8.7). Dullness at lung bases points to pulmonary edema. Hyper-resonance on percussion increases likelihood of suspected chronic airflow obstruction (i.e. hyperinflation, LR+ 5.1) or Pneumothorax."], "imgs": []}, {"sec": "Percussion", "name": "Diaphragmatic Excursion", "phase": "percuss", "tags": [], "pg": 50, "say": ["I will assess how the diaphragm moves up and down along the back with breathing."], "do": ["1. Start below the level of the scapula on one side.", "2. Patient should expire and hold while you percuss down until transition from resonant to dull.", "3. Patient can now inspire and hold while you percuss further down until dull again.", "4. Measure distance and repeat on other side."], "normal": ["4-5 cm"], "report": ["Diaphragmatic excursion is 4-5cm bilaterally."], "why": ["Unilateral changes can indicate a pneumothorax or pleural effusion re filling up pleural space."], "more": ["Alternate method: Reverse order i.e. percuss while patient inspires first, then percuss while patient expires."], "imgs": ["resp-10.webp"]}, {"sec": "Auscultation", "name": "Listening to Breathing GeneralStridor - Pleural RubStridor (Peds) - Wheeze (Infant)", "phase": "auscultate", "tags": ["peds"], "pg": 50, "say": ["I will now listen to the chest and back – breathe in and out each time you feel the stethoscope. Please pause if you become light-headed."], "setup": ["Patient crosses arms to displace scapulae."], "do": ["Hold stethoscope still when listening (don’t want to only hear rustling of moving it around)."], "report": ["I note air entry bilaterally with vesicular breath sounds and no adventitious sounds."], "normal": ["Normal auscultation depends on listening location (1) Trachea: Bronchial – harsh, high-pitched, heard through full inspiration and expiration (2) Sternum: Bronchovesicular – less harsh, heard through full inspiration, short and softer on expiration (3) Everywhere else: Vesicular - gentle, low-pitched, quiet on inspiration and nearly silent on expiration"], "why": ["Assessing for Adventitious (Abnormal) Sounds, including:", "Sound Respiratory Description Significance Phase Fine Crackles Inspiration Inspiration Discontinuous, soft, Distal lower airway process (e.g. pulmonary fibrosis, congestive heart failure) high-pitched, more per breath, popping sound. Coarse Crackles Inspiration Discontinuous, loud, low-pitched, fewer per breath, bubbling sound. Discontinuous, loud, Proximal lower airway process (e.g. pneumonia, pulmonary edema, adult respiratory distress syndrome) alone; or low-pitched, fewer per Inspiration + breath, bubbling sound. early expiration Stridor Inspiration Inspiration Loud, musical sound, constant pitch, louder over neck. Upper airway obstruction (e.g. croup, foreign body aspiration, epiglottitis, bacterial tracheitis, retropharyngeal abscess, peritonsillar abscess) Pleural Expiration alone; or Expiration + Inspiration Loud, grating or rubbing Pleural inflammation (e.g. pleural effusion, Rub sound; can be crackling. pulmonary embolism, pleuritis) Wheeze Wheeze Continuous, high- ↓ Distal lower airway diameter (e.g. asthma, pitched, musical sound. chronic obstructive pulmonary disease) Rhonchus Continuous, low- ↓ Proximal lower airway diameter by pitched, coarse sound; mucous secretions, lesions or foreign bodies may clear after cough. (e.g. pneumonia, cystic fibrosis)", "• Bronchial breath sounds over lung (normal over trachea) points to consolidation", "• Diminished breath sounds greatly increases likelihood for suspected pleural fluid (LR+ 18.6)", "• Early Crackles increases likelihood of suspected obstructive disease (LR+ 14.6), and particularly for severe obstruction in patients with chronic airflow limitation (LR+ 20.8; LR- 0.1)", "• Stridor: Sensitivity of 80.4% & specificity of 59.5% for Foreign Body Aspiration6. May be the earliest sign worrisome for airway compromise."], "imgs": ["resp-11.webp"]}, {"sec": "Auscultation", "name": "Consolidation Testing (Egophony, Whispered Pectoriloquy, Bronchophony", "phase": "auscultate", "tags": [], "pg": 51, "do": ["Part 1 – Egophony:", "• Say: When you feel the stethoscope, please say “EEEE” while I listen with the stethoscope.", "• Do: Place stethoscope in same locations as general auscultation. Hearing change to AAAA is abnormal. Part 2 – Whispered Pectoriloquy:", "• Say: When you feel the stethoscope, please whisper “1,2,3,4” while I listen with the stethoscope.", "• Do: Place stethoscope in same locations as general auscultation. Hearing the whisper is abnormal. Part 3 – Bronchophony:", "• Say: When you feel the stethoscope, please say “toy boat” in a normal tone of voice while I listen with the stethoscope.", "• Do: Place stethoscope in same locations as general auscultation. Hearing loud(er) voice is abnormal."], "report": ["I note evidence of consolidation. If positive – specify which lobe(s) you heard abnormal findings in."], "why": ["Check if you suspect consolidation in a particular lobe from tactile fremitus, percussion, etc. Though uncommonly used in clinical practice, Egophony does moderately increase the likelihood of suspected pneumonia (LR+ 4.1). Reduced vocal resonance (bronchophony) increases the likelihood of pleural effusion (LR+ 6.5, LR- 0.27)."], "imgs": []}, {"sec": "Auscultation", "name": "Forced Expiratory Time (FET)", "phase": "auscultate", "tags": [], "pg": 51, "say": ["I will now listen to the trachea (point on yourself to where you will auscultate) with maximum effort breathing. Please take in a deep breath as much as possible, and then exhale as fast as possible with the mouth wide open."], "do": ["1. Place bell of stethoscope over trachea. Listen to a cycle of normal breathing. Monitor your clock", "2. Listen until end inspiration. Start recording time at this point.", "3. Patient then exhales with an open mouth as quickly as possible. Once airflow is inaudible, this is the end point of forced expiratory time."], "report": ["The recorded forced expiratory time is less than 9 seconds, a normal value."], "why": ["Forced Expiratory Time (FET) is a simple, inexpensive, sensitive and fairly reproducible test of airway obstruction (defined as FEV1/FVC < 70%). FET >9 seconds increases the likelihood for suspected Obstructive Airway Disease (e.g. COPD) with LR+ 6.7. In practice, pulmonary function testing (e.g. spirometry) is commonly used."], "imgs": []}]}, "cardiac": {"title": "Cardiac", "pg": [56, 70], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Patient Positioning during Cardiac exam: After taking vitals, patient should be supine, arms at sides and legs uncrossed", "• What is the Hematological Physical Examination? This includes looking for signs of Pallor, Jaundice, Signs of Bleeding & Easy Bruising, Central Cyanosis, and Hypovolemia. Each is described below except for Hypovolemia which is included in the Volume Status Examination (Chapter 9 – MF2)", "• Draping: In both Respiratory and Cardiac examinations, draping important especially for females. Advise minimal exposure."], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 59, "do": ["• Check Orthostatic vitals (re. dizziness, orthostatic hypotension, severe blood loss)", "• Check BP in both arms (e.g. difference ≥ 20 mmHg can be seen in Aortic Dissection)", "• Heart rate and rhythm – is it regular, irregularly regular, or irregularly irregular?"], "imgs": []}, {"sec": "Vitals", "name": "Pulsus Paradoxus", "phase": "vitals", "tags": ["conditional"], "pg": 59, "say": ["I will measure the blood pressure using a manual Blood Pressure cuff."], "do": ["Similar to manual blood pressure measurement detailed in Chapter 4, with an additional recorded value.", "1. Listen for first Korotkoff sound that appears then disappears with inspiration (recorded as SBP, as usual).", "2. Listen for when the sound no longer disappears with inspiration (a pressure in between SBP and DBP).", "3. Calculate the difference between these values; a difference of < 10 mmHg is normal – above this, is positive for pulsus paradoxus.", "4. Then listen for last sounds in series (DBP, as usual), deflate cuff more quickly as normal."], "report": ["The recorded drop in systemic blood pressure is <10mmHg, which is negative for pulsus paradoxus."], "normal": ["A drop of <10mmHg is physiologic due to increased venous return on inspiration → pressure transmitted to RV wall, accommodated → more blood in pulmonary circulation."], "why": ["• Can’t Miss Diagnosis – Cardiac Tamponade: The presence of pulsus paradoxus increases likelihood of suspected cardiac tamponade, and the lack of pulsus paradoxus reduces the likelihood (At >12mmHg, LR+ve 5.9 and LR-ve 0.03; at >10mmHg, LR+ve 3.3 and LR-ve 0.03. Also look for Beck’s Triad for acute cardiac tamponade i.e. distended neck veins, low arterial blood pressure, and muffled heart sounds.", "◦ Mechanism: In Cardiac tamponade, the intrapericardial volume reaches above the elastic limit and becomes fixed. This means as the right heart fills, the left heart compresses, and vice versa. Inspiration increases preload → pressure transmits to ventricular septum → septal deviation towards LV → decreased stroke volume → decreased systolic blood pressure.", "◦ Cardiac Tamponade vs. Pericarditis/Pericardial Effusions:", "• Distinguishing Cardiac Tamponade from Pericarditis and Pericardial Effusions: On EKG, both Severe Pericardial Effusions and Cardiac Tamponade may show Electrical Alternans (i.e. alternating QRS complex amplitudes). Cardiac Tamponade may be secondary to Pericarditis (inflammation of pericardium). The classic symptoms of pericarditis are pleuritic chest pain worse on inspiration and in supine position.", "• Differential Diagnosis for Pulsus Paradoxus: Severe constrictive pericarditis & severe asthma/COPD exacerbations. False Negatives may occur with Aortic Regurgitation and Atrial Septal Defect (ASD)"], "imgs": []}, {"sec": "Inspection", "name": "General & Body Habitus", "phase": "inspect", "tags": [], "pg": 59, "say": ["I will begin with general inspection of the head and torso."], "do": ["Look for signs of respiratory distress (see Chapter 5 – Resp Exam), and diaphoresis (heavy perspiration/ sweating). Is patient endomorphic (overweight), ectomorphic (underweight), or mesomorphic (normal weight)? Observe their level of consciousness: are they alert and oriented to person, place and time?"], "report": ["I note no signs of respiratory distress such as accessory muscle use (in an OSCE station, state full list of signs of increased work of breathing). Patient not diaphoretic with a mesomorphic body habitus, alert and oriented to person, place and time."], "why": ["Creates an initial picture; important especially when formulating impression of presentation."], "imgs": []}, {"sec": "Inspection", "name": "Eyes", "phase": "inspect", "tags": [], "pg": 59, "say": ["Can you open one eye and Conjunctival Pallor4 Scleral Icterus5 Arcus Senillis6 pull the lower eyelid down? Now the other side?"], "do": ["Look for conjunctival pallor, scleral icterus (jaundice) or arcus senilis (grey arc around cornea)"], "report": ["I note no conjunctival pallor, scleral icterus (jaundice) or arcus senilis (grey arc around cornea). Conjunctival Pallor4 Scleral Icterus5 Arcus Senillis6"], "why": ["Conjunctival pallor is a sign of anemia; Scleral Icterus (jaundice) can be a sign of Pre-hepatic (e.g. hemolytic anemia), Hepatic (e.g. Acute hepatitis) or Post-Hepatic (obstructive – cholecystitis, choledocholithiasis, etc.) hyperbilirubinemia. Arcus senilis can be a sign of dyslipidemia (lipid deposits)"], "imgs": ["cardiac-12.webp", "cardiac-13.webp", "cardiac-14.webp"]}, {"sec": "Inspection", "name": "Hands & Mouth", "phase": "inspect", "tags": [], "pg": 60, "say": ["I will inspect under the tongue and the hands. Splinter Hemorrhages7 Janeway Lesions8"], "do": ["Look for the following abnormalities in the hands and mouth", "1. Splinter Hemorrhages: tiny blood clots running vertically under nails.", "2. Janeway Lesions: small nodular lesions on palms", "3. Osler Nodes: painful red, raised lesions on hands and feet. Osler Nodes9 Palmar Pallor4", "4. Respiratory findings: clubbing, tar staining, peripheral cyanosis (Ch 5 – Respiratory Exam).", "5. Capillary Refill Time: <2 seconds for children and adult men; <3 seconds for women; <4 seconds for elderly patients (see Ch 8- Peripheral Vascular Exam).", "6. Tremor: an involuntary, oscillating movement of a fixed frequency/rhythmic quality.", "7. Pallor: Assess hands at palmar creases & nailbeds.", "8. Central Cyanosis: in the mouth, assess under tongue for central cyanosis (see Ch 5 – Respiratory Exam)"], "report": ["I note no signs of central cyanosis or findings in the hands (in an OSCE station, verbalize all findings). Splinter Hemorrhages7 Janeway Lesions8 Osler Nodes9 Palmar Pallor4"], "why": ["• Splinter hemorrhages, Janeway lesions and Osler nodes are signs of infective endocarditis due to immune complex deposition and/or septic micro-emboli, and can be used as minor criteria in the Duke Criteria for Infective Endocarditis (Click here for link).", "• Tremor can be seen in thyrotoxicosis (see Thyroid Exam – Ch 15 – MF3).", "• Pallor in palmar creases & nailbeds are signs of anemia.", "• Peripheral cyanosis indicates circulatory insufficiency; central cyanosis indicates poor oxygenation in the lungs (specifically PaO2 <50mmHg given an Hb of 140-160g/L; PaO2 45mmHg if Hb 120 g/L)."], "imgs": ["cardiac-15.webp", "cardiac-16.webp", "cardiac-17.webp", "cardiac-18.webp"]}, {"sec": "Inspection", "name": "Jugular Venous Pressure (JVP) – mix of inspection & palpation Also seen in Ch 9 – Volume Status Exam – MF2 JVP - JVP Waveform", "phase": "inspect", "tags": [], "pg": 60, "say": ["Please lay back on the exam table and tilt the head all the way to the left. How do you differentiate the JVP from the Carotid Pulse? JVP Carotid Occludable and bounces back Non-occludable after occlusion Non-palpable Palpable Biphasic 1-1 Pulse to Heartbeat Decreases: with elevated No change with position and with inspiration position or inspiration Increases: with Abdomino- No change with AJR Jugular Reflux (See below) maneuver"], "do": ["1. Prop up head of exam table to 30-45°. Stand at right side. Look for JVP between 2 heads of sternocleidomastoid (i.e. sternal head medially, clavicular head laterally), or look lateral to sternal head of sternocleidomastoid.", "2. Once you have located the JVP, measure by placing ruler on sternal angle facing vertically", "3. Make a right-angle triangle going from the apex of the JVP to the ruler.", "4. The height on the ruler is the measured JVP."], "more": ["Note: on OSCE, estimate using your fingers, < 3 finger breadths is normal – not expected to use ruler."], "normal": ["3-4 cm Above Sternal Angle (ASA)"], "report": ["JVP was located and is < 5 cm above the sternal angle JVP Carotid Occludable and bounces back Non-occludable Non-occludable after occlusion Non-palpable Palpable Biphasic 1-1 Pulse to Heartbeat Decreases: with elevated No change with position and with inspiration position or inspiration Increases: with Abdomino- No change with AJR Jugular Reflux (See below) maneuver"], "why": ["The Jugular Venous Pressure (JVP) is used to check the intravascular volume status of patients (termed “wet” if the patient is volume overloaded and the JVP is elevated, or “dry” if the patient is volume depleted and the JVP is flat). The JVP is an indirect measure of right atrial pressure via visualization of the internal jugular vein. The Central Venous Pressure (cm H2O) can be estimated from the JVP by adding 5cm to the measured value, since right atrium is approximately 5cm below the sternal angle. In the appropriate clinical context (e.g. dyspneic patients in Emergency Department), an elevated JVP increases the likelihood of suspected Congestive Heart Failure (LR+ 5.1; LR- 0.66) If the JVP increases with inspiration, this is called Kussmaul’s Sign and may be a sign of severe pericarditis or right-sided heart failure. Beck’s Triad (for Acute Cardiac Tamponade) includes distended neck veins, low Arterial Blood Pressure, and Muffled Heart Sounds."], "imgs": ["cardiac-19.webp"]}, {"sec": "Inspection", "name": "Abdominal", "phase": "inspect", "tags": [], "pg": 61, "say": ["I will briefly inspect the abdomen for abnormalities."], "do": ["Look for signs of ascites, any pulsations or surgical scars in abdominal area"], "report": ["I note no ascites, pulsations or surgical scars in the abdomen."], "why": ["Looking for signs of portal hypertension – note that patients may have ascites without physical findings (Ultrasound more sensitive). May also look for other signs of venous congestion (e.g. Edema, Jugular Venous Distension – see JVP assessment above), and for other signs of liver disease (e.g. jaundice, coagulopathy, telangiectasias, etc. – see Abdominal Exam – Ch 13 – MF3)"], "imgs": []}, {"sec": "Inspection", "name": "Legs", "phase": "inspect", "tags": [], "pg": 61, "say": ["I will briefly inspect the legs for abnormalities."], "do": ["Look for signs of edema, erythema, surgical scars and peripheral vascular disease."], "report": ["I note no edema, erythema, surgical scars or concerns for peripheral vascular disease."], "why": ["Assessing extent of vasculopathy (see Peripheral Vascular Exam – Ch 8 – MF1 for more details), potential extent of Congestive Heart Failure, etc."], "imgs": []}, {"sec": "Inspection", "name": "Xanthoma", "phase": "inspect", "tags": [], "pg": 61, "say": ["I will inspect for any visible yellow depositions."], "do": ["Assess for Xanthomata (yellowish cholesterol-rich fat depositions). Common sites include eyes, joints, hands, and tendons (e.g. Achilles tendon)"], "report": ["No xanthomata visible on inspection"], "why": ["Xanthomata are complications of hyperlipidemia – significant risk factor of cardiovascular disease"], "imgs": ["cardiac-20.webp"]}, {"sec": "Inspection", "name": "Coagulopathy", "phase": "inspect", "tags": [], "pg": 61, "say": ["I am going to inspect for any signs of coagulopathy"], "do": ["Assess for Hematomas: Based on size, either Petechiae (1-2 mm diameter red spot), Purpura (3-10 mm), and/or Ecchymosis (>10 mm); as well as Telangiectasias (spider veins)"], "report": ["No Petechiae, purpura or ecchymosis noted on inspection."], "why": ["Signs of both platelet disorders, and vascular disorders."], "imgs": ["cardiac-21.webp", "cardiac-22.webp"]}, {"sec": "Palpation", "name": "Abdominojugular Reflux (AJR) – formerly Hepatojugular Reflux (HJR)", "phase": "palpate", "tags": [], "pg": 61, "say": ["Please lay back on the exam table and tilt the head to the left. I’m going to press on the upper abdomen and monitor the veins in the neck."], "do": ["Press firmly over right upper quadrant or centre of abdomen for 10-15 seconds. Observe the JVP. If JVP does rise significantly (≥4cm), observe if JVP returns to baseline while applying pressure. Sustained elevation of JVP beyond 10 seconds is abnormal. This can be confirmed by suddenly releasing abdominal pressure and seeing a return to baseline (≥4cm fall)."], "normal": ["In an otherwise healthy individual, the JVP remains constant or temporarily rises for 1-2 heartbeats before returning to normal."], "report": ["Abdominojugular Reflux lasted less than 10 seconds, which is normal."], "why": ["An alternative test for measuring JVP, method to assess right ventricular failure. This is also useful if you are having trouble seeing or differentiating the JVP from carotid."], "imgs": []}, {"sec": "Palpation", "name": "Heaves and Thrills", "phase": "palpate", "tags": [], "pg": 61, "say": ["I will now be palpating the chest at the four valve regions of the heart. Where to Palpate: See image"], "do": ["Use whole hand to palpate heaves, then pads of 2-3 fingers to palpate for thrills at each valve region (Heaves = Hands, Thrills = Tips)"], "report": ["There are no heaves or thrills on palpation."], "why": ["Heaves provide evidence of hypertrophy. Thrills provide evidence of turbulent blood flow, complemented by murmurs heard on auscultation."], "imgs": ["cardiac-23.webp"]}, {"sec": "Palpation", "name": "PMI (Point of Maximal Impulse) Loc.– Amp. – Dur. – Size", "phase": "palpate", "tags": [], "pg": 62, "say": ["I will palpate the chest for where the heart beats strongest. Can you lean forward?"], "do": ["Using 2-3 fingers, locate the 5th intercostal space at left mid-clavicular line (MCL) – the expected site of PMI. Assess Location, Amplitude, Duration and Size (LADS)."], "report": ["PMI located at 5th intercostal at left MCL, is brisk and tapping, lasts 2/3rd systole, and size of quarter."], "why": ["Apex beat being palpated can provide evidence of hypertrophy – PMI not always apical impulse", "• Location of Apex: Displaced location can be evidence of decreased ejection fraction, left ventricular dilatation, increased left atrial pressure, or enlarged Cardiothoracic Ratio on Chest X-Ray.", "• Amplitude of Apex: If patient has known mitral stenosis, increased apex amplitude suggests comorbid aortic stenosis or mitral regurgitation", "• Duration of Apex: Sustained apex with an aortic murmur argues for aortic stenosis; Lack of sustained apex with Aortic Regurgitation argues against moderate-severe severity of Aortic regurgitation", "• Size of Apex: Increased size evidence of increased LV End-Diastolic Volume"], "imgs": []}, {"sec": "Palpation", "name": "Edema", "phase": "palpate", "tags": [], "pg": 62, "say": ["I will palpate for leg swelling (Sacral edema if patient immobile). Please Pedal Edema13 tell me if you are in discomfort."], "do": ["Press firmly with pads of your thumbs on the dorsal surface of patient’s leg, just above the ankle at bony prominence. Hold for 10s, then release. Look for pitting edema – skin does not bounce back immediately (i.e. pits). How high does it go on the leg? Is it pitting (transudate) or non-pitting (exudate)? Look at patient for signs of discomfort and stop exam signs of distress. Grading: 0 = none; 1+ = 2mm depression; 2+ = 4mm depression; 3+ = 6mm depression; 4+ = 8mm depression"], "report": ["I note (grade) pitting edema bilaterally, up to the level of (location e.g. ankles)."], "why": ["Edema is excess interstitial fluid accumulation causing swelling, particularly in gravity dependent areas (e.g. feet). Normally, this fluid returns through lymphatic drainage. Pitting edema = transudate (non-protein filled) – sign of increased hydrostatic pressure (e.g. congestive heart failure, decreased venous return) or decreased oncotic pressure (e.g. nephrotic syndrome, hypoalbuminemia). Non- pitting edema = exudate (protein) filled, or an issue with lymphatic drainage (e.g. lymphedema)."], "imgs": ["cardiac-24.webp"]}, {"sec": "Palpation", "name": "Central & Upper Limb Pulses", "phase": "palpate", "tags": [], "pg": 62, "say": ["I will palpate the central pulses in the neck, arms and groin."], "do": ["Palpate for pulses bilaterally. For peripheral pulses, you can palpate the most distal pulse. If it is non- palpable, move more proximally. Should be symmetrical, regular rate/rhythm and no delay between them. Note that Lower Limb Peripheral Pulses are explored in Ch 8 – Peripheral Vascular Exam. Where to Palpate – Upper Extremities:", "• Radial: Along radius bone just proximal to wrist on palmar side of hand", "• Brachial: Medial to biceps tendon and 2-3cm above antecubital fossa Where to Palpate – Central Pulses:", "• Carotid: Medial to sternocleidomastoid muscle, roughly at level of cricoid cartilage", "• Abdominal Aorta: Slightly left and superior to umbilicus", "• Femoral: Midway between ASIS and Symphysis pubis"], "more": ["Note: Auscultate for carotid bruits before palpation of carotid pulses using bell of stethoscope (see below) Grading: 0 = Non-palpable; 1 = Barely palpable; 2 = Easily Palpable (Normal); 3 = Bounding; 4 = Aneurysmal."], "report": ["Central and most distal upper limb peripheral pulses are symmetrical with regular rate and rhythm."], "why": ["Note that palpation of peripheral and central pulses is a core element of the Peripheral Vascular Exam (see Chapter 8 – Peripheral Vascular Exam). Specific findings include Pulses alternans (two strong systolic with mid-systolic dip) suggests LV dysfunction or Cardiac tamponade. An Irregularly irregular rhythm may suggest Atrial fibrillation. Modification for Patients with Obesity: Use a handheld Doppler Ultrasound to locate pulses if they are difficult to appreciate by palpation. In this population, a doppler may be more sensitive than palpation."], "imgs": []}, {"sec": "Auscultation", "name": "Cardiac Precordial Auscultation S3, S4Murmur Abnormal S1, S2 Position", "phase": "auscultate", "tags": [], "pg": 63, "say": ["I will auscultate the chest for heart sounds. Please breathe normally as I listen."], "do": ["Listen carefully with the diaphragm of the stethoscope at each valve region (Aortic, Pulmonic, Tricuspid, and Mitral). Listen for abnormal heart sounds or murmurs."], "report": ["I note a normal S1 and S2. There are no extra heart sounds or murmurs present."], "normal": ["S1 and S2, regular rate and rhythm, with no extra heart sounds and no murmurs", "• S1 = loudest at Tricuspid & Mitral valves (re atrioventricular valves closing at start of systole)", "• S2 = loudest at Aortic & Pulmonic valves (re semilunar valves closing at end of systole). Physiologic splitting of S2 is normal on inspiration due to ↑ negative intrathoracic pressure – best heard in a sitting position. Abnormal Findings – Abnormal S1 and S2 and Associated Conditions:", "Characteristic S1 S2 Loud Loud Mitral Valve Prolapse (MVP); Mitral Stenosis Systemic hypertension (loud A2) or (MS); Left Atrial Myxoma; Tachycardia Pulmonary hypertension (loud P2) Faint Mitral Regurgitation; Left Bundle Branch Aortic Stenosis (LR+ 7.5, LR- 0.5) Aortic Stenosis (LR+ 7.5, LR- 0.5) Block (LBBB); Long PR interval (1st degree AV block); Acute Aortic Regurgitation (AR) Variable AV Dissociation (LR+ 24.4, LR- 0.4); Atrial N/A Fibrillation Wide Split Right Bundle Branch Block (RBBB); Right Atrial Myxoma Right Bundle Branch Block (RBBB); Right RBBB; Pulmonic Stenosis; Mitral Atrial Myxoma Regurgitation; Ventricular Septal Defect (VSD); Right Ventricular Failure Paradoxical N/A LBBB; Severe Aortic Stenosis; Wolff- Split Parkinson-White (WPW); LV Dysfunction Fixed Split N/A Atrial Septal Defect (ASD) Abnormal Findings – Extra heart sounds: Best heard in left lateral decubitus position.", "• S3: Heard just after S2, with rapid and early diastolic filling of ventricles, “Sloshing in” (e.g. volume overload). In the appropriate clinical context (e.g. dyspneic patients in Emergency Department), hearing an S3 increases the likelihood of Congestive Heart Failure (LR+11, LR- 0.88).", "• S4: Heard just before S1, with diastolic rapid late filling of ventricles, “A stiff wall” (e.g. pressure overload, Left Ventricular Hypertrophy).", "• S3 + S4: Summation gallop Abnormal Findings – Murmurs (represent Turbulent blood flow). Listen for Location (i.e. identify valve); Radiation (e.g. to carotids, left sternal border, etc.); Timing (e.g. Systolic vs. Diastolic); Configuration (e.g. Crescendo, Decrescendo, Crescendo-decrescendo, Plateau); Quality (e.g. high vs. low pitch; harsh, musical, blowing, rumbling, etc.); Change with maneuvers (e.g. with inspiration, Valsalva, squat); and Volume/Grade", "• Systolic Murmur: Grades 1 (very faint); Grade 2 (soft, readily detectable); Grade 3 (easily detectable without thrill); Grade 4 (easily detectable with thrill); Grade 5 (very loud murmur audible with stethoscope placed lightly on chest); Grade 6 (extremely loud, audible with stethoscope off chest)", "• Diastolic Grade: Grade 1 (barely audible); Grade 2 (audible, soft); Grade 3 (easily audible); Grade 4 (loud) Common Murmur Description Mitral Stenosis (MS) Mitral Stenosis", "• Pathophysiology: Mitral valve should be open in diastole – mitral stenosis (MS) causes incomplete opening of mitral valve in diastole", "• Murmur: Diastolic murmur with Opening Snap best heard at cardiac apex in left lateral decubitus position. Worsened by ↑ venous return (squat/leg raise) Aortic", "• Pathophysiology: Aortic valve should be closed in diastole – aortic Regurgitation / regurgitation causes incomplete closing of aortic valve in diastole Insufficiency", "• Murmur: Diastolic murmur heard best at right base in sitting position. (AR/AI) Worsened by ↑ venous return (squat/leg raise)"], "imgs": ["cardiac-25.webp"]}, {"sec": "Auscultation", "name": "Carotid Bruits", "phase": "auscultate", "tags": [], "pg": 64, "say": ["I will auscultate the carotid arteries in the neck (point on yourself to where you will auscultate) for signs of turbulent blood flow."], "do": ["Listen with Bell of Stethoscope. Listen for duration, intensity, and pitch. If applicable, also listen for any radiation of a systolic murmur to the right carotid (e.g. Aortic Stenosis)"], "report": ["I note no carotid bruits on auscultation bilaterally."], "why": ["Can assess for carotid artery stenosis prior to palpating, where the presence of a carotid bruit has a 53% sensitivity and 83% specificity of a clinically relevant stenosis14. In addition, radiation of a systolic murmur to the right carotid ↑ likelihood of suspected aortic stenosis (LR+ 8.1, LR- 0.29)"], "imgs": []}, {"sec": "Auscultation", "name": "Carotid Upstroke", "phase": "auscultate", "tags": ["conditional"], "pg": 64, "say": ["I will continue auscultating the heart while I also palpate over a carotid artery on one side of the neck (point on yourself to where you will palpate)."], "setup": ["Auscultate over the valve that you suspect may be stenotic or regurgitant. Place the pads of your 2-3 fingers over the carotid artery gently (after auscultating for carotid bruits)."], "do": ["As you listen for murmur, there should be no delay between murmur onset (systole) and carotid pulse.", "• If carotid pulse is delayed and relatively diminished, this is Pulsus parvis et tardus (sign of aortic stenosis).", "• If the carotid pulse is brisk, this may be a sign of aortic regurgitation.", "• If the carotid pulse is biphasic (2 pulses per cardiac cycle), this is called pulsus bisferiens and may be a sign of coexisting Aortic Stenosis and Regurgitation."], "report": ["I note a normal carotid upstroke with no delay between the murmur and carotid pulse."], "why": ["Carotid upstroke is a conditional test that can be used if you suspect an aortic stenosis or aortic regurgitation murmur. Aortic stenosis is expected to cause carotid upstroke to be delayed and diminished due to partially obstructed forward flow, where this finding (pulsus parvis et tardus) increases likelihood of suspected aortic stenosis (LR + 9.2, LR- 0.56). Aortic regurgitation is expected to cause brisk carotid upstroke due to ↑ preload from regurgitation. Biphasic carotid pulse (pulsus bisferiens) due to comorbid Aortic stenosis and Aortic regurgitation is a combination of these morphologies."], "imgs": []}]}, "pv": {"title": "Peripheral vascular", "pg": [90, 96], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Chapter Connections: Given that poorly controlled Diabetes Mellitus can lead to Peripheral Vascular Disease (PVD) complications, the Peripheral Vascular examination (Chapter 8) is closely tied to the Diabetes Exam (Ch 14 – MF3)"], "steps": [{"sec": "Inspection", "name": "Varicose Veins", "phase": "inspect", "tags": [], "pg": 91, "say": ["I will inspect for varicose veins (appropriately drape patient)."], "do": ["Look for varicosities (swollen veins visible under skin – caused by surface vein damage, loss of valve integrity facilitating pooling) – typically examined with patient standing"], "report": ["I note no varicosities present on inspection bilaterally"], "why": ["Sign of peripheral venous disease. Varicosities can be supported with compression stockings. Colour Pallor Brown, Blue, Purple Hair Loss No Change Ulceration Ulceration Pressure points – soles, ventral surface of foot Tend to be dry lesions Tibial plateau, Medial Malleolus Tend to be wet lesions (e.g. wound drainage) Skin Changes Shiny Flaky Edema N/A Peripheral Edema Temperature Cold Warm Photos2,3,4,5 Photos2,3,4,5", "Differentiates peripheral arterial vs. peripheral venous disease. Note that in peripheral arterial disease, critical limb ischemia is defined by chronic (≥2 weeks) ischemic rest pain, nonhealing wound/ulcer, or gangrene in 1 or both legs attributable to proven arterial occlusive disease. Gangrene can be divided into:", "• Dry gangrene: Presents with hard, dry texture; often a clear border of viable and black, necrotic tissue. This can be seen in photo above, with dry gangrene of the first 3 digits of the right foot.", "• Wet gangrene: Moist, swollen appearance with blistering – a surgical emergency."], "imgs": ["pv-49.webp", "pv-50.webp", "pv-51.webp", "pv-52.webp"]}, {"sec": "Inspection", "name": "Bruits", "phase": "inspect", "tags": [], "pg": 92, "say": ["I will use the bell of my stethoscope to auscultate key arteries for any signs of turbulent blood flow."], "do": ["With patient in supine position, auscultate Carotid → Epigastric → Abdominal aorta → Renal→ Iliac → Femoral Arteries for bruits.", "• R/L Carotid: Medial to sternocleidomastoid muscle, roughly at level of cricoid cartilage", "• Abdominal Aorta: Slightly left and superior to umbilicus", "• Right and Left Renal: 5cm superior and 5cm lateral to umbilicus", "• Right and Left Iliac: 5cm inferior and 5cm lateral to umbilicus", "• Right and Left Femoral: Midway between ASIS and Symphysis pubis"], "report": ["I note no bruits on auscultation."], "why": ["Bruits may be indicative of obstructive arterial diseases e.g. atherosclerotic processes, or an aortic dissection (aortic bruit). An abdominal bruit in a patient with hypertension raises concern for Renal Artery Stenosis as a secondary cause of hypertension. Also explored in Chapter 13 – Abdominal Exam – MF3."], "imgs": ["pv-53.webp"]}, {"sec": "Palpation", "name": "Temperature to Touch", "phase": "palpate", "tags": [], "pg": 92, "say": ["I will palpate the top of each foot to check temperature on each side."], "do": ["Feel the dorsum of each foot with back of hand – assess whether it is cold to touch, or warm to touch. Migrate proximally on each side and compare temperature between each."], "report": ["I note no temperature deviation at the dorsal surface of the feet."], "why": ["Cold feet is a sign of arterial deficiency; Warmer feet is a sign of venous deficiency"], "more": ["Note: Kneecap (patella) can be physiologically slightly cooler than rest of body"], "imgs": []}, {"sec": "Palpation", "name": "Capillary Refill Time", "phase": "palpate", "tags": [], "pg": 92, "say": ["I will palpate for circulation in the fingers and toes. Can you raise one arm above the level of the heart?"], "do": ["Press down on the nail bed until it turns colourless. If unable to see nail bed (e.g. with nail polish present), can press on pad of finger/toe as a backup. Record time when colour returns to the nail. Normal Values: 2s for children and adult men, 3s for women, 4s for elderly; evidence suggests >5s for moderate-severe peripheral arterial disease."], "report": ["I note normal capillary refill time."], "why": ["Volume status sign, and also used to assess moderate-severe peripheral arterial disease."], "imgs": []}, {"sec": "Palpation", "name": "Edema", "phase": "palpate", "tags": [], "pg": 92, "say": ["I will palpate for leg swelling (Sacral edema if patient immobile). Please Pedal Edema6 tell me if you are in discomfort."], "do": ["Press firmly with pads of your thumbs on the dorsal surface of patient’s leg, just above the ankle at bony prominence. Hold for 10s, then release. Look for pitting edema – skin does not bounce back immediately (i.e. pits). How high does it go on the leg? Is it pitting (transudate) or non-pitting (exudate)? Look at patient for signs of discomfort and stop exam signs of distress. Grading: 0 = none; 1+ = 2mm depression; 2+ = 4mm depression; 3+ = 6mm depression; 4+ = 8mm depression"], "report": ["I note (grade) pitting edema bilaterally, up to the level of (location e.g. ankles)."], "why": ["Specific to the Peripheral Vascular Exam, pitting edema can be a sign of peripheral venous disease. Edema is excess interstitial fluid accumulation causing swelling, particularly in gravity dependent areas (e.g. feet). Normally, this fluid returns through lymphatic drainage. Pitting edema = transudate (non- protein filled) – sign of increased hydrostatic pressure (e.g. congestive heart failure, decreased venous return) or decreased oncotic pressure (e.g. nephrotic syndrome, hypoalbuminemia). Non-pitting edema = exudate (protein) filled, or an issue with lymphatic drainage (e.g. lymphedema)."], "imgs": ["pv-54.webp"]}, {"sec": "Palpation", "name": "Calf Circumference", "phase": "palpate", "tags": [], "pg": 92, "say": ["I will now measure calf circumference in each leg, looking for symmetry."], "do": ["Using a measuring tape, measure the largest circumference bilaterally. Assess whether difference > 3cm."], "report": ["Calf circumference difference is less than 3 cm at the largest circumference."], "why": ["Difference in calf circumference > 3cm is a clinical sign of DVT (see Well’s DVT Criteria below)"], "imgs": ["pv-55.webp"]}, {"sec": "Palpation", "name": "Peripheral Pulses", "phase": "palpate", "tags": [], "pg": 93, "say": ["I will palpate the peripheral pulses in the arms, lower legs and feet."], "do": ["Palpate for pulses bilaterally. You can palpate the most distal pulse in each limb first. If non-palpable, move more proximally until pulses are palpable. Pulses should be symmetrical, a regular rate and rhythm with no delay between them. Where to Palpate – Lower Extremities:", "• Dorsalis Pedis: Dorsal side of foot, just lateral to extensor tendon of big toe", "• Posterior Tibial: Posterior and inferior to medial malleolus = bony prominence on side of ankle", "• Popliteal: Behind knees, use 2 hands Where to Palpate – Upper Extremities:", "• Radial: Along radius bone just proximal to wrist on palmar side of hand", "• Brachial: Medial to biceps tendon and 2-3cm above antecubital fossa Grading: 0 = Non-palpable; 1 = Barely palpable; 2 = Easily Palpable (Normal); 3 = Bounding; 4 = Aneurysmal."], "report": ["I palpated the dorsalis pedis and radial arteries as most distal pulse in each extremity. They were grade 2, symmetrical bilaterally with no delay, and regular rate and rhythm."], "why": ["Assess extent of arterial insufficiency (distal pulses lost prior to more proximal pulses). 6P’s of Acute Limb Ischemia: Pulseless, Pallor, Pain, Paresthesia (Pins/Needles), Polar (Cold) & Paralysis. Modification for Patients with Obesity: Use a handheld Doppler Ultrasound to locate pulses if difficult to appreciate by palpation. In this population, handheld Doppler may be more sensitive than palpation."], "imgs": []}, {"sec": "Palpation", "name": "Central Pulses", "phase": "palpate", "tags": [], "pg": 93, "say": ["I will palpate the central pulses in the neck, arms and abdominal region."], "do": ["Palpate pulses and note any differences bilaterally. You should observe symmetry in amplitude, contour and upstroke. Where to Palpate – Central Pulses:", "• Carotid: Medial to sternocleidomastoid muscle, roughly at level of cricoid cartilage", "• Abdominal Aorta: Slightly left and superior to umbilicus", "• Femoral: Midway between ASIS and Symphysis pubis Grading: 0 = Non-palpable; 1 = Barely palpable; 2 = Easily Palpable (Normal); 3 = Bounding; 4 = Aneurysmal."], "report": ["I note symmetry in amplitude, contour and upstroke at the arterial pulses examined."], "why": ["Assess signs of obstructive arterial pathologies. Note that Renal and Iliac Arteries cannot be palpated and are assessed through auscultation alone. Modification for Patients with Obesity: Use a handheld Doppler Ultrasound to locate pulses if difficult to appreciate by palpation. In this population, handheld Doppler may be more sensitive than palpation."], "imgs": []}, {"sec": "Special Tests", "name": "BrodieTrendelenburg Test", "phase": "special", "tags": [], "pg": 93, "say": ["I will assess each leg’s venous drainage for valve competency."], "do": ["Patient in supine position. Raise the patient’s leg, placing a tourniquet around the upper thigh (Normal:", "occluding the veins). Have patient stand up with tourniquet on. Look for venous system to fill from below the superficial saphenous system within 35-60 seconds."], "report": ["Brodie-Trendelenburg Test showed a venous refilling time within normal limits."], "why": ["If re-filling occurs faster than 35 seconds, evidence of valvular incompetence."], "imgs": []}, {"sec": "Special Tests", "name": "Buerger’s Test", "phase": "special", "tags": [], "pg": 93, "say": ["I will hold each leg up, then lower the leg to inspect for colour changes."], "do": ["With patient supine, elevate leg for 30-60s and look for pallor on elevation. Normally, the leg should not become pale after 60s. Then, have patient sit with legs down for 15s, to assess delayed rubor on dependency (erythema). Normally, colour should return to the leg within 10 seconds (in a darker-skinned patient, look for time to venous filling <15 seconds)."], "report": ["I note no pallor on elevation or rubor on dependency."], "why": ["Pallor on Elevation → Peripheral Arterial Disease. The angle at which pallor begins correlates with the severity of arterial disease (e.g. pallor at <20° indicates severe ischemia). Rubor on Dependency → >15s colour return correlates with arterial disease; extreme red/pink colour suggests venous disease."], "imgs": ["pv-56.webp"]}, {"sec": "Special Tests", "name": "Allen’s Test", "phase": "special", "tags": [], "pg": 94, "say": ["I will assess each hand for the collateral circulation between the ulnar and radial arteries. Please raise the arm to the level of the heart and clench a tight fist for 30 seconds."], "do": ["After the 30s of patient making a fist, apply pressure over ulnar and radial arteries to occlude them. Have patient open hand while still occluding the arteries – the hand should be blanched. Release one artery. See whether the colour returns to whole hand in 5 seconds. Repeat for the other artery in the same hand. Repeat on each hand."], "report": ["Allen’s Test shows normal collateral circulation."], "why": ["Confirms adequate collateral circulation (anastomosis) to hand. Typically done in advance of arterial line placement, arterial blood gas sampling, or catheterization."], "imgs": ["pv-57.webp"]}, {"sec": "Special Tests", "name": "Ankle Brachial Index (ABI)", "phase": "special", "tags": [], "pg": 94, "say": ["Using a Doppler Ultrasound (U/S), I will assess blood pressure differences between the Ankle and Arm."], "setup": ["Requires Doppler U/S Equipment. Lay patient supine."], "do": ["Brachial Systolic BP: Place the manual cuff 2-3cm above crease of the elbow (as you would for normal BP measurement – see Chapter 4 – Vital Signs – MF1). Use the Doppler as your stethoscope by placing the U/S probe in the antecubital fossa. Inflate the cuff to 20 mmHg above expected systolic BP (where Doppler signal disappears). Deflate cuff until the Doppler signal has re-appeared. This is sBP for arm. Repeat for the patient’s other arm. Ankle Systolic BP: Place the manual BP cuff just proximal to the ankle malleoli. Place the U/S probe on the dorsum of the foot to find dorsalis pedis pulse, or posterior to the medial malleolus for posterior tibial pulse. Use the higher sBP between dorsalis pedis and posterior tibial pulses. Calculating ABI: Calculate the ratio between the highest sBP from either arm and the highest sBP of the foot of interest. (e.g .) 𝐻𝐻𝐻𝐻𝐻𝐻ℎ𝑒𝑒𝑒𝑒𝑒𝑒 𝑒𝑒𝑠𝑠𝑒𝑒𝑒𝑒𝑠𝑠𝑠𝑠𝐻𝐻𝑠𝑠 𝐵𝐵𝐵𝐵 𝐻𝐻𝑖𝑖 𝑅𝑅 𝐹𝐹𝑠𝑠𝑠𝑠𝑒𝑒 Grading:", "𝑅𝑅𝑅𝑅𝑅𝑅ℎ𝑡𝑡 𝐴𝐴𝐴𝐴𝐴𝐴 = 𝐻𝐻𝐻𝐻𝐻𝐻ℎ𝑒𝑒𝑒𝑒𝑒𝑒 𝑏𝑏𝑏𝑏𝑏𝑏𝑠𝑠ℎ𝐻𝐻𝑏𝑏𝑠𝑠 𝑒𝑒𝑠𝑠𝑒𝑒𝑒𝑒𝑠𝑠𝑠𝑠𝐻𝐻𝑠𝑠 𝐵𝐵𝐵𝐵 𝐻𝐻𝑖𝑖 𝑒𝑒𝐻𝐻𝑒𝑒ℎ𝑒𝑒𝑏𝑏 𝑏𝑏𝑏𝑏𝑎𝑎 ABI Interpretation >1.4 Abnormal: Non-compressible vessels (e.g. hardening from PAD/calcification", "1.0 – 1.4 Normal (sBP higher in leg than arm)", "0.9 – 0.99 Borderline peripheral arterial disease", "0.5 – 0.89 Abnormal: Mild-moderate peripheral arterial disease <0.5 Abnormal: Severe peripheral arterial disease"], "report": ["I note a normal ratio of Ankle BP to Brachial BP of 1.0. 𝑅𝑅𝑅𝑅𝑅𝑅ℎ𝑡𝑡 𝐴𝐴𝐴𝐴 ABI 𝐴𝐴 = Interpretation >1.4 Abnormal: Non-compressible vessels (e.g. hardening from PAD/calcification", "1.0 – 1.4 Normal (sBP higher in leg than arm)", "0.9 – 0.99 Borderline peripheral arterial disease", "0.5 – 0.89 Abnormal: Mild-moderate peripheral arterial disease <0.5 Abnormal: Severe peripheral arterial disease"], "why": ["The Ankle-Brachial Index is a more accurate test for assessing the severity of Peripheral Arterial Disease. It is not assessed on the OSCE exam (requiring proficiency in use of doppler ultrasound), but you may encounter it in clinical practice. For patients with suspected peripheral arterial disease (PAD) or critical limb ischemia (CLI), the ABI is a key investigation to send patients for to guide next steps in management – where a key differentiation between PAD and CLI guiding urgency of investigation and management is the presence of rest pain, non-healing wounds, and/or gangrene8."], "imgs": []}]}, "abdo": {"title": "Abdominal", "pg": [144, 163], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Patient Positioning during Abdominal exam: After taking vitals, patient should be supine, arms at sides and legs uncrossed with a pillow underneath their head. There should be good lighting, with the exam room warm and your hands warm. Make sure the patient has an empty bladder before you start your exam.", "• Draping: Drape appropriately when need area exposed; return covered up state at end of portion of exam/end of exam. If the patient has abdominal pain, during the exam and with patient consent, expose the groin and genitalia for a few seconds to check for inguinal and femoral hernias. Why Move from Inspection → Auscultation → Percussion → Lighter Palpation → Deeper Palpation?", "• Auscultation is performed first in the abdominal examination because palpation and percussion can cause a disturbance in bowel sounds, obscuring the value of auscultation maneuvers.", "• In general, moving from percussion → light palpation → deep palpation allows one to be progressively invasive for pain reasons and to get a good outline as to where to palpate via preparatory percussion."], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 151, "do": ["• Check for Orthostatic Hypotension (if concerned about severe blood loss, nausea/vomiting/diarrhea)", "• Systemic Inflammatory Response Syndrome (SIRS) Criteria (Click for link): (1) Fever > 38C or < 36C; (2) HR > 90 bpm; (3) RR > 20/min or Arterial CO2 < 32 mmHg; (4) Abnormal WBC Count (> 12000/µL or < 4000/µL, or >10% bands) – Note: SIRS may occur in several non-infectious conditions e.g. autoimmune disease, pancreatitis, vasculitis, thromboembolism, burns or surgery.", "◦ Sepsis Threshold: 2 of 4 SIRS criteria plus suspected infection (e.g. appendicitis, diverticulitis)", "◦ Other screening tools for sepsis or septic shock: NEWS (National Early Warning Score – Click for link); MEWS (Modified Early Warning Score for Clinical Deterioration – Click for link); qSOFA (quick screen of in-hospital mortality for non-ICU patients with infection – Click for link)", "◦ Recommendation: As per 2021 Surviving Sepsis Guidelines, “We recommend against using qSOFA compared with SIRS, NEWS, or MEWS as a single-screening tool for sepsis or septic shock”6."], "imgs": []}, {"sec": "General Inspection", "name": "General & Body Habitus", "phase": "inspect", "tags": [], "pg": 152, "say": ["I will begin with general inspection of the head and torso."], "do": ["Look for signs of respiratory distress (see Ch 5 – Resp Exam – MF1), and diaphoresis (heavy perspiration/ sweating). Is patient endomorphic (overweight), ectomorphic (underweight), or mesomorphic (normal weight)? Observe their level of consciousness: are they alert and oriented to person, place and time?"], "report": ["I note no signs of respiratory distress such as accessory muscle use (state full list). Patient not diaphoretic with a mesomorphic body habitus, alert and oriented to person, place and time."], "why": ["Important especially when formulating your impression including the acuity of the presentation. Here, altered LOC could be a sign of hepatic encephalopathy, or a sign of shock (e.g. hemorrhagic shock from GI bleed, Reynaud’s Pentad re. Acute Suppurative Cholangitis). Encephalopathy greatly increases the likelihood of suspected cirrhosis in patients with known liver disease (LR+ 10, LR-0.86)"], "imgs": []}, {"sec": "General Inspection", "name": "Volume Status Exam", "phase": "inspect", "tags": [], "pg": 152, "do": ["Perform a quick exam to check for hypervolemia if you suspect hepatic congestion (e.g. auscultate lung bases, assess JVP, inspect for peripheral cyanosis, auscultate the heart, palpate peripheral pulses, edema, etc.)"], "why": ["Heart failure can cause hepatic congestion, which can contribute to acute liver failure, esophageal varices and variceal bleeding, and venous thrombosis. (Ch 9 – Volume Status Exam – MF2)."], "imgs": []}, {"sec": "General Inspection", "name": "General Shape of Abdomen & Hernias", "phase": "inspect", "tags": [], "pg": 152, "say": ["I will now inspect the abdomen for its shape, and for scars and skin changes. Bulging Flanks7"], "do": ["Inspect the abdomen:", "• Does abdomen look flat, rounded, scaphoid or protuberant (with generalized or localized distension)?", "• Do you observe bulging flanks (difficult to assess on inspection in Obese patients)?", "• Do you observe obvious bulges or peristalsis? – may be a hernia (need to palpate)", "◦ Check the umbilicus for any bulging (e.g. in umbilical hernias, bowel obstruction)", "◦ Check if it is reducible (returns to abdomen on pressure or when the patient lays down flat and relaxes. If it is not reducible, it may be incarcerated (stuck) or strangulated (ischemic bowel disease risk – this is when the patient presents with central abdominal pain).", "• Can you see any past surgical scars? Any colostomies?", "• Any visible pregnancy (e.g. fetal movement)?", "• Any pulsations (e.g. aortic pulsation as potential aneurysm)?", "• Does the abdomen move with respiration?", "• Check for straie, for superficial dilated veins (e.g. in IVC obstruction) and bruising (e.g. history of trauma)."], "report": ["The abdomen is flat and non-distended. I note no bulging flanks, hernias, or surgical scars."], "why": ["Bulging flanks mildly increase the likelihood of suspected ascites (LR+ 2.0, LR- 0.3). Further, hernias are very common in the general population, with the most common hernias being inguinal hernias, though abdominal hernias can commonly present at surgical sites and the umbilicus. Both a reducible and a strangulated bowel can cause small bowel obstructions. Likelihood of suspected bowel obstruction is greatly increased by visible peristalsis (LR+ 18.8) and distended abdomen (LR+ 9.6, LR- 0.4). Finally, an abdomen not moving with inspiration or spontaneously is suspicious for peritoneal irritation. Modification for Patients with Obesity: Use fluid wave or shifting dullness tests to appreciate ascites. Bulging flanks due to adipose tissue may be difficult to differentiate from ascites on inspection."], "imgs": ["abdo-75.webp"]}, {"sec": "General Inspection", "name": "Stigmata of Chronic Liver Disease – Facial", "phase": "inspect", "tags": [], "pg": 152, "say": ["I will inspect the face for signs of liver disease. Scleral Icterus8"], "do": ["Look for Frontal Balding (especially in females), Temporal Muscle Wasting (temporal regions of head), Parotid Enlargement, Fetor Hepaticus (sour, fecal breath), and Scleral Icterus"], "report": ["I note no signs of liver disease in the face including Frontal Balding, Temporal Muscle Wasting, Parotid Enlargement, Fetor Hepaticus, or Scleral Icterus."], "why": ["Liver disease can present with facial findings:", "• Jaundice (including scleral icterus) – due to hyperbilirubinemia – jaundice mildly increases the likelihood of suspected cirrhosis in patients with liver disease (LR+ 3.8, LR- 0.82). This can be due to prehepatic causes (e.g. hemolysis), intrahepatic causes (e.g. cirrhosis, hepatitis, liver cancer), or post-hepatic causes (e.g. choledocholithiasis; cholangitis; Mirizzi syndrome where inflamed gallbladder compresses common hepatic duct as a complication of cholecystitis; pancreatitis; cholangiocarcinoma; pancreatic cancer)", "• Temporal Muscle Wasting – due to impaired protein synthesis.", "• Parotid Enlargement – seen especially in patients with alcohol-related cirrhosis.", "• Fetor Hepaticus – due to portal hypertension.", "• Frontal balding – look for especially in female patients."], "imgs": ["abdo-76.webp", "abdo-77.webp"]}, {"sec": "General Inspection", "name": "Stigmata of Chronic Liver Disease – Hands", "phase": "inspect", "tags": [], "pg": 153, "say": ["I will now inspect the hands for signs of liver disease.", "Can you keep both hands held out with wrist extended? Thank you; now, open both Terry’s Nails9, 10 Palmar Erythema11 hands fully."], "do": ["Look for Terry’s Nails (whitening of proximal 2/3rd of nailbed); Palmar Erythema; Thenar Atrophy (Muscle wasting proximal to thumb; DDx includes carpal tunnel syndrome); and Hypothenar Atrophy (Wasting of muscle proximal to little finger).", "Look for Asterixis – a flapping tremor of the hand with wrist extended (DDx includes Diabetes Mellitus and other causes of myoclonus e.g. neuromuscular disorders). When opening hand, look for Dupuytren’s Contracture – fingers cannot be relaxed from a flexed position."], "report": ["I note no signs of liver disease in the hands including Terry’s Nails, Palmar Erythema, Thenar Atrophy, Asterixis or Dupuytren’s Contracture. Terry’s Nails9, 10 Palmar Erythema11"], "why": ["Liver disease can present with physical findings on the hands:", "• Terry’s Nails – due to hypo-albuminemia. Terry’s Nails greatly increases the likelihood of cirrhosis in patients with liver disease (LR+ 16-22, LR- 0.57-0.58)", "• Palmar Erythema – due to impaired estrogen metabolism – greatly increases the likelihood of suspected hepatocellular disease in patients with jaundice (LR+ 9.8, LR- 0.5). Absence of palmar erythema mildly decreases the likelihood of suspected cirrhosis in patients with known liver disease (LR- 0.59).", "• Thenar and Hypothenar atrophy – due to impaired protein synthesis.", "• Asterixis – Asterixis is an example of negative myoclonus (transient <0.5s inhibition of tonic muscle contraction) due to impaired metabolism in liver disease (e.g. ammonia metabolism to urea), and part of assessment for hepatic encephalopathy.", "• Dupuytren’s Contracture – mainly manifestation of alcohol consumption."], "imgs": ["abdo-78.webp", "abdo-79.webp", "abdo-80.webp", "abdo-81.webp"]}, {"sec": "General Inspection", "name": "Stigmata of Chronic Liver Disease – Abdomen", "phase": "inspect", "tags": [], "pg": 153, "say": ["I will now inspect the Spider Angiomata12 Caput Medusae13 Bulging Flanks/Ascites7 abdomen (and chest if male) for signs of liver disease."], "do": ["Look for Spider Angiomas or Caput Medusae in umbilical region. Look for Ascites. In male patients, look for Gynecomastia and Hypogonadism."], "report": ["I note no signs of liver disease in the abdomen including spider angiomas, caput medusae, ascites, or gynecomastia/hypogonadism (if male)."], "why": ["Many findings of liver disease present on the abdomen:", "• Spider Angiomata – due to impaired estrogen metabolism – slightly increase the likelihood of suspected hepatocellular disease in patients with jaundice (LR+ 4.7, LR- 0.6), and cirrhosis in patients with known liver disease (LR+ 4.3, LR- 0.61).", "• Caput Medusae – due to portal hypertension – greatly increase the likelihood of suspected hepatocellular disease in patients with jaundice (LR+ 17.5, LR- 0.6) and cirrhosis in patients with known liver disease (LR+ 11, LR- 0.72)", "• Gynecomastia and Testicular Atrophy (in male patients) – due to impaired estrogen metabolism. The likelihood of suspected cirrhosis in patients with known liver disease is moderately increased by the presence of testicular atrophy (LR+5.8, LR- 0.84) or gynecomastia (LR+ 5.8-35, LR- 0.43-0.84)", "• Ascites – due to portal hypertension, hypoalbuminemia – moderately increases the likelihood of suspected cirrhosis in patients with known liver disease (LR+ 7.2, LR- 0.69)"], "imgs": ["abdo-82.webp", "abdo-83.webp", "abdo-84.webp"]}, {"sec": "General Inspection", "name": "Cullen’s Sign and GreyTurner Sign", "phase": "inspect", "tags": [], "pg": 153, "say": ["I will now inspect for bruising in the abdomen."], "do": ["Look for bruising in the subcutaneous tissue around the umbilicus (Cullen’s sign) and in the flanks of the abdomen (Grey-Turner sign)"], "report": ["Cullen’s sign and Grey-Turner sign are negative, which is normal."], "why": ["May be seen in patients who experience retroperitoneal bleeds, a complication of several conditions including pancreatitis and AAA rupture."], "imgs": ["abdo-85.webp"]}, {"sec": "Auscultation", "name": "Bowel Sounds – With Diaphragm", "phase": "auscultate", "tags": [], "pg": 154, "say": ["I will auscultate for bowel sounds using the diaphragm of my stethoscope."], "do": ["Listen over either the 4 quadrants or 9 regions, depending on time. Stop once you hear them in ONE region, no additional value to doing all of them."], "report": ["Bowel sounds heard on auscultation within 2 minutes in one of the 9 abdominal regions (epigastric, umbilical, hypogastric, R/L hypochondriac, R/L lumbar, R/L iliac) with diaphragm of stethoscope. Alternatively, can specify by the quadrant – RUQ, RLQ, LLQ, LUQ"], "why": ["The likelihood of suspected bowel obstruction is increased moderately by hyperactive bowel sounds (LR+ 5.0, LR- 0.6), and slightly by abnormal bowel sounds (LR+ 3.2, LR- 0.4). Hypoactive or absent bowel sounds may suggest ileus or peritonitis; decreased sounds mildly increase the likelihood of suspected appendicitis in pediatrics (LR+ 2.5, LR- 0.77)."], "imgs": []}, {"sec": "Auscultation", "name": "Abdominal Bruits – With Bell (also explored in Chapter 10 - Renal Exam - MF2)", "phase": "auscultate", "tags": [], "pg": 154, "say": ["I will use the bell of my stethoscope to auscultate key arteries for any signs of turbulent blood flow."], "do": ["With patient in supine position, auscultate:", "• Abdominal Aorta: Slightly left and superior to umbilicus", "• R and L Renal: 5cm superior, 5cm lateral to umbilicus", "• R and L Iliac: 5cm inferior and 5cm lateral to umbilicus", "• R and L Femoral: Midway between ASIS & symphysis pubis If you detect a renal bruit (“whoosh” sound), clarify if it is systolic or systolic-diastolic (e.g. via timing of carotid upstroke on palpation). Also clarify if it is unilateral vs. bilateral."], "report": ["I note no bruits on auscultation in any of the 7 abdominal areas."], "why": ["In a normal vessel, a pulse can be palpated but not auscultated. Bruits occur due to turbulent flow within a vessel, where the pitch and radiation are a function of flow and direction of the turbulent stream. Bruits can be innocent (particularly in young, normotensive, asymptomatic patients), typically described as short, faint and mid-systolic. A systolic-diastolic abdominal bruit greatly increases likelihood of renovascular hypertension (LR+ 39, LR- 0.62) (e.g. renal artery stenosis), a cause of secondary hypertension."], "imgs": ["abdo-86.webp"]}, {"sec": "Auscultation", "name": "Venous Hum – Liver", "phase": "auscultate", "tags": [], "pg": 154, "say": ["I will use the bell of my stethoscope to auscultate for a venous hum over the epigastric and umbilical areas."], "do": ["Listen for a humming noise in these areas"], "report": ["I note no venous hum heard over the epigastric and umbilical areas."], "why": ["Portal hypertension can increase collateral circulation between portal and systemic circulation, creating a hum that may be heard on auscultation (especially when listening for esophageal varices and periumbilical veins (Caput Medusae)). A rub may also result from liver metastases/hepatoma/liver mass."], "imgs": ["abdo-87.webp"]}, {"sec": "Auscultation", "name": "Friction Rub – Peritoneal Irritation", "phase": "auscultate", "tags": [], "pg": 154, "say": ["I will use the diaphragm of my stethoscope to auscultate for a friction rub over the liver and spleen."], "do": ["Listen for a rough and high-pitched sound when liver and spleen rub peritoneum"], "report": ["I note no friction rub in the lower right or left costal areas"], "why": ["A friction rub can indicate peritoneal irritation, and may be heard with free fluid, hepatic metastases/abscesses, or a splenic infarct/infection/abscess."], "imgs": ["abdo-88.webp"]}, {"sec": "Auscultation", "name": "Liver Scratch Test", "phase": "auscultate", "tags": ["conditional"], "pg": 154, "say": ["I will use the diaphragm of my stethoscope to auscultate for the lower liver edge. Please breathe normally and let me know if you feel any pain."], "do": ["Place diaphragm of stethoscope at xiphisternum over the liver, just above the costal margin at the Right Midclavicular Line (MCL). Starting in RLQ, move one finger up the surface of the abdomen, scratching gently. The intensity of the transmitted sound is greatly enhanced once the finger is over the lower border of liver. Look at patient for signs of discomfort and stop the exam if the patient is in distress."], "report": ["At the right midclavicular line, liver excursion measures 8cm by the liver scratch test, which is normal."], "why": ["Check and comment if you have clinical suspicion of liver disease, hepatomegaly, etc. Evidence14 suggests clinicians should refrain from this test as it “yields a result with no correlation to the actual liver span”, with better evidence for Palpation of the Liver Edge. In patients with obesity15, it is noted that “abdominal fat makes it difficult to palpate deep structures (e.g. liver edge)” with preference for the Liver Scratch test to find the lower liver edge recommended in this population."], "imgs": []}, {"sec": "Percussion", "name": "General Gen. - Peritonitis", "phase": "percuss", "tags": [], "pg": 155, "say": ["I will percuss the abdomen in 9 regions. Are you experiencing any pain? If so, I will percuss that area last."], "do": ["Percuss with a good surface area of hand on patient for max capacity for hearing sounds on percussion."], "normal": ["Expect more tympanic sounds heard in epigastric region, as well as the cecum (re air pockets). Expect variably dull or tympanic sounds at bladder (re bladder distension/pregnancy), liver and spleen may be physiologically dull). Is there any tenderness on percussion?"], "report": ["I note tympanic sounds on percussion of nine abdominal quadrants with no tenderness on percussion."], "why": ["Dullness to percussion may be suspicious of impaction or ascites. Tenderness on percussion mildly increases likelihood of suspected peritonitis (LR+ 2.4, LR- 0.5)."], "imgs": []}, {"sec": "Percussion", "name": "Fluid Wave Test – Ascites", "phase": "percuss", "tags": ["conditional"], "pg": 155, "say": ["I will assess for abdominal fluid using a fluid wave test. Could you place one hand over the umbilical region? (demonstrate with your own hand)."], "do": ["Have patient hold their hand over the midline in umbilical region, put your hands on the patient’s sides, and tap with one side, check to the other side for feeling the impulse sent."], "normal": ["To not feel the impulse sent on the opposite. Pressing on Abdominal wall prevents vibrations from transmitting through adipose tissue, while underlying fluid can transmit the energy."], "report": ["The fluid wave test for ascites is negative."], "why": ["Ascites may be suspected when the patient presents with abdominal distension, fluid overload, and dullness to percussion in all areas. Positive fluid wave test moderately increases the likelihood of suspected ascites (LR+ 5.3, LR- 0.57). Further, confirmed ascites may represent liver disease, as ascites moderately increases the likelihood of suspected hepatocellular disease in patients with jaundice (LR+ 4.4, LR- 0.6), and of suspected cirrhosis in patients with liver disease (LR+ 7.2, LR- 0.69). Modification for Patients with Obesity: Use the fluid wave or shifting dullness tests to appreciate ascites, rather than inspecting for bulging flanks. Bulging flanks due to adipose tissue may be difficult to differentiate from ascites on inspection."], "imgs": ["abdo-89.webp"]}, {"sec": "Percussion", "name": "Shifting Dullness Test – Ascites", "phase": "percuss", "tags": ["conditional"], "pg": 155, "say": ["I will percuss for abdominal fluid using a shifting dullness test."], "do": ["With patient starting in supine position, tap from umbilicus laterally until you hear dullness. Ask patient to move into a decubitus position that raises that side of their body, wait a moment for the fluid to move, and see if it’s tympanic"], "normal": ["Dullness does not shift"], "report": ["Dullness does not shift with position change. The shifting dullness test for ascites is negative."], "why": ["Ascites may be suspected when the patient presents with abdominal distension, fluid overload, and dullness to percussion in all areas. Shifting dullness mildly increases the likelihood of suspected ascites (LR+ 2.1, LR- 0.40). Further, confirmed ascites may represent liver disease, as ascites moderately increases the likelihood of suspected liver disease in patients with jaundice (LR+ 4.4, LR- 0.6), and of suspected cirrhosis in patients with liver disease (LR+ 7.2, LR- 0.69). Modification for Patients with Obesity: Use the fluid wave or shifting dullness tests to appreciate ascites, rather than inspecting for bulging flanks. Bulging flanks due to adipose tissue may be difficult to differentiate from ascites on inspection."], "imgs": ["abdo-90.webp"]}, {"sec": "Percussion", "name": "Liver Excursion", "phase": "percuss", "tags": [], "pg": 155, "say": ["I will percuss for the liver span. Please breathe normally."], "do": ["Beginning at right Anterior superior iliac spine (ASIS) at MCL and percuss up 2 cm with each inspiratory rise of the abdomen. Note progression from tympanic → dull → resonant and landmark the two transition points. The distance between them is liver span assessed via percussion, also assessable at mid-sternal line."], "normal": ["At MCL, liver excursion measures 6-12cm on percussion (at midsternal line, normal 4-8cm)"], "report": ["At the right midclavicular line, liver excursion measures 8 cm on percussion; at midsternal line, the liver excursion measures 6 cm on percussion, which is normal."], "why": ["Can be used to investigate for hepatomegaly, however this finding does not significantly alter the likelihood. Confirmed hepatomegaly mildly increases the likelihood of suspected cirrhosis in patients with liver disease (LR+ 2.4, LR- 0.37)."], "imgs": []}, {"sec": "Percussion", "name": "Castell’s Sign-Spleen", "phase": "percuss", "tags": [], "pg": 156, "say": ["I will now be percussing the spleen in the left lower chest. Can you take a deep breath in? And now out?"], "do": ["Percussion of point defined by last intercostal space along the anterior axillary line during full inspiration, looking for shift to dullness. Percuss throughout respiratory cycle. The area should remain tympanic throughout the breath. Any dullness throughout the breath cycle may indicate splenomegaly."], "report": ["Castell’s sign yields tympanic sounds throughout."], "why": ["Can be used to investigate splenomegaly, or if you’re performing a lymph node exam (Ch 11 – Lymph Node Exam – MF2). Positive Castell’s sign mildly increases likelihood of splenomegaly (LR+ 1.7, LR-", "0.7). Castell’s sign is more sensitive and specific than Traube’s space (Sensitivity 82% and Specificity 83% for Castell’s sign, vs. Sensitivity 62% and Specificity 72% for Traube’s space)7. Confirmed splenomegaly mildly increases the likelihood of suspected cirrhosis in patients with known liver disease (LR+ 3.5, LR- 0.74)."], "imgs": ["abdo-91.webp"]}, {"sec": "Percussion", "name": "Traube’s Space – Spleen", "phase": "percuss", "tags": [], "pg": 156, "say": ["I will now be percussing the spleen over a wider area in the left lower chest."], "do": ["Percussion of the area defined by the sixth rib superiorly, the anterior axillary line laterally, and the left costal margin inferiorly (see diagram above). You are looking for dullness – can be done along a straight line following the Left last intercostal space anteriorly until reaching anterior axillary line. Report Traube’s space yields tympanic sounds throughout."], "why": ["Can be used to investigate splenomegaly, or if you’re performing a lymph node exam (Ch 11 – Lymph Node Exam – MF2). Dull Traube’s Space mildly increases likelihood of splenomegaly (LR+ 2.1, LR- 0.8). Castell’s sign is more sensitive and specific than Traube’s space (Sensitivity 82% and Specificity 83% for Castell’s sign, vs. Sensitivity 62% and Specificity 72% for Traube’s space)7. Confirmed splenomegaly mildly increases the likelihood of suspected cirrhosis in patients with known liver disease (LR+ 3.5, LR- 0.74)."], "imgs": []}, {"sec": "Palpation", "name": "Light Palpation", "phase": "palpate", "tags": [], "pg": 156, "say": ["I will now palpate the abdomen in 9 regions using light palpation Are you experiencing any pain right now? If so, I will palpate that area last."], "do": ["Using the palm standing at patient’s side, palpate the abdomen (should be good surface contact), and progress along in a systematic way. Should be good amount of pressure, it is palpated using the fingers. Assess for masses, tenderness, distension, and hardness/rigidity (involuntary guarding). While doing this, look at patients’ face for signs of pain."], "report": ["No evidence of guarding, facial discomfort, or masses on light palpation in 9 abdominal regions"], "why": ["Can identify tenderness, masses, hernias, and peritonitis. In patients with acute abdominal pain, the likelihood of suspected peritonitis increases slightly with rigidity (LR+ 3.9) and guarding (LR+ 2.6, LR- 0.6), and decreases significantly with positive abdominal wall tenderness test (LR+ 0.1). Further, the likelihood of suspected acute appendicitis increases moderately with RLQ pain (LR+ 7.3-8.5, LR- 0-0.28), and slightly with rigidity (LR+ 3.8, LR- 0.82) and guarding (LR+ 1.7-1.8, LR- 0-0.54). The likelihood of suspected acute cholecystitis may be slightly increased by RUQ tenderness (LR+ 1.6); however this finding is not statistically significant. Additionally, Courvoisier’s Sign states that a patient with painless jaundice and a RUQ mass/palpable gallbladder has a pancreatobiliary neoplasm until proven otherwise. A palpable gallbladder/RUQ mass (Courvoisier's Sign) greatly increases the likelihood of suspected obstructive bile ducts in patients with jaundice (LR+ 26, LR- 0.7), mildly increases the likelihood of suspected malignant obstruction in patients with obstructive jaundice (LR+ 2.6, LR- 0.7), and significantly decreases the likelihood of suspected hepatocellular disease in patients with jaundice (LR+ 0.04, LR- 1.4)."], "imgs": []}, {"sec": "Palpation", "name": "Deep Palpation", "phase": "palpate", "tags": [], "pg": 156, "say": ["I will now palpate the abdomen in 9 regions using deep palpation Are you experiencing any pain right now? If so, I will palpate that area last."], "do": ["Similar to Light General Palpation, proceeding in a systematic way with deeper pressure (visibly depressed into abdomen). Palpate for masses, tenderness, distension, and hardness/rigidity (involuntary guarding)."], "more": ["Note: May be able to palpate cecum in right iliac fossa if patient very thin."], "report": ["No evidence of tenderness, masses or organomegaly on deep palpation in 9 abdominal regions."], "why": ["Can identify tenderness, masses, hernias, and peritonitis. In patients with acute abdominal pain, the likelihood of suspected peritonitis increases slightly with rigidity (LR+ 3.9) and guarding (LR+ 2.6, LR- 0.6), and decreases significantly with positive abdominal wall tenderness test (LR+ 0.1). Further, the likelihood of suspected acute appendicitis increases moderately with RLQ pain (LR+ 7.3-8.5, LR- 0-0.28), and slightly with rigidity (LR+ 3.8, LR- 0.82) and guarding (LR+ 1.7-1.8, LR- 0-0.54). The likelihood of suspected acute cholecystitis is slightly increased by RUQ tenderness (LR+ 1.6); however this finding is not statistically significant."], "imgs": []}, {"sec": "Palpation", "name": "Rebound Tenderness", "phase": "palpate", "tags": ["conditional"], "pg": 157, "say": ["I will now assess for rebound tenderness in the area of the abdomen you felt tenderness on palpation earlier. Tell me if it hurts more when I press down with my hand, or when I remove it."], "do": ["Only assess for Rebound Tenderness in areas of tenderness identified. Using the tips of the fingers, press perpendicularly into the abdomen slowly. Hold this position until the patient’s tenderness appears to have calmed. Then quickly release your hand from the abdomen and assess for signs of pain in the patient’s face."], "report": ["Patient shows no rebound tenderness and does not appear peritonitic."], "why": ["The stretching and movement produced by rebounding can elicit pain when peritonitis is present. Rebound tenderness mildly increases likelihood of suspected peritonitis (LR+ 2.1, LR- 0.5). Positive rebound tenderness mildly increases likelihood of suspected appendicitis (LR+ 1.1-6.3, LR- 0-0.86 in adults; LR+ 3.0, LR- 0.28 in pediatrics). Further, diffuse peritonitis largely increases the likelihood of suspected appendicitis (LR+ 25, LR- 0.76 in pediatrics)."], "imgs": []}, {"sec": "Palpation", "name": "Shake Test", "phase": "palpate", "tags": ["conditional"], "pg": 157, "say": ["I will now shake the abdomen (or the exam table). Please let me know if this causes pain or discomfort."], "do": ["Grasp the patient’s hips, and gently shake the patient in order to shake the abdomen. Alternatively, using your hands or your knees, gently shake the patient’s exam table."], "report": ["Patient shows to pain on shake test and does not appear peritonitic."], "why": ["Pain on shaking the abdomen may be suggestive of peritonitis. Similarly, you can ask the patient if they had pain on the road while riding to the hospital, or if they have pain with coughing. Positive cough test mildly increases likelihood of suspected peritonitis (LR+ 1.8, LR- 0.4). Further, diffuse peritonitis greatly increases the likelihood of suspected appendicitis in pediatrics (LR+ 25, LR- 0.76)."], "imgs": []}, {"sec": "Palpation", "name": "Palpation of Liver Edge Gen. - Consistency - Tenderness - Pulsatility", "phase": "palpate", "tags": [], "pg": 157, "say": ["I will palpate for the lower liver edge. Please breathe normally and let me know if you feel any pain."], "do": ["Make an L shape with your right hand in patient’s Right Lower Quadrant along MCL and use hand to mimic the liver edge you’re palpating for. Move up 2 cm with each rise of the patients’ belly (to keep it consistent due to liver moving down with inspiration). Your hand’s orientation should be parallel with the rectus abdominus muscle. Check for pulsatility. Look at patient for signs of discomfort and stop the exam if the patient is in distress."], "report": ["(If you can feel liver) The liver is palpable less than 2 cm below the right costal margin along the MCL with rest inspiration. Liver edge is smooth and non-nodular, and non- tender to palpation."], "why": ["Palpation of the liver edge essentially confirms hepatomegaly (LR+ 233.7, LR- 0.5). The likelihood of suspected cirrhosis in patients with known liver disease is slightly increased by hepatomegaly (LR+ 2.4, LR-", "0.37) and by firm liver edge (LR+ 3.3, LR- 0.37).", "• Consistency: Nodularity is indicative of cirrhosis.", "• Tenderness: Indicative of inflammation.", "• Pulsatility: A specific finding of severe Tricuspid Regurgitation (TR)."], "imgs": ["abdo-92.webp"]}, {"sec": "Palpation", "name": "Splenic Palpation", "phase": "palpate", "tags": [], "pg": 157, "say": ["I will palpate for an enlarged spleen in the abdomen. Please take a deep breath each time there is pressure on the abdomen."], "do": ["Use a deep palpation technique, where the spleen should not be palpable. The spleen moves down on inspiration due to the displacement of the diaphragm, so time your deep palpation during inspiration. Use your findings on percussion (Castell’s Sign, Traube’s Space) to guide the starting point of palpation:", "• If Castell’s Sign/Traube’s Space yield tympanic sounds: Start palpation close to the left costal margin. You can pull the left side of the rib cage towards your right hand as you palpate for the spleen.", "• If Castell’s Sign/Traube’s Space yield dull sounds (increasing likelihood of splenomegaly): Start palpation in RLQ along right MCL, moving slowly towards LUQ through umbilicus."], "report": ["The spleen is non-palpable, including on inspiration."], "why": ["In cases of splenomegaly, the spleen will grow diagonally, so it is important to start at the RLQ and work towards the LUQ. A palpable spleen moderately increases the likelihood of suspected splenomegaly (LR+ 8.5, LR- 0.5). Additionally, splenomegaly mildly increases the likelihood of suspected hepatocellular disease in patients with jaundice (LR+ 2.9, LR- 0.7), and of suspected cirrhosis in patients with known liver disease (LR+ 3.5, LR- 0.74)."], "imgs": ["abdo-93.webp"]}, {"sec": "Palpation", "name": "Digital Rectal Exam (DRE) Inspect – Palpate", "phase": "palpate", "tags": [], "pg": 158, "do": ["In an OSCE: Always OFFER to do a DRE if abdominal exam is required (rule of thumb is every abdominal exam requires a DRE). You will likely not have to perform a DRE in the OSCE, as you would in clinical practice.", "Next, soft rounded pad of your finger should go through; stop for a moment at the anal verge then continue; make note of anal sphincter tone (re: Neurology, Upper motor neuron lesion vs. Lower motor neuron lesion differentiation – explored in Ch 31 – Neurology Exam – MF4). Rotate hand to feel all sides of walls, checking for any irregularity in thickness of the wall, hemorrhoids, abscesses, or fecal impaction. May also check for swelling or tenderness of rectovesical pouch in males or rectouterine pouch (Pouch of Douglas) in females. In male exam, may also check the prostate for size, swelling, tenderness, consistency symmetry, and nodularity (do not need to palpate prostate in DRE specifically, but may be combined as part of exam if indicated). There should not be a sensation for patient, except the urge to pass urine when palpating around the prostate in male exam. After completing exam, inspect the gloved finger for any blood or melena stool."], "say": ["Based on your findings on history and physical exam, a rectal exam is important to determine next best steps in your care. This is something we do with all our patients who come in with ___ (e.g. abdominal pain and blood in the stool) The exam should take under 5 minutes. How does that sound to you?"], "setup": ["Offer a chaperone (see Ch 4 – Vital Signs and Introduction to the Physical Exam – MF1). With patient providing informed consent, in a private exam room space, give the patient a gown and drape, and ask them to change with undergarments off after leaving the room. Let them know you will return in 5 minutes. Knock on door to ask for permission to re-enter room. Put gloves on and lubricate gloved finger (if stock, DROP from nozzle – avoid contamination of stock) with good lighting. The patient lies on their left side, both knees flexed towards the chest. Spread the buttocks, and inspect for external hemorrhoids, fissures, rectal prolapse, perianal abscesses, or anal fistula."], "report": ["There is no evidence of external or internal hemorrhoids, fissures, fistula, rectal prolapse, perianal abscesses, or inflammation on DRE, which is reassuring. (If prostate was palpated, report if enlarged, nodularity, firm or asymmetrical)."], "why": ["A DRE is distinct from Bimanual Exam or Male Genital Exam (Chapter 19 – Sensitive Pelvic Exams). It is a routine part of abdominal exam (hence “every abdominal exam requires a DRE”), though it is particularly important if patient complains of BRBPR (Hematochezia) or Melena. Melena stool on exam greatly increases the likelihood of suspected upper GI bleed (LR+ 25, LR-0.52). A DRE can also help with the assessment of internal and external hemorrhoids, which can be a cause of BRBPR. For patients with constipation refractory to laxatives, a DRE can be helpful to note rectal tone, masses, consistency of stool and stool impaction. A ↓ rectal tone can be helpful in assessment for spinal cord compression (explored in Ch 31 – Screening Neuro Exam – MF4)."], "imgs": []}, {"sec": "Palpation", "name": "McBurney’s Point (Appendicitis Special Test)", "phase": "palpate", "tags": [], "pg": 158, "say": ["I will palpate for signs of appendicitis."], "do": ["McBurney’s Point is 1/3rd the distance from the ASIS to the umbilicus on side of ASIS. Palpate at this point using deep palpation. While doing this, you look at patients’ face for signs of pain."], "report": ["No evidence of discomfort on palpation of McBurney’s Point"], "why": ["If present, would raise suspicion of inferior appendicitis. RLQ pain moderately increases the likelihood of acute appendicitis (LR+ 7.3-8.5, LR- 0-0.28 in adults; LR+ 1.3, LR- 0.45 in pediatrics)."], "imgs": ["abdo-94.webp"]}, {"sec": "Palpation", "name": "Rovsing’s Sign (Appendicitis Special Test) Peds", "phase": "palpate", "tags": ["peds"], "pg": 158, "say": ["I will palpate for signs of appendicitis."], "do": ["Palpate at the LLQ, and look at the patient’s face for signs of pain in RLQ"], "report": ["No evidence of tenderness in RLQ on LLQ deep palpation."], "why": ["If present, would raise suspicion of inferior appendicitis (LR+ 1.9, LR- 0.83 in pediatrics)."], "imgs": ["abdo-95.webp"]}, {"sec": "Palpation", "name": "Psoas’ Sign (Appendicitis Special Test) Peds", "phase": "palpate", "tags": ["peds"], "pg": 158, "say": ["I will palpate for signs of appendicitis. Please lie down on the exam table and relax the right leg. I will maneuver the right leg, so the right knee and hip are flexed. When you feel my hand pressing down on the right thigh, could you push against it? Did you feel any pain?"], "do": ["Patient in supine position, right leg relaxed and then manipulate so knee in approximately 90 degrees flexion. Press against thigh with resistance from patient. Look at patient’s face during the maneuver for signs of pain. Leave right leg in same position (to check for Obturator Sign)."], "report": ["No evidence of RLQ discomfort on flexion of hip against resistance."], "why": ["Named after the Psoas muscle. If present, would slightly raise suspicion of retrocecal appendicitis (LR+ 2.4, LR- 0.9)."], "imgs": ["abdo-96.webp"]}, {"sec": "Palpation", "name": "Obturator Sign (Appendicitis Special Test)", "phase": "palpate", "tags": [], "pg": 159, "say": ["I will continue to assess for appendicitis by rotating the right leg. Could you continue to keep the right leg relaxed? Let me know if you feel any pain as I rotate."], "do": ["Grasp patient’s right leg below knee and ankle, hip and knee both flexed at 90°. Internally rotate the hip. Look at patient’s face during the maneuver for signs of pain."], "report": ["No evidence of RLQ discomfort on right hip flexion and internal rotation."], "why": ["If present, would raise suspicion of pelvic appendicitis - Named after Obturator muscle"], "imgs": ["abdo-97.webp"]}, {"sec": "Palpation", "name": "Murphy’s Sign (Cholecystitis Special Test) MurphyCourvoisier", "phase": "palpate", "tags": [], "pg": 159, "say": ["I will now palpate for the gallbladder. Please take a deep breath in."], "do": ["As patient begins deep inspiration, hook right hand under right costal margin at MCL. Look at patient to assess whether inspiration has been arrested."], "report": ["On palpating underneath the right costal margin during deep inspiration, the gallbladder is non-palpable with no signs of acute pain or arrested inspiration. Murphy’s sign is negative."], "why": ["A positive Murphy’s sign is 87% specific for acute cholecystitis. The likelihood of acute cholecystitis may be slightly increased by positive Murphy’s Sign (LR+ 2.8, LR- 0.5) and by general RUQ pain (LR+ 1.5, LR- 0.7) and tenderness (LR+ 1.6). However, none of these likelihood ratios were statistically significant, limiting their utility."], "more": ["Note: Sonographic Murphy’s Sign may be completed during ultrasound when assessing for cholecystitis.", "Note: Courvoisier’s Law – A palpable non-tender gallbladder with mild jaundice is cancer of the gallbladder or pancreas until proven otherwise. A palpable gallbladder is also specific for obstructive bile ducts in patients with jaundice (LR+ 26.0, LR- 0.70)"], "imgs": ["abdo-98.webp"]}]}, "headneck": {"title": "Head & neck", "pg": [71, 89], "notes": ["• Based on Chief Complaint: e.g. if a patient endorses hearing loss, you should examine their hearing (e.g. Weber’s, Rinne test)", "• Note: The Lymph Node exam (Chapter 11 – MF2) and Thyroid exam (Chapter 15 – MF3) are typically included in the Head & Neck Examination, and are deferred in MF1. The ophthalmic exam (Chapter 40 – IF) is explored in Integration foundation."], "steps": [{"sec": "Vitals", "name": "Vitals", "phase": "vitals", "tags": [], "pg": 78, "do": ["• Fever could be indicative of an infection or a constitutional symptom Maneuver Say & Setup; Do; Report"], "imgs": []}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Head", "phase": "inspect", "tags": [], "pg": 78, "say": ["I will inspect the head for signs of trauma, masses, lesions or scars."], "do": ["Check scalp for signs of trauma (Battle sign or mastoid ecchymosis; Racoon eyes or periorbital ecchymosis)."], "report": ["I note no visible signs of trauma or lesions."], "why": ["External signs of a traumatic brain injury and basilar skull fracture (Assessment of Traumatic brain injury and concussion explored in Ch 31 – Screening Neuro Exam – MF4)"], "imgs": ["headneck-26.webp"]}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Eyes", "phase": "inspect", "tags": [], "pg": 78, "say": ["Can you open one eye and pull the lower eyelid down? Now the other side?"], "do": ["Check for scleral icterus (jaundice), conjunctivitis (increased vascular markings), discharge (differentiate watery from mucopurulent), or conjunctival pallor (anemia). Look for infraorbital edema/ darkening (“allergic shiners”)"], "report": ["No scleral icterus, conjunctivitis, discharge or conjunctival pallor noted. Bacterial Allergic Infraorbital Conjunctivitis17 Conjunctivitis18 edema/darkening19"], "why": ["Scleral icterus is a possible sign of liver disease. Conjunctival pallor is a sign of anemia. Acute conjunctivitis can represent:", "• Viral conjunctivitis: Classically appears as a pink or red colour, with minimal-to-no itching and watery discharge, which usually begins unilateral but may progress to bilateral. Ask about sick contacts, where contact with another person with red-eye mildly increases the likelihood of viral conjunctivitis (LR+ 2.5, LR- 0.89). Ask if eyelids are stuck together on awakening which mildly decreases the likelihood of viral conjunctivitis (LR+ 0.72, LR- 3.5). On exam, look for mucopurulent ocular discharge (LR+ 0.47, LR- 2.7) which moderately decreases the likelihood of viral conjunctivitis. Also look for pharyngitis (LR+ 5.4-9.9, LR- 0.48-0.48) and preauricular lymphadenopathy (LR+ 2.5-5.6, LR- 0.73-0.89) which moderately increase the likelihood of viral conjunctivitis.", "• Bacterial conjunctivitis: Classically appears as a pink or red colour, with minimal-to-no itching and mucopurulent discharge which is usually unilateral. Ask about sick contacts, where contact with another person with red-eye moderately reduces the likelihood of bacterial conjunctivitis (LR+ 0.40). Ask if eyelids are stuck together on awakening (LR+ 1.4, LR- 0.29) which mildly increases the likelihood of bacterial conjunctivitis. On exam, assess for ocular discharge, where watery discharge greatly reduces the likelihood of bacterial conjunctivitis (LR+ 0.03), as well as mucopurulent discharge (LR+ 2.1, LR- 0.37) and otitis media (LR+ 2.5, LR -0.84) which mildly increase the likelihood of bacterial conjunctivitis. look for pharyngitis (LR+ 0.10-0.19, LR- 2.1-2.14) and preauricular lymphadenopathy (LR+ 0.18-0.40, LR- 1.1-", "1.4) which moderately decrease the likelihood of bacterial conjunctivitis.", "• Allergic conjunctivitis: Pink; Prominent itching; Watery discharge; bilateral. In allergic rhinitis, can also see infraorbital edema/darkening due to subcutaneous venodilation re. “allergic shiners”."], "imgs": ["headneck-27.webp", "headneck-28.webp", "headneck-29.webp", "headneck-30.webp", "headneck-31.webp", "headneck-32.webp"]}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Nose – General Inspection", "phase": "inspect", "tags": [], "pg": 79, "say": ["I will inspect the nose."], "do": ["Look for epistaxis (nose bleeds), rhinorrhea (runny nose), and a transverse nasal crease (“allergic salute”). Using anterior rhinoscopy (with otoscope, or nasal speculum with headlight), look at the septum and nares for symmetry or deviations. Look at the nasal mucosa – is it hyperemic (inflamed), bluish/pale, congested or dry? Look for discharge – is it clear or mucopurulent? Look for any nasal polyps and/or masses (rare) – but do NOT confuse with the turbinates which are normal anatomy."], "report": ["I note no swelling, trauma, or deviation of the nares, which show good symmetry."], "why": ["Assessing for conditions listed above. Specific diseases include:", "• Chronic rhinosinusitis (CRS) requires evidence of mucosal inflammation (e.g. hyperemic nasal mucosa, mucopurulent discharge, polyposis) in addition to the 4 cardinal symptoms of CRS – Nasal obstruction/blockage/congestion; Anterior and/or posterior nasal mucopurulent discharge; Facial pain/pressure/fullness; and Reduction or loss of smell (hyposmia or anosmia).", "• In allergic rhinitis, look for a transverse nasal crease (“allergic salute”) which occurs due to patient’s repeated rubbing of the tip of the nose with their hand, in addition to clear rhinorrhea and bluish/pale swelling of nasal mucosa.", "• Note that clear rhinorrhea (nasal discharge) and clear otorrhea (ear discharge) in the setting of a traumatic brain injury raise concern for a basilar skull fracture (Assessment of Traumatic brain injury and concussion explored in Ch 31 – Screening Neuro Exam – MF4)"], "imgs": []}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Nose – Palpation", "phase": "palpate", "tags": [], "pg": 79, "say": ["I will now palpate the nasal bones. Please tell me if you are in discomfort."], "do": ["As you palpate, assess for step deformities and pain. Stop the exam if the patient is in distress."], "report": ["I note no signs of nasal fracture or pain evident on palpation of nasal bones."], "why": ["Assessing for step deformities and pain in nasal fracture / trauma to face"], "imgs": []}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Mouth – Inspection", "phase": "inspect", "tags": [], "pg": 79, "say": ["I will now inspect the mouth; can you open the mouth wide?"], "setup": ["Have both a light source and a tongue depressor available"], "do": ["Inspect outer lips for symmetry, colour, moisture, ulcers, cracking, scaling and masses. Have the patient open mouth and shine a light to inspect for colour, ulcers, white patches and nodules. Look for signs of inflammation on gums, and abnormalities of teeth (e.g. dental infections such as carries). Look at the surface of tongue – should be symmetrical, rough with papillae, and possibly covered with white coating, or clear. Look for white plaques that can scrape off on the tongue (thrush). Look at the hard palate, under-surface of tongue and floor of mouth for nodules, ulcers, or white, erythematous or cyanotic areas."], "report": ["I note no abnormalities to the outer lips, gums, or teeth. I note no oral ulcers, nodules, or erythematous areas. Aphthous Ulcer22 Dental Carries23"], "why": ["Important to detect thrush (common in patients who are immunosuppressed, including e.g. on glucocorticoid medications); cysts, calculi in sub-mandibular ducts; and oral cancers (e.g. of tongue). Note that dental infections are a common cause of secondary otalgia (ear pain originating outside the ear). Trismus (inability to open the jaw), drooling and pooling of saliva in the mouth raises concern for deep neck space infection and upper airway obstruction (Emergency)."], "imgs": ["headneck-33.webp", "headneck-34.webp", "headneck-35.webp", "headneck-36.webp"]}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Oropharynx – Inspection", "phase": "inspect", "tags": [], "pg": 79, "say": ["I will now inspect the at Normal Inspection24 Strep Pharyngitis25 Peritonsillar Abscess26 the back of the throat for the palate, tonsils and uvula. Can you say “Aaaah”?"], "setup": ["Have both a light source and a tongue depressor available"], "do": ["Look at soft palate and uvula for redness and swelling. When patient says “Aaaah”, the soft palate should rise symmetrically, and the uvula should remain in midline. You may need to use your tongue depressor to visualize the soft palate adequately. This is easier to see with the patient keeping their tongue in their mouth while saying ahh. Assess tonsils for evidence of hyperplasia, inflammation, or exudates."], "report": ["Uvula is midline on palate elevation. Tonsils are a Grade 0 with no focal inflammation or exudates.", "• You can report your tonsil findings based on the Tonsillar Hypertrophy Grading Scale (Grade 0: Tonsils absent/atrophied; Grade 1: Tonsils 0-25% of oropharyngeal diameter; Grade 2: 25-50% of oropharyngeal diameter; Grade 3: 50-75% of oropharyngeal diameter; Grade 4: 75-100% of oropharyngeal diameter)"], "imgs": ["headneck-37.webp", "headneck-38.webp", "headneck-39.webp"]}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Mallampati Score", "phase": null, "tags": ["conditional"], "pg": 80, "say": ["I will inspect the mouth to look at airway structures. Can you briefly open the moth and stick the tongue out?"], "do": ["Inspect the patient’s oropharynx structures for the soft palate, uvula, fauces, and pillars. Scoring: see image. Mallampati 1 = soft palate, uvula, pillars completely visible. Mallampati 2 = soft palate and part of uvula visible. Mallampati 3 = only soft palate and base of uvula visible. Mallampati 4 = soft palate not visible."], "report": ["I can visualize all of the soft palate, uvula and pillars. The Mallampati Score is 1."], "why": ["Part of the airway assessment in the pre-op anesthesia exam. Useful in collaboration with other tests to assess the difficulty of intubation by direct laryngoscopy. Can help classify a patient’s airway as easy (Mallampati Class I or II) or a difficult (Mallampati Class III or IV) intubation and helps direct the anesthesia pre-op planning process. Risk factors of a difficult airway can be assessed by as LEMON: Look (e.g. C-spine immobilization, trauma, facial swelling, teeth); Evaluate (3-3-2 rule: 3 fingerbreadths of mouth opening, 3 fingerbreadths of hyomental distance, 2 fingerbreadths of thyromental distance); Mallampati score; Obstruction/obesity; Neck mobility (C-spine ROM). A Mallampati Score of 3 or 4 is also significant in assessing patients for Obstructive Sleep Apnea."], "imgs": ["headneck-40.webp"]}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Neck (then lymph node & thyroid exams)", "phase": "inspect", "tags": [], "pg": 80, "say": ["I will now inspect the neck."], "do": ["Look for swelling or scars, masses or lesions; goiter; or muscular hypertrophy. Palpate the Temporomandibular Joint (TMJ) and ask the patient to open and close their mouth repeatedly, checking for tenderness and instability. Also, ask the patient to swallow in good lighting."], "report": ["I note no neck swelling scars, masses, or lesions."], "why": ["• Goiter – thyroid condition (non-specific re hypo/eu/hyperthyroid); good for swallow assessment.", "• Muscular Hypertrophy – chronic problems with breathing re. work of breathing.", "• Jaw Claudication – pain on chewing is a diagnostic clue to Temporal Arteritis (Giant Cell Arteritis), classically presenting with new onset headache in patient of age >50 years old.", "• TMJ Tenderness – important to detect mechanical disease of the jaw or TMJ pathology, which can be an important cause of secondary otalgia (ear pain) Maneuver Say & Setup; Do; Report"], "imgs": []}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Outer Ear Inspection", "phase": "inspect", "tags": [], "pg": 80, "say": ["I will now inspect the ears."], "setup": ["Stand lateral to patient."], "do": ["Examine external auditory canal and auricle. Look for vesicles (small <1cm fluid filled lesions)"], "report": ["I note normal external auditory canal (some hair, ± yellow/brown cerumen i.e. earwax = cerumen); the auricle shows no signs of scars, inflammation, or deformity."], "why": ["Looking for gross damage to external ear. Inflammation of the canal (edema, erythema) may point to otitis externa, along with otorrhea (drainage – in otitis externa, otorrhea often occurs with otalgia; whereas in otitis media, otalgia often precedes otorrhea which can occur in perforated otitis media). In a patient with history of recent trauma, a temporal bone fracture (emergency) may present with lacerations or bruising around the ear. Vesicles in the ear canal or external ear may indicate Herpes zoster oticus (Ramsay Hunt syndrome – otalgia can be present before lesions develop)."], "imgs": ["headneck-41.webp"]}, {"sec": "Inspection & palpation (head → neck → ears)", "name": "Outer Ear Palpation", "phase": "palpate", "tags": [], "pg": 81, "say": ["I will palpate the pinna and peri-auricular area of each ear. Please tell me if you are in discomfort."], "do": ["Assess for tenderness, nodules, or inflammation on palpation; push tragus (small eminence of external ear anterior to the concha); palpate mastoid bone (immediately behind ear re structures draining ear). Look for erythema, edema & pain vs. mastoid tip tenderness. Stop the exam if the patient is in distress."], "report": ["I note no pain induced on pushing of tragus or palpation of mastoid bone."], "why": ["Looking for signs of mastoiditis (e.g. a middle ear infection that spread – pain, edema & erythema on palpation of mastoid bone. Tenderness while pushing down on the tragus is suggestive of otitis externa."], "imgs": ["headneck-42.webp"]}, {"sec": "Otoscopy & hearing", "name": "Middle Ear Otoscopy", "phase": null, "tags": ["peds"], "pg": 81, "say": ["I will use an otoscope to look at the eardrums in each ear (tympanic membranes)."], "do": ["Standing laterally, pull the auricle (superior cartilaginous prominence) up and back in an adult, or down/ down and back in kids. Slowly guide the otoscope into the ear canal, until you can see the tympanic membrane.", "• Pneumatic Insufflation: With a pneumatic otoscope (if available), a gentle application of positive then negative pressure will cause the normal tympanic membrane to move inwards and then outwards. When the middle ear is filled with fluid (as in acute otitis media or otitis media with effusion), the tympanic membrane will be poorly mobile."], "report": ["I have identified the drum’s colour (red, white, yellow); translucency (transparent, opaque); position (retracted, neutral or bulging); and cerumen (wax). I note no signs of inflammation or effusion (with air-fluid level along the tympanic membrane) or perforation. The tympanic membrane is mobile with pneumatic insufflation."], "why": ["Can assess for signs of otitis media (middle ear inflammation), tympanic membrane (TM) perforation, middle ear effusion (MEE), or ↑ inner ear pressure. Note that in otitis externa, the tympanic membrane may be only partially visible due to ear canal edema.", "• Acute Otitis Media (AOM): Acute onset of symptoms (e.g. otalgia) with a purulent middle ear effusion (MEE) and significant middle ear inflammation. In children, TM findings increasing likelihood of AOM include bulging (LR+ 51), cloudy (LR+ 34) or distinctly red (LR+ 8.4), and distinctly impaired mobility (LR+ 31).", "• Otitis Media with Effusion (OME): Presence of MEE without signs acute middle ear inflammation.", "• A cholesteatoma may present and appears as epithelial debris behind the tympanic membrane.", "• A glomus tumor may present with a bulging erythematous mass behind the tympanic membrane, accompanied by unilateral pulsatile tinnitus.", "• In a patient with history of traumatic brain injury, a basilar skull fracture may present with pooling of blood behind the tympanic membrane called hemotympanum (Assessment of Traumatic brain injury and concussion explored in Ch 31 – Screening Neuro Exam – MF4)"], "imgs": []}, {"sec": "Otoscopy & hearing", "name": "Hearing Loss Screening Test: Whispered Voice Test", "phase": null, "tags": [], "pg": 81, "say": ["I will now assess hearing. I will stand behind you, cover one of the ears with one finger, then whisper a combination of 3 numbers and letters. Please repeat back the 3 numbers or letters you hear."], "setup": ["• With patient seated, stand arm’s length (2 feet) behind the patient (to prevent lip reading).", "• Mask the hearing in one ear using your finger to gently occlude and rub the external auditory canal.", "• A trial run using a loud voice to ensure the patient understands the instructions may be helpful."], "do": ["• Examiner takes in a full breath, exhales, then whispers 3 random numbers and letters (e.g. “5, B, 6”).", "• Ask the patient to repeat the 3 numbers and letters. If the patient repeats all 3 numbers and letters correctly, this is a normal result.", "• If the patient responds incorrectly, repeat the test using a new combination of numbers and letters (e.g. “D, 1, C”). The screening test is normal if the patient repeats 3 out of 6 total letters/numbers correctly.", "• Repeat with the other ear, using new combination of numbers and letters."], "report": ["You repeated 3 out of 6 letters correctly with each ear. This is a normal whispered voice screening test for hearing loss."], "why": ["The whispered voice test is a helpful initial screening test for hearing loss, with an alternative screening test being the Finger Rub Test (below). The likelihood of hearing loss is moderately increased by an abnormal whispered voice test (LR+ 6.0) and greatly decreased by a normal whispered voice test (LR- 0.03). This test cannot differentiate sensorineural from conductive hearing loss, where Weber and Rinne testing (see below) can help delineate conductive, sensorineural and mixed hearing loss. An abnormal screening test should be referred for formal audiology assessment."], "imgs": []}, {"sec": "Otoscopy & hearing", "name": "Hearing Loss Screening Test Alternative: Finger Rub Test", "phase": null, "tags": [], "pg": 82, "say": ["I will now assess hearing. I will stand behind you and rub my fingers together close to one of your ears with your eyes closed and arms at the sides. Please raise your hand on the side you hear the fingers rubbing."], "do": ["Standing in front of the patient, once their eyes are closed, bring your arms close to each side of the patient’s ears, ensuring there is no contact with the patient’s outer ear or hair. On each side in a random order, rub your thumb against your index finger while progressing to the middle finger and then back to the index finger three times. Test this with a strong rub (as loud as you can muster); as well as a faint rub (the softest you can hear as the clinician). Monitor for the patient raising their hand to the side they hear the finger rub. Randomize the order of these 4 maneuvers (e.g. left ear, right ear, right ear, left ear)."], "report": ["The patient heard both a strong and faint rub in bilateral ears. This is a normal finger rub screening test for hearing loss."], "why": ["The finger rub test is a helpful initial screening test for hearing loss, with an alternative screening test being the Whispered Voice Test (above). The test can also be performed by standing in front of the patient. The likelihood of hearing loss is greatly increased by being unable to hear a strong finger rub (LR+", "355.4)28. Being able to hear a faint finger rub greatly decreases the likelihood of hearing loss (LR- 0.02)28. Note that ambient noise can impact the performance of this test, where a study demonstrated that being unable to hear a strong finger rub in a quiet environment greatly increases the likelihood of hearing loss (LR+ 16.73), while the same result in a noisy environment moderately increases the likelihood of hearing loss (LR+ 6.76)29. This test cannot differentiate sensorineural from conductive hearing loss, where Weber and Rinne testing (see below) can help delineate conductive, sensorineural and mixed hearing loss. An abnormal screening test should be referred for formal audiology assessment."], "imgs": []}, {"sec": "Otoscopy & hearing", "name": "Hearing Loss Assessment: Weber’s & Rinne’s Test", "phase": null, "tags": [], "pg": 82, "do": ["Part 1: Weber’s:", "Ask where the sound is heard – left ear, right ear, or in the middle. For example, if the sound is heard louder in the right ear, then it is described as “Weber lateralizes to right ear”. Part 2: Rinne’s Test:", "Ask the patient if the sound is louder at the back or front. Sound is heard louder at the front = air conduction better than bone conduction (AC > BC). This can be normal but can also be present in sensorineural hearing loss.", "• Sound is heard louder at the back = bone conduction better than air conduction (BC > AC). This is abnormal and suggests conductive hearing loss. Repeat for opposite ear."], "say": ["I will now use tuning forks to assess hearing."], "setup": ["Place vibrating 512 Hz tuning fork on the midline of the patient’s head.", "Place vibrating 512 Hz tuning fork against patient’s mastoid bone. Then move it to just in front of the tragus."], "report": ["Based on table below – can determine nature of the hearing loss as Conductive or Sensorineural:", "Weber Result Rinne Result Sensorineural Hearing Loss Lateralizes to opposite affected ear AC > BC Conductive Hearing loss Lateralizes towards affected ear BC > AC Weber Result Rinne Result Sensorineural Hearing Loss Lateralizes to opposite affected ear AC > BC Conductive Hearing loss Lateralizes towards affected ear BC > AC"], "why": ["The Weber and Rinne tests help assess for conductive hearing loss (CHL), sensorineural hearing loss (SNHL) or mixed hearing loss.", "• Sensorineural hearing loss (SNHL) affect conversion of mechanical sound to neuroelectric signals in inner ear or auditory nerve. The most common causes are presbycusis (age-related hearing loss – slowly progressive and symmetrical) and noise-induced – both with gradual onset. The exam of the tympanic membrane is often normal. Other causes include:"], "imgs": ["headneck-43.webp", "headneck-44.webp"]}, {"sec": "Closer look: eyes & fundoscopy", "name": "Closer Assessment of Eyes", "phase": null, "tags": [], "pg": 83, "say": ["I will now inspect the eyes more closely. Can you Ptosis30 Exophthalmos31 look straight ahead?"], "setup": ["Have a flashlight and direct ophthalmoscope present, facing patient. Have lights dimmed. If available, a Snellen Pocket Card is helpful."], "do": ["• Look at eyelids for a drooping eyelid → Ptosis.", "• Look at the margins of the iris: If you see white sclera under the bottom iris margin (± top margin too) → Exophthalmos.", "• Using a flashlight and standing in front of patient, have patient look straight ahead. Inspect pupil size (Snellen Pocket Card tends to have a guide). ≤1 mm difference between two eyes is normal.", "• Using a flashlight, shine light in one eye. Look for pupillary constriction both direct and consensual (part of the Pupillary Light Reflex). Repeat in the other eye. Then, swing the flashlight back and forth between both eyes. Each pupil should constrict (i.e. no relative afferent pupillary defect)."], "report": ["Pupils are equal and reactive to light, and there is no relative afferent pupillary defect."], "why": ["• Ptosis: Cranial Nerve injury or sympathetic nerve injury (Horner Syndrome –Ophtho Exam – Ch 40 – Integration Foundation)", "• Exophthalmos: Sign of Thyroid disease (Ch 15 – Thyroid Exam – MF3)", "• Pupillary Light Reflex Lost: Optic nerve or Oculomotor nerve lesion (Ch 31 – Screening Neuro Exam – MF4)", "• Positive relative afferent pupillary defect (RAPD): Dilation of one pupil during swinging flashlight test suggests a Retina or Optic nerve injury."], "imgs": ["headneck-45.webp", "headneck-46.webp"]}, {"sec": "Closer look: eyes & fundoscopy", "name": "Direct Fundoscopy", "phase": null, "tags": [], "pg": 83, "say": ["I will now inspect each eye using a direct ophthalmoscope. You will feel my hand touch the shoulder to keep the ophthalmoscope steady. Please look at an object on the wall in the distance at your eye level (preventing constriction due to pupillary accommodation reflex)"], "setup": ["Room should still be dim. Stand facing the patient; if you’re examining the patient’s right eye first, use your right eye to look (vice versa). Adjust the scope’s focus (if you’re not wearing your nearsighted prescription glasses, may take more adjusting) by focusing on an object in room. Use low-moderate light intensity typically with medium aperture."], "do": ["Steady your hand on their shoulder. Shine the light from ophthalmoscope in patient’s eye; should see the red reflex. Follow reflex and slowly move toward patient. Find an artery and follow that towards the centre. You should come upon the optic disc (head of optic nerve, a confluence of retinal nerve fibers exiting the globe) and the optic cup (white centre of optic disc). Look for signs of optic disc swelling, and loss of venous pulsations. Follow the Superonasal Arcade, Inferonasal Arcade, Superotemporal Arcade, and Inferotemporal Arcade. Focus on Macula (temporal to optic disc), which contains Fovea where you can see a Yellow Reflex in healthy people. Look for signs of hemorrhages, neovascularization (small branching vessels) and cotton wool spots (fluffy white patches)."], "report": ["The optic disc was visualized in each eye, with no signs of optic disc swelling, neovascularization or loss of venous pulsations."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Sinus Transillumination", "phase": null, "tags": ["conditional", "extra"], "pg": 84, "say": ["I will examine the sinuses using a light source. Please remove any dentures. Please keep the neck slightly extended back and mouth open during the assessment."], "setup": ["Examination must be conducted in completely darkened room with patient’s dentures removed. Ideal test requires use of a transilluminator (a focused light source); otoscope may also be used."], "do": ["Begin with the maxillary sinus: angle light toward mouth – a normal transillumination is dim glow on hard palate. Progress to the frontal sinus: light source below eyebrow, angling light superomedially – a normal transillumination is dim glow over frontal area."], "report": ["I note normal bilateral transillumination of frontal and maxillary sinuses."], "why": ["Abnormal transillumination mildly increases the likelihood of sinusitis (LR+ 1.6) while normal sinus transillumination moderately decreases the likelihood of sinusitis (LR- 0.5). Note frontal sinuses may have non-pathologic unequal transillumination – may develop asymmetrically. This is not recommended as part of routine physical exam by otolaryngologists. Pediatrics – Sinus Development: Ethmoid Sinuses present & pneumatized at birth; Maxillary Sinuses present at birth, pneumatized age 4; Sphenoid Sinuses present by Age 5; Frontal Sinuses begin development age 7, fully developed in adolescence (age 14-18). Sinus drainage occurs through narrow ostia (1-3mm) into middle meatus in ostiomeatal complex (OMC). The sphenoid sinus drains into the roof of the nose."], "imgs": ["headneck-47.webp", "headneck-48.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Hearing Loss Assessment Alternative: Hum Test", "phase": null, "tags": ["extra"], "pg": 84, "say": ["I will assess your hearing. Please hum an “eee” or “hmm” sound at a consistent pitch for a few seconds. It can be helpful to repeat the test with both high- and low-pitch hums. Please tell us which ear is loudest."], "do": ["Ask patient to hum an “eee” or “hmm” sound at a consistent pitch for a few seconds as noted above, with potential variation of the pitch over multiple trials. Ask the patient which ear hears the hum the loudest."], "report": ["The patient reports hearing loss in their left ear, and the Hum test lateralizes to the left ear, consistent with conductive hearing loss."], "why": ["For patients with hearing loss, the Hum test is a simple alternative to the Weber’s test which doesn’t require a tuning fork. Interpretation is the same as the Weber’s test: if the sound lateralizes to the affected ear, this suggests conductive loss. If it lateralizes to the unaffected ear, this suggests sensorineural hearing loss. The Hum test can be helpful in Telemedicine and triaging patients needing urgent assessment for Sudden Sensorineural Hearing Loss (SSNHL)30 where tuning forks are unavailable at initial intake. Pearl: You can test the hum test on yourself: use your finger to plug and unplug your ear (conductive hearing loss) while making a hum, and see which side the sound lateralizes to."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "HINTS Exam", "phase": null, "tags": ["conditional", "extra"], "pg": 84, "do": ["• When to do the HINTS+ Exam? The HINTS+ exam is only indicated with acute onset, continuous dizziness, imbalance, and nystagmus lasting hours to days (Acute Vestibular Syndrome = AVS). Patients must have ongoing nystagmus at rest (involuntary repetitive jerking eye movements) to be eligible for the HINTS exam. Patients presenting with the acute vestibular syndrome could be having a peripheral (nerve) problem (acute vestibular neuritis) or a central (brain) problem (stroke or other acute brain lesion). The HINTS exam is a battery of 3 bedside tests which accurately differentiate peripheral versus central causes of the acute vestibular syndrome – but it is only validated in patients with ongoing, continuous acute dizziness and nystagmus. If the patient does not have continuous nystagmus, the HINTS exam is NOT indicated. Make sure you do a history and physical to exclude any RED FLAGS for stroke (explored in Chapter 7 – Head and Neck Exam) prior to doing the HINTS+ exam."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Dix-Hallpike Test", "phase": null, "tags": ["conditional", "extra"], "pg": 85, "do": ["Provocative Testing for Diagnosing BPPV Benign Positional Paroxysmal Vertigo (BPPV) is caused by loose debris (otoconia) within one of the semi- circular canals of the vestibular apparatus. Each ear has 1 vestibular apparatus and each vestibular apparatus has 3 semi-circular canals. The most common location for otoconia in BPPV is the posterior canal (~65%), followed by the horizontal canal (~30%), while the anterior canal is relatively rare. Movement of loose otoconia within a semicircular canal will reliably produce vertigo with a different type of nystagmus depending on which canal is affected. Therefore, we use provocative testing in BPPV to watch for which type of nystagmus and LOCALIZE which ear and canal the otoconia are in. Once we have localized the otoconia, we can then use the appropriate particle repositioning maneuver to correct the problem and cure our patients. Provocative tests for BPPV are indicated only if you suspect a diagnosis of BPPV based on a history of brief, (less than one minute), intense attacks of dizziness that are always triggered by head movements (most commonly lying down or turning over in bed). A patient who has continuous dizziness present at rest lasting hours to days should never get provocative tests for BPPV. You should also ensure that the patient does not have any red flags for a serious central cause of dizziness, and that there is not another cause (such as postural hypotension or vestibular migraine or Meniere’s disease) that better explains their symptoms, prior to provocative tests. Since the most common type of BPPV is posterior canal (~65%), this is the first canal which we test in a patient with suspected BPPV. Posterior canal BPPV is identified using the Dix-Hallpike Test."], "say": ["I will move you from a sitting to lying down position on the exam table and move the neck to the side and back. Please tell me if these movements reproduce your symptoms of vertigo."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Supine Roll", "phase": null, "tags": ["conditional", "extra"], "pg": 86, "do": ["Since the second most common type of BPPV is horizontal canal (~30%), this is the second canal which we test in a patient with suspected BPPV. Horizontal canal BPPV is identified using the Supine Roll test.", "Have patient lie supine on an exam bed. Turn their head to one side and examine their eyes for nystagmus. Then turn their head to the other side and examine for nystagmus. If they have horizontal canal BPPV, you will see horizontal nystagmus on both head turns which is either towards the ground (geotropic) or away from the ground (apogeotropic)."], "say": ["I will reposition you to look to one side and then the other side while lying flat on your back."], "report": ["There is no horizontal nystagmus on supine roll test, therefore it is unlikely the patient has horizontal canal BPPV."], "why": ["Used to localize the affected ear in patients with Horizontal Canal Benign Paroxysmal Positional Vertigo (BPPV). On the side that has the more intense nystagmus, the nystagmus will beat towards the affected ear. When you have identified which ear is affected and whether it is geotropic or apogeotropic, you can proceed with an appropriate particle repositioning maneuver (Gufoni or Barbecue roll) for the affected side."], "imgs": []}]}, "lymph": {"title": "Lymph nodes", "pg": [118, 123], "notes": ["• Patient Draping: Start by exposing neck from chin down to manubrium and clavicles for neck lymph nodes; in stepwise fashion, then expose axilla, upper limbs, pelvis, and lower limbs, re-draping after each step completed."], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 119, "do": ["Looking for vitals characteristic of an acute infection (e.g. fever), disseminated infection (e.g. sepsis, fever, hypotension, tachycardia), or oncologic emergencies (e.g. arrhythmias, hypotension, tachypnea)."], "imgs": []}, {"sec": "Inspection", "name": "General", "phase": "inspect", "tags": [], "pg": 119, "say": ["I will begin with general inspection. As I assess for lymph nodes, I will also assess for masses, bruises, etc."], "do": ["Look at the patient and assess whether they are in acute distress or diaphoretic (heavy perspiration or sweating). With each area you examine, look for bruises, obvious masses, edema, asymmetry, color changes, obvious lymphadenopathy, surgical scars, erythema, rashes, etc."], "report": ["I note no signs of acute distress. There are no bruises, obvious masses or lymphadenopathy, surgical scars, erythema or rashes on inspection."], "why": ["General inspection routinely done; also, looking to get a clinical picture whether patient is currently well or unwell."], "imgs": []}, {"sec": "Inspection", "name": "Tonsils – for complete Mouth inspection, please see Chapter 7 – Head & Neck Exam – MF1", "phase": "inspect", "tags": [], "pg": 120, "say": ["I will now inspect at the back of the throat for the Normal Inspection5 Strep Pharyngitis6 tonsils. Can you say “Aaaah”?"], "setup": ["Have both a light source and a tongue depressor available"], "do": ["Look at hard palate for colour and form; soft palate and uvula for redness and swelling. When patient says “Aaaah”, the soft palate should rise symmetrically, and the uvula should remain in midline. You may need to use your tongue depressor to visualize the soft palate adequately. Assess tonsils for evidence of hyperplasia, inflammation, or exudates."], "report": ["Uvula is midline on palate elevation. Tonsils are a Grade 0 with no focal inflammation or exudates.", "• You can report your tonsil findings based on the Tonsillar Hypertrophy Grading Scale (Grade 0: Tonsils absent/atrophied; Grade 1: Tonsils 0-25% of oropharyngeal diameter; Grade 2: 25-50% of oropharyngeal diameter; Grade 3: 50-75% of oropharyngeal diameter; Grade 4: 75-100% of oropharyngeal diameter) Normal Inspection5 Strep Pharyngitis6"], "why": ["Important in assessment of Acute Infectious Pharyngitis (e.g. Strep Pharyngitis vs. Viral Pharyngitis – in photo of Strep Pharyngitis above, note tonsillar exudate seen bilaterally – part of CENTOR score). With respect to tonsillar enlargement or snoring as chief complaint, this may require referral to ENT or Sleep Study for further study if clinically significant. Inspection for Acute Infectious Pharyngitis should also include a Head & Neck Examination – Chapter 7 (MF1). Oropharyngeal tumours and masses can cause deviations in the symmetry of the palate. Modification for Patients with Obesity: Use a tongue depressor to visualize the posterior oropharynx. This may make it easier to see the oropharynx if the view is obstructed."], "imgs": ["lymph-67.webp", "lymph-68.webp"]}, {"sec": "Percussion", "name": "Castell’s Sign-Spleen", "phase": "percuss", "tags": [], "pg": 120, "say": ["I will now be percussing the spleen in the left lower chest. Can you take a deep breath in? And now out?"], "do": ["Percussion of point defined by last intercostal space along the anterior axillary line during full inspiration, looking for shift to dullness. Percuss throughout respiratory cycle. The area should remain tympanic throughout the breath. Any dullness throughout the breath cycle may indicate splenomegaly."], "report": ["Castell’s sign yields tympanic sounds throughout."], "why": ["A positive Castell’s sign mildly increases likelihood of splenomegaly, and a negative Castell’s sign mildly decreases likelihood of splenomegaly (LR+ 1.7, LR- 0.7)"], "imgs": ["lymph-69.webp"]}, {"sec": "Percussion", "name": "Traube’s Space – Spleen", "phase": "percuss", "tags": [], "pg": 120, "say": ["I will now be percussing the spleen over a wider area in the left lower chest."], "do": ["Percussion of the area defined by the sixth rib superiorly, the anterior axillary line laterally, and the left costal margin inferiorly (see diagram above). You are looking for dullness – can be done along a straight line following the Left last intercostal space anteriorly until reaching anterior axillary line. Report Traube’s space yields tympanic sounds throughout."], "why": ["Dullness on percussion of Traube’s space mildly increases likelihood of splenomegaly. Tympanic sounds on percussion of Traube’s space mildly decreases likelihood of splenomegaly (LR+ 2.1, LR- 0.8)"], "imgs": []}, {"sec": "Palpation", "name": "Spleen", "phase": "palpate", "tags": [], "pg": 120, "say": ["I will palpate for an enlarged spleen in the abdomen. Please take a deep breath each time there is pressure on the abdomen."], "do": ["Use a deep palpation technique, where the spleen should not be palpable. The spleen moves down on inspiration due to the displacement of the diaphragm, so time your deep palpation during inspiration. Use your findings on percussion (Castell’s Sign, Traube’s Space) to guide the starting point of palpation:", "• If Castell’s Sign/Traube’s Space yield tympanic sounds: Start palpation close to the left costal margin. You can pull the left side of the rib cage towards your right hand as you palpate for the spleen.", "• If Castell’s Sign/Traube’s Space yield dull sounds (increasing likelihood of splenomegaly): Start palpation in RLQ along right MCL, moving slowly towards LUQ through umbilicus."], "report": ["The spleen is non-palpable, including on inspiration."], "why": ["Positive splenic palpation raises suspicion of splenomegaly. In cases of splenomegaly, the spleen will grow diagonally, so it is important to start at the RLQ and work towards the LUQ. A palpable spleen moderately increases the likelihood of splenomegaly (LR+ 8.5, LR- 0.5)."], "imgs": ["lymph-70.webp"]}, {"sec": "Palpation", "name": "Lymph Nodes", "phase": "palpate", "tags": [], "pg": 121, "say": ["I will palpate for lymph nodes. Please tell me if you are in discomfort."], "setup": ["Follow draping progression as suggested above."], "do": ["Follow the following chains USING PADS OF FINGERS (index & middle fingers, almost like a massage; move the skin in circular motion over underlying tissue in each area; compare bilaterally and move from light pressure to deep palpation). Feel the following lymph nodes in the head, neck and body. Look at the patient for signs of discomfort, and stop the exam if the patient is in distress."], "normal": ["◦ SIZE – < 1 cm", "◦ SHAPE – Regular Borders", "◦ TENDERNESS – Non-tender", "◦ CONSISTENCY – Soft", "◦ MOBILITY – Mobile", "◦ Or may be non-palpable"], "report": ["Comment whether lymph nodes are palpable or not. If palpable, comment on location, number, size, shape, tenderness, consistency, and mobility."], "why": ["The lymphatic system works in a manner where lymph from different parts of the body is drained to particular nodes along the lymphatic vessels. This can allow you to localize or generalize an inflammatory or malignant process. As you examine lymph nodes, think about what regions they drain, and look for signs of infection or malignancy in these areas.", "• Infection: Palpable, enlarged, tender lymph nodes, soft, mobile.", "• Malignancy: Palpable, enlarged (>9cm2 LR+ 8.4), hard (LR+ 3.2), non-tender (LR+ve 0.4 if tender, LR- 1.3 if non-tender), non-mobile (LR+ 10.9, LR- 0.7).", "◦ Nodes may represent a metastatic solid tumor malignancy or a blood malignancy (e.g. lymphoma).", "◦ Virchow’s Node (Left Supraclavicular Lymphadenopathy): Classically represents abdominal cancer metastasis, though may also be seen in non-GI malignancies (e.g. breast, pelvic, lymphoma)", "• Note: Enlarged lymph nodes are usually, but not necessarily, indicative of current pathological process."], "imgs": ["lymph-71.webp", "lymph-72.webp", "lymph-73.webp", "lymph-74.webp"]}]}, "volume": {"title": "Volume status", "pg": [97, 109], "notes": ["• Volume Loss Vs Dehydration - Both Are Hypovolemic:", "Volume Loss (loss of Extracellular fluid water + Na → hypo-Na): URGENTLY TRANSFUSE SALINE", "▪ Etiologies: GI hemorrhage, vomiting, diarrhea, diuresis - more common than dehydration", "▪ Bloodwork: Elevated BUN/Cr ratio, low Na Dehydration (↓ Intracellular fluid water without Na→ hyper-Na): Volume transfusion less critical, 5% dextrose more slow", "▪ Etiologies: Glycosuria from Diabetes Mellitus, Cholera (classic example)", "▪ Bloodwork: Hypernatremia or hyperosmolarity", "• Pediatric Volume Status: Posterior Fontanelle closes by 3 months old; Anterior Fontanelle closes by 18-24 months old.", "• OSCE Tip: Do not forget to ask for Orthostatic vitals before you start the physical exam"], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 102, "do": ["• Hypervolemia: ↓ O2 saturation (re: pleural effusion); weight ↑ (often checked daily, re. edema)", "• Hypovolemia: Look for tachycardia (often first sign – is a compensatory mechanism in early shock); hypotension; tachypnea (e.g. compensatory mechanism for metabolic acidosis in shock); orthostatic vitals (see below); and Oliguria (<0.5mL/kg/hour in adult or child, <1mL/kg/hour in neonates – if urine output is being charted, this will be recorded alongside patient vital signs)", "◦ In young otherwise healthy patients, and depending on the extent of hypovolemia, supine vitals may be normal but orthostatic vitals may be abnormal"], "imgs": []}, {"sec": "Vitals", "name": "Orthostatic Vitals", "phase": "vitals", "tags": [], "pg": 102, "say": ["I will now measure the blood pressure and heart rate when standing up. Before starting, do you feel dizzy?"], "do": ["4. Ensure you have the patient’s supine measurements for BP and HR", "5. Have patient stand with back facing exam table for safety in case they experience syncope with standing.", "6. Wait 1 minute then measure HR, then after an additional 1 minute, measure BP"], "report": ["The blood pressure and heart rate changes are reassuring with no evidence of orthostatic hypotension."], "normal": ["HR ↑ 10, SBP ↓ 5, DBP ↓3.5"], "why": ["Orthostatic hypotension occurs due to changes in venous return with standing, in combination with insufficient counter-regulatory mechanisms (e.g. volume depletion; autonomic dysfunction or medication adverse effects causing lack of appropriate reflex tachycardia or vasoconstriction responses). Orthostatic hypotension is a common cause of pre-syncopal symptoms and falls in elderly patients. Threshold for Orthostatic Hypotension = 30-20-10 rule: 30 HR ↑; 20 SBP ↓; 10 DBP ↓ - or if patient becomes dizzy. HR ↑ 30 is most sensitive sign of orthostatic hypotension. Notes:", "• Keep in mind dizziness could be due to inner ear vertigo, ask whether common for patient. See Chapter 7 – Head and Neck Exam – MF1 for more information about dizziness. 30-20-10 rule doesn’t work as well for elderly patients due to Autonomic Nervous System’s ↓ Agility. Modification for Patients with Obesity:", "• Use a handheld Doppler Ultrasound to locate pulses if they are difficult to feel by palpation. In this population, a handheld doppler may be more sensitive than palpation.", "• Ensure blood pressure cuff is the appropriate size. If BP cuff is too small, reading will be falsely elevated."], "imgs": []}, {"sec": "Inspection", "name": "Hypervolemia", "phase": "inspect", "tags": [], "pg": 103, "say": ["If you can breathe normally, I will examine the face and torso for signs of work of breathing.", "I will now inspect under the tongue for signs Central Cyanosis4 Cyanosis Resolved4 of low oxygen levels. Can you briefly open the mouth, and lift the tongue up?"], "do": ["3. Look for signs of increased work of breathing: tripod position, pursed lips, nasal flaring, accessory muscle use (sternocleidomastoid, scalene, trapezius, internal intercostal, or abdominal muscles), paradoxical breathing (Hoover’s sign), tracheal tug (abnormal downward movement of trachea during inspiration), suprasternal indrawing, intercostal indrawing, supraclavicular retraction, grunting (pediatrics).", "4. Observe if patient can finish complete sentences (not interrupted by work of breathing).", "Inspect under the tongue for central cyanosis"], "report": ["There are no signs of increased work of breathing (comment on all the above out loud as you observe on inspection). You are speaking in complete sentences, which is reassuring as well. volemia", "I note no signs of central cyanosis; I note the tongue appears proper size, free in motion, slightly red in colour and with thin white coating layer."], "why": ["Important in assessing dyspneic patients whether a patient is in respiratory distress (e.g. due to pulmonary edema secondary to CHF or nephrotic syndrome). The inability to speak in complete sentences demonstrates a higher degree of respiratory distress.", "Central cyanosis indicates poor oxygenation in the lungs (specifically PaO2 <50mmHg given an Hb of 140-160g/L; PaO2 45mmHg if Hb 120 g/L); can occur in hypervolemic states e.g. pulmonary edema secondary to congestive heart failure or nephrotic syndrome. Images show tongue colouration changes before and after resolution of central cyanosis3."], "imgs": ["volume-58.webp", "volume-59.webp"]}, {"sec": "Inspection", "name": "Hypovolemia", "phase": "inspect", "tags": [], "pg": 103, "say": ["I will briefly assess how you are doing cognitively.", "I will now inspect the eyes to look for sunken-ness", "I will now inspect the mucous membranes. Can you briefly open the mouth and tilt the head back slightly?", "I will now inspect the tongue. Can you briefly open the mouth and stick out the tongue?"], "do": ["Can you tell me where you are right now? What kind of place is this? Do you know what day it is? What month? Year? What is your name? Do you know my name?", "Look for signs of sunken eyes on inspection", "Assess for dryness of mucous membranes of nose and mouth (lips, inner cheeks, tongue)", "Look for longitudinal furrows"], "report": ["You are alert and oriented to person, place and time (Alert and Oriented x3)", "Eyes do not appear sunken on inspection", "Mucous membranes appear moist.", "Tongue appears absent of longitudinal furrows"], "why": ["Altered Mental Status can be due to cerebral hypoxia from ↓ volume and cardiac output. It is a worrying sign of shock. Sunken Eyes Peds - [1, 3]", "Important sign for hypovolemia, especially in pediatrics. The lack of sunken eyes slightly decreases the likelihood of hypovolemia (LR- 0.5) in adult patients. In pediatric patients, sunken eyes mildly increase the likelihood of dehydration (LR+ 1.7, LR- 0.49)", "In hypovolemia, might note chapped lips and dry mouth. Lack of dry mucus membranes slightly decreases the likelihood of hypovolemia (LR- 0.3) in adult patients. In pediatric patients, dry mucous membranes mildly increase the likelihood of dehydration (LR+ 1.7, LR- 0.41) Longitud- inal Tongue Furrows", "Important sign for hypovolemic state. Lack of longitudinal tongue furrows slightly decreases the likelihood of hypovolemia (LR- 0.3) in adult patients."], "imgs": ["volume-60.webp"]}, {"sec": "Inspection", "name": "Jugular Venous Pressure (JVP) – important for both hyperand hypo-volemia Also seen Ch 6 – Cardiac Exam – MF1 JVP - JVP Waveform", "phase": "inspect", "tags": [], "pg": 104, "say": ["Please lay back on the exam table and tilt the head all the way to the left. How do you differentiate the JVP from the Carotid Pulse? JVP Carotid Occludable and bounces back Non-occludable after occlusion Non-palpable Palpable Biphasic 1-1 Pulse to Heartbeat Decreases: with elevated No change with position and with inspiration position or inspiration Increases: with Abdomino- No change with AJR Jugular Reflux (See below) maneuver"], "do": ["5. Prop up head of exam table to 30-45°. Stand at right side. Look for JVP between 2 heads of sternocleidomastoid (i.e. sternal head medially, clavicular head laterally), or look lateral to sternal head of sternocleidomastoid.", "6. Once you have located the JVP, measure by placing ruler on sternal angle facing vertically", "7. Make a right-angle triangle going from the apex of the JVP to the ruler.", "8. The height on the ruler is the measured JVP."], "more": ["Note: on OSCE, estimate using your fingers, < 3 finger breadths is normal – not expected to use ruler."], "normal": ["3-4 cm Above Sternal Angle (ASA)"], "report": ["JVP was located and is < 5 cm above the sternal angle JVP Carotid Occludable and bounces back Non-occludable Non-occludable after occlusion Non-palpable Palpable Biphasic 1-1 Pulse to Heartbeat Decreases: with elevated No change with position and with inspiration position or inspiration Increases: with Abdomino- No change with AJR Jugular Reflux (See below) maneuver"], "why": ["JVP is the most common and perhaps most important sign to assess intravascular volume status of patients (termed “wet” if the patient is volume overloaded and the JVP is elevated, or “dry” if the patient is volume depleted and the JVP is flat). In general, the JVP will be flat in hypovolemic and distributive shock and elevated in cardiogenic and obstructive shock. The JVP is an indirect measure of right atrial pressure via visualization of the internal jugular vein. The Central Venous Pressure (cm H2O) can be estimated from the JVP by adding 5cm to the measured value, since right atrium is approximately 5cm below the sternal angle. In the appropriate clinical context (e.g. dyspneic patients in Emergency Department), an elevated JVP increases the likelihood of suspected Congestive Heart Failure (LR+ 5.1; LR- 0.66) If the JVP increases with inspiration, this is called Kussmaul’s Sign and may be a sign of severe pericarditis or right-sided heart failure. Beck’s Triad (for Acute Cardiac Tamponade) includes distended neck veins, low Arterial Blood Pressure, and Muffled Heart Sounds – as a cause of Obstructive Shock."], "imgs": ["volume-61.webp"]}, {"sec": "Palpation", "name": "Hypervolemia", "phase": "palpate", "tags": [], "pg": 104, "say": ["I will palpate for leg swelling (Sacral edema if patient immobile). Pedal Edema5 Please tell me if you are in discomfort."], "do": ["Press firmly with pads of your thumbs on the dorsal surface of patient’s leg, just above the ankle at bony prominence. Hold for 10s, then release. Look for pitting edema – skin does not bounce back immediately (i.e. pits). How high does it go on the leg? Is it pitting (transudate) or non-pitting (exudate)? Look at patient for signs of discomfort and stop exam signs of distress. Grading: 0 = none; 1+ = 2mm depression; 2+ = 4mm depression; 3+ = 6mm depression; 4+ = 8mm depression"], "report": ["I note (grade) pitting edema bilaterally, up to the level of (location e.g. ankles). volemia"], "why": ["Edema is excess interstitial fluid accumulation causing swelling. Normally, this fluid returns through lymphatic drainage. Pitting edema = transudate (non-protein filled) – sign of increased hydrostatic pressure (e.g. congestive heart failure, decreased venous return) or decreased oncotic pressure (e.g. nephrotic syndrome, hypoalbuminemia). Dependent areas (e.g. legs if patient upright/mobile, sacrum if patient supine/bedbound) will become edematous with increased hydrostatic pressure or decreased oncotic pressure. Non-dependent areas (e.g. periorbital) will become edematous with decreased oncotic pressures (e.g. nephrotic syndrome)."], "more": ["Note: Non-pitting edema = exudate (protein) filled, or lymphatic drainage issue (e.g. lymphedema)."], "imgs": ["volume-62.webp"]}, {"sec": "Palpation", "name": "Hypovolemia", "phase": "palpate", "tags": [], "pg": 105, "say": ["I will palpate for skin turgor at the skin just below the clavicle.", "I will palpate the armpits to assess for signs of sweat.", "I will palpate for circulation in the fingers and toes. Can you raise one arm above the level of the heart?"], "do": ["Pinch the skin and look for it recoil back into position", "Using a tissue, place it under patient’s axilla for a few seconds, then withdraw and assess", "Press down on the nail bed until it turns colourless. If unable to see nail bed (e.g. with nail polish present), can press on pad of finger/toe as a backup. Record time when colour returns to the nail. Normal Values: 2s for children and adult men, 3s for women, 4s for elderly; evidence suggests >5s for moderate-severe peripheral arterial disease."], "normal": ["< 2 seconds is normal, > 2 seconds is poor skin turgor"], "report": ["Skin turgor recoil occurs within 2 seconds, which is normal.", "No signs of axillary dryness on palpation.", "I note normal capillary refill time."], "why": ["Important sign for hypovolemia state. In pediatric patients, decreased skin turgor mildly increases the likelihood of dehydration (LR+ 2.5, LR- 0.66)", "• Note: Limited utility in elderly patients – generally have physiologically decreased skin turgor.", "In hypovolemia, the axilla will be dry as patients physiologically try to retain fluids. Dry axilla mildly increases the likelihood of hypovolemia (LR+ 2.8)", "Volume status sign, but also used to assess moderate-severe peripheral arterial disease. Prolonged capillary refill moderately increases the likelihood of hypovolemia (LR+ 6.9, LR- 0.7)."], "imgs": []}, {"sec": "Palpation", "name": "Abdomino-jugular Reflux (AJR) – (Hyperand Hypovolemia) See Ch 6 – Cardiac Exam – MF1", "phase": "palpate", "tags": [], "pg": 105, "say": ["Please lay back on the exam table and tilt the head to the left. I’m going to press on the upper abdomen and monitor the veins in the neck."], "do": ["Press firmly over right upper quadrant or centre of abdomen for 10-15 seconds. Observe the JVP. If JVP does rise significantly (≥4cm), observe if JVP returns to baseline while applying pressure. Sustained elevation of JVP beyond 10 seconds is abnormal. This can be confirmed by suddenly releasing abdominal pressure and seeing a return to baseline (≥4cm fall)."], "normal": ["In an otherwise healthy individual, the JVP remains constant or temporarily rises for 1-2 heartbeats before returning to normal."], "report": ["Abdominojugular Reflux lasted less than 10 seconds, which is normal."], "why": ["An alternative test for measuring JVP, method to assess right ventricular failure. This is also useful if you are having trouble seeing or differentiating the JVP from carotid."], "imgs": []}, {"sec": "Palpation", "name": "Central & Peripheral Pulses (Hyperand Hypovolemia) See Ch 6 – Cardiac Exam and Ch 8 – Peripheral Vascular Exam", "phase": "palpate", "tags": [], "pg": 105, "say": ["I will palpate the central pulses in the neck, arms and groin."], "do": ["Palpate for pulses bilaterally. For peripheral pulses, you can palpate the most distal pulse. If it is non-palpable, move more proximally. Should be symmetrical, regular rate/rhythm and no delay between them. Where to Palpate – Lower Extremities:", "• Dorsalis Pedis: Dorsal side of foot, just lateral to extensor tendon of big toe", "• Posterior Tibial: Posterior and inferior to medial malleolus = bony prominence on side of ankle", "• Popliteal: Behind knees, use 2 hands Where to Palpate – Upper Extremities:", "• Radial: Along radius bone just proximal to wrist on palmar side of hand", "• Brachial: Medial to biceps tendon and 2-3cm above antecubital fossa Where to Palpate – Central Pulses:", "• Carotid: Medial to sternocleidomastoid muscle, roughly at level of cricoid cartilage", "• Abdominal Aorta: Slightly left and superior to umbilicus", "• Femoral: Midway between ASIS and Symphysis pubis"], "more": ["Note: Auscultate for carotid bruits before palpating carotid pulses using bell of the stethoscope (see Chapter 6 – Cardiac Exam for details) Grading: 0 = Non-palpable; 1 = Barely palpable; 2 = Easily Palpable (Normal); 3 = Bounding; 4 = Aneurysmal."], "report": ["The central and most distal peripheral pulses are symmetrical with regular rate and rhythm"], "why": ["Pulses will feel bounding in hypervolemic state, and barely/non-palpable in hypovolemic state. In pediatric patients, weak pulses slightly increase likelihood of dehydration (LR+ 3.1-7.2). You can also assess for Pulses alternans (two strong systolic pulses with mid-systolic dip – suggests LV dysfunction or Cardiac tamponade) or Irregularly irregular rhythm (Atrial fibrillation). Modification for Patients with Obesity: Use handheld Doppler Ultrasound to locate pulses if difficult to appreciate by palpation. In this population, a doppler may be more sensitive than palpation."], "imgs": []}, {"sec": "Palpation", "name": "Temperature to Touch - Extremities (Hyperand Hypovolemia)", "phase": "palpate", "tags": [], "pg": 106, "say": ["I will palpate the top of each foot to check temperature on each side."], "do": ["Feel the dorsum of each foot with back of hand – assess whether it is cold to touch, or warm to touch. Migrate proximally on each side and compare temperature between each."], "report": ["I note no temperature deviation at the dorsal surface of the feet."], "why": ["In the context of a volume status exam, Temperature to touch is a common way to describe various shock states. Patients are often described as “cool and clammy” or “warm and flushed”. In particular, distributive shock states (due to decreased systemic vascular resistance) cause warm and flushed extremities, whereas hypovolemic, cardiogenic, and obstructive shock states (due to low cardiac output) cause cool and clammy extremities.", "• Recall: In context of peripheral vascular exam (Ch 8 – Peripheral Vascular Exam), temperature can help differentiate arterial deficiency (cold feet) vs. venous deficiency (warm feet)."], "imgs": []}, {"sec": "Auscultation", "name": "Listening to Breathing GeneralStridor - Pleural Rub – Stridor (Peds) - Wheeze (Infant)", "phase": "auscultate", "tags": ["peds"], "pg": 106, "say": ["I will now listen to the chest and back – breathe in and out each time you feel the stethoscope. Please pause if you become light-headed."], "setup": ["Patient crosses arms to displace scapulae."], "do": ["Hold stethoscope still when listening (don’t want to only hear rustling of moving it around)."], "report": ["I note air entry bilaterally with vesicular breath sounds and no adventitious sounds. In the context of a Volume status exam, primarily listening for signs of hypervolemia e.g. diminished breath sounds which greatly increases likelihood of Pleural Fluid (LR+ 18.6), fine crackles (e.g. in congestive heart failure) or coarse crackles (e.g. with pulmonary edema) particularly in dependent areas (e.g. at lung bases)."], "normal": ["Normal auscultation depends on listening location (1) Trachea: Bronchial – harsh, high-pitched, heard through full inspiration and expiration (2) Sternum: Bronchovesicular – less harsh, heard through full inspiration, short and softer on expiration (3) Everywhere else: Vesicular - gentle, low-pitched, quiet on inspiration and nearly silent on expiration"], "why": ["Assessing for Adventitious (Abnormal) Sounds, including:", "Sound Respiratory Description Significance Phase Fine Crackles Inspiration Inspiration Discontinuous, soft, Distal lower airway process (e.g. pulmonary fibrosis, congestive heart failure) high-pitched, more per breath, popping sound. Coarse Crackles Inspiration Discontinuous, loud, low-pitched, fewer per breath, bubbling sound. Discontinuous, loud, Proximal lower airway process (e.g. pneumonia, pulmonary edema, adult respiratory distress syndrome) alone; or low-pitched, fewer per Inspiration + breath, bubbling sound. early expiration Stridor Inspiration Inspiration Loud, musical sound, constant pitch, louder over neck. Upper airway obstruction (e.g. croup, foreign body aspiration, epiglottitis, bacterial tracheitis, retropharyngeal abscess, peritonsillar abscess) Pleural Expiration alone; or Expiration + Inspiration Loud, grating or rubbing Pleural inflammation (e.g. pleural effusion, Rub sound; can be crackling. pulmonary embolism, pleuritis) Wheeze Wheeze Continuous, high- ↓ Distal lower airway diameter (e.g. asthma, pitched, musical sound. chronic obstructive pulmonary disease) Rhonchus Continuous, low- ↓ Proximal lower airway diameter by pitched, coarse sound; mucous secretions, lesions or foreign bodies may clear after cough. (e.g. pneumonia, cystic fibrosis)", "• Bronchial breath sounds over lung (normal over trachea) points to consolidation", "• Early Crackles increases likelihood of suspected obstructive disease (LR+ 14.6), and particularly for severe obstruction in patients with chronic airflow limitation (LR+ 20.8; LR- 0.1)", "• Stridor: May be earliest sign of airway compromise.", "• Note - Pediatrics: Wheezing in Infants: Respiratory exam of wheezing in infants shows good inter-rater reliability, but respiratory status overall is most reliable.6", "• Issue: Adventitious sounds on auscultation is “the most ambiguous and confusing nomenclature in all of physical diagnosis” where clinicians use diverse terms to describe similar sounds6."], "imgs": ["volume-63.webp"]}, {"sec": "Auscultation", "name": "Cardiac Precordial Auscultation S3, S4Murmur Abnormal S1, S2 Position", "phase": "auscultate", "tags": [], "pg": 107, "say": ["I will auscultate the chest for heart sounds. Please breathe normally as I listen."], "do": ["Listen carefully with the diaphragm of the stethoscope at each valve region (Aortic, Pulmonic, Tricuspid, and Mitral). Listen for abnormal heart sounds or murmurs."], "report": ["I note a normal S1 and S2. There are no extra heart sounds or murmurs present."], "normal": ["S1 and S2, regular rate and rhythm, with no extra heart sounds and no murmurs", "• S1 = loudest at Tricuspid & Mitral valves (re atrioventricular valves closing at start of systole)", "• S2 = loudest at Aortic & Pulmonic valves (re semilunar valves closing at end of systole). Physiologic splitting of S2 normal on inspiration due to ↑ -ve intrathoracic pressure – best heard in sitting position. Abnormal Findings – Abnormal S1 and S2 and Associated Conditions:", "Characteristic S1 S2 Loud Loud Mitral Valve Prolapse (MVP); Mitral Stenosis Systemic hypertension (loud A2) or (MS); Left Atrial Myxoma; Tachycardia Pulmonary hypertension (loud P2) Faint Mitral Regurgitation; Left Bundle Branch Aortic Stenosis (LR+ 7.5, LR- 0.5) Aortic Stenosis (LR+ 7.5, LR- 0.5) Block (LBBB); Long PR interval (1st degree AV block); Acute Aortic Regurgitation (AR) Variable AV Dissociation (LR+ 24.4, LR- 0.4); Atrial N/A Fibrillation Wide Split Right Bundle Branch Block (RBBB); Right Atrial Myxoma Right Bundle Branch Block (RBBB); Right RBBB; Pulmonic Stenosis; Mitral Atrial Myxoma Regurgitation; Ventricular Septal Defect (VSD); Right Ventricular Failure Paradoxical N/A LBBB; Severe Aortic Stenosis; Wolff- Split Parkinson-White (WPW); LV Dysfunction Fixed Split N/A Atrial Septal Defect (ASD) Abnormal Findings – Extra heart sounds: Best heard in left lateral decubitus position.", "• S3: Heard just after S2, with rapid and early diastolic filling of ventricles, “Sloshing in” (e.g. volume overload). In the appropriate clinical context (e.g. dyspneic patients in Emergency Department), hearing an S3 increases the likelihood of Congestive Heart Failure (LR+11, LR- 0.88).", "• S4: Heard just before S1, with diastolic rapid late filling of ventricles, “A stiff wall” (e.g. pressure overload, Left Ventricular Hypertrophy).", "• S3 + S4: Summation gallop Abnormal Findings – Murmurs (represent Turbulent blood flow). Listen for Location (i.e. identify valve); Radiation (e.g. to carotids, left sternal border, etc.); Timing (e.g. Systolic vs. Diastolic); Configuration (e.g. Crescendo, Decrescendo, Crescendo-decrescendo, Plateau); Quality (e.g. high vs. low pitch; harsh, musical, blowing, rumbling, etc.); Change with maneuvers (e.g. with inspiration, Valsalva, squat); and Volume/Grade", "• Systolic Murmur: Grades 1 (very faint); Grade 2 (soft, readily detectable); Grade 3 (easily detectable without thrill); Grade 4 (easily detectable with thrill); Grade 5 (very loud murmur audible with stethoscope placed lightly on chest); Grade 6 (extremely loud, audible with stethoscope off chest)", "• Diastolic Grade: Grade 1 (barely audible); Grade 2 (audible, soft); Grade 3 (easily audible); Grade 4 (loud) Common Murmur Description Mitral Stenosis (MS) Mitral Stenosis", "• Pathophysiology: Mitral valve should be open in diastole – mitral stenosis (MS) causes incomplete opening of mitral valve in diastole", "• Murmur: Diastolic murmur with Opening Snap best heard at cardiac apex in left lateral decubitus position. Worsened by ↑ venous return (squat/leg raise) Aortic", "• Pathophysiology: Aortic valve should be closed in diastole – aortic Regurgitation / regurgitation causes incomplete closing of aortic valve in diastole Insufficiency", "• Murmur: Diastolic murmur heard best at right base in sitting position. (AR/AI) Worsened by ↑ venous return (squat/leg raise) Aortic Stenosis (AS) Aortic Stenosis", "• Pathophysiology: Aortic valve should be open in systole – aortic stenosis (AS) causes incomplete opening of aortic valve in systole", "• Murmur: Systolic murmur with crescendo-decrescendo pattern heard best at right base. Radiates to R clavicle and/or R carotid. Worsened by ↑ venous return (squat/leg raise)"], "imgs": ["volume-64.webp"]}]}, "renal": {"title": "Renal / GU", "pg": [110, 117], "notes": ["• Note about Renal Issues: In general, you will need to order bloodwork and urinalysis to differentiate these issues. There are very few specific tests for the Renal system; instead, use your discretion and clinical judgment, based on your differential diagnosis (see Appendix 3 – Differential Diagnoses Practice – MF1) to guide what pieces from other examinations you should incorporate", "• Key idea for Renal Histology: For the kidneys, every day is garbage day – the kidneys will export its contents at the glomeruli in nephrons, and then specific transporters will bring specific contents back. It is a future proof system, one that enables us to introduce novel drugs into our systems that the kidneys at a rate they could never evolve to accommodate, while still being capable of being cleared by the renal system."], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 114, "do": ["• Do Orthostatic vitals re volume status, a critical piece of regulation of volume status is the renal system"], "imgs": []}, {"sec": "Other Examinations to Perform (not exhaustive)", "name": "Respiratory", "phase": null, "tags": [], "pg": 114, "do": ["See Chapter 5 – Resp Exam (MF1)– should perform a scanning Respiratory physical exam, particularly listening to the lungs at the bases"], "why": ["Kidneys, lungs and heart are all interconnected with respect to the hematological system and maintaining homeostasis of its contents."], "imgs": []}, {"sec": "Other Examinations to Perform (not exhaustive)", "name": "Cardiovascular", "phase": null, "tags": [], "pg": 114, "do": ["See Chapter 6 – Cardiac Examination (MF1) – should perform a scanning Cardiac physical examination, particularly auscultating the heart for murmurs and extra heart sounds, and assessing JVP"], "why": ["Kidneys, lungs and heart are all interconnected with respect to the hematological system and maintaining homeostasis of its contents."], "imgs": []}, {"sec": "Other Examinations to Perform (not exhaustive)", "name": "Volume Status", "phase": null, "tags": [], "pg": 114, "do": ["See Chapter 9 – Volume Status Exam (MF2) – should perform a more complete Volume Status examination if you suspect renal issues"], "why": ["The renal system is particularly important for maintaining volume homeostasis; consider how variable our fluid intake can be, and how well the renal system and supporting endocrine signalling paths, etc. can accommodate for this flexibility in behavior."], "imgs": []}, {"sec": "Other Examinations to Perform (not exhaustive)", "name": "Abdominal", "phase": null, "tags": [], "pg": 114, "do": ["Explored in Ch 13 – Abdo Exam (MF3) – should perform a scanning Abdominal physical exam: specifically, look for signs of liver disease and splenomegaly, listen to bowel sounds, and palpate the liver and spleen"], "why": ["Liver is vital in clearance (and many other functions), and so is strongly interconnected with kidneys. It is important to ask about bowel history when asking about urinary history."], "imgs": []}, {"sec": "Palpation", "name": "Ballottement of Kidneys", "phase": "palpate", "tags": [], "pg": 114, "say": ["I will palpate the abdomen and the back for the kidneys. Could you hold the arms across the chest? (avoids tensing up abdominal muscles)"], "do": ["Standing at right side of patient (normally the one that is palpable is right side, if at all, slightly inferior vs left kidney). Place your right hand anteriorly, and left hand posteriorly in the iliac region (just below 12th rib, more lateral than midline). Ask patient to breathe in deeply (this causes diaphragm expansion to push kidneys down). Use pancaking maneuvers to attempt ballottement of kidneys. Can be normal to be able to do ballottement of kidneys in children or thin adults."], "report": ["Kidneys are non-palpable."], "why": ["If palpable, would raise suspicion of kidney enlargement or excursion."], "imgs": []}, {"sec": "Palpation", "name": "Costovertebral Angle (CVA) Tenderness", "phase": "palpate", "tags": [], "pg": 115, "say": ["I will palpate the back to assess for pain from the kidneys. Please tell me if you are in discomfort."], "do": ["Stand behind the patient and place a hand flat on the patients back at the level of the CVA and use a fist to tap with some force at costovertebral angle. An appropriate force exerted causes the patient’s head to bob forward. Observe for a severe pain response. Stop the exam if the patient is in distress."], "report": ["No costovertebral angle tenderness is observed."], "why": ["Sign of inflammation in the area of the kidney, such as pyelonephritis, ureterolithiasis, or perinephric abscess. Positive renal tenderness mildly increases the likelihood of suspected ureterolithiasis (LR+ 3.6), while absence of renal tenderness moderately decreases the likelihood of suspected ureterolithiasis (LR- 0.2). When present with fevers, nausea/vomiting, malaise, and/or UTI signs, positive CVA tenderness may be more concerning for suspected pyelonephritis."], "imgs": ["renal-65.webp"]}, {"sec": "Palpation", "name": "Bladder Palpation", "phase": "palpate", "tags": [], "pg": 115, "say": ["I will palpate the lower abdomen for a distended bladder. Could you please lie flat on the exam table?"], "setup": ["Expose lower abdomen to be able to palpate/landmark symphysis pubis."], "do": ["Palpate over lower abdomen – check if bladder palpable above symphysis pubis"], "report": ["I detect an enlarged bladder on palpation – would recommend a bladder scan."], "why": ["Urinary retention can cause post-obstructive acute kidney injury, with inability to pass urine, suprapubic pain, and delirium. While a Bladder Scan (ultrasound) is best to assess bladder volume, a palpable bladder has an LR+ of 1.9, LR- of 0.3 for detecting ≥400mL in bladder5 to determine who would benefit from a bladder scan and intervention e.g. with catheterization if appropriate. Causes include urinary outlet obstruction (e.g. benign prostatic hypertrophy, pelvic organ prolapse, constipation), neurogenic causes (e.g. spinal cord compression, stroke) and medication causes (e.g. anticholinergics, opioids)"], "imgs": []}, {"sec": "Auscultation for Bruits", "name": "Abdominal Bruits Exam", "phase": "auscultate", "tags": [], "pg": 115, "say": ["I will use the bell of my stethoscope to auscultate key arteries for any signs of turbulent blood flow."], "do": ["With patient in supine position, auscultate epigastric, R/L renal, R/L iliac and R/L femoral arteries at the following locations:", "• Abdominal Aorta: Slightly left and superior to umbilicus", "• Right and Left Renal: 5cm superior and 5cm lateral to umbilicus", "• Right and Left Iliac: 5cm inferior and 5cm lateral to umbilicus", "• Right and Left Femoral: Midway between ASIS and Symphysis pubis If you detect a renal bruit (“whoosh” sound), clarify if it is systolic or systolic-diastolic (e.g. via timing of carotid upstroke on palpation). Also clarify if it unilateral vs. bilateral."], "report": ["I note no bruits on auscultation."], "why": ["In a normal vessel, a pulse can be palpated but not auscultated. Bruits occur due to turbulent flow within a vessel, where the pitch and radiation are a function of flow and direction of the turbulent stream. Bruits can be innocent (e.g. in young, normotensive and asymptomatic patients), typically described as short, faint and mid-systolic. A systolic-diastolic abdominal bruit greatly increases the likelihood of renovascular hypertension (LR+ 39, LR- 0.62) (e.g. renal artery stenosis), a cause of secondary hypertension."], "imgs": ["renal-66.webp"]}]}, "thyroid": {"title": "Thyroid", "pg": [173, 178], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Patient Positioning: Should be seated during the Thyroid exam, with a glass of water re. swallow assessment for goiter.", "• Patient Draping: Expose the neck from chin to level of manubrium & clavicles"], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 173, "do": ["Hyperthyroidism:", "• Tachycardia (HR >90 bpm – LR+ 4.4, LR- 0.2)", "◦ Can’t Miss Diagnosis: Thyroid Storm – Febrile, Hypertension, Altered Mental Status, Tachyarrhythmia (e.g. atrial fibrillation), Congestive heart failure."], "imgs": []}, {"sec": "Inspection", "name": "Head", "phase": "inspect", "tags": [], "pg": 173, "say": ["I will inspect the eyes, eyebrows and hair to look for signs of thyroid issues. Please look straight ahead. Hyperthyroidism:", "Look for Eyelid retraction (white of sclera visible at upper margin of cornea in direct outward stare), Exophthalmos and hair loss. Exophthalmos2 Hypothyroidism:", "Look for hair thinning, Queen Anne’s Eyebrows/Hertoghe Sign (loss of outer 1/3rd of eyebrows), and periorbital puffiness. Queen Anne’s eyebrows3"], "report": ["I note no signs of exophthalmos, hair thinning, Queen Anne’s eyebrows, or periorbital puffiness."], "why": ["The likelihood of suspected hyperthyroidism (particularly Grave's Disease) is greatly increased by eyelid retraction (LR+ 31.5, LR- 0.7). Both lid retraction and exophthalmos form part of the Wayne Index for Hyperthyroidism, where the likelihood of suspected hyperthyroidism greatly reduced for a score <11 (LR+ 0.04) and greatly increased for a score of >20 hyperthyroidism (LR+ 18.2). Alternatively, the likelihood of suspected hypothyroidism is slightly increased by loss of eyebrow hair (LR+ 1.9). Periorbital puffiness forms part of the Billewicz Score for Hypothyroidism, where the likelihood of suspected hypothyroidism is greatly reduced for a score of < -15 (LR+ 0.1), and greatly increased for a score of ≥ 30 (LR+ 18.8)."], "imgs": ["thyroid-108.webp", "thyroid-109.webp"]}, {"sec": "Inspection", "name": "Neck", "phase": "inspect", "tags": [], "pg": 173, "say": ["I will inspect the neck for signs of thyroid issues. Please look straight ahead. Goiter4 When you can, please swallow."], "do": ["Expose neck from chin to level of manubrium & clavicles. Look at neck from both sides, looking for an obvious mass or goiter. Have patient take a sip of water and swallow – the thyroid should move up and down as patient swallows. If no goiter visible, have patient extend their neck and repeat inspection."], "report": ["I note no obvious mass or goiter. The thyroid is mobile on swallowing."], "why": ["A goiter may be present with hyperthyroid, euthyroid or hypothyroid disease. A goiter detected by palpation and visible on inspection with neck in neutral position (non-extended) greatly increases the likelihood of the presence of goiter (LR+ 26.3); a goiter detected by palpation but only visible on inspection with neck extended does not significantly alter the likelihood of the presence of goiter. An enlarged thyroid mildly increases the likelihood of suspected hyperthyroidism (LR+ 2.3, LR- 0.1), and of suspected hypothyroidism (LR+", "2.8, LR- 0.6). The absence of an enlarged thyroid decreases the likelihood of both as well. Modification for Patients with Obesity: Ask the patient to look up at the ceiling when inspecting their thyroid. This is because stretching the neck tissue can help to make the thyroid more prominent during inspection."], "imgs": ["thyroid-110.webp"]}, {"sec": "Inspection", "name": "Skin", "phase": "inspect", "tags": [], "pg": 174, "say": ["I will inspect the hands, forearms and elbows to look for signs of thyroid issues. Hyperthyroidism:", "Assess for moist and warm skin. Hypothyroidism:", "Assess for cool and dry skin, or coarse skin. Look for wrist puffiness, and dry or brittle nails."], "report": ["I note no moist and warm, or cool and dry skin. The nails are not dry or brittle, with no wrist puffiness."], "why": ["Thyroid disease can often manifest as changes in the skin. The likelihood of suspected hyperthyroidism is moderately increased by moist and warm skin (LR+ 6.7, LR- 0.7). Both hands hot and hands moist form part of the Wayne Index for Hyperthyroidism, where a score of <11 greatly reduces the likelihood of suspected hyperthyroidism (LR+ 0.04) and a score of >20 greatly increases the likelihood of suspected hyperthyroidism (LR+ 18.2). Alternatively, the likelihood of suspected hypothyroidism is slightly increased by cool and dry skin (LR+ 4.7, LR- 0.9), by coarse skin (LR+ 3.4, LR- 0.7), and by wrist puffiness (LR+ 2.9, LR- 0.7). Both coarse skin and cold skin form part of the Billewicz Score for Hypothyroidism, where a score of < -15 points greatly reduces the likelihood of suspected hypothyroidism (LR+ 0.1), and a score of ≥ 30 points greatly increases the likelihood of suspected hypothyroidism (LR+ 18.8)."], "imgs": []}, {"sec": "Inspection", "name": "Fine Tremor of Hands (hyperthyroidism)", "phase": "inspect", "tags": [], "pg": 174, "say": ["I will inspect the hands. Can you stretch your arms out, with palms down and with fingers separated?"], "setup": ["Need a piece of paper available"], "do": ["Place piece of paper on top of hands and observe for fine tremor of fingers."], "report": ["No fine tremor of fingers observed."], "why": ["The presence of fine finger tremor greatly increases the likelihood of suspected hyperthyroidism (LR+ 11.4, LR- 0.3), and also forms part of the Wayne Index for Hyperthyroidism, where a score of <11 greatly reduces the likelihood of suspected hyperthyroidism (LR+ 0.04) and a score of >20 greatly increases the likelihood of suspected hyperthyroidism (LR+ 18.2)."], "imgs": []}, {"sec": "Inspection", "name": "Pretibial Myxedema (hyperthyroidism)", "phase": "inspect", "tags": [], "pg": 174, "say": ["I will now assess the lower legs below the knee, in particular the front of the legs and top of the feet for skin changes for signs of thyroid issues."], "do": ["Look for peau d’orange appearance (waxy, discoloured induration of skin); usually begins at anterior aspect of lower legs, spreads to dorsal surface of feet; can progress to the upper extremities too."], "report": ["I note no abnormal skin discolorations such as peau d’orange to suggest thyroid disease."], "why": ["Pretibial myxedema is a rare complication of Graves’ disease (hyperthyroidism)."], "imgs": ["thyroid-111.webp"]}, {"sec": "Palpation", "name": "Thyroid Gland", "phase": "palpate", "tags": [], "pg": 174, "say": ["I will palpate the thyroid. I will need to place my hands on the neck to examine the thyroid. I will ask you to swallow a sip of water when you can at points. Please tell me if you are in discomfort."], "setup": ["Have glass of water available. Stand either in front of, or behind patient (patient comfort-dependent)."], "more": ["Note: Monitor for signs of patient discomfort here and stop the exam if the patient is in distress."], "do": ["Landmark for Isthmus: Find the thyroid cartilage (first big bump, in males it’s the Adam’s Apple) → Move inferiorly to Cricoid Cartilage (second big bump, after a space) → palpate just below that → found the isthmus. Palpating gland → Once found the Isthmus, push the sternocleidomastoids out of the way on one side with that hand; with other hand, palpate around the area laterally to the isthmus you found Technique: sometimes easier to approach patient posteriorly for this (for example, landmark with right finger the isthmus, push left sternocleidomastoids out of way with left hand, and with right finger move laterally to palpate) Assessment → Assess for size, nodularity, consistency, shape/symmetry, and tenderness"], "report": ["Thyroid gland is small, non-palpable, non-tender without nodules"], "why": ["A goiter may be present with hyperthyroid, euthyroid or hypothyroid disease. An enlarged thyroid mildly increases the likelihood of suspected hyperthyroidism (LR+ 2.3, LR- 0.1), and of suspected hypothyroidism (LR+ 2.8, LR- 0.6). The absence of an enlarged thyroid decreases the likelihood of both as well. Typical presentations:", "• Grave’s Disease (Hyperthyroid): Soft, diffusely enlarged, and soft with no nodules", "• Hashimoto’s Thyroiditis (Hypothyroid): Firm, diffusely enlarged, and slightly tender with no nodules", "• Malignancy: Firm, singular nodes", "• Iodine Deficiency: Multinodular goiter"], "imgs": ["thyroid-112.webp"]}, {"sec": "Percussion", "name": "Retrosternal Goiter", "phase": "percuss", "tags": [], "pg": 175, "say": ["I will percuss near the sternum (point on yourself to where you will percuss) for signs of thyroid issues."], "do": ["Percuss over sternum, looking for dullness as evidence of a retrosternal goiter."], "report": ["I note no dullness to percussion over the sternum."], "why": ["A retrosternal goiter is a thyroid gland/goiter that has extended posteriorly into the mediastinum rather than anteriorly and is more occult. Percussion may thus help assess a goiter’s extent in thyroid disease."], "imgs": []}, {"sec": "Auscultation", "name": "Thyroid Bruits (hyperthyroidism)", "phase": "auscultate", "tags": [], "pg": 175, "say": ["I will auscultate for bruits in the thyroid gland using the diaphragm of my stethoscope. Can you take a deep breath in and hold it for a moment as I listen?"], "do": ["Auscultation of each of the two lobes of the thyroid"], "report": ["I note no bruits on auscultation of the thyroid gland."], "why": ["Hyperthyroidism may present with localized and continuous bruits. In practice, doppler ultrasound may help in assessing for increased thyroid perfusion and bruits as well. A bruit over thyroid forms part of the Wayne Index for Hyperthyroidism, where a score of <11 greatly reduces the likelihood of suspected hyperthyroidism (LR+ 0.04) and a score of >20 greatly increases the likelihood of suspected hyperthyroidism (LR+ 18.2)."], "imgs": []}, {"sec": "Special Tests", "name": "Lid Lag Test (Hyperthyroidism)", "phase": "special", "tags": [], "pg": 175, "say": ["Please follow my fingers (stand > 1 m away) without moving the head."], "do": ["As you raise and lower your fingers, watch both the eyes and eyelids. Negative (normal) when the lids and eyes movements are synchronized. Positive (abnormal) when the lids move slower than the eyes."], "report": ["Lid Lag Test is negative, with eyes and lids moving together simultaneously."], "why": ["Grave’s Disease (hyperthyroid) may present with ocular manifestations, such as exophthalmos, lid retraction and lid lag. Eyelid lag greatly increases the likelihood of suspected hyperthyroidism (LR+ 17.6, LR-", "0.8). Lid lag also forms part of the Wayne Index for Hyperthyroidism, where a score of <11 greatly reduces the likelihood of suspected hyperthyroidism (LR+ 0.04) and a score of >20 greatly increases the likelihood of suspected hyperthyroidism (LR+ 18.2)."], "imgs": []}, {"sec": "Special Tests", "name": "Pemberton’s Sign", "phase": "special", "tags": [], "pg": 175, "say": ["Please raise both arms straight above the head and keep them elevated for 1 minute."], "do": ["As patient raises arms, look for signs of facial congestion and cyanosis, as well as respiratory distress."], "report": ["I note no facial congestion, cyanosis, or respiratory distress with Pemberton’s Sign"], "why": ["Pemberton’s Sign assesses for symptoms of Superior Vena Cava obstruction (e.g. congestion) occurring here secondary to mass effect from enlarged thyroid gland/goiter."], "imgs": []}, {"sec": "Special Tests", "name": "Proximal Muscle Weakness (Hyperthyroidism)", "phase": "special", "tags": [], "pg": 175, "say": ["Please sit on the floor. Now, can you stand up without using either arm to support you?"], "do": ["Assess whether patient able to comply with instructions or require arm support. Alternative method: have patient sit in a chair initially, and then stand without using their arms."], "report": ["No evidence of proximal muscle weakness"], "why": ["May be suggestive of hyperthyroidism, which can cause myopathy. The proximal muscles are those closer to the trunk, and aid in gross movements such as standing."], "imgs": []}, {"sec": "Special Tests", "name": "Deep Tendon Reflexes", "phase": "special", "tags": [], "pg": 175, "say": ["I will now be checking the deep tendon reflexes for signs of thyroid issues using a reflex hammer. Please keep the joints relaxed."], "do": ["Patellar reflex (knee), Brachialis reflex (Biceps), Triceps reflex, Achilles reflex. Also perform the plantar response (should normally see downward of big toe; Babinski = upgoing plantar response). Assess for bilateral symmetry of reflexes, briskness of the response, and clonus. If patient’s reflex is difficult to elicit, can try the Jendrassik Maneuver (patient’s teeth clenched, fingers interlocked, and pull on the count of 3) for distraction. Clonus = seizure of the reflex (normal to see 2 beats of flapping of the foot). Grading: 0 = Absent; 1+ = Hypoactive (or requiring Jendrassik Maneuver); 2+ = Normal; 3+ = Hyperactive, no Clonus; 4+ = Hyperactive, with Clonus (repeating reflex)"], "report": ["I note normal Grade 2+ Deep tendon reflexes in all 4 limbs."], "why": ["Hyperreflexia (3+ or 4+) may suggest hyperthyroidism. Alternatively, hyporeflexia (0 or 1+; specifically with a delayed relaxation phase) may suggest hypothyroidism. In particular a delayed ankle reflex mildly increases the likelihood of suspected hypothyroidism (LR+ 3.4, LR- 0.6). A slow ankle jerk forms part of the Billewicz Score for Hypothyroidism – score <-15 pts greatly reduces likelihood of suspected hypo- thyroidism (LR+ 0.1), and score ≥ 30 pts greatly increases likelihood of suspected hypothyroidism (LR+ 18.8)."], "imgs": []}]}, "diabetes": {"title": "Diabetes", "pg": [164, 172], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Communication Moment: Discussing weight gain as a chief complaint can be a sensitive topic for patients; consider how to develop good rapport while obtaining and conveying appropriate detail and information and develop strategies to use.", "• Major Systems to Examine:", "Eyes (Fundoscopy – Ch 7 Head & Neck Exam – MF1; Ch 31 – Screening Neuro Exam – MF4; Ch 40 – Ophtho Exam – IF) Kidneys (e.g. Renal bruits – Ch 10 – Genitourinary History and Renal Exam – MF2) Neuropathy (this Chapter; screening neurologic exam explored in Ch 31 – Screening Neuro Exam – MF4) Cardiac (Ch 6 – Cardiac & Hematological Exam – MF1) Diabetes Foot Exam (re Peripheral Vascular Disease + Diabetic Neuropathy – this Chapter; may also wish to do a dedicated Peripheral Vascular Exam, as detailed in Ch 8 – Peripheral Vascular Exam – MF1)"], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 165, "do": ["• Blood Pressure – Target Systolic BP <130 mmHg, Diastolic BP <80 mmHg", "• Be sure to do Orthostatic Vitals as well (re Autonomic neuropathy complication)"], "imgs": []}, {"sec": "Inspection", "name": "Waist Circum, Waist-Height Ratio, WaistHip Ratio and BMI", "phase": "inspect", "tags": [], "pg": 166, "say": ["Would it be alright if we measure your height, weight, hip circumference and waist circumference today? Set-Up: Ask permission before weighing someone, and never weigh a patient in front of others. Weighing scales should be placed in private areas in clinical spaces."], "do": ["7. Ask patient to remove shoes.", "8. Requires a weight scale, a method of measuring height, and a tape measure.", "9. Measure the patient’s weight and height using appropriate scales.", "10. For waist circumference, measure circumference at a level midway between the Iliac Crest and last palpable rib (WHO guidelines)", "11. For hip circumference, measure at the level with the widest portion of the buttocks.", "12. Using these measurements, calculate BMI (kg /m2), Waist-Height Ratio, and Waist-Hip Ratio."], "report": ["The height and weight we measured today were _____, with a BMI of ______."], "why": ["Waist-Height Ratio and Waist-Hip ratio are objective measures of central (abdominal) obesity associated with ↑ cardiovascular risk. These calculated measures, including BMI, are imperfect, but clinically useful to monitor individual patients over time. Differential diagnoses for weight changes include Nutritional state, malignancy, chronic illness, eating disorders, hyper/hypothyroidism, hyper/hypo-cortisolism, etc. WHO Classification of Weight Status:", "Weight Status Under- Normal Range Overweight Class I Class II Class III Obesity Weight Obesity Obesity BMI (kg/m2) < 18.5", "18.5 – 24.9 25 – 29.9 30 – 34.9 35 – 39.9 ≥ 40 Edmonton Obesity Staging System (EOSS)2: Staging according to obesity-related risk factors, physical symptoms, psychological symptoms, and functional impairment. Overall stage determined by highest component (e.g. pt with Stage 3 Physical Symptoms, Stage 1 otherwise is considered EOSS Stage 3 Overall) EOSS Obesity-Related Risk Physical Symptoms Psychological Functional Stage Factors Symptoms Impairment Stage 0 None None None None Stage 1 Stage 1 Subclinical Risk Factors Mild Not Requiring Mild Mild Mild (Quality of Life not impacted) Mild (Quality of Life (Borderline HTN, Medical Intervention not impacted) Impaired fasting (e.g. moderate exertional glucose, elevated liver dyspnea; occasional enzymes, etc.) aches/ pains; fatigue) Stage 2 Obesity-Related Comorbidities Requiring Medical Intervention (HTN, T2DM, OSA, PCOS, OA, GERD) Obesity-Related Comorbidities Requiring Medical Moderate (e.g. Moderate (QoL beginning to be impacted) Intervention (HTN, T2DM, OSA, PCOS, OA, GERD) Depression, Eating D/O, Anxiety D/O) Stage 3 Significant Obesity-Related End-Organ Damage (MI, HF, Diabetes Complications, Incapacitating OA) Significant (e.g. Significant (QoL Depression, significantly Suicidal Ideation) impacted) Stage 4 Severe (Potentially End-Stage) Obesity-Related Severe disabling Severe functional End-Organ Damage psych. symptoms limitations Modification for Patients with Limited Mobility:", "• Height: Can be measured using the demi-span (distance from mid-sternal notch to the end of the middle finger in the coronal plane) and then calculated with the following formulas:", "◦ For female patients: Height (cm) = (1.35 x Demi-span) + 60.1", "◦ For male patients: Height (cm) = (1.40 x Demi-span) + 57.8", "• Weight: A patient’s estimate of their own weight is more accurate vs. physician’s. If the patient is unable to give an estimation, body weight can be estimated using body height, and hip and waist circumference. Modification for Patients who are Transgender:", "• Transmasculine Patients (FTM): Patients on masculinizing hormone therapy may have body fat redistribution and/or increased muscle mass.", "• Transfeminine Patients (MTF): Patients on feminizing hormone therapy may have body fat redistribution and/or decreased muscle pass."], "imgs": []}, {"sec": "Inspection", "name": "Direct Fundoscopy", "phase": "inspect", "tags": [], "pg": 167, "say": ["I will now inspect each eye using a direct ophthalmoscope. You will feel my hand touch the shoulder to keep the ophthalmoscope steady. Please look at an object on the wall in the distance at your eye level (preventing constriction due to pupillary accommodation reflex)"], "setup": ["Room should still be dim. Stand facing the patient; if you’re examining the patient’s right eye first, use your right eye to look (vice versa). Adjust the scope’s focus (if you’re not wearing your nearsighted prescription glasses, may take more adjusting) by focusing on an object in room. Use low-moderate light intensity typically with medium aperture."], "do": ["Steady your hand on their shoulder. Shine the light from ophthalmoscope in patient’s eye; should see the red reflex. Follow reflex and slowly move toward patient. Find an artery and follow that towards the centre. You should come upon the optic disc (head of optic nerve, a confluence of retinal nerve fibers exiting the globe) and the optic cup (white centre of optic disc). Look for signs of optic disc swelling, and loss of venous pulsations. Follow the Superonasal Arcade, Inferonasal Arcade, Superotemporal Arcade, and Inferotemporal Arcade. Focus on Macula (temporal to optic disc), which contains Fovea where you can see a Yellow Reflex in healthy people. Look for signs of hemorrhages, neovascularization (small branching vessels) and cotton wool spots (fluffy white patches)."], "report": ["The optic disc was visualized in each eye, with no signs of optic disc swelling, neovascularization or loss of venous pulsations."], "why": ["Direct fundoscopy allows for a focused exam of intraocular structures, alongside external examination and the slit lamp examination (explored in Ch 40 – Ophtho Exam – IF). Fundoscopy also forms a part of the screening neurological examination (See Chapter 31 –Neuro Exam – MF4). Major pathologies to look for include:", "• Absent Red Reflex: Can be due to cataracts, retinoblastoma, retinal detachment, vitreous hemorrhage, etc.", "• Glaucoma (Chronic): Enlarged cup/disc ratio >0.5 (normal cup-to-disc ratio ≤0.5)", "• Papilledema: Swollen optic disc with no clear demarcated disc border due to ↑ Intracranial Pressure, coupled with loss of venous pulsations. Particularly important to assess for in patients with new onset headaches.", "• Retinal Detachment/Tear/Break: Can occur inside field of view on direct ophthalmoscopy.", "• Cotton Wool Spots: Sign of vascular insufficiency or ischemia to an area of retina – most common causes being hypertensive and diabetic retinopathy (Ch 14 – Diabetes Exam – MF3)", "• Hypertensive Changes: Arteriolar spasm, exudates, flame-shaped hemorrhages, loss of venous pulsations, ghost vessels, cotton wool spots.", "• Diabetic Retinopathy: Cotton wool spots, dot and blot hemorrhages, neo-vascularisations Colour Pallor Brown, Blue, Purple Hair Loss No Change Ulceration Pressure points – soles, ventral surface of foot Tibial plateau, Medial Malleolus Skin Changes Shiny Flaky Edema N/A Peripheral Edema Temperature Cold Warm", "Differentiates peripheral arterial vs. peripheral venous disease – Checking for macrovascular complications of diabetes", "Differentiates peripheral arterial vs. peripheral venous disease – Checking for macrovascular complications of diabetes"], "imgs": []}, {"sec": "Inspection", "name": "Skin Changes", "phase": "inspect", "tags": [], "pg": 167, "say": ["I will inspect the neck, armpits, navel and forehead, as well as Acanthosis Nigricans3, 4 the lower legs to look for skin changes."], "setup": ["Be sure to drape patient appropriately for the areas to be examined"], "do": ["Assess for Acanthosis nigricans (hyperpigmentation of skin typically found in body folds), as well as evidence of Impaired Healing (re longstanding cuts and bruises)"], "report": ["I note no Acanthosis nigricans or impaired healing. Acanthosis Nigricans3, 4"], "why": ["Characteristic skin changes in diabetes complications"], "imgs": ["diabetes-99.webp", "diabetes-100.webp"]}, {"sec": "Inspection", "name": "Mouth", "phase": "inspect", "tags": [], "pg": 167, "say": ["I will now inspect the mouth for thrush or ulcers. Can you open the mouth wide?"], "do": ["Look for Thrush (white velvety plaques that can scrape off) on tongue and in mouth) and for Ulcerations."], "report": ["I note no evidence of oral thrush or ulcerations."], "why": ["Thrush is important to detect, and is common in patients with diabetes mellitus and who are immunosuppressed e.g. on glucocorticoid medication; Ulcerations evidence of peripheral vascular disease"], "imgs": ["diabetes-101.webp"]}, {"sec": "Palpation", "name": "Peripheral Vascular", "phase": "palpate", "tags": [], "pg": 168, "do": ["See Chapter 8 – Peripheral Vascular Exam – MF1 – Temperature, cap refill, pitting edema, paralysis, pulses"], "why": ["Macrovascular complications of Diabetes"], "imgs": []}, {"sec": "Auscultation", "name": "Respiratory Examination", "phase": "auscultate", "tags": [], "pg": 168, "do": ["See Chapter 5 – Respiratory Exam – MF1 – auscultate lung fields for crackles or wheezes"], "why": ["Looking to see signs of respiratory infections"], "imgs": []}, {"sec": "Auscultation", "name": "Cardiac Examination", "phase": "auscultate", "tags": [], "pg": 168, "do": ["See Chapter 6 – Cardiac & Heme Exam – MF1 - looking for extra heart sounds or murmurs"], "why": ["Diabetes is a part of the Framingham risk score; therefore, you should conduct a cardiac examination as part of the diabetes examination"], "imgs": []}, {"sec": "Auscultation", "name": "Peripheral Vascular", "phase": "auscultate", "tags": [], "pg": 168, "do": ["See Chapter 8 – Peripheral Vascular Exam – MF1 – auscultation of bruits"], "why": ["Macrovascular complications of Diabetes"], "imgs": []}, {"sec": "Auscultation", "name": "Abdominal Examination", "phase": "auscultate", "tags": [], "pg": 168, "do": ["See Chapter 13 – Abdominal Exam – MF3 – looking for general appearance"], "why": ["General scanning examination"], "imgs": []}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Inspection of Feet", "phase": "special", "tags": [], "pg": 168, "say": ["I will now inspect the feet for any University of Texas Diabetic Wound Classification6 wounds, ulcers or infection. Grade 1 Grade 2 Grade 3"], "do": ["Look for any ulceration/wounds on the feet. If present, comment on location, size, depth, infection or discharge, surrounding erythema/ swelling/fluctuance or cellulitis, and visible bone. Wounds can be classified according to the University of Texas Diabetic Wound Classification, as follows:", "• Grade 0 – Pre- or Post-ulcerative with lesion completely epithelialized.", "• Grade 1 – Superficial wound not involving tendon, capsule or bone.", "• Grade 2 – Wound penetrating to tendon or capsule, not to bone.", "• Grade 3 – Wound penetrating to bone or joint."], "report": ["I note no wounds or ulcers, no infection or discharge, no surrounding erythema or cellulitis, no swelling or fluctuance, and no visible bone on inspection. University of Texas Diabetic Wound Classification6 Grade 1 Grade 2 Grade 3"], "why": ["Wounds and ulcers are common in diabetes (re: peripheral neuropathy, peripheral vascular disease, and poor wound healing) and may go unnoticed by patients with neuropathy. Ulcers are concerning due to increased risk of infection, which can also present with skin infection (e.g. cellulitis) or progress to osteomyelitis (infection of underlying bone) if missed or untreated for a prolonged duration. Severe diabetes foot infections with osteomyelitis may require an amputation and can cause bacteremia/sepsis. The likelihood of osteomyelitis in patients with foot ulcers is proportionally impacted by increasing ulcer area size (e.g. Ulcer area >3cm2 → LR+ 3.5, LR- 0.3; Ulcer area >5cm2 → LR+ 11.0, LR- 0.5), and is also slightly increased by positive bone probe test (LR+ 5.3, LR- 0.2) or ulcer depth >3mm/visible bone exposed (LR+ 3.9, LR- 0.3). Erythema, swelling and purulence as a finding on its own is not statistically significant. The likelihood of a non-healing wound at 20 weeks increases with 3 findings: Ulcer Grade 3 or higher (full thickness and subcutaneous tissue involvement with exposed tendon, ligament or joint), Ulcer size >2cm2, and duration >2 months. Having all 3 of these findings mildly increases the likelihood of a non-healing wound at 20 weeks (LR+ 3.84), while having none of these findings moderately decreases the likelihood (LR+ 0.48)."], "imgs": ["diabetes-102.webp", "diabetes-103.webp", "diabetes-104.webp"]}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Inspection of Soles", "phase": "special", "tags": [], "pg": 168, "say": ["I will now inspect the shape of the foot, and shoes for their wearing pattern."], "do": ["Look for Charcot Foot (occurs due to bumping into items without feeling re: peripheral neuropathy). Look in shoes for areas where shoes are worn out (in Charcot Foot, occurs more on medial side of shoe)."], "report": ["There are no abnormal wearing patterns in patients’ shoes, and the foot has a normal arch shape with no Charcot Foot."], "imgs": ["diabetes-105.webp"]}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Inspection of Gait", "phase": "special", "tags": [], "pg": 169, "say": ["I would like to examine your gait with walking. Could you stand up and walk up and down the room, turning around to continue walking when you get to the end of the room?", "Can you please walk on the toes with both feet? And now the heels with both feet?", "Are you in any pain when you walk (re: foot damage, ulcers, Charcot’s Foot)? Does it feel like you are walking on foam/cotton wool, or are unable to feel the roughness of the ground (re: peripheral neuropathy)?"], "do": ["Assess patient’s gait for symmetry/balance. Assess how they turn – quick, slow, staggered? Observing for patients’ gait. Assess whether they’re adopting an antalgic gait re avoiding movements causing pain.", "Assess the patient’s gait for symmetry/balance."], "report": ["I note no gait abnormalities, with good symmetry, balance and quick turning."], "why": ["Assessing gait can provide a functional assessment of impact of chronic diabetes foot damage. It is important to note that patients with peripheral neuropathy may not present with an antalgic gait even with ulceration or foot damage. Gait can help assess peripheral neuropathy, looking at balance and heel walking. The likelihood of peripheral neuropathy is mildly decreased by no inability to walk on heels (LR- 0.76)."], "imgs": []}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Touch", "phase": "special", "tags": [], "pg": 169, "say": ["I will now test sensation in the feet, beginning with a monofilament test. I will ask you to close both eyes, and lightly press on each foot several times with this monofilament (show monofilament to patient). Say “yes” when you feel a light touch."], "setup": ["Need a 10-mmHg monofilament (a standardized tool to make sure you’re applying same pressure)."], "do": ["Press monofilament near sternal notch of chest of patient re sure to feel, then proceed to do so at locations indicated on diagram."], "report": ["I note a negative monofilament test, where each of the 10 locations tested elicited a patient response."], "why": ["Assessing for presence of sensory peripheral neuropathy via testing of the Posterior Columns (explored in Ch 31 – Screening Neuro Exam – MF4). The likelihood of peripheral neuropathy is greatly increased by inability to feel the monofilament in ≥5 of 8 trials (LR+ 11), while it is decreased by inability to feel the monofilament in only 0-1 of 8 trials (LR+ 0.54). Further, inability to feel the monofilament mildly increases the likelihood of subsequent foot ulceration (LR+ 2.4, LR- 0.5)."], "imgs": ["diabetes-106.webp"]}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Vibration", "phase": "special", "tags": [], "pg": 169, "say": ["I will now test sensation in the feet, using a tuning fork. I will ask you to close both eyes, and then the tuning fork will feel like a vibration when the tuning fork touches the foot (show tuning fork to patient). Please tell me when you begin to feel the vibration sensation, and when you can no longer feel the vibration sensation."], "setup": ["Use 128 Hz tuning fork. Test on your own sternum first. Strike the tuning fork hard so will vibrate for 40 seconds, then place it on the patient’s sternum to provide them a reference."], "do": ["Test dorsum of first toe on feet, as well as Medial Malleolus, Metatarsal Joint and Head of 1st Metatarsal Bone. Repeat the strike between each location. Ask the patient to report when they feel the vibrating tuning fork first placed on their feet, and then when the vibration dampens. Grading: 1st point if patient can perceive vibration sensation (on); 2nd point if patient can perceive vibration dampening (off)."], "report": ["I note a normal vibration test, where each time the patient sensed both the on sensation when the tuning fork was applied and the off sensation when the tuning fork was removed from the foot."], "why": ["Assessing for presence of sensory peripheral neuropathy via testing of the Posterior Columns (explored in Ch 31 – Screening Neuro Exam – MF4). The likelihood of peripheral neuropathy is greatly increased by inability to feel on-off sensation in ≥5 of 8 trials (LR+ 35), slightly increased by inability to feel on-off sensation in 2-4 of 8 trials (LR+ 3.9) and decreased by inability to feel on-off sensation in only 0-1 of 8 trials (LR+ 0.51). Further, the likelihood of peripheral neuropathy is greatly increased by timed toe vibration testing >20s sensation (LR+ 16), while it is decreased by <11s sensation (LR+ 0.33)."], "imgs": ["diabetes-107.webp"]}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Proprioception", "phase": "special", "tags": [], "pg": 169, "say": ["I will now test sensation in the feet by testing your sense of direction with toe pointing. I will ask you to close both eyes, then point the toe with my hand up or down, and ask you which direction the toe is pointing."], "setup": ["Stabilize the joint you’re testing and grab a toe from its sides. While the patient’s eyes are open, demonstrate “up” by extending the toe, and “down” by flexing the toe. Then have the patient close their eyes and tell you if they can feel their toe moving up or down."], "do": ["Move toe up or down, randomly, each time asking patient whether it is up or down."], "report": ["I note a normal proprioception test, where each time the patient sensed the direction of toe movement."], "why": ["Assessing extent of peripheral neuropathy elicited via testing of the Posterior Columns (explored in Ch 31 – Screening Neuro Exam – MF4)."], "imgs": []}, {"sec": "Special Test – Diabetes Foot Exam", "name": "Ankle Jerk Reflex", "phase": "special", "tags": [], "pg": 170, "say": ["I will now test the Achilles Tendon reflex using a reflex hammer. Please keep the leg relaxed."], "do": ["Loosen the patient’s ankle joint by rolling it around. Tap Achilles Tendon with reflex hammer. If patient’s reflex is difficult to elicit, can try the Jendrassik Maneuver (patient’s teeth clenched, fingers interlocked, and pull on the count of 3) for distraction. Clonus = seizure of the reflex (normal to see 2 beats of flapping of the foot). Grading: 0 = Absent; 1+ = Hypoactive (or requiring Jendrassik Maneuver); 2+ = Normal; 3+ = Hyperactive, no Clonus; 4+ = Hyperactive, with Clonus"], "report": ["I note a normal Grade 2+ Ankle Jerk Reflex bilaterally."], "why": ["Can help assess the extent of peripheral neuropathy. The ankle deep-tendon reflex (DTR) is innervated by S1-S2 (Tibial Nerve) (explored in Ch 31 – Screening Neuro Exam – MF4). Absence of deep tendon reflexes mildly increases the likelihood of suspected peripheral neuropathy (LR+ 3.6, LR- 0.36)."], "imgs": []}]}, "adrenal": {"title": "Adrenal", "pg": [179, 185], "notes": ["• OSCE Tip: Always start with the vitals in an OSCE situation with physical exam component", "• Inspection: For inspection, use a system-by-system approach as outlined in Part 1.", "• Communication Moment: Discussing weight gain as a chief complaint can be a sensitive topic for patients; consider how to develop good rapport while obtaining and conveying appropriate detail and information and develop strategies to use."], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 180, "do": ["• Blood Pressure, Heart Rate, Temp, and Orthostatic Vital Signs"], "why": ["• Blood Pressure: The presence of hypertension mildly increases the likelihood of suspected Cushing’s Syndrome (LR+ 2.3, LR- 0.8), while the absence of hypertension mildly increases the likelihood of suspected Pheochromocytoma (LR- 1.683). Hypotension is associated with Hypocortisolism.", "• Orthostatic Hypotension: Mildly increases the likelihood of Pheochromocytoma (LR+ 1.885, LR- 0.792), and is associated with Hypocortisolism as well.", "• Adrenal Crisis: Important cause of distributive shock (warm shock) – see Ch 9 – Volume Status – MF2. Presents with hypotension, tachycardia, and may present with fever (inflammatory response)"], "imgs": []}, {"sec": "Vitals", "name": "Waist Circum, Waist-Height Ratio, WaistHip Ratio and BMI – Adult", "phase": "vitals", "tags": [], "pg": 180, "say": ["Would it be alright if we measure your height, weight, hip circumference and waist circumference today? Set-Up: Ask permission before weighing someone, and never weigh a patient in front of others. Weighing scales should be placed in private areas in clinical spaces."], "do": ["13. Ask patient to remove shoes.", "14. Requires a weight scale, a method of measuring height, and a tape measure.", "15. Measure the patient’s weight and height using appropriate scales.", "16. For waist circumference, measure circumference at a level midway between the Iliac Crest and last palpable rib (WHO guidelines)", "17. For hip circumference, measure at the level with the widest portion of the buttocks.", "18. Using these measurements, calculate BMI (kg /m2), Waist-Height Ratio, and Waist-Hip Ratio."], "report": ["The height and weight we measured today were _____, with a BMI of ______."], "why": ["With respect to obesity in connection with Cushing’s Syndrome, the distribution of obesity is important. Where central obesity (e.g. abdominal) mildly increases the likelihood of Cushing’s Syndrome (LR+", "3.0, LR- 0.2), the presence of generalized obesity significantly decreases the likelihood of Cushing’s Syndrome (LR+ 0.1, LR- 2.5). To differentiate central and generalized obesity, the Waist-Height Ratio and Waist-Hip ratio are objective measures of central (abdominal) obesity. These calculated measures, including BMI, are imperfect, but clinically useful to monitor over time. Differential for weight changes include Nutritional state, malignancy, chronic illness, eating disorder, hyper/hypothyroid, hyper/hypocortisolism, etc. WHO Classification of Weight Status:", "Weight Status Under- Normal Range Overweight Class I Class II Class III Weight Obesity Obesity Obesity BMI (kg/m2) < 18.5", "18.5 – 24.9 25 – 29.9 30 – 34.9 35 – 39.9 ≥ 40"], "imgs": []}, {"sec": "Inspection", "name": "General Inspection – Head and Neck", "phase": "inspect", "tags": [], "pg": 181, "say": ["I will inspect the head and neck for signs of Adrenal disorders."], "do": ["Look at the patient’s head shape for moon facies (round head) and hair pattern for temporal hair loss (in cis-gender female patients). Look at the patient’s eyes for conjunctival pallor. Look at the patient’s skin for facial plethora (redness), hyperpigmentation (particularly in face and neck), oily complexion, acne and diaphoresis. Inspect the patient’s mouth for Thrush (white plaques that can scrape off the tongue). Look at the patient’s neck for increased neck thickness and signs of dorsocervical fat pad."], "report": ["I note no moon facies, skin and hair changes of the face and neck to suggest Cushing’s syndrome, or hyperpigmentation to suggest Hypocortisolism. I note no diaphoresis or pallor to suggest Pheochromocytoma. I note no signs of temporal hair loss to suggest virilization (in cis-gender female patient) Moon Facies1 Conjunctival Pallor2 Oral Candidiasis3 Dorsocervical Fat Pad4 Moon Facies1 Conjunctival Pallor2 Oral Candidiasis3 Dorsocervical Fat Pad4"], "why": ["• Hypercortisolism (Cushing’s Syndrome): Moon facies (round head) mildly increases likelihood of suspected Cushing’s syndrome, while its absence greatly reduces its likelihood (LR+ 1.6, LR- 0.1). The likelihood of suspected Cushing’s syndrome is mildly increased by Facial plethora (LR+ 2.7, LR- 0.3) and Acne (LR+ 2.2, LR- 0.6). Hyperpigmentation can occur due to increased ACTH (as in Cushing’s disease). Note that facial plethora can be an indicator of other conditions, including dermatologic conditions such as rosacea or sunburn, hematologic conditions such as polycythemia vera, and vascular emergencies such as superior vena cava syndrome. Thrush can be an indication of immunosuppression associated with glucocorticoid excess as in Cushing’s Syndrome.", "• Virilization: Alongside hirsutism (see below), deepened voice and clitoral enlargement, oily skin and temporal hair loss can be signs of virilization (androgen excess) in patients assigned female sex at birth.", "• Hypocortisolism: Hyperpigmentation can be a sign of Hypocortisolism (e.g. Addison’s disease, Adrenal insufficiency) particularly in sun-exposed areas (e.g. face, neck, back of hands) and areas of chronic friction (e.g. elbows, knees, knuckles, waist on belt line, and shoulders along bra line).", "• Pheochromocytoma: Conjunctival pallor mildly increases likelihood of Pheochromocytoma (LR+ 4.667, LR- 0.718), and diaphoresis mildly increases the likelihood of Pheochromocytoma (LR+ 2.184, LR- 0.451). Modification for Transgender Patients:", "• Transmasculine Patients (FTM): Patients on masculinizing hormone therapy may have oilier skin, more acne, increased facial and body hair, or ↓ scalp hair – important to normalize these changes.", "• Transfeminine Patients (MTF): Patients on feminizing hormone therapy may have softening of skin/decreased skin oiliness, less acne, thinning/slowed growth of facial and body hair, or arrested progression of scalp hair loss – important to normalize these changes."], "imgs": ["adrenal-113.webp", "adrenal-114.webp", "adrenal-115.webp", "adrenal-116.webp"]}, {"sec": "Inspection", "name": "Inspection – Arms", "phase": "inspect", "tags": [], "pg": 182, "say": ["I will inspect the arms and hands for signs of Adrenal disorders. Acanthosis Nigricans5, 6"], "do": ["Inspect at the patient’s axilla for acanthosis nigricans (hyperpigmentation re. Cushing’s syndrome). Inspect the patient’s shoulders along bra line and elbows for hyperpigmentation (re. Hypocortisolism). Inspect the patient’s dorsal surface of hands, knuckles and palmar creases for hyperpigmentation (re. Hypocortisolism). Assess palmar creases and nailbeds for pallor."], "report": ["I note no acanthosis nigricans, hyperpigmentation or pallor. Acanthosis Nigricans5, 6"], "why": ["Acanthosis nigricans (hyperpigmentation of skin in body folds e.g. axilla, intertriginous areas) can be a sign of Cushing’s Syndrome, also seen in Diabetes Mellitus. Hyperpigmentation can be a sign of Hypocortisolism (e.g. Addison’s disease, Adrenal insufficiency) particularly in sun-exposed areas (e.g. face, neck, back of hands) and areas of chronic friction (e.g. elbows, knees, knuckles, waist on belt line, and shoulders along bra line). Pallor mildly increases the likelihood of Pheochromocytoma (LR+ 4.667, LR- 0.718)"], "imgs": ["adrenal-117.webp", "adrenal-118.webp"]}, {"sec": "Inspection", "name": "Inspection – Abdomen", "phase": "inspect", "tags": [], "pg": 182, "say": ["I will inspect the abdomen for signs of Adrenal disorders."], "do": ["Inspect for red, purple or blue striae >1cm wide particularly along the abdomen and lower flanks."], "report": ["I note no purple striae to suggest Cushing’s syndrome."], "why": ["Red, purple or blue striae occur as fragile skin stretches with enlarging trunk, breasts and abdomen, which mildly increases the likelihood of Cushing’s syndrome (LR+ 1.9, LR- 0.7). Note that striae distensae also occur in pregnancy – where over time, these progress to striae alba (hypopigmented with fine wrinkling) and tend to be thinner and less prominent than striae seen in Cushing’s syndrome."], "imgs": ["adrenal-119.webp"]}, {"sec": "Inspection", "name": "Hirsutism", "phase": "inspect", "tags": ["conditional"], "pg": 182, "say": ["I will inspect the skin for hair growth and Ferriman-Gallway Visual Scale7 signs of Adrenal disorders."], "setup": ["In this exam, draping is important, with sequential exposure of examined areas after obtaining consent. For dermatological exam in sensitive areas, consider the role of a chaperone."], "do": ["Inspect Upper lip; Chin; Mid-sternum; Upper Arms; Upper & Lower Abdomen; Thighs; Upper & Lower Back for terminal hair growth (dark, coarse hairs). Record score of 0 (no hair) to 4 (frankly virile) for each region, as outlined in the Ferriman-Gallway Visual Scale (see right)."], "report": ["The patient’s Ferriman-Gallwey hirsutism score is 5. There is no evidence of hirsutism."], "why": ["Hirsutism is defined by excess terminal hair growth (dark, coarse hairs) in androgen-dependent areas (i.e. 9 regions tested above). The presence of hirsutism mildly increases the likelihood of Cushing’s Syndrome (LR+ 1.7, LR- 0.7); other causes include Polycystic Ovary Syndrome (PCOS), Hyperprolactinemia, Thyroid disorders, Acromegaly, and drug-induced (including a number of neuroleptic medications, SSRIs, SNRIs, and corticosteroids). One way to grade Hirsutism is the Ferriman-Gallwey hirsutism score, which scores each of 9 regions from 0 (no hair) to 4 (frankly virile). This system has limitations (e.g. originally a population study of Caucasian female patients in England). It has been adapted with cut-off scores for hirsutism in female patients vary by race/ethnicity: ≥2 in Asian populations; ≥8 in Black or Caucasian populations; and ≥9 for Mediterranean, Hispanic and Middle Eastern populations. A score of <15 is considered mild hirsutism, 16-25 moderate, >25 severe. Conversely, loss of hair may indicate Hypocortisolism (e.g. Adrenal insufficiency, Addison’s Disease). Modification for Transgender Patients:", "• Transmasculine Patients (FTM): Patients on masculinizing hormone therapy may have oilier skin, more acne, increased facial and body hair, or ↓ scalp hair – important to normalize these changes, where the Ferriman-Gallwey hirsutism score would not apply here.", "• Transfeminine Patients (MTF): Patients on feminizing hormone therapy may have softening of skin/decreased skin oiliness, less acne, thinning/slowed growth of facial and body hair, or arrested progression of scalp hair loss – important to normalize these changes, where the Ferriman-Gallwey hirsutism score would not apply here."], "imgs": ["adrenal-120.webp"]}, {"sec": "Inspection", "name": "Coagulopathy", "phase": "inspect", "tags": [], "pg": 183, "say": ["I will inspect the skin for signs of coagulopathy."], "do": ["Assess for Hematomas: Based on size, either Petechiae (1-2 mm diameter red spot), Purpura (3-10 mm), and/or Ecchymosis (>10 mm); as well as Telangiectasias (spider veins)"], "report": ["I note no petechiae, purpura or ecchymosis on inspection."], "why": ["Generally, these are important signs of platelet or vascular disorders. In the context of an Adrenal exam, Ecchymosis mildly increases the likelihood of Cushing’s Syndrome (LR+ 4.5, LR- 0.5)."], "imgs": ["adrenal-121.webp", "adrenal-122.webp"]}, {"sec": "Palpation", "name": "Skinfold measurement with Calipers", "phase": "palpate", "tags": [], "pg": 183, "say": ["I will measure the thickness of the skin of the hand using calipers."], "do": ["Using skin-safe calipers (if available in your clinical setting, ensure caliper points are dulled), hold the patient’s non-dominant hand (e.g. left hand if patient is right-handed) with palm facing down. At the 3rd digit (D3), palpate dorsal skin between the 3rd Metacarpophalangeal (MCP) and 3rd Proximal Interphalangeal (PIP) Joints. Grasp dorsal skin between your 1st an 2nd fingers to create skinfold. Measure skin thickness with calipers."], "report": ["I note the patient’s skin thickness is 3 millimeters, a negative test for Cushing’s Disease."], "why": ["A thin skinfold of <1.8 mm on back of patient’s hand using calipers to measure greatly increases the likelihood of Cushing’s Syndrome (LR+ 115.6, LR- 0.2). Note the population under study was young women with hirsutism and menstrual irregularities, where these findings are most applicable to similar patients1."], "imgs": []}, {"sec": "Palpation", "name": "Edema", "phase": "palpate", "tags": [], "pg": 183, "say": ["I will palpate for leg swelling (Sacral edema if patient immobile). Please tell Pedal Edema10 me if you are in discomfort."], "do": ["Press firmly with pads of your thumbs on the dorsal surface of patient’s leg, just above the ankle at bony prominence. Hold for 10s, then release. Look for pitting edema – skin does not bounce back immediately (i.e. pits). How high does it go on the leg? Is it pitting (transudate) or non-pitting (exudate)? Look at patient for signs of discomfort and stop exam signs of distress. Grading: 0 = none; 1+ = 2mm depression; 2+ = 4mm depression; 3+ = 6mm depression; 4+ = 8mm depression"], "report": ["I note (grade) pitting edema bilaterally, up to the level of (location e.g. ankles)."], "why": ["In the context of an adrenal exam, dependent edema mildly increases the likelihood of Cushing’s syndrome (LR+ 1.8, LR- 0.7). Edema is excess interstitial fluid accumulation causing swelling, particularly in gravity dependent areas (e.g. feet). Normally, this fluid returns through lymphatic drainage. Pitting edema = transudate (non-protein filled) – sign of increased hydrostatic pressure (e.g. congestive heart failure, decreased venous return) or decreased oncotic pressure (e.g. nephrotic syndrome, hypoalbuminemia). Non-pitting edema = exudate (protein) filled, or an issue with lymphatic drainage (e.g. lymphedema)."], "imgs": ["adrenal-123.webp"]}]}, "breast": {"title": "Breast", "pg": [247, 249], "notes": ["• Key Idea: It is essential to conduct sensitive exams in a patient-centred, trauma-informed way before, during, and after exams. This includes close attention to privacy, consent, draping, verbal communication and non-verbal communication. For more information, see Ch 4 – Vital Signs and Introduction to Patient-Centred Physical Exams – MF1. Third-Party Attendance at Intimate Examinations (See CPSO Policy – Boundary Violations)4: Physicians must give patients the option of having a third-party present (e.g. Support Person, or Chaperone) during an intimate examination, including bringing their own third party if the physician does not have one (See Ch 4 – Vital Signs – MF1 for more info)."], "steps": [{"sec": "Inspection", "name": "Localized Differences", "phase": "inspect", "tags": [], "pg": 247, "say": ["I will inspect for localized differences between the breasts such as lumps, skin dimples and differences.", "Could you lie back on the exam table, with one arm resting under your head?", "Can you switch the arm resting under your head?"], "setup": ["Patient should be sitting with both arms at sides, hands on knees initially."], "do": ["Inspect the skin for changes, as well as the nipple for discharge. Check the skin for Peau d’orange (Orange Peel Skin), Dimples (Ask patient to lift arms or press on hips re: tensing pectoral muscles, pulls on Cooper’s ligaments to reveal dimpling), Retracted Nipples, or Dermatitis of Areola. If you note any discharge, comment on Amount, Consistency, Colour and Odor. Also inspect for redness (mastitis) and for breast abscess.", "Repeat inspection for same features on other breast"], "report": ["USE CLOCK METHOD TO REPORT FINDING (X minutes from nipple to finding). I note no discharge, redness, skin changes, dimpling, nipple inversion or abscesses."], "why": ["No longer part of screening for breast cancer (no difference in outcomes over & above mammogram). Still a part of clinical encounters (e.g. for symptomatic patients). Now the focus is on palpation. While you are palpating the breast, you can continue to inspect for the findings outlined above as well.", "• Malignant: Bloody discharge may represent intraductal papilloma (benign papillary tumor in lining of breast duct) or breast cancer (e.g. ductal carcinoma in situ, invasive ductal carcinoma). Skin erythema, retraction or dimpling, peau d’orange, nipple inversion may all be signs of locally advanced breast cancer. Peau d’orange with tenderness, burning and blood-tinged nipple discharge may be seen in inflammatory breast cancer. Erythematous/scaly/vesicular/ulcerated rash that begins at the nipple and spreads to areola may represent Paget disease of the breast.", "• Non-malignant: Clear or slightly milky nipple discharge may represent fibrocystic breast changes (most common benign lesion). Milky or bloody nipple discharge can also represent mastitis if present with signs of inflammation (e.g. swelling, erythema, warmth). Skin retraction, erythema and bruising may represent fat necrosis (benign). A fluctuant, tender, palpable mass with red streaks around the mass and constitutional symptoms may represent a breast abscess. Eczema of the breast (benign) may present with an eczematous rash with poor margins and pruritis and may become complicated by secondary cellulitis. In lactating patients, a plugged duct may present with a tender and painful lump without systemic findings.", "• Presenting with new symptoms of breast cancer (e.g. concerning nipple discharge, new nipple retraction, sin changes of nipple or breast, asymmetric thickening/nodularity) warrants further imaging2:", "◦ Patient <30 years old and/or breastfeeding or pregnant → Ultrasound (re. density of breast tissue)", "◦ Patient 30-40 years old → Ultrasound ± Mammogram ± Galactography (in appropriate context)", "◦ Patient >40 years old → Ultrasound and Mammogram ± Galactography (in appropriate context) Modification for Patients who are Transgender:", "• Transmasculine Patients (FTM): Transmasculine patients may use a binder to flatten their chest. They may not use the word “breast” and may instead refer to their chest or use another word of their choice. If they have had top surgery, you may see evidence of a scar and/or chest contouring.", "• Transfeminine Patients (MTF): Patients on feminizing hormone therapy may have some breast tissue development. If they have had top surgery (aka breast augmentation), you may notice breast implants and/or nipple reconstruction on exam, and you may see evidence of scars from the procedure."], "imgs": []}, {"sec": "Inspection", "name": "Tanner Staging (Adolescent Females) – Breast Development", "phase": "inspect", "tags": [], "pg": 248, "say": ["I will inspect the breasts for adolescent development."], "do": ["Inspect the breasts according to Tanner Staging. What is Normal Breast Tanner Staging?", "• Stage 1 – No glandular tissue, areola following skin contours of breast (Age 10 and younger)", "• Stage 2 – Breast bud forms, small area of glandular tissue around it; areola widens (Age 10-11.5)", "• Stage 3 – Breast becomes more elevated, extends beyond areola which continues to be in contour with rest of the surrounding breast (Age 11.5-13)", "• Stage 4 – Increased size and elevation; areola and papilla form secondary mound projection from contour of surrounding breast (Age 13-15)", "• Stage 5 – Final adult size; areola in contour with breast, projecting central papilla (Age 15+)"], "report": ["Based on tanner staging of breasts, patient is in Tanner Stage 4."], "why": ["Important tool for measuring development based on primary and secondary sex characteristics – for Tanner Staging of Pubic Hair, see Chapter 19 – Sensitive Pelvic Examinations; normal progression is breast development (thelarche) → pubic hair development (pubarche) → growth spurt → menarche. Modification for Transfeminine Patients (MTF): Patients on feminizing hormone therapy may have some breast tissue development. If they have had top surgery (aka breast augmentation), you may notice breast implants and/or nipple reconstruction on exam, and you may see evidence of scars from the procedure."], "imgs": []}, {"sec": "Palpation", "name": "Lumps Assessment", "phase": "palpate", "tags": [], "pg": 248, "say": ["I will now palpate the breast. Can you roll the pelvis to the opposite side, bring the shoulder back and make it flat with the exam table, and place the hand on your forehead in a “drama queen” pose?", "• Once palpation reaches the midclavicular line, ask patient to change positions to lay flat on the exam table, and have their elbow raised to the same level as their shoulder. This will shift breast tissue and make the medial half of the breast flat with the chest wall so you can palpate more medial structures", "• Note: Your technique depends on breast size. If the breast is large and extends over the abdominal wall, you will need to have one hand underneath the section of the breast sitting on top of the abdominal wall, while your other hand is palpating the breast anteriorly."], "do": ["Breast palpation for lumps assessment should take ~ 3 minutes per breast.", "• Breasts are bounded superiorly by the clavicle, inferiorly by the inframammary crease (“bra line”), medially by the sternum, and laterally by the mid-axillary line.", "• Palpate each breast using the Vertical Pattern technique (“Mowing the lawn”) with 3 pads of fingers with enough pressure you bring the skin with you as you palpate in circles (Light Pressure → Medium → Firm).", "• With patient in “drama queen” pose, start mid-axillary line, high near axilla, down to the inframammary crease (“bra line”), mowing lawn technique proceeding medially, palpating the lateral breast.", "• Once reaching Midclavicular line, have patient put hips flat and elbow raised to same level of the shoulder to shift structures so medial breast now at chest wall, and continue palpating.", "• Once reaching nipple, use “claw” technique. Note tenderness, pulsatility, warmth & colour. If you detect lesions, note size, shape, location, consistency and colour. Check for discharge from the nipple."], "report": ["I note no concerning lumps (if you do, use clock method re X minutes from nipple to finding)."], "why": ["Looking for evidence of cysts or cancerous growths.", "• Breast Implants: Placed deep to pectoral muscle; therefore, any lumps will be above it", "• Cysts – Round lump (Mushroom)", "• Cancerous – Multi-lobed (Broccoli)", "• Presenting with new symptoms of breast cancer (e.g. palpable mass) warrants further imaging3:", "◦ Patient <30 years old and/or breastfeeding or pregnant → Ultrasound (re. density of breast tissue)", "◦ Patient 30-40 years old → Ultrasound ± Mammogram ± Galactography (in appropriate context)", "◦ Patient >40 years old → Ultrasound and Mammogram ± Galactography (in appropriate context)"], "imgs": ["breast-124.webp"]}, {"sec": "Palpation", "name": "Lymph Nodes", "phase": "palpate", "tags": [], "pg": 248, "do": ["• Note: Important to include palpation of lymph nodes in the supraclavicular, Infraclavicular & axillary Lymph Node regions; for how to conduct a Lymph Node exam, see Chapter 11 – Lymph Node Exam –MF2"], "why": ["Lymphadenopathy in these regions can be indicative of metastasis of breast cancer"], "imgs": []}]}, "neuro": {"title": "Neurological", "pg": [334, 374], "notes": ["• Key Principle: Within a screening neuro exam, ask where is the lesion – and does this test help me with figuring that out? For particular patient presentations, it is important to establish a baseline neuro exam that can be tracked serially.", "• Tools you will need for a screening neuro exam: Percussion hammer (Reflex Testing); Pocket Snellen Acuity Card (CN II); Flashlight (CN II); Ophthalmoscope (CN II); Pins (Spinothalamic Sensory Exam); Cotton Ball (Posterior Column Sensory Exam) Pediatric Neurologic Exam: Age-Appropriate Toys and Objects (especially for Cranial Nerve & Coordination Exams)"], "steps": [{"sec": "Vitals", "name": "Vitals: what to look for in this exam", "phase": "vitals", "tags": [], "pg": 351, "do": ["• Blood Pressure:", "◦ Hypertension – Risk factor for stroke/TIA, cerebral artery dissection and intracranial hemorrhage.", "◦ Hypertensive Emergency – Severely elevated BP (e.g. >180/120 mmHg) with end-organ damage (e.g. hypertensive encephalopathy, acute aortic dissection, acute LV failure, acute coronary syndrome, acute kidney injury, intracranial hemorrhage, acute ischemic stroke, eclampsia in pregnancy).", "◦ Hypertensive urgency: Severely elevated BP without evidence of end-organ damage.", "◦ Elevated ICP – Look for Cushing’s Triad (bradycardia, widened pulse pressure, irregular respirations)", "◦ In a patient with a coma, the likelihood of having an intracranial structural lesion is greatly increased with sBP >160 mmHg (LR+ 10.4), and greatly decreased with sBP <120 mmHg (LR+ 0.1).", "• Oxygen Saturation: In patients with recent strokes, the likelihood of significant aspiration risk is greatly increased if patient experiences oxygen desaturation 0 to 2 min after swallowing (LR+ 3.1, LR- 0.3).", "• Temperature: Classic triad for meningitis = fever, nuchal rigidity and altered mental status"], "imgs": []}, {"name": "Level of consciousness – Glasgow Coma Scale", "ref": "gcs", "do": ["• Quick screen: Alert & Oriented ×3 (person, place, time).", "• If level of consciousness is reduced, score GCS (min 3, max 15): Eyes /4, Verbal /5, Motor /6 (table below)."], "why": ["Altered mental status is an acute emergency needing prompt assessment and treatment. Etiologies may be acute or chronic, reversible or irreversible. In cases of Traumatic Brain Injury (TBI), the GCS helps to grade TBI severity: A mild TBI has GCS 13-15; moderate TBI has GCS 9-12; severe TBI has GCS ≤ 8. GCS is also important as a prognostic tool for patients following cardiac arrest. In a patient with ↓ level of consciousness, it is helpful to look for focal or lateralizing signs (asymmetry between right-and left-sided responses e.g. on cranial nerve, motor, deep tendon reflex, brainstem reflex exams) and Meningismus (e.g. Kernig Sign, Brudzinski Sign, Jolt Accentuation of Headache) on exam to inform a differential diagnosis:"], "sec": "General Assessment", "phase": "inspect", "tags": [], "pg": 351, "imgs": []}, {"name": "Behaviour", "do": ["• Aggression, verbal or motor tics, pacing"], "sec": "General Assessment", "phase": "inspect", "tags": [], "pg": 351, "imgs": []}, {"name": "Cognitive function", "do": ["• Can administer Mini-Mental Status Examination (MMSE – Click here for link), Montreal Cognitive Assessment (MOCA – Click here for link), or Mini-Cog (Click here for link) to screen.", "• Explored further in Chapter 36 – Assessment of Psychosis, Delirium and Dementia – MF4"], "sec": "General Assessment", "phase": "inspect", "tags": [], "pg": 351, "imgs": []}, {"name": "Language", "do": ["• Assess Naming: Ask patient to name their hand, finger, fingernail, common objects (e.g. pencil)", "• Fluency: Ask “how do you get from your house to the hospital?", "• Commands: Ask patient a simple 3-step command across the midline, e.g. with your right hand, touch your left shoulder, then point to the ceiling, then close your eyes.", "• Repetition: Ask patient to repeat: “no ifs, ands or buts”; or “you can’t teach an old dog new tricks”", "• Optional Tests: Can also check reading (Dyslexia), writing (Dysgraphia), and counting (Dyscalculia – e.g. Serial 7s test subtracting 7 from 100 sequentially e.g. 100, 93, 86, 79 etc. as tested on MOCA) – Explored further in Chapter 36 – Assessment of Psychosis, Delirium and Dementia – MF4)"], "why": [], "sec": "General Assessment", "phase": "inspect", "tags": [], "pg": 351, "imgs": []}, {"name": "Dysmorphia", "do": ["• More important in pediatric populations (e.g. Down syndrome)"], "sec": "General Assessment", "phase": "inspect", "tags": [], "pg": 351, "imgs": []}, {"name": "Abnormal movements", "do": ["• Athetosis: slow, continuous, writhing movements of distal body parts, especially fingers/hands", "• Chorea/ballism: chaotic, random, repetitive, brief, purposeless movements (large-amplitude chorea = ballism)", "• Dystonia: repetitive, sustained abnormal postures/movements, often with a twisting quality", "• Myoclonus: sudden, brief, shock-like movements that may be repetitive or rhythmic", "• Tremor (rest vs. postural vs. intention) and bradykinesia (slowness, progressively smaller movements on repeated finger taps)"], "sec": "General Assessment", "phase": "inspect", "tags": [], "pg": 351, "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "I (Olfactory)", "phase": null, "tags": [], "pg": 353, "say": ["I will now be checking your sense of smell with Coffee and Cinnamon samples. Close your eyes, cover one nostril, and let me know what you smell."], "do": ["Hold up coffee grinds sample near to each nostril, ask smell they detect. Repeat with cinnamon."], "report": ["Sense of smell intact, no evidence of olfactory nerve lesion."], "why": ["Check if concern for smell loss (hyposmia or anosmia). Olfactory nerve is a sensory nerve that projects from olfactory tract, where deficits cause anosmia. Note this can occur in Parkinson Disease."], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "II (Optic)", "phase": null, "tags": [], "pg": 353, "do": ["Part 1: VISUAL ACUITY:", "• Say: I will assess your vision reading an eye chart. If you have glasses or contacts, please keep them on as I need to test your corrected vision. Please cover one eye.", "• Setup: Holding pocket Snellen chart to patient’s nose 16 inches from patient’s nose (slightly more than a card length) to ensure an appropriate reading distance.", "• Do: With one eye covered, read from bottom of card up, reading the lowest line they can. Then, cover the other eye, and read from top down, until they reach the lowest line they can (this prevents the patient from remembering the lines which would obscure results)", "• Report: The patient has a vision of 20/20 in both the left and right eye Part 2: CONFRONTATIONAL VISUAL FIELDS:", "• Say: I will now be checking your vision in 4 quadrants in each eye by counting fingers. If you have glasses or contacts, please keep them on. Please stare at my nose during this test.", "• Setup: Sit at same level as patient. Key idea –you are the standard the patient is compared to i.e. symmetry should exist between you and patient to test the same visual field. When holding up fingers, use 0, 1 or 2 fingers in a plane perpendicular to axis formed by examiner and patient’s noses.", "• Do: The patient should close and cover one eye while you close opposite eye, so you have same field of vision. Hold out your hand in one quadrant equidistant between yourself and pt (fingers in same visual field). How many fingers am I holding up? Repeat in all 4 quadrants and for other eye.", "• Report: The patient has a normal field of vision bilaterally in all 4 quadrants. If any visual field defects, record your findings using circle diagrams noting defects in quadrants of each eye. Part 3: PUPILLARY RESPONSE TO LIGHT:", "• Say: I will assess each eye’s response to light. Please remove your glasses and keep both eyes open during this test.", "• Do: Inspect pupil size (Snellen Pocket card tends to have a guide). ≤1 mm difference between two eyes is normal. Using a flashlight, shine light in one eye. Look for pupillary constriction both direct and consensual (part of the Pupillary Light Reflex). Repeat in the other eye. Then, swing flashlight back and forth between both eyes, where each pupil should constrict (i.e. no relative afferent pupillary defect).", "• Report: Pupils are equal and reactive to light, and there is no relative afferent pupillary defect. Part 4: FUNDOSCOPIC SCREEN:", "• Say: I will now inspect each eye using a direct ophthalmoscope. You will feel my hand touch the shoulder to keep the ophthalmoscope steady. Please look at an object on the wall in the distance at your eye level (preventing constriction due to pupillary accommodation reflex)", "• Setup: Room should still be dim. Stand facing the patient; if you’re examining the patient’s right eye first, use your right eye to look (vice versa). Adjust the scope’s focus (if you’re not wearing your nearsighted prescription glasses, may take more adjusting) by focusing on an object in room. Use low-moderate light intensity typically with medium aperture.", "• Do: Steady your hand on their shoulder. Shine the light from ophthalmoscope in patient’s eye; should see the red reflex. Follow reflex and slowly move toward patient. Find an artery and follow that towards the centre. You should come upon the optic disc (head of optic nerve, a confluence of retinal nerve fibers exiting the globe) and the optic cup (white centre of optic disc). Look for signs of optic disc swelling, and loss of venous pulsations. Follow the Superonasal Arcade, Inferonasal Arcade, Superotemporal Arcade, and Inferotemporal Arcade. Focus on Macula (temporal to optic disc), which contains Fovea where you can see a Yellow Reflex in healthy people. Look for signs of hemorrhages, neovascularization (small branching vessels) and cotton wool spots (fluffy white patches).", "• Report: The optic disc was visualized in each eye, with no signs of optic disc swelling, neovascularization or loss of venous pulsations."], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "III (Oculomotor) IV (Trochlear) & VI (Abducens) Note: Extraocular movements also explored in Ch 40 – Ophtho Exam – IF", "phase": null, "tags": [], "pg": 354, "say": ["I will assess movements in each eye; please focus on my finger without turning your head."], "do": ["Move in a slow H pattern and observe eye movements of patient. As you move your finger slowly, observe a smooth pursuit where eyes have a conjugacy of gaze (align to focus on your finger). Give patient feedback if you notice them visibly moving their head as they track, as this prevents testing lateral aspects of ocular movements. Ensure there are no restrictions in eye movements at extremes of gaze."], "report": ["I note conjugacy of gaze with smooth pursuit, no nystagmus or abnormal eye movements."], "why": ["CN VI (pons) is a motor nerve that mainly abducts (laterally moves) eye. CN IV (midbrain) is a motor nerve that mainly depresses the eye during adduction (medial movement) of the eye. CN III (midbrain) is a mixed nerve with oculomotor nucleus (motor) controlling all movements except lateral horizontal movement; and Edinger-Westphal nucleus (parasympathetic pre-ganglionic nucleus) controlling pupil dilation. The deficit in eye movements can indicate which CN is impacted. Findings to watch for include:", "• Nystagmus: Upset of eye control balance, with slow drift in one direction followed by fast corrective movement. Nystagmus maximal when eyes are turned in direction of fast phase; may be horizontal or vertical. If observed, note direction of fast phase, and gaze direction where nystagmus is maximal. In patients presenting with dizziness, direction-changing nystagmus mildly increases the likelihood of stroke (LR+ 4.51, LR- 0.68).", "• Saccadic Intrusions on Smooth Pursuit: Indicative of Cerebellar lesions (could also be due to an injury of one of muscles e.g. post-trauma to the facial area).", "• Screening Question on Hx: Do you see double? May indicate subtle lesion not picked up on exam. Interpretations of Isolated Palsies:", "• CN III Isolated Palsy: Affected eye usually in “down and out” position, can have ptosis (droopy eyelid) or loss of pupil constriction (both of these are also controlled by CN III).", "◦ If pupils are dilated, consider posterior communicating artery aneurysm", "◦ If pupils are not dilated, consider ischemic lesions (e.g. due to diabetes, giant cell arteritis)", "• CN IV Isolated Palsy: Affected eye usually in “up and out” position, patient has limitations looking down or will have diplopia (double vision) in this position. Consider head trauma– head, cavernous sinus, orbital injury; or consider infarct", "• CN VI Isolated Palsy: Affected eye usually in “inward” position, patient has limitations looking outward or will have diplopia (double vison) in this position.", "◦ Consider ↑ ICP, or ischemia/lesions in skull base, or head trauma"], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "V (Trigeminal)", "phase": null, "tags": [], "pg": 355, "do": ["Part 1: Motor:", "Palpate temporalis muscle at temples, masseter and pterygoid muscles at upper cheeks.", "Test ophthalmic (above eyebrows), maxillary (lateral to nose) and mandibular (inferior to lips) divisions of the trigeminal nerve with a cotton ball (i.e. testing Posterior Column Tract – see Sensory Exam below) and with pin prick (i.e. testing Spinothalamic Tract – see Sensory Exam below)"], "say": ["When you feel my hand on the cheek, please clench the jaw.", "I will check for sensation of the face using a cotton ball. Close both eyes and tell me when you feel the cotton ball touch the face."], "report": ["I note normal muscle bulk and power in the temporalis, masseter and pterygoid muscles Part 2: Sensory:", "Full sensory function at ophthalmic, maxillary and mandibular divisions of the trigeminal nerve"], "why": ["Trigeminal Nerve (CN V) is a mixed nerve that originates in the pons with three divisions – ophthalmic (V1 – sensory), maxillary (V2 – sensory) and mandibular (V3 – mixed motor + sensory).", "• Pterygoid Muscle Weakness: If unilateral weakness, jaw will deviate to the weak side.", "• Interpretations: Lesions may indicate Trigeminal neuralgia, stroke, cerebellopontine lesions, Herpes Zoster, etc.; high sensitivity but low specificity in thalamic/hemispheric injury"], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "VII (Facial)", "phase": null, "tags": [], "pg": 355, "say": ["I will assess the muscles of facial expression."], "do": ["Ask patient to raise brows; close eyes shut; blow out cheeks; and smile/show teeth. Look for asymmetry (e.g. eye closure, elevated corner of mouth, flattened nasolabial fold); minor asymmetry may be normal."], "report": ["I note full motor function in the facial nerve."], "why": ["Facial Nerve (CN VII) is a mixed nerve originates in pons. We only test the motor component here.", "• Solitary nucleus (sensory) with lesions causing loss of taste of anterior 2/3rds of tongue", "• Motor nucleus with lesions causing hyperacusis ipsilateral to lesion (due to deficits of Stapedius muscle which dampens excess movement of stapes movement reaching inner ear), and facial muscle paralysis.", "◦ Interpretations - Does it spare the forehead? An UMN lesion spares the forehead; a LMN lesion (e.g. Bell’s Palsy) does not, and one side of the forehead will sag downward.", "• Superior salivatory nucleus (parasympathetic pre-ganglionic) – lesions cause dry mouth and dry eye (deficits of greater petrosal nerve supplying sublingular, submandibular and lacrimal glands)"], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "VIII (Vestibulocochlear) – Whispered Voice Screening Test", "phase": null, "tags": [], "pg": 355, "say": ["I will now assess hearing. I will stand behind you, cover one of the ears with one finger, then whisper a combination of 3 numbers and letters. Please repeat back the 3 numbers or letters you hear."], "setup": ["• With patient seated, stand arm’s length (2 feet) behind the patient (to prevent lip reading).", "• Mask the hearing in one ear using your finger to gently occlude and rub the external auditory canal.", "• A trial run using a loud voice to ensure the patient understands the instructions may be helpful."], "do": ["• Examiner takes in a full breath, exhales, then whispers 3 random numbers and letters (e.g. “5, B, 6”).", "• Ask the patient to repeat the 3 numbers and letters. If the patient repeats all 3 numbers and letters correctly, this is a normal result.", "• If the patient responds incorrectly, repeat the test using a new combination of numbers and letters (e.g. “D, 1, C”). The screening test is normal if the patient repeats 3 out of 6 total letters/numbers correctly.", "• Repeat with the other ear, using new combination of numbers and letters."], "report": ["You repeated 3 out of 6 letters correctly with each ear. This is a normal whispered voice screening test for hearing loss."], "why": ["Vestibulocochlear Nerve (CN VIII) is a sensory nerve that originates in pons. A lesion to vestibular nucleus causes Vertigo, disequilibrium and nystagmus. A lesion to cochlear nucleus causes deafness. Hearing tests such as the Whispered Voice Screening Test, and the Weber and Rinne’s tests focuses on the Cochlear nucleus component, whereas tests such as the HINTS exam and Romberg test can help identify lesions of the vestibular nucleus e.g. in central vertigo (Click for Link – see below). If you find evidence of hearing loss, a neurotologist may be helpful for more rigorous diagnostic testing and formal diagnosis. The Whispered Voice Screening test is a helpful initial screening test that doesn’t require tuning forks (Weber’s and Rinne’s Tests do – see Ch 7 – Head and Neck Exam – MF1). The likelihood of hearing loss is moderately increased by an abnormal whispered voice test (LR+ 6.0) and greatly decreased by a normal whispered voice test (LR- 0.03). This screening test cannot differentiate sensorineural from conductive hearing loss, where Weber and Rinne testing can help delineate conductive, sensorineural and mixed hearing loss. An alternative initial screening test, called the Finger Rub Test, is detailed below and in Ch 7 – Head and Neck Exam – MF1."], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "IX (Glossopharyngeal) & X (Vagus)", "phase": null, "tags": [], "pg": 356, "say": ["I will now assess the palate and uvula. Can you open the mouth and say “ahh”?"], "do": ["Listen to the patient’s voice. If high pitched may indicate vocal cord paresis (CN X palsy). Ask patient to open their mouth and say “ah”? Look for asymmetric palatal movement, uvular deviation"], "report": ["I note no abnormal palate movement, and uvula is midline on examination"], "why": ["We only test motor components of CN IX and CN X here.", "• The Glossopharyngeal Nerve (CN IX) is a mixed nerve that originates in the medulla, with 3 Nuclei:", "◦ Nucleus Ambiguus (Sensory nuclei) – lesions causing loss of taste to posterior 1/3rd of tongue", "◦ Solitary Nucleus (Motor nuclei) – lesions causing loss of gag reflex", "◦ Inferior Salivatory Nucleus (parasympathetic pre-ganglionic nuclei) – lesions causing ↓ salivation (due to deficits of the lesser petrosal neve supplying parotid gland)", "• The Vagus Nerve (CN X) is a mixed nerve that originates in the medulla, with 3 Nuclei:", "◦ Solitary Nucleus (Sensory nuclei) – lesions causing loss of taste", "◦ Nucleus Ambiguus (Motor Nuclei) – lesions causing dysphagia and hoarseness of voice", "◦ Dorsal Motor Vagal Nuclei (parasympathetic pre-ganglionic nuclei) – controls vagal functions of Cardiac, Respiratory and GI systems – lesions: tachycardia, loss of cough reflex, ↓ GI motility, etc.", "• Alternative Test: Water Swallow test is specifically helpful to assess aspiration risk after stroke."], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "XI (Accessory)", "phase": null, "tags": [], "pg": 356, "say": ["I will assess muscle strength. When you feel my hand on the jaw, push against the hand."], "do": ["Place your hand on mandible. Ask patient to turn their head against your resistance to assess sternocleidomastoid muscle. Repeat for other side. Next, place your hands on patient’s shoulders and ask patient to shrug shoulders, comparing power on each side."], "report": ["I note normal power bilaterally of the sternocleidomastoids and trapezius muscles."], "why": ["Technically, the Accessory Nerve tested is the spinal accessory nerve which arises in the Cervical spine. The Cranial accessory nerve is a motor nerve originating in Medulla, with its Nucleus Ambiguus nuclei innervating muscles of larynx and pharynx. In testing CN XI, looking for signs of unilateral vs. bilateral deficits.", "• Note: When patient turns their head against resistance, the contralateral sternocleidomastoid is recruited e.g. Left sternocleidomastoid turns the head to the right.", "• Interpretations: Cerebral hemispheric lesions, medullary and high spinal lesions; brainstem lesions."], "imgs": []}, {"sec": "Cranial Nerve (CN) Exam", "name": "XII (Hypoglossal)", "phase": null, "tags": [], "pg": 356, "say": ["I will assess the tongue muscles. Can you open the mouth and stick out the tongue?"], "do": ["Assess for tongue deviation with protrusion, fasciculations or atrophy (folds, wasting) on affected side."], "report": ["Tongue is midline on protrusion, with no wasting or fasciculations bilaterally."], "why": ["The Hypoglossal Nerve (CN XII) is a motor nerve originating in the medulla, with the Hypoglossal Nuclei controlling tongue movement and lesions causing tongue muscle atrophy, tongue deviation on protrusion (testing here) and fasciculations of tongue. We are looking for signs of unilateral vs. bilateral deficits. A lesion of CN XII shifts the tongue towards the weak side = tongue points to side of the lesion.", "• Interpretations: Lesions associated with lower cranial nerves; Lesions in upper neck/skull base."], "imgs": []}, {"sec": "Motor Examination", "name": "Tone", "phase": null, "tags": [], "pg": 357, "say": ["I will assess muscles of the arms and legs for tone and any signs of spasticity."], "do": ["Passively move joints in upper and lower limbs by supporting proximal joints (e.g. if testing the wrist, support patient forearm). Passively move joint throughout ROM. Rigidity is velocity-independent – i.e. variations in movement velocity should not alter tone. If rigidity present, assess whether it is smooth throughout ROM (Lead-pipe rigidity) or intermittent increased resistance (Cogwheel rigidity). To test for spasticity, perform a rapid limb movement e.g. forearm supination or ankle dorsiflexion. Spasticity is felt as a “catch” with increased tone.", "• Example Joints to Examine: Wrist rotation; Elbow flexion/extension; Ankle rotation; Knee flexion/extension"], "report": ["I note a normal tone in the upper and lower limbs with no spasticity or rigidity."], "why": ["Tone is the amount of resistance to passive stretch in a muscle. Tone helps to differentiate Upper Motor Neuron (UMN) from Lower Motor Neuron (LMN) Lesions.", "• UMN Lesions (Brain, Spine) → Hypertonia", "◦ Spasticity (velocity-dependent, ↑ resistance at extremes of velocity and ROM, pyramidal tract lesion) → e.g. Stroke, Cerebral Palsy", "◦ Rigidity (velocity-independent, extra-pyramidal tract lesion)", "▪ Lead-pipe (steady ↑ resistance during ROM) → e.g. Parkinsonism, Neuroleptic Malignant Syndrome (Tetrad: Altered Mental Status, Rigidity, Hyperthermia, Autonomic instability)", "▪ Cogwheel (ratchet-like ↑ resistance during ROM, may worsen with repetitive movements) → e.g. Parkinsonism (superimpose on lead-pipe rigidity)", "▪ The likelihood of suspected Parkinson’s Disease is mildly increased with presence of rigidity (LR+ 2.8, LR-", "0.38), and by rigidity with bradykinesia (LR+ 4.5, LR- 0.12).", "◦ Other UMN signs: Contractures (upper limb flexion contractures, lower limb extension contractures), Hyper-reflexia, Upgoing plantar response, Paralysis or Paresis, may develop muscle atrophy.", "• LMN Lesions (Anterior Horn, Peripheral Nerve, Neuromuscular Junction, Muscle) → Hypotonia", "◦ Other LMN signs: Fasciculations, Hypo-reflexia, Down-going plantars (normal), Paralysis, muscle atrophy"], "imgs": []}, {"sec": "Motor Examination", "name": "Power – Upper Limb", "phase": "power", "tags": [], "pg": 357, "do": ["• Approach:", "◦ Resisted Isometric Testing i.e. patient resists force applied by clinician.", "◦ Meet Like with like if possible – e.g. to test wrist extension, apply isometric force with your own wrist.", "◦ To test distal muscle strength, group muscles together – e.g. press down on DIPs to test MCPs together", "Test the following functions:", "• Arm Abduction at Shoulder (C5, C6 - Axillary Nerve): Patient abducts arm at shoulder; brace above shoulder, and apply a downward force on the arm; patient resists motion.", "• Arm Adduction at Shoulder (C6, C7, C8 – Thoracodorsal Nerve): Patient abducts arm at shoulder; brace above shoulder, and apply an upward force on the arm; patient resists motion.", "• Elbow Flexion (C5, C6 – Musculocutaneous Nerve): Patient flexes elbow with arm supinated; brace shoulder, grasp forearm, apply extensor force; patient resists motion.", "• Elbow Extension (C6, C7, C8 – Radial Nerve): Patient flexes elbow with arm supinated; brace shoulder, grasp forearm and apply a flexor force; patient resists motion.", "• Forearm Pronation (C6, C7, C8, T1 – Median Nerve): Elbow flexed to 90° with palms up. Brace forearm with wrist in neutral position; apply supination force; patient resists motion.", "• Forearm Supination (C5, C6, C7 – Radial Nerve): Elbow flexed to 90° with palms down. Brace forearm with wrist in neutral position; apply pronation force; patient resists motion.", "• Wrist Extension (C5, C6 – Radial Nerve): Elbow flexed to 90° in pronation; brace elbow, and apply downward force on dorsal surface of hand; patient resists motion.", "• Wrist Flexion (C6, C7 – Median Nerve & C7, C8, T1 – Ulnar Nerve): Patient adopts elbow flexion with pronation; brace elbow, and apply upward force on palmar surface of hand; patient resists motion.", "• Flexion at MCPs (Digits 2&3 – C7, C8 – Median Nerve; Digits 4 & 5 – C7, C8 – Ulnar Nerve): Elbow flexion with pronation; brace wrist, apply a downward force on the DIPs grouped together; patient resists motion.", "• Dorsal Interossei (C7, C8 – Ulnar Nerve): Abduct fingers; patient resists motion.", "• Palmar Interossei (C7, C8 – Ulnar Nerve): Adduct fingers; patient resists motion.", "• Thumb Abduction, Flexion, Opposition (C7, C8 – Median Nerve) and Extension C5, C6 – Radial Nerve)"], "say": ["I will now test power in the upper limb muscles. When I apply pressure to a joint, resist the motion."], "report": ["For each muscle group tested, assess per the Medical Research Council (MRC) Power Grading. If all power assessments are 5/5, you can say “Power was 5/5 bilaterally in upper limbs” and report specific deficits."], "imgs": []}, {"sec": "Motor Examination", "name": "Power – Lower Limb", "phase": "power", "tags": [], "pg": 359, "say": ["I will now test power in the lower limb muscles. When I apply pressure to a joint, resist the motion. Please sit over the side of the exam table with the legs relaxed throughout the assessment."], "do": ["Test the following functions:", "• Hip Flexion (L1, L2, L3 –Femoral Nerve): Brace hip. Apply downward force on quadriceps; patient resists motion.", "• Hip Extension (S1, S2 – Tibial Nerve): Brace hip. Apply upward force on hamstrings; patient resists motion.", "• Knee Extension (L2, L3, L4 – Femoral Nerve): Brace knee. Apply posterior force on anterior knee; patient resists motion.", "• Knee Flexion (L5, S1, S2 – Sciatic Nerve): Brace knee. Apply anterior force on posterior knee; patient resists motion.", "• Ankle Dorsiflexion (L4, L5 – Fibular Nerve): Brace ankle. Apply plantar force on dorsal ankle; patient resists motion.", "• Ankle Plantarflexion (S1, S2 – Tibial Nerve): Brace ankle. Apply dorsal force on plantar ankle; patient resists motion.", "• D1 Dorsiflexion (L5, S1 – Fibular Nerve): Brace 1st MTP. Apply plantar force on dorsal hallux; patient resists motion."], "report": ["For each muscle group tested, assess per the Medical Research Council (MRC) Power Grading. If all power assessments are 5/5, you can say “Power was 5/5 bilaterally in lower limbs” and report specific deficits."], "why": ["Assessing muscle power allows you to screen major spinal levels and particular peripheral nerves which can be affected. This allows for differentiating Upper Motor Neuron (UMN) and Lower Motor Neuron (LMN) lesions and is also an important part of the Musculoskeletal (MSK) Exam. Use the Medical Research Council (MRC) Power Grading to report your findings (see Upper Limb Assessment, above). In the lower limbs, the likelihood of suspected lumbosacral radiculopathy in patients with sciatica is increased by weak ankle dorsiflexion (LR+ 4.9, LR- 0.5). Specifically, the likelihood of an L3-L4 radiculopathy is increased with weakness of knee extension (LR+ 3.7, LR- 0.7). The likelihood of an L5 radiculopathy is increased with weakness of hallux extension (LR+ 1.6). The likelihood of an S1 radiculopathy is decreased by normal strength of ankle plantarflexion (LR- 0.7). Neurological Assessment of the Lower Limb – Derived from Lumbosacral Plexus:", "Nerve Muscle Spinal Movement Sensation Reflex Levels Femoral Iliopsoas L1, L2, L3 Hip Flexion N/A N/A Quadriceps L2, L3, L4 Knee Extension Anterior Thigh Patellar Obturator Hip Adductors L2, L3, L4 Hip Adduction Innermost Thigh N/A Superior Gluteal Hip Abductors L4, L5, S1 Hip Abduction N/A N/A Sciatic Hamstrings L5, S1, S2 Knee Flexion Outer Thigh, Calf Achilles Fibular Fibular Tibialis Anterior L4, L5 Ankle Dorsiflexion N/A N/A Extensor Hallucis L5, S1 L5, S1 Great Toe Space between N/A N/A Longus Dorsiflexion hallux and 2nd Toe Tibial Gastrocnemius, S1, S2 Ankle Plantar aspect of Achilles Soleus Plantarflexion arch of the foot Posterior Tibial Tibialis Posterior Tibialis Posterior L4, L5 Posterior Foot N/A N/A N/A Inversion Superficial Peroneus Longus, L5, S1 Foot Eversion Foot Eversion Dorsum of Foot N/A Peroneal Brevis"], "imgs": []}, {"sec": "Motor Examination", "name": "Bulk", "phase": null, "tags": [], "pg": 359, "say": ["I will assess particular muscles in the arms and legs for their bulk, and any signs of atrophy."], "do": ["Inspect the shoulder girdle; Thenar/hypothenar eminence, quadriceps, and arch of foot."], "report": ["I note no atrophy of shoulder girdle, Thenar or hypothenar eminences, the quadriceps or arch of foot."], "why": ["Muscle Bulk can ↓ in both UMN and LMN lesions over time – UMN can avoid atrophy with physiotherapy. In patients with sciatica, Ipsilateral calf wasting moderately increases the likelihood of suspected lumbosacral radiculopathy (LR+ 5.2, LR- 0.8); specifically, ipsilateral calf wasting in patients with sciatica mildly increases the likelihood of an S1 radiculopathy (LR+ 2.4, LR- 0.7)."], "imgs": []}, {"sec": "Reflex Exam", "name": "Reflex Testing", "phase": null, "tags": [], "pg": 360, "do": ["• Approach: To test reflexes with Reflex Hammer, grasp hammer at distal end and allow it to drop on tendon being tested. This technique helps to keep the force exerted relatively constant between tests. Muscles must be relaxed for reflex exam; can check if muscles relaxed by removing the support of limb.", "• Say: I will test the deep tendon reflexes of the arms and legs. Please sit over the side of the exam table with socks off. Please keep the arms and legs relaxed.", "• Do: Test the following reflexes:", "◦ Ankle Jerk (S1 & S2 – Tibial Nerve = “One-Two Tie My Shoe”): Brace foot into a slightly dorsiflex position with muscles relaxed. Strike surface of Achilles tendon with hammer. Look for plantar flexion jerk of foot.", "◦ Patellar Reflex (L2, L3 & L4 – Femoral Nerve = “Three-Four Open The Door”): With patient’s leg relaxed, strike Patellar tendon with reflex hammer. Look for quadriceps contraction and knee extension.", "◦ Brachioradialis (C5 & C6 – Radial Nerve = “Five-Six Pick Up Sticks”): With arms relaxed, resting on thighs and supinated. Landmark 2 fingerbreadths above radial styloid, and strike Brachioradialis tendon with hammer. Look for supination and slight elbow flexion.", "◦ Biceps (C5 & C6 – Radial Nerve = “Five-Sick Pick-Up Sticks”): With arm relaxed and slightly flexed, resting on thighs and supinated, place 2 fingers along cubital fossa. Strike biceps tendon with the reflex hammer; look for biceps contraction and forearm supination.", "◦ Triceps (C7 & C8 – Radial Nerve = “Seven-Eight Lay Them Straight”): Arms relaxed at sides and pronated, brace arm above level of elbow, and abduct with internal rotation. Place 2 fingers above the olecranon. Strike triceps tendon with the reflex hammer. Look for triceps contraction and elbow extension."], "report": ["I note normal Grade 2+ deep tendon reflexes bilaterally throughout the upper and lower limbs."], "why": ["A reflex involves a coordinated contraction in one Reflex Description compartment and relaxation in the antagonistic compartment Grade (e.g. contraction of quadriceps, relaxation of hamstrings in 0 Absent patellar tendon reflex). Deep tendon reflexes help differentiate an Upper Motor Neuron Lesion from a Lower Motor Neuron Lesion. needed to elicit e.g. patient Reflexes are graded according to a scale of 0-4 (see right). clenches teeth, locks fingers) Abnormal DTRs have diagnostic value ONLY when asymmetric or 2+ Normal accompanied by other motor neuron disease signs. 3+ Hyperactive without clonus", "• Hyper-reflexia → Upper Motor Neuron lesion (Brain, Spine) 4+ Hyperactive with clonus", "• Hypo-reflexia → Lower Motor Neuron lesion (Anterior Horn, Peripheral Nerve, NMJ, Muscle)", "◦ ↓ Deep Tendon Reflexes have High +ve Likelihood Ratio for radiculopathy.", "◦ In the upper limbs, the likelihood of suspected cervical radiculopathy in patients with neck/arm pain is increased by reduced biceps reflex (LR+ 9.1), or any reduced arm reflex (biceps, triceps or brachioradialis reflexes – LR+ 3.6, LR- 0.8). Specifically, the likelihood of a C6 radiculopathy is increased with reduced biceps or brachioradialis reflex (LR+ 14.2, LR- 0.5). The likelihood of a C7 radiculopathy is increased with diminished triceps reflex (LR+ 3.0).", "◦ In the lower limbs, the likelihood of suspected lumbosacral radiculopathy in patients with sciatica is increased by abnormal ankle jerk reflex (LR+ 2.7). Specifically, the likelihood of an L3-L4 radiculopathy is increased with asymmetric quadriceps reflexes (LR+ 8.7, LR- 0.6). The likelihood of an S1 radiculopathy is increased with asymmetric Achilles reflexes (LR+ 2.9, LR- 0.4)."], "imgs": []}, {"sec": "Reflex Exam", "name": "Plantar Response “Scratch the foot”", "phase": null, "tags": [], "pg": 360, "say": ["I will test the Plantar responses by scratching each foot; please keep both socks removed."], "do": ["Patient sits over side of exam table, legs relaxed, socks off. You may need to rub foot to desensitize initially.", "• Using a blunt edge (e.g. reflex hammer edge), scrape plantar surface of foot firmly on lateral edge, moving medially as you approach the forefoot in an “L” shape. Look for initial plantarflexion of hallux i.e. down- going plantar response. Other toes may normally plantar flex in this process.", "• Note: “Babinski” does not refer to the name of the test; a Babinski refers to an upgoing plantar response."], "report": ["Plantar Responses are down-going bilaterally."], "why": ["Plantar responses help to differentiate an Upper Motor Neuron from Lower Motor Neuron Lesion.", "• Up-going Plantar Response (also called a Babinski response) → Upper Motor Neuron lesion (Brain, Spine)", "◦ An upgoing plantar response greatly increases the likelihood of suspected unilateral cerebral hemispheric disease (LR+ 19.0, LR- 0.6).", "◦ Children < 2 years old: Have physiologic up-going plantar responses as their Cerebrospinal Tracts (pyramidal tracts) are not yet myelinated, where extrapyramidal tracts give upgoing plantars. Beyond 2 years of age, cerebrospinal tracts are myelinated → central control and down-going plantar responses.", "• Down-going Plantar Response → Seen in normal exam, and also seen in Lower Motor Neuron lesions (Anterior Horn, Peripheral Nerve, NMJ, Muscle)"], "imgs": []}, {"sec": "Reflex Exam", "name": "Ankle Clonus", "phase": null, "tags": [], "pg": 361, "say": ["I will test for Clonus of each ankle. Please keep the legs relaxed."], "do": ["• Brace leg posteriorly with one hand; with the other, grasp foot from the lateral edge for manipulation.", "• Manipulate foot with slow wiggling movements; then dorsiflex ankle briskly and hold in dorsiflexion.", "• Look for rhythmic contraction at the ankle (positive test: >3-5 beats). Test bilaterally."], "report": ["I note no ankle clonus bilaterally."], "why": ["Helping to differentiate an Upper Motor Neuron lesion from a Lower Motor Neuron lesion.", "• +ve Ankle Clonus → Upper Motor Neuron Lesion (e.g. Brain, Spine)"], "imgs": []}, {"sec": "Sensory Exam", "name": "Posterior Column", "phase": null, "tags": [], "pg": 361, "say": ["I will test for sensation of light touch in the arms and legs using a cotton ball. Please close both eyes. Let me know when you feel the cotton ball, and if so, where?"], "do": ["Using cotton ball, test distal aspects of Upper and Lower Limbs. At each stage, ask patient if they can sense it and where sensation is."], "report": ["No deficits of the posterior column on sensory exam."], "imgs": []}, {"sec": "Sensory Exam", "name": "Spinothalamic", "phase": null, "tags": [], "pg": 361, "say": ["I will test for sharp and dull sensation in the arms and legs using a pin. It should be felt, but not painful. Please close both eyes. Let me know when you feel the pin, and if so, where?"], "do": ["Using pin, test distal aspects of Upper Limb and Lower Limb. Two methods include:", "• Sharp/Dull Discrimination: Alternate with sharp and dull end of pin – they should be able to distinguish them. At each stage, ask patient if they can sense it and where sensation is. If patient can’t sense the testing distally, then move up the affected limb and ask at what point it becomes stronger.", "• Relative Differences Side-to-Side: Compare side-to-side with sharp end of pin at equivalent structures (e.g. left versus right D1 toe). Ask if one side feels significantly less sharp (relative sensation changes can present earlier than loss of sharp/dull discrimination seen in more significant lesions)."], "report": ["No deficits of the spinothalamic tract on sensory exam."], "why": ["Sensory testing of both Posterior Column and Spinothalamic Tracts and mapping out areas of sensory loss helps differentiate “where is the lesion” – decussation (crossing over) of posterior column tract occurs at Medulla (brainstem), whereas decussation of spinothalamic tract occurs within 1-2 spinal levels. Example distributions for different lesions include:", "Lesion Posterior Column (Touch, Pressure, Spinothalamic (Pain & Temperature) Proprioception) Mononeuropathy (e.g. Carpal Tunnel Peripheral nerve distribution (e.g. Median nerve – Palmar aspect first 3 ½ digits) Peripheral nerve distribution (e.g. Median nerve – Palmar aspect first 3 ½ digits) Syndrome – median nerve compression) Symmetric Generalized Polyneuropathy Glove-and-stocking distribution (e.g. Diabetic neuropathy, Chemo- induced neuropathy, Guillain-Barre) Sensory Nerve Root Impingement Dermatomal distribution of sensory nerve root (Dermatome Map) Complete spinal cord injury Bilateral deficit up to level of lesion. Hemi-Section of Spinal Cord Hemi-Section of Spinal Cord Ipsilateral deficit below level of Contralateral deficit below level of lesion. lesion, ipsilateral at level of lesion. Anterior Spinal Artery Syndrome (e.g. Normal posterior column testing Normal posterior column testing Bilateral deficit up to level of lesion. Bilateral deficit up to level of lesion. infarct of anterior spinal artery) Brainstem Stroke Syndromes Brainstem Stroke Syndromes Medial Brainstem stroke:", "Contralateral deficit of body Lateral Brainstem stroke: Ipsilateral hemi-sensory deficit of face, Contralateral deficit of body MCA Territory Stroke Contralateral deficit (lower limb Contralateral deficit (lower limb relatively spared) relatively spared) ACA Territory Stroke Contralateral deficit of lower limb Contralateral deficit of lower limb"], "imgs": ["neuro-195.webp"]}, {"sec": "Coordination Exam", "name": "Finger-tonose Testing", "phase": null, "tags": [], "pg": 362, "say": ["I will assess coordination with upper limb movements."], "do": ["• Stand at arms’ length distance from the patient so they need to extend their arm to reach your finger.", "• Ask patient to touch their nose with their left index finger while clinician holds their index finger in front.", "• Ask patient to now touch the clinician’s index finger with their left index finger.", "• Ask the patient to then move back and forth between touching their nose and clinician’s index finger.", "• Observe for smooth movement with reasonable accuracy and precision. Test patient’s right hand as well.", "• Clinician can increase difficulty by moving their finger to different location and ask the patient to continue to move back and forth between touching their nose and clinician’s index finger – this tests ataxia."], "report": ["Normal finger-to-nose movements bilaterally on examination."], "why": ["Finger-to-nose testing is a Point-to-Point movement exam. Abnormal finger-to-nose testing may be caused by a cerebellar lesion (dysmetria – lack of coordinated movement leading to misjudging distance to target) or a tremor (involuntary, rhythmic, oscillatory movement of body part). Cerebellar lesions cause Ipsilateral deficits (e.g. Right cerebellar infarct causing Right-sided dysmetria). Note: subtle incoordination can be normal especially in non-dominant hand."], "imgs": []}, {"sec": "Coordination Exam", "name": "Rapid Alternating Movements of Upper Limb", "phase": null, "tags": [], "pg": 362, "say": ["I will assess coordination with rapid movement of the upper limbs. Please follow my example."], "do": ["• Ask patient to flex elbows to 90° with palms up. Ask patient to pronate right hand, clap palms together.", "• Ask patient to quickly remove right hand, supinate right hand, and clap dorsum of right hand to left palm.", "• Helpful to demonstrate the maneuver for the patient to model the task.", "• Ask patient to go back and forth alternating clapping palm and dorsum of right hand to left palm as fast as they can. Model maneuver. Observe for smooth movement with reasonable accuracy and precision with reasonable frequency. Test with left hand rapid alternating movements as well."], "report": ["Normal rapid alternating movements of the upper limb bilaterally."], "why": ["Dysdiadochokinesia is the term for inability to perform rapid alternating muscle movements. This may be caused by Cerebellar ataxia (lack of coordination of voluntary movements), although other movement disorders (e.g. Parkinson’s Disease with rigidity and bradykinesia) may create a false impression of dysdiadochokinesia. Cerebellar lesions cause Ipsilateral deficits (e.g. Left cerebellar infarct causing Left-sided dysdiadochokinesia)."], "imgs": []}, {"sec": "Coordination Exam", "name": "Heel-to-Shin Testing", "phase": null, "tags": [], "pg": 362, "say": ["I will assess coordination with lower limb movements."], "do": ["• With patient lying supine, ask patient to place their right heel on their left shin just below knee. Ask patient to move right heel smoothly down the left shin to ankle. Repeat test with left heel movement.", "• Observe for smooth movement with reasonable accuracy and precision (not falling off the shin, etc.)."], "report": ["Normal heel-to-shin movements bilaterally on examination."], "why": ["Heel-to-Shin testing is a Point-to-Point movement exam. Abnormal heel-to-shin testing may be caused by a cerebellar lesion (dysmetria – as above), motor deficit (tested with motor exam), or loss of proprioception (tested with sensory exam). Cerebellar lesions cause Ipsilateral deficits (e.g. Right cerebellar infarct causing Right-sided dysmetria)."], "imgs": []}, {"sec": "Coordination Exam", "name": "Toe-Tapping", "phase": null, "tags": [], "pg": 362, "say": ["I will assess coordination with rapid movement of the lower limbs by asking you to tap each foot."], "do": ["• Ask patient to tap their right foot against the floor (e.g. if seated) or against examiner’s hand (e.g. if lying supine) as fast as they can.", "• Observe for smooth movement with reasonable accuracy and precision with reasonable frequency. Test with left foot rapid alternating movements as well."], "report": ["Normal toe tapping on examination."], "why": ["Toe-Tapping test is a Rapid Alternating Movement of the lower limb, where an abnormal exam indicates dysdiadochokinesia i.e. inability to perform rapid alternating muscle movements. This may be caused by Cerebellar ataxia (lack of coordination of voluntary movements), although other movement disorders (e.g. Parkinson’s Disease with rigidity and bradykinesia) may create a false impression of dysdiadochokinesia. Cerebellar lesions cause Ipsilateral deficits (e.g. Left cerebellar infarct causing Left-sided dysdiadochokinesia)."], "imgs": []}, {"sec": "Stance Assessment", "name": "Normal Stance", "phase": null, "tags": [], "pg": 363, "say": ["I will assess stance. Please stand up with both feet together and stay standing."], "do": ["Look whether the stance of the patient is wide based; look at their trunks."], "report": ["Patient’s stance appears to be steady and not wide-based."], "why": ["If patient feels unsteady and need to catch themselves, it could be due to vestibular lesions, cerebellar lesions (e.g. truncal ataxia – oscillation of body while standing), or loss of sensation in feet. The likelihood of ≥1 fall in the next year in community-dwelling patients ≥65 years old is increased by inability to rise from a chair of knee-height without using the chair arms (LR+ 4.3, LR- 0.77), and by abnormal tandem stand (LR+ 1.7-2.0, LR- 0.69-0.74). In patients living in nursing homes ≥65 years old, the likelihood of ≥1 fall in the next year is increased by inability to stand with feet together and eyes open for 10 seconds (LR+ 4.5)."], "imgs": []}, {"sec": "Stance Assessment", "name": "Romberg Test", "phase": "rom", "tags": [], "pg": 363, "say": ["I will continue to assess the ability to maintain the same stance after I ask you to close both eyes."], "do": ["Stand behind patient, standing close by to prevent injury if the patient appears to be close to falling.", "• Ask patient to stand still with both eyes open and arms at sides and heels together. Observe that patient is able to hold this stance without visible swaying.", "• Ask patient to close their eyes while remaining still. Observe if patient’s stance visibly sways and loses their balance (Note: some swaying normal)."], "report": ["Patient has a negative Romberg test."], "why": ["The components of balance are visual confirmation of position, non-visual confirmation of vision (including proprioception and vestibular input) and a functioning cerebellum. In cerebellar ataxia, a patient may be unable to hold a Romberg stance even with eyes open. A positive Romberg test is when swaying and loss of balance occurs after patient eyes are closed. A +ve Romberg suggests sensory ataxia (either proprioceptive or vestibular) rather than cerebellar ataxia. Note Romberg is unspecific and has low inter-observer agreement. In patients living in nursing homes ≥65 years old, the likelihood of ≥1 fall in the next year is increased by inability to stand with feet together and eyes open for 10 seconds (LR+ 4.5) – this is the first step of the Romberg Test (i.e. before patient closes eyes to remove visual component of balance)."], "imgs": []}, {"sec": "Gait Exam", "name": "Normal Walking Gait", "phase": null, "tags": [], "pg": 363, "say": ["I would like to examine gait with walking. Could you walk in a straight line, and then turn around?"], "do": ["Have patient remove their shoes and expose their ankles to improve your ability to assess. Observe for the heel strike, mid-stance, toe-off; hip movement; and arm swing – note you can only effectively observe one leg at a time. You should have them walk back and forth several times – realistically, how can you extract all the info you need to with one look?"], "report": ["Normal gait assessment, with 40% swing phase, 60% stance phase, and able to turn quickly."], "why": ["If patient stops walking when talking, helps predict falls risk, where the likelihood of ≥1 fall in the next year in nursing home patients ≥65y is increased by stopping walking when talking (LR+ 3.0), and by stopping talking when walking (LR+ 8.8, LR- 0.6). In community-dwelling patients ≥65y, the likelihood of ≥1 fall in the next year is increased by slow gait (LR+ 2.0-2.1, LR- 0.73-0.80). Look for characteristic gaits:", "• Foot drop: Weakness of ankle dorsiflexion, where foot remains in plantarflexion during stance phase.", "◦ Unilateral causes: e.g. Deep Fibular Mononeuropathy; L5 Radiculopathy; Lumbosacral plexopathy", "◦ Bilateral causes: e.g. ALS, Charcot-Marie-Tooth disease, Peripheral neuropathy e.g. due to Diabetes", "• Hemiplegic gait (e.g. Stroke): Patient holds arm to one side (↓ arm swing) with circumducting gait (drags affected leg in semicircle due to foot drop and extensor hypertonia of lower limb)", "• Diplegic gait (Spastic gait, e.g. Cerebral Palsy): Narrow gait base, dragging both legs, scraping toes.", "• Parkinsonian gait (e.g. Parkinson’s Disease, Extra-pyramidal symptoms): Shuffling gait – Walking with slow and small steps, with narrow base (versus normal pressure hydrocephalus, where gait is wide- based, with a similar slow movement and small steps)", "◦ The likelihood of suspected Parkinson’s disease is increased by shuffling gait (LR+ 3.3-15, LR- 0.32-", "0.5).", "• Waddling gait (e.g. Duchenne Muscular Dystrophy): Bilateral weakness of hip abductors with shifting centre of gravity to compensate. Recall: unilateral weak hip abductor gives a Trendelenburg gait.", "• Truncal Ataxia (Lesion to midline cerebellum i.e. vermis): Unsteady on standing, walking and sitting with oscillation of the body.", "• Ataxia of Extremities (Cerebellar hemisphere lesion): Limb ataxia towards the side of the lesion.", "• Sensory Ataxia (Loss of Proprioception, lesion to Posterior Columns or Spinocerebellar tract e.g. B12 deficiency, Uncontrolled diabetes): Wide-based, careful gait “stamping on the ground”", "• Choreiform Gait (e.g. Huntington’s disease): Irregular, jerky, involuntary movements in all extremities."], "imgs": []}, {"sec": "Gait Exam", "name": "Tandem Gait", "phase": null, "tags": [], "pg": 364, "say": ["I will continue to examine gait, this time walking in a line with one foot in front of the other (point to a line on the floor if available e.g. line formed by floor tiles)."], "do": ["Observe whether they can maintain some steadiness during the gait – does not need to be perfectly linear but should approximate walking a line."], "report": ["Normal tandem gait assessment."], "why": ["Can help to assess for ataxia, especially truncal ataxia; and detect subtle signs of cerebellar dysfunction. The likelihood of suspected Parkinson’s disease is increased by difficulty walking heal-to-toe (LR+ 2.9, LR- 0.32). The likelihood of ≥1 fall in the next year in nursing home patients ≥65y is increased by inability to tandem walk (LR+ 1.7, LR- 0.7)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Hearing Loss Screening Test Alternative: Finger Rub Test", "phase": null, "tags": ["extra"], "pg": 364, "say": ["I will now assess hearing. I will stand behind you and rub my fingers together close to one of your ears with your eyes closed and arms at the sides. Please raise your hand on the side you hear the fingers rubbing."], "do": ["Standing in front of the patient, once their eyes are closed, bring your arms close to each side of the patient’s ears, ensuring there is no contact with the patient’s outer ear or hair. On each side in a random order, rub your thumb against your index finger while progressing to the middle finger and then back to the index finger three times. Test this with a strong rub (as loud as you can muster); as well as a faint rub (the softest you can hear as the clinician). Monitor for the patient raising their hand to the side they hear the finger rub. Randomize the order of these 4 maneuvers (e.g. left ear, right ear, right ear, left ear)."], "report": ["The patient heard both a strong and faint rub in bilateral ears. This is a normal finger rub screening test for hearing loss."], "why": ["The finger rub test is a helpful initial screening test for hearing loss, with an alternative screening test being the Whispered Voice Test (as detailed above in CN VIII testing). The test can also be performed by standing in front of the patient. The likelihood of hearing loss is greatly increased by being unable to hear a strong finger rub (LR+ 355.4)21. Being able to hear a faint finger rub greatly decreases the likelihood of hearing loss (LR- 0.02)21. Note that ambient noise can impact the performance of this test, where a study demonstrated that being unable to hear a strong finger rub in a quiet environment greatly increases the likelihood of hearing loss (LR+ 16.73), while the same result in a noisy environment moderately increases the likelihood of hearing loss (LR+ 6.76)22. This test cannot differentiate sensorineural from conductive hearing loss, where Weber and Rinne testing (see below) can help delineate conductive, sensorineural and mixed hearing loss. An abnormal screening test should be referred for formal audiology assessment."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Hearing Loss Assessment Alternative: Hum Test", "phase": null, "tags": ["extra"], "pg": 364, "say": ["I will assess your hearing. Please hum an “eee” or “hmm” sound at a consistent pitch for a few seconds. It can be helpful to repeat the test with both high- and low-pitch hums. Please tell us which ear is loudest."], "do": ["Ask patient to hum an “eee” or “hmm” sound at a consistent pitch for a few seconds as noted above, with potential variation of the pitch over multiple trials. Ask the patient which ear hears the hum the loudest."], "report": ["The patient reports hearing loss in their left ear, and the Hum test lateralizes to the left ear, consistent with conductive hearing loss."], "why": ["For patients with hearing loss, the Hum test is a simple alternative to the Weber’s test which doesn’t require a tuning fork. Interpretation is the same as the Weber’s test: if the sound lateralizes to the affected ear, this suggests conductive loss. If it lateralizes to the unaffected ear, this suggests sensorineural hearing loss. The Hum test can be helpful in Telemedicine and triaging patients needing urgent assessment for Sudden Sensorineural Hearing Loss (SSNHL)23 where tuning forks are unavailable at initial intake. Pearl: You can test the hum test on yourself: use your finger to plug and unplug your ear (conductive hearing loss) while making a hum, and see which side the sound lateralizes to."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "HINTS Exam", "phase": null, "tags": ["conditional", "extra"], "pg": 364, "do": ["• When to do the HINTS+ Exam? The HINTS+ exam is only indicated with acute onset, continuous dizziness, imbalance, and nystagmus lasting hours to days (Acute Vestibular Syndrome = AVS). Patients must have ongoing nystagmus at rest (involuntary repetitive jerking eye movements) to be eligible for the HINTS exam. Patients presenting with the acute vestibular syndrome could be having a peripheral (nerve) problem (acute vestibular neuritis) or a central (brain) problem (stroke or other acute brain lesion). The HINTS exam is a battery of 3 bedside tests which accurately differentiate peripheral versus central causes of the acute vestibular syndrome – but it is only validated in patients with ongoing, continuous acute dizziness and nystagmus. If the patient does not have continuous nystagmus, the HINTS exam is NOT indicated. Make sure you do a history and physical to exclude any RED FLAGS for stroke (explored in Chapter 7 – Head and Neck Exam) prior to doing the HINTS+ exam."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Dix-Hallpike Test", "phase": null, "tags": ["conditional", "extra"], "pg": 365, "do": ["Provocative Testing for Diagnosing BPPV Benign Positional Paroxysmal Vertigo (BPPV) is caused by loose debris (otoconia) within one of the semi- circular canals of the vestibular apparatus. Each ear has 1 vestibular apparatus and each vestibular apparatus has 3 semi-circular canals. The most common location for otoconia in BPPV is the posterior canal (~65%), followed by the horizontal canal (~30%), while the anterior canal is relatively rare. Movement of loose otoconia within a semicircular canal will reliably produce vertigo with a different type of nystagmus depending on which canal is affected. Therefore, we use provocative testing in BPPV to watch for which type of nystagmus and LOCALIZE which ear and canal the otoconia are in. Once we have localized the otoconia, we can then use the appropriate particle repositioning maneuver to correct the problem and cure our patients. Provocative tests for BPPV are indicated only if you suspect a diagnosis of BPPV based on a history of brief, (less than one minute), intense attacks of dizziness that are always triggered by head movements (most commonly lying down or turning over in bed). A patient who has continuous dizziness present at rest lasting hours to days should never get provocative tests for BPPV. You should also ensure that the patient does not have any red flags for a serious central cause of dizziness, and that there is not another cause (such as postural hypotension or vestibular migraine or Meniere’s disease) that better explains their symptoms, prior to provocative tests. Since the most common type of BPPV is posterior canal (~65%), this is the first canal which we test in a patient with suspected BPPV. Posterior canal BPPV is identified using the Dix-Hallpike Test."], "say": ["I will move you from a sitting to lying down position on the exam table and move the neck to the side and back. Please tell me if these movements reproduce your symptoms of vertigo."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Supine Roll", "phase": null, "tags": ["conditional", "extra"], "pg": 366, "do": ["Since the second most common type of BPPV is horizontal canal (~30%), this is the second canal which we test in a patient with suspected BPPV. Horizontal canal BPPV is identified using the Supine Roll test.", "Have patient lie supine on an exam bed. Turn their head to one side and examine their eyes for nystagmus. Then turn their head to the other side and examine for nystagmus. If they have horizontal canal BPPV, you will see horizontal nystagmus on both head turns which is either towards the ground (geotropic) or away from the ground (apogeotropic)."], "say": ["I will reposition you to look to one side and then the other side while lying flat on your back."], "report": ["There is no horizontal nystagmus on supine roll test, therefore it is unlikely the patient has horizontal canal BPPV."], "why": ["Used to localize the affected ear in patients with Horizontal Canal Benign Paroxysmal Positional Vertigo (BPPV). On the side that has the more intense nystagmus, the nystagmus will beat towards the affected ear. When you have identified which ear is affected and whether it is geotropic or apogeotropic, you can proceed with an appropriate particle repositioning maneuver (Gufoni or Barbecue roll) for the affected side."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Additional Cerebellar Examination Tests", "phase": null, "tags": ["extra"], "pg": 366, "do": ["• Core Elements on Screening Exam Above: Oculomotor (Nystagmus, or Saccadic movements on smooth pursuit); Scanning Speech; Dysarthria/Dysphonia (errors in impulse timing of speech muscles) Coordination Exam elements above; Pendular reflexes; Gait Assessment (Truncal Ataxia); Hypotonia", "• Pronator Drift of Upper Extremity: Have patient hold arms out for 30 seconds in supinated positions with eyes closed (thus, taking away one input to the cerebellum – patient must rely on proprioception to maintain arm position).", "◦ UMN Lesion: Disinhibition of muscles – Pronator muscles stronger than Supinator, so will see arms drifting downwards towards floor. Drift while supinated does not indicate specific lesions.", "◦ Cerebellar Lesion: Inability to maintain position of arms; you will see an upward drift.", "• Rebound Test: At the end of the Pronator Drift test, keep the patients’ eyes closed. Press down on the palms of both arms simultaneously, and release. You should see arms rebound back to starting position", "◦ Cerebellar Lesion: You will see an accentuation of the upward drift.", "• Arm/Finger Rolling Test: Ask the patient to hold their arms up in front of them, elbows flexed at 90º, forearms parallel to the ground, and with one forearm/finger above the other. Then, have the patient make a forward cycling motion with their arms/fingers.", "• Finger Tapping Test: Ask the patient to tap /oppose the tip of their thumb to the tip of each finger. Pay attention to their ability to do the task, while also looking for involuntary facial movements (e.g. tardive dyskinesia, extrapyramidal symptoms)."], "why": ["To differentiate an UMN lesion from a Cerebellar Lesion. The likelihood of unilateral cerebral hemispheric disease is greatly increased by an abnormal arm rolling test (LR+ 21.7), abnormal pronator drift (LR+ 10.3, LR- 0.1), and moderately increased by abnormal finger tapping test (LR+ 6.6, LR- 0.3)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Additional Posterior Column Sensory Tests Note: Also seen in Ch 14 – Diabetes Foot Exam – MF3.", "phase": null, "tags": ["extra"], "pg": 366, "do": ["• Vibration Test (Pressure): Place 128 Hz tuning fork on bony prominence, especially D1 of Foot to test vibration sense. If no sensation, move to more proximal bony prominences, such as medial malleolus.", "• Proprioceptive Test: Stabilizing the hallux joint at its sides, show what up and down is with eyes open. Then, have the patient close their eyes, and move up and down randomly."], "why": ["Helps further define sensory deficit. Note that cotton ball assesses light touch as component of posterior column testing.", "• Vibration: ↓ in peripheral neuropathies and spinal cord disease", "• Proprioception: ↓ in peripheral neuropathies, spinal cord disease and cortico-hemispheric disease", "• The likelihood of ≥1 falls in the next year in community-dwelling patients ≥65y is increased by absence of vibratory sensation (LR+ 2.0-2.1, LR- 0.73-0.80)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Cortical Sensation Testing", "phase": null, "tags": ["extra"], "pg": 367, "do": ["• Stereognosis: Ability to recognize objects placed in hand. Use common items easily/safely manipulated in hand (pen cap, coin, watch, paper clip).", "• Graphesthesia: Ability to recognize numbers or letters traced on skin. Note that some drawings are difficult to distinguish in a normal person (e.g. drawing a 3 poorly could be interpreted as an 8).", "• Two-Point Discrimination: Ability to discriminate between when two points on body are stimulated, vs. only one. To test, touch individual body parts B/L at same time; more sensitive if testing different regions B/L (e.g. Point 1 = right face; Point 2 = left hand). Alternate between touching only Point 1, only Point 2, and both, and ask which was touched each time."], "why": ["For cortical sensation, intact primary sensation (i.e. Posterior Column & Spinothalamic Tracts in Screening exam normal) is necessary but not sufficient to preserve cortical sensation (higher order sensory testing). If primary sensation deficits (spinal cord or lower) exist, these tests will generate false +ve cortical sensation deficits:", "• Deficits in Stereognosis and Graphesthesia may indicate lesion to contralateral primary sensory cortex (post-central gyrus), or secondary association areas in parietal, temporal or occipital lobes.", "• Deficits in Two-point discrimination are a sign of sensory inattention, commonly localizing to a lesion in parietal lobe of non-dominant hemisphere (Right-handed = Left-dominant; Left-handed = 90% of patients Left-dominant, 10% Right-dominant)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Brainstem Reflexes", "phase": null, "tags": ["extra"], "pg": 367, "say": ["I will now test the brainstem reflexes."], "do": ["• Pupillary Light Reflex: Shine penlight into each eye, testing the direct and consensual response. With intact brainstem, see both direct and consensual pupillary constriction. If pupillary light reflex is lost, the pupils will be mid-position and size 3.5-4mm with no pupillary constriction direct or consensual.", "• Corneal Reflex: Touch cornea with a small piece of wet cotton wool, or squirts of water or saline to one side. Observe whether both eyes blink.", "• Oculocephalic Reflex (Doll’s Eye – AVOID in C-spine trauma): Observe eyes with passive rotation of head – with intact brainstem, patient eyes will move in opposite direction to head movement. If doll’s eye reflex lost, globes will remain fixed, and eyes will stare in whatever direction the head is pointed.", "• Oculovestibular Reflex (Cold Calorics):", "◦ Inspect tympanic membrane first to ensure no perforation or impacted cerumen", "◦ With head raised 30 degrees from horizontal (to facilitate irrigation), irrigate 50-120mL ice water slowly into auditory canal. Wait 5 minutes, then repeat on other side. If brainstem intact, expect tonic deviation of both eyes toward irrigated ear. If cold caloric reflex lost, eyes would not move.", "• Jaw Jerk Reflex: Ask patient to open mouth and relax jaw. Place finger on chin and tap with reflex hammer. Observe for increased jerk (slight jerk is normal - ↑ jerk indicates bilateral UMN lesion).", "• Gag Reflex: Use tongue depressor or suction tube to depress patient’s tongue. Touch palate, pharynx or tonsil on each side until patient gags. If brainstem intact, observe soft palate rises symmetrically.", "• Cough Reflex (intubated patients): Apply deep suction through endotracheal tube to the carina. If brainstem intact, will see gasp and several rapid coughs."], "why": ["Brainstem Reflexes test Cranial Nerves spanning from Midbrain to Medulla, as follows:", "Brainstem Reflex Afferent Arc Efferent Arc Brainstem Area Pupillary Light CN II CN III (E-W) Midbrain Corneal Reflex CN V1 CN VII Pons Oculocephalic Reflex (Doll’s Eye) CN VIII CN III, IV, VI Pons-Midbrain Oculovestibular Reflex (Cold Calorics) CN VIII CN III, IV, VI Pons-Midbrain Jaw Jerk CN V3 CN V3 Pons Gag CN IX CN X Medulla Cough CN X CN X Medulla", "• Diagnosis 1: Brain Death – 3 conditions required:", "◦ Persistent Coma: No eye, verbal or movement response to painful stimulus (Glasgow Coma Scale 3)", "◦ No Brainstem Reflexes:", "◦ Apnea Test: No breathing for 8-10 minutes without mechanical ventilation in response to PaCO2 >60mmHg or 20mmHg greater than baseline values and final arterial pH <7.28.", "▪ Prerequisites: With patient Core temperature >36oC, Systolic BP >100mmHg, PaCO2 35-45mmHg (i.e. ABG pre-test), absent hypoxia, and euvolemic state.", "▪ Not Valid In: CO2-retainers; Neuromuscular paralysis; or high C-spine cord lesions.", "• Diagnosis 2: Persistent Vegetative Stage: Permanent after 6 months (non-traumatic), 1 yr. (traumatic)", "◦ No awareness of self or environment, inability to interact with others.", "◦ No evidence of sustained, reproducible, purposeful or voluntary behavioural responses to stimuli."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Frontal Release Signs", "phase": null, "tags": ["extra"], "pg": 368, "do": ["• Glabellar Tap Sign: Tap patient’s forehead above eyes with your index finger 5-10 times. This causes reflexive contraction of orbicularis oculi muscle where both eyes blink. The patient should stop blinking after 5-10 taps. If blinking persists → Myerson’s sign, suggests frontal release seen in Parkinsonism", "• Palmomental Reflex – scrape the palm, look to see if the omentum (chin) moves; abnormal to elicit the chin muscle twitch re positive frontal release sign", "• Palmar Grasp – place object in patient’s palm; assess whether patient flexes their fingers in response.", "• Plantar Grasp – place object in patient’s sole of foot; assess whether patient curls toes in response."], "why": ["Primitive reflexes exist in infancy, disappear as brain matures in childhood, but can then reappear if normal cortical inhibitory pathways are disrupted. An abnormal Glabellar Tap Sign increases the likelihood of suspected Parkinson’s Disease (LR+ 4.5, LR- 0.13). The likelihood of ≥1 falls in the next year in nursing home residents ≥65y is increased by presence of palmomental reflex (LR+ 2.8, LR- 0.8)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Digital Rectal Exam (for Rectal Tone)", "phase": null, "tags": ["extra"], "pg": 368, "do": ["For instructions on performing a DRE, please see Chapter 13 – Abdominal Examination, in MF3"], "why": ["A decreased anal tone is indicative of a UMN lesion and is a critical screen when you’re clinically differentiating an UMN lesion from a LMN lesion (where tone is preserved)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Parietal Neglect", "phase": null, "tags": ["extra"], "pg": 368, "do": ["Patient keeps both eyes open, examiner’s hands in both right and left visual fields. Move fingers in either field – assess whether if moving both left and right simultaneously, but they can only see one."], "why": ["If you suspect a lesion in parietal lobe (spatial awareness, perception & integration centres)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Gower’s Sign (Pediatrics)", "phase": null, "tags": ["extra", "peds"], "pg": 368, "do": ["When rising from a seated position, you normally need to use hip extension, knee extension and ankle dorsiflexion. In a +ve Gower’s sign, children climb up themselves to rise from a chair (Typically Ages 4-7)"], "why": ["Gower’s sign is useful for Duchenne’s Muscular Dystrophy screening, as it tests the proximal muscle groups that patients with DMD exhibit motor weakness in."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Subclavian Steal Screen", "phase": null, "tags": ["extra"], "pg": 368, "do": ["Arm Exercises: Repetitive arm motions, see if the patient has become dizzy"], "why": ["Subclavian Steal is Retrograde blood flow in vertebral artery or internal thoracic artery due to proximal stenosis or occlusion of subclavian artery. Causes vertigo, visual changes, loss of consciousness. Patients may complain of chest pain as well–episodes can be provoked by exercise of the ipsilateral arm."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Meningismus", "phase": null, "tags": ["extra"], "pg": 368, "do": ["• Kernig’s Sign: Patient lies supine with one leg on exam table, and one leg with hips and knees flexed at 90 degrees. Patient resists full extension of the flexed knee by the examiner. Repeat on the other side. A positive sign is resistance or pain and inability to extend patient’s knee beyond 135 degrees because of pain.", "• Brudzinski’s Sign: Patient lies supine; examiner passively flexes the neck. A positive sign for meningeal irritation is bilateral flexion of hips/knees on passive flexion of neck.", "• Jolt Accentuation of Headache: Ask the patient to turn their head horizontally at a frequency of 2-3 rotations per second. Worsening of baseline headache represents a positive sign."], "why": ["The classic triad of meningitis is fever, headache and neck stiffness (sometimes aLOC is included), however often only 1-2 of these will be seen in patients with meningitis. Fever has a sensitivity of 87%, Headache has a sensitivity of 68%, Neck stiffness has a sensitivity of 80%, and Altered Mental Status has a sensitivity of 69% for adult patients with acute meningitis, where the classic triad of fever, headache and neck stiffness has a sensitivity of only 46%. Kernig’s & Brudzinski’s Signs along with Jolt accentuation of headache are all tests of meningeal irritation. Do NOT perform Brudzinski’s sign in patients with suspected cervical instability e.g. trauma presentations."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Timed Up-AndGo (TUG) Test", "phase": null, "tags": ["extra"], "pg": 369, "say": ["I will assess your ability to rise from your chair, walk a short distance at your normal speed, and then come back to sit down in your chair. Please use your mobility aid (e.g. walker, cane) if needed."], "do": ["Allow patient one practice run. Patient rises from their chair, and timer starts once the patient’s back is off their chair. Patient walks a line on the floor 3 meters away. They then turn, return to the chair, and sit down again. Timer stops when the patient’s buttocks touch the seat of the chair."], "report": ["The patient’s timed up-and-go test was 12 seconds."], "why": ["The Timed Up and Go test is important in assessing patients for falls risk. The likelihood of ≥1 fall in the next year in nursing home patients ≥65y is mildly increased by timed up-and-go test >35 seconds (LR+ 2.6), while it is greatly decreased by timed up-and-go test <15 seconds (LR+ 0.1)."], "imgs": []}]}, "mse": {"title": "Mental status exam", "pg": [375, 390], "steps": [{"sec": "Mental status exam (in write-up order)", "name": "Appearance", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Age (looks stated age?), sex/gender presentation, build, dress & grooming, hygiene, distinguishing features, position (e.g. sitting up in bed)."], "report": ["32-year-old woman who appears younger than stated age; reasonably groomed, dressed in hospital gown; sitting up in bed."], "gloss": []}, {"sec": "Mental status exam (in write-up order)", "name": "Behaviour", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Eye contact, psychomotor activity (agitation/retardation), abnormal movements (tremor, tics, tardive dyskinesia, EPS), mannerisms."], "report": ["Some increased psychomotor activity (wringing hands). Good eye contact. No abnormal movements."], "gloss": ["Other Movements: No abnormal movements, fidgety, bobbing knee, facial tic, parkinsonism, decreased shoulder movement, lip-smacking, lip-puckering, twitching, jittery, tremulousness, resting tremor, essential tremor, restless, wringing hands, motionless, rigid, limp, stiff, slumped, asymmetrical", "Advertence/Aversion: Turning towards/away from the examiner in an exaggerated way when addressing them", "Agitation: Excessive motor activity and restlessness (e.g. fidgeting or pacing)", "Akathisia: A state of motor restlessness, sometimes produced by neuroleptic medication, that ranges from a feeling of inner distress to an inability to sit still (e.g. shuffling feet or pacing)", "Ambitendence: Alternation of opposite movements (e.g. putting out a hand and then pulling it back again before the action can be completed)", "Athetosis: Slow semi-rotatory and writhing movement of the limbs", "Avolition: Decrease in self-initiated purposeful activities – can present as sitting for long periods of time, showing little interest in participating in work/social activities.", "Catalepsy: Limbs can be placed in any posture, maintained for unusually long time (vs. mitmachen, mitgehen & wavy flexibility)", "Catatonia: Motor inability and stupor-like state", "Catatonic Excitement: Purposeless and excessive motor activity without obvious cause", "Chorea: Sudden, jerky and involuntary movements of > 1 muscle group that resemble fragments of goal- directed behaviour", "Compulsion: The behavioural component of an obsession. The individual feels compelled to repeat a behaviour which has no immediate benefit beyond reducing the anxiety associated with the obsessional idea. Associated with phobias as well", "Dyskinesia: Abnormal movements as in tardive dyskinesia involving late-onset of abnormal involuntary movements. Tardive dyskinesia is conventionally thought a late side effect of first-generation antipsychotics, but some abnormal movements were seen in schizophrenia before the introduction of antipsychotics", "Dystonia: Abnormal tonicity of muscle, characterized by prolonged, repetitive muscle contractions that may cause twisting or jerking movements of the body or a body part", "Echopraxia: Imitation of the examiner’s body movements despite requests not to do so", "Extrapyramidal Side Effects (EPS): Physical symptoms primarily associated with improper dosing of or unusual reactions to neuroleptic (anti-psychotic) medications, including tremor, slurred speech, akathisia, dystonia, anxiety, distress, paranoia, and bradyphrenia", "Forced Grasping: Repetitive grasping and shaking of the examiner’s body movements despite requests not to do so", "Gegenhalten: Involuntary resistance to passive movement", "Mannerism: Odd, repetitive and goal-directed movement (vs. stereotypy as non-goal directed)", "Mitgehen: An extreme form of mitmachen – the limbs can be placed in any posture, even at a slight touch", "Mitmachen: Limbs can be placed in any posture, after which return to resting position (vs. mitgehen, catalepsy, & wavy flexibility)", "Mutism: Failure to speak despite the physical ability to do so", "Myoclonus: Sudden, jerky and involuntary movement of a muscle or a group of muscles", "Negativism: Found on examination, refers to when a patient resists and does the opposite of what is asked. It is usually a sign of catatonia. It may progress to (catatonic) rigidity. It is slightly different from gegenhalten in which the patient resists movement but does not perform the opposite movement", "Obstruction: Irregular blocking of movements", "Orobuccal: Continual chewing movements, lip smacking, puckering and pursing. (e.g. in tardive dyskinesia)", "Posturing: Voluntary association and maintenance of unusual and uncomfortable body postures, often for hours on end. This includes “psychological pillow” in which the patient lies prone with head raised a few cm above horizontal as if resting on an invisible pillow", "Retardation: Lack of motor activity; the opposite of agitation", "Rigidity: Maintenance of a rigid posture against attempts to be moved", "Static Tremor: Resting tremor, usually attenuated by voluntary movement", "Stereotypies: Odd, repetitive and non-goal-directed movements (vs. mannerisms as goal-directed)", "Stupor: Extreme form of retardation such that the patient is immobile and mute", "Tardive Dyskinesia: Abnormal involuntary movement disorder which may manifest as lip-smacking, bucco-lingual movements or grimacing, truncal movements or athetoid limb movements", "Tic: Involuntary, sudden, rapid, recurrent, non-rhythmic, stereotyped movement or vocalization", "Wavy Flexibility: Slight & Even resistance to positioning by examiner (vs. catalepsy, Mitgehen and Mitmachen)"]}, {"sec": "Mental status exam (in write-up order)", "name": "Cooperation", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Attitude toward the interviewer: cooperative, guarded, evasive, hostile; reliability as a historian."], "report": ["Pleasant and cooperative throughout the interview."], "gloss": []}, {"sec": "Mental status exam (in write-up order)", "name": "Mood", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Inquired", "do": ["Ask directly: “How has your mood been lately?” Record the patient’s own words in quotes."], "report": ["Mood: “ok, but a bit anxious”."], "gloss": []}, {"sec": "Mental status exam (in write-up order)", "name": "Affect", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Comment on quality (euthymic, dysphoric, anxious, euphoric, flat), range (broad, restricted, blunted, flat), stability (stable vs. labile), congruence with mood, and appropriateness to content."], "report": ["Affect euthymic, broad range, stable, congruent and appropriate."], "gloss": ["Indifferent: Indifferent, shallow, superficial, cool, distant, apathetic (lack of interest or concern especially on matters of general importance or appeal, impassiveness), aloof, dull, vacant, affectless (lack of emotional reactivity), uninterested, cynical", "Isolation of: Defense mechanism where emotion is detached from an idea and rendered unconscious, leaving the idea bland and emotionally flat. It is often a feature of Obsessive-Compulsive Disorder"]}, {"sec": "Mental status exam (in write-up order)", "name": "Speech", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Rate, rhythm, volume, tone/prosody, articulation, latency, spontaneity, quantity (e.g. pressured, poverty of speech)."], "report": ["Speech normal rate, rhythm and volume."], "gloss": ["Corprolalia: Involuntary utterance of socially inappropriate phrases. It is a phonic tic associated with Tourette syndrome, although < 15% of persons with Tourette’s have coprolalia", "Cryptolalia: Use of an entire private idiom", "Dysarthria: Impairment of ability to articulate speech", "Dysphasia: Impairment of ability to comprehend or express language", "Dysphonia: Impairment of ability to vocalize speech", "Dysprosody: Unusual speech rhythm, melody, intonation or pitch", "Glossolalia: Use of non-speech sounds as a substitute for speech", "Logoclonia: Repetition of the last syllable of every word", "Logorrhoea: Increased quantity (but not rate) of speech", "Metonym: Use of an existing word but with a new meaning attached to it", "Paragrammatism: Incorrect grammatical construction", "Paraphasia: Incorrect selection of words; the production of one word when another is meant", "Poverty of Speech: Reduced quantity of speech – brief, unelaborated or unanswered response to questions. Occurs in Hypothyroidism, dementia, depression, and severe chronic schizophrenia.", "Pressure of Speech: Increased quantity and rate of speech; speech is difficult to interrupt", "Pseudologica: Fluent and plausible lying", "Verbigeration: Meaningless repetition of words or phrases, not necessarily requiring external stimulus to elicit (as opposed to perseveration, which is an inappropriately persistent response to a stimulus)"]}, {"sec": "Mental status exam (in write-up order)", "name": "Thought process / form", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed & inquired", "do": ["How thoughts connect: logical and goal-directed vs. circumstantial, tangential, flight of ideas, loosening of associations, thought blocking, perseveration."], "report": ["Thought form logical and coherent."], "gloss": ["Concrete Thinking: Inability to understand abstract concepts and metaphorical ideas as demonstrated by a literal understanding of proverbs. (E.g. “He who lives in a glass house should not throw stones”)", "Circumstantiality: A pattern of speech that seems to wander because of excessive detail, but eventually reaches its goal idea – often not pathological", "Clang Associations: Pattern of speech observed in some types of mental illness, such as manic disorder, in which associations are based on punning or rhyming. Linkage of words is based on sound rather than meaning.", "Derailment: “Loosening of associations” or pattern of speech in which a person’s ideas slip off one track into another in a way that is completely unrelated. The person shifts from one frame of reference to another in a way that lacks any meaningful relationship. This is a common symptom of mania or schizophrenia", "Dereistic Thinking: Idiosyncratic thinking that is not being falsified by reality (e.g. daydreaming)", "Echolalia: A speech disorder in which the person inappropriately and automatically repeats the last words he or she has heard. Palilalia is a form of echolalia in which the last syllable heard is repeated endlessly", "Flight of ideas: Rapid, continuous verbalizations with constant shifting from one idea to another – a form of derailment. It has strong connotations with mania, but also occurs in Schizophrenia, substance intoxication, and some neurological syndromes. In mania and hypomania specifically, thoughts become pressured, and ideas may race from topic to topic, guided sometimes only by rhymes or puns. Ideas are associated thoughts, unlike thought disorder.", "Knight’s Move Thinking: Phenomenon similar to derailment of thought or loosening of associations, characterized by odd, tangential associations between ideas that lead to disruption in the smooth continuity of speech. The name for this disorder likely derived from the odd movement pattern of knights in the game of chess", "Loose associations: In schizophrenia, an aspect of thought disorder wherein the patient has difficulty sticking to one topic and drifts off on a train of associations evoked by an idea from the past", "Neologisms: The creation or use of new words or senses; including word approximations and word distortions", "Overinclusive: Inability to preserve the conceptual boundaries of thought. This is experienced by the examiner as circumstantiality", "Palilalia: Repetition of a word or phrase after once having said (a perseveratory phenomenon)", "Paralogia: False reasoning or self-deception characterized by inappropriate responses to questions. Based on underlying autistic or dereistic processes as in schizophrenia", "Perseveration: Repetition of a movement or behaviour, or topic requested by the examiner even after it is no longer appropriate. Perseveration is sometimes a feature of frontal lobe lesions (vs. verbigeration which doesn’t require the initial external stimulus). Be careful of perseveration of a topic vs word; not considered a perseveration if there is a play on a single word (which is clang associations)", "Poverty of Content: Speech conveying very little information. Language tends to be vague, often over-abstract or over- concrete, repetitive and stereotyped. Generally, the person can speak at great length, but without giving adequate information to answer questions. Often a result of derailment.", "Tangentiality: A pattern of speech where one tends to get off topic by responding to questions obliquely rather than directly – never coming back to the question", "Thought Blocking: Unpleasant experience of having one’s train of thought curtailed absolutely, often more a sign than a symptom", "Thought Disorder: Disorder of the form of thought, where associations between ideas are lost or loosened – typically inferred from speech.", "Word Salad: An extreme form of derailment - confused, often repetitious language with no apparent meaning or relationship attached to them. It is often symptomatic of various mental illnesses, such as psychoses including schizophrenia. Also called incoherence."]}, {"sec": "Mental status exam (in write-up order)", "name": "Thought content", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed & inquired", "do": ["Always comment on suicidal ideation (SI), homicidal ideation (HI) and presence/absence of delusions (with sub-type and example if present).", "Also: obsessions, compulsions, preoccupations, phobias, overvalued ideas, prominent depressive or anxious cognitions, themes of discussion."], "report": ["No SI, HI, or delusions. Thought content notable for themes of loss."], "gloss": ["Capgras Syndrome: Patient feels that a person familiar to them, usually a family member, has been replaced by a double i.e. an identical looking imposter. Capgras syndrome and Fregoli syndrome along with some other conditions are classified as delusional misidentification syndromes", "Delusion: A false belief not susceptible to argument and inconsistent with subject’s sociocultural background", "Delusional memory: Attribution of delusional significance to a normal percept – a first rank symptom of schizophrenia", "Delusional mood: A feeling that something unusual is about to happen of special significance for that person", "Delusional Perception: Attribution of delusional significance to a normal percept – a first rank symptom of schizophrenia", "Delusions of Control,: Delusions they are being controlled by another person or thing; the belief they are being made to do something or feel emotions from an outside force. This is a first rank symptom of schizophrenia", "Delusions of Thought Control: Delusions that their thoughts are being controlled by another person or being. This is a first rank symptom of schizophrenia, and includes the following subtypes of delusions of thought control: • Thought Insertion  Thoughts which are not their own put into their head • Thought withdrawal  Thoughts are being removed from their head • Thought broadcasting  Thoughts are accessible to other people", "Delusions of: Delusions of exaggerated self-importance – that they have special powers, status, abilities or role in the world, or a special relationship to a deity or famous person", "Delusions of Guilt: Delusions that they have committed a crime, or sinned greatly, and deserve punishment", "Delusions of: Delusions that one’s skin is infested by parasites. In the context of a monosymptomatic delusional disorder, this is referred to Ekborn’s syndrome", "Delusions of Jealousy (Othello Syndrome): Delusions in which a person believes that their spouse or sexual partner is being unfaithful, often associated with violence and stalking behaviour. The affected person typically makes repeated accusations of infidelity based on insignificant or minimal evidence and will go to considerable lengths to monitor their partner’s behaviour and movements. Most common in males", "Delusions of Love: Delusions of being loved by a person that one has never spoken to or by an inaccessible person. Most common in females", "Delusions of Misidentification: • Capgras’ Syndrome: Delusion that a familiar individual has been replaced by an identical-looking imposter (separate definition above) • Fregoli’s Syndrome: Delusion that a familiar individual is disguising as various strangers • Intermetamorphosis: Delusions that a familiar individual transformed into another person • Subjective Doubles or Doppelganger of Oneself: In clonal pluralization, there is more than just one Doppelganger • Reduplicative Paramnesia: Delusion that an object, place or person has been doubled • Delusional Companions: Delusion that objects are sentient beings, as in children’s cartoons", "Delusions of: Delusions that one is being persecuted – that people are conspiring against them or that they are being followed.", "Delusions of Poverty: Delusions in which a person believes they are financially troubled", "Delusions of: Strongly held belief that random events, objects, media content, or behaviours of others have an unusual significance to oneself.", "Erotomanic Delusions: Delusions in which the person has a false belief that a particular person is deeply in love with them. Lack of response is rationalized, and pursuit and harassment may occur", "Folie a Deux: Also called induced psychosis, folie a deux is a delusional disorder shared by two or more people who are closely related emotionally. One has a real psychosis, while the symptoms of psychosis are induced in the other or others due to a close attachment to the one with psychosis. Separation usually results in symptomatic improvement in the one who is not psychotic", "Fregoli’s Syndrome: Delusional belief that different people are in fact a single person who changes appearance or is in disguise. The delusional person often believes that he or she is being persecuted by the person he or she believes to be in disguise", "Ideas of Reference: Delusional ideas wherein seemingly random stimuli are thought to be referring to the individual. For example, if a car beeps outside, the individual feels it was directed toward them.", "Magical Thinking: An irrational belief that certain outcomes are connected to certain thoughts, words or actions (e.g. if I hold my nose, someone will die)", "Nihilistic Delusions: Delusion that they are decomposing, their bodies don’t work, and their internal organs are rotten or solidifying, or even that they are actually dead", "Obsession: An unpleasant or nonsensical thought which intrudes into a person’s mind, despite a degree of resistance by the person who recognizes the thought as pointless or senseless, but nevertheless a product of their own mind. Obsessions may be accompanied by compulsive behaviours which serve to reduce the associated anxiety. An example is the idea that one’s hands are covered with dirty germs.", "Overvalued Idea: Idiosyncratic and firmly held belief which is in itself acceptable and comprehensible, but which comes to dominate thinking and behaviour. It differs from a delusion in that the belief is not fixed, and from an obsessional thought in that it is not perceived as being senseless", "Passivity Phenomenon: Individual feels some aspect of themselves is under external control of another or others. These include “made acts and impulses” where individual feels they are being made to do something by another;” made movements” where their arms or legs feel as if they are moving under another’s control; “made emotions” where they are experiencing someone else’s emotions; and “made thoughts” characterized under delusions of thought control as insertion and withdrawal", "Phobia: Irrational, intense, persistent fear of certain situations, activities, things or people, generally associated with anxiety disorders. Involves an excessive, unreasonable desire to avoid the feared subject or object. Associated with compulsions.", "Preoccupations: May involve patient’s illness, environmental problems. Suicidal or homicidal preoccupations, thoughts, wishes, impulses or plans.", "Religious Delusions: Delusions about God that are either guilt-oriented (being punished for something minor) or expansive (having a special mission or special powers)", "Rumination: Repetitive, pointless internal debates, often with pseudo-philosophical issues and obsessional quality", "Somatic Delusions: Delusions about the body, for example, having a medical condition or deformity. Also referred to as hypochondriacal delusions (vs. somatoform disorder, factitious disorder, malingering)", "Thought Broadcasting: Experience that one’s thoughts are being transmitted from one’s mind and broadcast to everyone", "Thought Insertion: Experience of alien thoughts being inserted into the mind", "Thought Withdrawal: Experience of thoughts being removed or extracted from one’s mind"]}, {"sec": "Mental status exam (in write-up order)", "name": "Perception", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed & inquired", "do": ["Ask about hallucinations (auditory, visual, tactile, olfactory, gustatory) and illusions; note whether patient appears to be responding to internal stimuli. If present, give sub-type and an example."], "report": ["No perceptual abnormalities; not responding to internal stimuli."], "gloss": ["Agnosia: Inability to organize sensory information to recognize objects (e.g. visual agnosia), or even parts of their body (e.g. hemisomatoagnosia)", "Auditory Hallucinations: • Simple Sounds • Complex Sounds – Voices may be second person (talking to the patient) or third person (talking about the patient), or may be a running commentary • Command hallucinations (imperative hallucination, teleological hallucination) refers to an auditory hallucination of a commanding voice • Gedankenlautweden (German: thoughts becoming loud) – thoughts are “heard” as they are being formulated (vs. thought broadcasting, echo de la pensee) • Echo de La Pensee (French: Echo of thoughts) – thoughts are “heard” shortly after they are formulated (vs. Gedankenlautweden, thought broadcasting)", "Command Hallucinations: Auditory hallucinations instructing patient to act in specific ways (associated with schizophrenia)", "Completion Illusions: Illusions that arise during periods of inattention", "Déjà vu: Already seen-sure a new situation has happened previously. Common in Anxiety Disorders and Temporal Lobe Epilepsy", "De-personalization: An experience where the self is felt to be unreal, detached from reality or different in some way. Depersonalization can be triggered by tiredness, dissociative episodes or temporal lobe seizures. Common in Anxiety Disorders and PTSD.", "Derealisation: An experience person perceives world around them to be unreal – linked to depersonalization.", "Extracampine: Hallucinations outside the limits of the sensory field (e.g. Hearing voices from Antarctica)", "Functional Hallucinations: Hallucinations triggered by an environmental stimulus in the same modality (e.g. Hallucinatory voices that are triggered by the sound of a running tap – reflex hallucination, synaesthesia)", "Gustatory Hallucinations: Hallucinations involving sensation of taste in absence of stimulus but are regarded by individual as real. May arise in temporal lobe epilepsy. Patient may interpret as result of poisoning.", "Hyperacusis: Super sensitivity to sounds to point of difficulty tolerating everyday noise. Common in Substance Withdrawal, Organic damage (especially damage to the acoustic nerve), Migraine headaches.", "Hypnogogic Hallucination: Visual or auditory hallucinations on going to sleep – not pathological", "Hypnopompic: Visual or auditory hallucinations on awakening – not pathological", "Jamais vu: Opposite of déjà vu, eerie feeling a familiar situation seems new. Common in Amnesia, Migraine Auras, and Temporal Lobe Epilepsy", "Lilliputian Hallucinations: Lilliputian Hallucinations are characterized by abnormal perception of objects as being shrunken in size but normal in detail. Usually seen in delirium tremens", "Olfactory Hallucinations: False perception of strong or pungent, often unpleasant odours; usually a result of organic disease but may signify psychiatric disease. For example, the person may smell decaying fish and believe that this odour is emanating from them; another common olfactory hallucination is burning rubber.", "Palinacousis: Subject continues to listen to a word, a syllable or any sound, even after the withdrawal of stimulus (a perseveratory phenomenon)", "Palinopsia: Persistence of recurrence of an image long after stimulus removed (perseveratory phenomenon)", "Paraidolic Illusions: Illusions that arise from poorly defined stimuli (e.g. seeing “shapes” in the clouds)", "Pseudo-hallucinations: Differ from a hallucination; these arise from the mind (inner space) and not from the sense organs (outer space). As such, they lack the quality of a true hallucination", "Reflex Hallucinations: Hallucinations triggered by an environmental stimulus in another modality (e.g. visual hallucinations triggered by the sound of music)", "Sensory Distortions: Sensory distortion includes distortions of intensity, colour, form and proportions", "Somatic Hallucinations: Hallucination of a physical state or event within the body, such as an electrical impulse running down one’s arms of an object inside one’s chest. Needs to be distinguished from physical sensations from undiagnosed medical conditions, hypochondriac preoccupation from normal physical sensation, and tactile hallucinations (e.g. insects under skin)", "Somatization: Conversion of an emotional, mental or psychosocial problem to a physical complaint", "Synesthesia: Neurologically based phenomenon in which stimulation of one sensory or cognitive pathway leads to automatic, involuntary experiences in a second sensory or cognitive pathway. This is known as “joined perceptions”. For example, tasting chocolate when you hear a specific song", "Tactile Hallucinations: A false sense of being touched or of something touching the skin. For example, a feeling of electric shock or sensation from an amputated limb", "Visual Hallucinations: • Simple: Flashes of light; Complex: Images of objects, animals and people • Panoramic Hallucination: Images of objects, animals and people PLUS the background • Lilliputian Hallucination: Images of objects, animals and people that are smaller than in reality (the inhabitants of Lilliput in Gulliver’s Travels are 6 inches tall) • Eidetic Image: Unusually vivid mental images of object (flashback, “photographic memory”) • Charles Bonnet Syndrome: Isolated, complex visual hallucinations usually secondary to sudden loss of vision • Autoscopic Hallucination: Image of the self is projected into external space. Differs from a near-death experience in that it does not involve a feeling of being outside the body • Negative Autoscopy: Image of the self cannot be seen in mirrors"]}, {"sec": "Mental status exam (in write-up order)", "name": "Cognition", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed (formal testing as needed)", "do": ["Level of consciousness, orientation (person, place, time), attention/concentration, memory. Screen with MMSE, MoCA or Mini-Cog if concern."], "report": ["Cognition grossly intact, not formally tested."], "gloss": ["Confabulation: Changing, loosely held and false memories created to fill in an organically derived amnesia delusion: an incorrect belief which is out of keeping with the personal cultural context, intelligence and social background, and which is held with unshakeable conviction"]}, {"sec": "Mental status exam (in write-up order)", "name": "Insight", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Awareness that they have an illness and need for treatment (full, partial, poor/absent)."], "report": ["Some insight into her issues."], "gloss": []}, {"sec": "Mental status exam (in write-up order)", "name": "Judgment", "phase": null, "tags": [], "pg": 383, "imgs": [], "how": "Observed", "do": ["Ability to make sound decisions; give an example from the history if impaired."], "report": ["Poor judgment (putting her health at risk through impulsive behaviours)."], "gloss": []}], "notes": ["Observed from open-ended interviewing: level of consciousness, appearance, behaviour, cooperation, affect, speech, thought process.", "Must be asked directly: orientation, cognition, SI/HI, perception, mood, thought content, insight, judgment.", "Always include every heading, even if not elicited (“Mood was not elicited during the interview”).", "Serious omissions: SI, HI, delusions, hallucinations, insight, judgment."]}, "eye": {"title": "Ophthalmology", "pg": [441, 451], "notes": [], "steps": [{"sec": "Ophthalmic exam", "name": "Visual Acuity (VA) Measurement (Adults and Children ≥5 years old)", "phase": null, "tags": [], "pg": 444, "do": ["• Say: I will assess your vision reading an eye chart. If you have glasses or contacts, please keep them on as I need to test your corrected vision. Please squint if you need to. Please cover one eye. METHOD 1 – POCKET SNELLEN CHART:", "• Setup: Holding pocket Snellen chart to patient’s nose 16 inches from patient’s nose (slightly more than a card length) to ensure an appropriate reading distance.", "• Do: With one eye covered, read from bottom of card up, reading the lowest line they can. Then, cover the other eye, and read from top down, until they reach the lowest line they can (this prevents the patient from remembering the lines which would obscure results).", "• Report: The patient has a vision of 20/20 in both the left and right eyes. METHOD 2 – PROJECTOR SNELLEN CHART:", "• Setup: Have patient 20 feet (6 meters) away from chart.", "• Do: With one eye covered, read lowest line they can. Then cover the other eye and read the lowest line (in reverse order).", "• Report: The patient has a vision of 20/20 in both the left and right eyes. CONDITIONAL TEST – IF PATIENT CANNOT SEE THE 20 / 400 (big E) LINE:", "• Say: I will now ask you to count fingers at a distance, and a couple other vision tests if needed.", "• Do – Counting Fingers (CF): Hold up your fingers at varying distances (e.g. 5 metres, 4 metres, etc.) and ask the patient to count fingers. Record the maximum distance they can count fingers between 1 and 5 metres (e.g. VA = CF 5 metres or VA = CF 1 metre)", "• Do – Hand Motion (HM): If patient unable to count fingers at 1 metre, wave your hand at 1 metre away and ask if the patient can see this. Record if the patient can see Hand Motion (e.g. VA = HM)", "• Do – Light On/Off Light Perception (LP or NLP): If patient unable to Count Fingers or see Hand Motion at 1 metre away, shine a light in eye and check if the patient can see the light. Record if the patient can see the light (VA = LP) or are unable to see the light (VA = NLP).", "• Report: The patient is unable to count fingers but is able to see Hand Motion. Documentation: (e.g. VA cc OD 20 / 40, OS CF at 2 feet)", "• Document on chart cc for corrected vision (with glasses or contacts), sc for uncorrected vision.", "• If pinhole available, document if vision improves with pinhole.", "• What does 20 / 100 – 2 mean? A patient sees at 20 feet what a normal sighted patient sees at 100 feet; with 2 letters incorrect on that line.", "• What does 20 / 100 + 2 mean? A patient sees at 20 feet what a normal sighted patient sees at 100 feet; with 2 correct and 3 incorrect on the line below."], "why": ["Visual Acuity is one of the 3 “vital signs” in ophthalmology, along with pupillary response to light and intraocular pressure. Visual acuity is a test of macular function and optic nerve function.", "• Design of Snellen Charts: 20/20 - Numerator is test distance; denominator is distance that a normal sighted person able to identify letter → e.g. 20/70, patient can discriminate letter from 20 feet, whereas a normal person can do so at 70 feet. Can use pocket Snellen chart in limited exam settings.", "• Ametropia: Refractive error in vision", "• Myopia: Near sightedness – sharp image formed in front of retina; refractive power too strong for axial length of eye", "• Hyperopia: Far sightedness – sharp image formed behind retina; refractive power not strong enough for axial length of eye", "• Why does Squinting improve visual acuity? Squinting ↓ light rays entering eye → ↓overall blurring of image. If squinting improves vision, ↑ suspicion refractive error is contributing to ↓ visual acuity. If squinting does not improve vision, ↑ suspicion of organic problem in visual pathway contributing to the ↓ acuity. This is why all abnormal visual acuity is tested with pinhole (PH) to eliminate any refractive error contributing to low visual acuity.", "• What is legal blindness? 20 / 200 best corrected visual acuity (wearing distance glasses) or worse in better eye.", "• What is legal requirement of vision to hold Ontario G or M license? 20 / 50 best corrected visual acuity in their better eye.", "• Note: flight license 20 / 30 best corrected visual acuity or better in better eye and uncorrected is not less than 20 / 200.", "• Pediatrics: For children 3-5 years old – use an Allen Picture Chart; for children 0-3 years old – assess ability to Fix and Follow a toy – described in Pediatric Ophthalmology section (below)"], "imgs": []}, {"sec": "Ophthalmic exam", "name": "Pupillary Response to Light", "phase": null, "tags": [], "pg": 445, "do": ["• Say: I will assess each eye’s response to light. Please remove your glasses and keep both eyes open during this test.", "• Do: Inspect pupil size (Snellen Pocket card tends to have a guide). ≤1 mm difference between two eyes is normal. Using a flashlight, shine light in one eye. Look for pupillary constriction both direct and consensual (part of the Pupillary Light Reflex). Repeat in other eye. Then, swing flashlight back and forth between both eyes, each pupil should constrict (no relative afferent pupillary defect).", "• Report: Pupils are equal and reactive to light, there is no relative afferent pupillary defect."], "why": ["Pupillary Response to Light is one of the 3 “vital signs” in ophthalmology, along with Visual Acuity and Intraocular Pressure.", "• Pupillary Response: PERRLA (Pupils Equal Round and Reactive to Light & Accommodation) test has high sensitivity for optic nerve disease, ipsilateral brain herniation, and Posterior Communicating Artery (Circle of Willis) aneurysm. It also has high sensitivity & specificity for Horner’s Syndrome.", "• Positive relative afferent pupillary defect (RAPD): Dilation of one pupil during swinging flashlight test suggests a retina or optic nerve injury – extremely important as often the only objective finding on exam in optic neuritis or a tumor compressing on the optic nerve."], "imgs": []}, {"sec": "Ophthalmic exam", "name": "Intraocular Pressure (IOP) Measurement", "phase": null, "tags": [], "pg": 445, "do": ["• Say: I will now freeze the eye with a local anesthetic, it will last 10 minutes. Please keep the eye open and look at one point in the distance. I will then measure the eye pressure by tapping gently, which is painless.", "• Setup: Use a Tonopen – commonly available in Emergency Departments", "• Do:", "(1) Freezing: Freeze eye with 1 drop of local anesthetic (e.g. Alcaine) – lasts about 10 minutes. (2) Calibrate Tonopen: Point Tonopen towards floor, press button twice, initially “CAL” will appear on screen followed by “UP”, then point Tonopen towards sky. (3) Approach: Do not push on eyelid (artificially elevates IOP), hold Tonopen like a pen, brace hand on cheek for stability, tap lightly on centre of cornea multiple times (each time will “beep”) until a number appears on screen.", "• Report: The Intraocular pressure measurement is 15 mmHg, which is normal."], "why": ["Intraocular Pressure is one of the 3 “vital signs” in ophthalmology, along with Visual Acuity and Pupillary Response to Light. Intraocular pressure is a balance between the rate of production of aqueous humor of the eye, resistance to aqueous outflow through trabecular meshwork and Schlemm’s Canal, and Episcleral venous pressure.", "• Normal: 10-21 mmHg; if a blockage occurs, Intraocular pressure (IOP) can quickly rise to 60-70 mmHg e.g. in acute angle closure glaucoma – an ophthalmologic emergency (may also present with headache, halos around lights, severe eye pain and nausea/vomiting)"], "imgs": []}, {"sec": "Ophthalmic exam", "name": "External Ocular Exam", "phase": null, "tags": [], "pg": 446, "do": ["• Say: I will inspect each eye quickly, before we proceed to the other steps of the exam.", "• Setup: Look at the eye without any tools in ambient lighting.", "• Do:", "◦ Shape of Eye/Eyelid: Check for Ptosis (drooping of eye), Exophthalmos (proptosis – protrusion of the eye), Entropion (eyelids folding inwards, eyelashes irritate cornea – Surgically corrected) or Ectropion (eyelid turned outwards – Surgically corrected).", "◦ Redness: Check for Conjunctivitis (generalized red vessels on conjunctiva); Iritis or Acute Angle Closure Glaucoma will have ciliary flush (red vessels just around the cornea)", "◦ Specific Lesions: Check for Chalazion (cyst of the eyelid), Papilloma (benign epithelial tumor)", "◦ Other Structures: Inspect the Lacrimal Gland, Puncta, Canaliculi, Nasolacrimal Sac and Duct", "• Report: There are no abnormalities in the external structures of the eye. Ptosis1 Exophthalmos2 Viral Bacterial Allergic Conjunctivitis3 Conjunctivitis4 Conjunctivitis5 Ptosis1 Exophthalmos2 Viral Bacterial Allergic Conjunctivitis3 Conjunctivitis4 Conjunctivitis5"], "why": ["Common part of the ophthalmic examination alongside the 3 “vital signs” of ophthalmology.", "• Globe Rupture = Ophthalmologic Emergency (the STEMI of Ophthalmological Practice): A communication between the outside world and the inside of the eye. This is a can’t miss diagnosis where the external ocular exam is an important part. Signs include a Sunken eye, pupil irregularity, prolapse of intraocular contents outside the eye, bullous subconjunctival hemorrhage, and hyphema (collection of blood in anterior chamber of the eye). If you suspect a Globe Rupture:", "◦ Document agent of injury, when injury occurred, and tetanus status.", "◦ Once diagnosis made, 1) Check vision → 2) patch eye with shield → 3) refer to ophthalmology for surgery immediately. Do NOT check Intraocular Pressure or do further exams.", "• Ptosis: Consider Cranial Nerve injury or sympathetic nerve injury (e.g. Horner Syndrome with triad of Miosis of affected side, partial ptosis due to Muller’s Muscle lesion, and facial anhidrosis", "• Exophthalmos: Sign of Thyroid disease (Ch 15 – Thyroid Exam – MF3) Acute conjunctivitis can represent:", "• Viral conjunctivitis: Classically appears as a pink or red colour, with minimal-to-no itching and watery discharge, which usually begins unilateral but may progress to bilateral. Ask about sick contacts, where contact with another person with red-eye mildly increases the likelihood of viral conjunctivitis (LR+ 2.5, LR-", "0.89). Ask if eyelids are stuck together on awakening which mildly decreases the likelihood of viral conjunctivitis (LR+ 0.72, LR- 3.5). On exam, look for mucopurulent ocular discharge (LR+ 0.47, LR- 2.7) which moderately decreases the likelihood of viral conjunctivitis. Also look for pharyngitis (LR+ 5.4-9.9, LR- 0.48-", "0.48) and preauricular lymphadenopathy (LR+ 2.5-5.6, LR- 0.73-0.89) which moderately increase the likelihood of viral conjunctivitis.", "• Bacterial conjunctivitis: Classically appears as a pink or red colour, with minimal-to-no itching and mucopurulent discharge which is usually unilateral. Ask about sick contacts, where contact with another person with red-eye moderately reduces the likelihood of bacterial conjunctivitis (LR+ 0.40). Ask if eyelids are stuck together on awakening (LR+ 1.4, LR- 0.29) which mildly increases the likelihood of bacterial conjunctivitis. On exam, assess for ocular discharge, where watery discharge greatly reduces the likelihood of bacterial conjunctivitis (LR+ 0.03), as well as mucopurulent discharge (LR+ 2.1, LR- 0.37) and otitis media (LR+ 2.5, LR -0.84) which mildly increase the likelihood of bacterial conjunctivitis. look for pharyngitis (LR+", "0.10-0.19, LR- 2.1-2.14) and preauricular lymphadenopathy (LR+ 0.18-0.40, LR- 1.1-1.4) which moderately decrease the likelihood of bacterial conjunctivitis.", "• Allergic conjunctivitis: Pink; Prominent itching; Watery discharge; bilateral. In allergic rhinitis, can also see infraorbital edema/darkening due to subcutaneous venodilation re. “allergic shiners”."], "imgs": ["eye-196.webp", "eye-197.webp", "eye-198.webp", "eye-199.webp", "eye-200.webp"]}, {"sec": "Ophthalmic exam", "name": "Confrontational Visual Fields", "phase": null, "tags": [], "pg": 447, "do": ["• Say: I will assess your vision in 4 quadrants in each eye by counting fingers. If you have glasses or contacts, please keep them on. Please stare at my nose during this test.", "• Setup: Sit at same level as patient. Key idea –you are the standard the patient is compared to i.e. symmetry should exist between you and patient to test the same visual field. When holding up fingers, use 0, 1 or 2 fingers in a plane perpendicular to axis formed by examiner and patient’s noses.", "• Do: The patient should close and cover one eye while you close opposite eye, so you have same field of vision. Hold out your hand in one quadrant equidistant between yourself and pt (fingers in same visual field). How many fingers am I holding up? Repeat in all 4 quadrants and for the other eye.", "• Report: The patient has a normal field of vision bilaterally in all 4 quadrants. If any visual field defects, record your findings using circle diagrams noting defects in quadrants of each eye."], "why": ["Alongside the 3 “vital signs” of ophthalmology – Visual Acuity, Intraocular Pressure and Pupillary Response to Light – Confrontational Visual Fields and Extraocular Muscle Movements are fundamental tests performed on each patient and part of the screening neurological examination (See Chapter 31 – Screening Neurologic Exam – MF4). By carefully testing the quadrants of the visual field of each eye, and drawing a diagram representing your findings as to where the deficit is, you can localize where the lesion is, as seen below:", "Where is the Lesion? Visual Field Areas Lost Visual Field Visual Field Description Diagram Partial lesion of left optic nerve (e.g. in Multiple Sclerosis) Loss of central vision in the left visual field Unilateral Central Scotoma in Left Visual Field Complete section of left optic nerve Loss of all vision in the left visual field Complete Blindness in Left Eye Optic chiasm (commonly associated with pituitary adenomas) Loss of temporal vision in both visual fields Bitemporal Hemianopia Left Optic Tract before Left Lateral Geniculate Nucleus Loss of LUQ and LLQ in both visual fields Left Homonymous Hemianopia Left Lower Optic Radiations Loss of LLQ in both visual fields Left Homonymous Lower Quadrantopia Left Upper Optic Radiations (Meyer’s Loop) Loss of LUQ in both visual fields Left Homonymous Upper Quadrantopia Left Occipital Lobe Loss of LUQ and LLQ in both visual fields, with macular sparing Left Homonymous Hemianopia with Macular Sparing Occipital contusion (often from backward falls) Loss of central vision in both visual fields Bilateral Central Scotomas"], "imgs": ["eye-201.webp", "eye-202.webp", "eye-203.webp", "eye-204.webp", "eye-205.webp", "eye-206.webp", "eye-207.webp", "eye-208.webp"]}, {"sec": "Ophthalmic exam", "name": "Extraocular Muscle Movemen ts", "phase": null, "tags": [], "pg": 447, "do": ["• Say: I will assess movements in each eye; please focus on my finger without turning your head.", "• Do: Move in a slow H pattern and observe eye movements of patient. As you move your finger slowly, observe a smooth pursuit where eyes have a conjugacy of gaze (align to focus on your finger). Give patient feedback if you notice them visibly moving their head as they track, as this does not allow you to test the more lateral aspects of their ocular movements. Ensure there are no restrictions in eye movements at extremes of gaze.", "• Report: I note conjugacy of gaze with smooth pursuit, no nystagmus or abnormal eye movements."], "why": ["Alongside the 3 “vital signs” of ophthalmology – Visual Acuity, Intraocular Pressure and Pupillary Response to Light – Confrontational Visual Fields and Extraocular Muscle Movements are fundamental tests performed on each patient and part of the screening neurological examination (See Chapter 31 – Screening Neurologic Exam – MF4). Specifically, testing the 6 cardinal extraocular movements also examines Cranial Nerves III, IV and VI (as detailed in screening neurologic examination)."], "imgs": []}, {"sec": "Ophthalmic exam", "name": "Anterior Segment (Slit-Lamp) Exam", "phase": null, "tags": [], "pg": 448, "do": ["• Say: I will inspect each eye more closely using a Slit Lamp. Would you please take a seat, and position the chin in the chin rest, and forehead against the top strap?", "• Setup: Room should have low ambient lighting. Ensure patient sitting upright comfortably with chin in chin rest, and forehead against forehead band. Adjust your own chair to comfortably perform exam.", "• Do:", "◦ Key Idea: The Slit Lamp an autofocus such that light source and your lenses are at same focal point. In the slit lamp exam, you move focal point of device in space using controls to examine anterior structures; each slit lamp arranged slightly differently.", "◦ To Start: Low-light and broad beam to begin, then narrow in. Examine one eye at a time.", "◦ Exam Anterior→Posterior: Lid→ Lacrimal→ Lashes → Sclera → Conjunctiva → Cornea → Iris → Anterior Chamber → Lens", "◦ Lids, Lashes and Adnexal Structures: Assess first to identify Blepharitis (flakes on lids), can flip upper lid for foreign bodies.", "◦ Conjunctival and Scleral Examination: Ask patient to look left, right, up, down to view entire sclera. Identify any conjunctivitis or ciliary flush (red ring around cornea).", "◦ Cornea: Assess for opacities or foreign bodies.", "◦ Anterior Chamber: Assess for any hypopyon (white blood cells) or hyphema (red blood cells). Cells or Flare is seen in uveitis: best observed with short beam of high intensity light into centre of pupil at angle, at high magnification. Consider cells as specks of dust seen, flare as beam of projector.", "◦ Lens: Assess for opacification suggesting cataracts", "◦ Special Light Filters and Dyes – Cobalt Blue: Apply fluorescein (yellow dye) to the eye, blue light will show corneal epithelial defects suggesting a corneal abrasion (lights up green).", "• Report: No abnormalities of the anterior segment of the eye are seen on Slit Lamp Exam. No corneal abrasion seen after Fluorescein staining."], "why": ["The Slit-Lamp Exam allows for a focused exam of intraocular structures, alongside external examination and direct fundoscopy. Some common presentations to Emergency Departments where a Slit Lamp exam is helpful include:", "1) Corneal Abrasion – A common presentation to Emergency Departments:", "• What is it? Corneal epithelial defect from scratching the eye. Patient presents with red painful eye.", "• Signs of corneal abrasion: Area of fluorescein uptake under blue light. Must rule out corneal ulcer which presents with corneal opacity.", "• What should you do? Prescribe topical antibiotics (e.g. Moxifloxacin QID and Ciprofloxacin ointment nightly), Tylenol and Advil for pain. Avoid patching the eye, especially if patient wears contacts – contacts can be a growth medium for Pseudomonas, which favours anaerobic conditions. Foreign Body – Visibly on eye surface: Common especially in industrial occupations, damaging glasses, etc.", "• What should you do? Ensure tetanus is up to date. Must order an orbital X ray to rule out intraocular foreign body for every case of metal foreign body. To remove the foreign body, using topical anesthesia and a small gauge needle balancing your hand on the patient’s face, gently pry the foreign body off the cornea. Refer to ophthalmology if any rust ring remains. Foreign Body –Under Upper eyelid: Common especially in industrial occupations, damaging glasses, etc.", "• Signs of foreign body under the eyelid: Vertical corneal abrasions on cornea with fluorescein under blue light.", "• What should you do?", "◦ Flip Upper Eyelid: Have patient look down and resist blinking. Firmly grasp a cotton swab at cotton end as if holding a pen. Press swab against middle of eyelid firmly. This creates a fulcrum for eyelid to be flipped over. Grasp upper eyelashes → firmly move eyelid over the cotton swab fulcrum. Hold the eyelashes to keep in position.", "◦ Remove foreign body: Using topical anesthesia and a small gauge needle, balance your hand on the face and gently pry the foreign body off cornea. Once finished, have patient look down and blink.", "◦ Ensure tetanus is up to date. Must order an orbital X ray to rule out intraocular foreign body for every case of metal foreign body."], "imgs": []}, {"sec": "Ophthalmic exam", "name": "Direct Fundoscopy", "phase": null, "tags": [], "pg": 449, "do": ["• Say: I will now inspect each eye using a direct ophthalmoscope. You will feel my hand touch the shoulder to keep the ophthalmoscope steady. Please look at an object on the wall in the distance at your eye level (preventing constriction due to pupillary accommodation reflex)", "• Setup: Room should still be dim. Stand facing the patient; if you’re examining the patient’s right eye first, use your right eye to look (vice versa). Adjust the scope’s focus (if you’re not wearing your nearsighted prescription glasses, may take more adjusting) by focusing on an object in room. Use low-moderate light intensity typically with medium aperture.", "• Do: Steady your hand on their shoulder. Shine the light from ophthalmoscope in patient’s eye; should see the red reflex. Follow reflex and slowly move toward patient. Find an artery and follow that towards the centre. You should come upon the optic disc (head of optic nerve, a confluence of retinal nerve fibers exiting the globe) and the optic cup (white centre of optic disc). Look for signs of optic disc swelling, and loss of venous pulsations. Follow the Superonasal Arcade, Inferonasal Arcade, Superotemporal Arcade, and Inferotemporal Arcade. Focus on Macula (temporal to optic disc), which contains Fovea where you can see a Yellow Reflex in healthy people. Look for signs of hemorrhages, neovascularization (small branching vessels) and cotton wool spots (fluffy white patches).", "• Report: The optic disc was visualized in each eye, with no signs of optic disc swelling, neovascularization or loss of venous pulsations."], "why": ["Direct fundoscopy allows for a focused exam of intraocular structures, alongside external examination and the slit lamp examination (see above). Fundoscopy also forms a part of the screening neurological examination (See Chapter 31 –Neuro Exam – MF4). Major pathologies to look for include:", "• Absent Red Reflex: Can be due to cataracts, retinoblastoma, retinal detachment, vitreous hemorrhage, etc.", "• Glaucoma (Chronic): Enlarged cup/disc ratio >0.5 (normal cup-to-disc ratio ≤0.5)", "• Papilledema: Swollen optic disc with no clear demarcated disc border due to ↑ Intracranial Pressure, coupled with loss of venous pulsations. Particularly important to assess for in patients with new onset headaches.", "• Retinal Detachment/Tear/Break: Can occur inside field of view on direct ophthalmoscopy.", "• Cotton Wool Spots: Sign of vascular insufficiency or ischemia to an area of retina – most common causes being hypertensive and diabetic retinopathy (Ch 14 – Diabetes Exam – MF3)", "• Hypertensive Changes: Arteriolar spasm, exudates, flame-shaped hemorrhages, loss of venous pulsations, ghost vessels, cotton wool spots.", "• Diabetic Retinopathy: Cotton wool spots, dot and blot hemorrhages, neo-vascularisations"], "imgs": []}]}, "gals": {"title": "GALS screen", "pg": [329, 333], "notes": [], "steps": [{"sec": "Screening Questions", "name": "3 Screening Questions", "phase": null, "tags": [], "pg": 328, "do": ["• Question 1: Do you have any pain or stiffness in your muscles, joint or back?", "• Question 2: Can you dress yourself completely without any difficulty?", "• Question 3: Can you walk up and down stairs without any difficulty? Why Ask: These 3 sensitive questions are aimed at identifying common problems of the Musculoskeletal system and significant abnormalities in limb function. Question 1 screens for the common symptoms associated with MSK pathologies. Question 2 screens Upper limb function and is an important daily activity, while Question 3 screens Lower limb function and is an important daily activity. *Note that in pediatric GALS exam, important to keep developmental context in mind (e.g. Dressing self as a cognitive/adaptive developmental milestone at 5 years old – would not expect a 4-year-old to be able to dress self without difficulty for example)"], "imgs": []}, {"sec": "Gait Assessment – Patient Standing", "name": "Gait", "phase": null, "tags": [], "pg": 328, "say": ["I will examine your gait with walking. Could you walk a few steps, then turn and walk back?"], "do": ["• As patient walks, observe their gait from multiple perspectives (from back, side and front)", "• Particularly looking for smoothness of movement (legs, arm swing, pelvic tilt), symmetry, and ability to turn quickly in the absence of back, hip or knee disease."], "report": ["Patient has a normal gait with no concern for an antalgic or Trendelenburg gait."], "why": ["Gait assessment is included as part of all lower limb assessments (Back, Hip, Knee, Ankle). Normal gait is comprised of the Stance Phase (60% of gait cycle) with initial contact (heel strike) → mid-stance → pre- swing (toe off); and the Swing Phase (40% of gait cycle) with initial swing → mid-swing → terminal swing. An abnormal gait on the GALS exam should prompt an assessment of the lower limbs (and may also require a screening neurological exam). Specific pathologies to look for include:", "• Antalgic Gait: Stance phase shortened on affected side, usually indicating pain on weight-bearing.", "◦ Why: Patient is trying to reduce the time spent weight-bearing on the affected limb.", "• Trendelenburg Gait:", "◦ Unilateral: During stance phase, if hip abductors weak on standing side, pelvis will drop to opposite side. The trunk compensates by lurching towards side of weakened abductor muscles.", "◦ Bilateral: Produces a Waddling Gait.", "◦ Why: Leaning on the affected side to align the centre of gravity allows for minimizing torque."], "imgs": []}, {"sec": "Gait Assessment – Patient Standing", "name": "Heelwalking and Toewalking (Pediatrics)", "phase": null, "tags": ["peds"], "pg": 328, "say": ["• I will continue to examine your gait. Can you walk on both heels for a few steps, then turn and walk back?", "• I will continue to examine your gait. Can you walk on both tiptoes for a few steps, then turn and walk back?"], "do": ["• As patient walks on tiptoes, observe foot posture including arches. Observe for antalgic gait for heel- and toe-walking as well. As above, observe gait from multiple perspectives (from back, side and front), looking for smoothness of movement, symmetry and ability to turn quickly."], "report": ["Patient has a normal gait with normal heel and toe-walking with no concerns for antalgic gait."], "why": ["These tests are part of the pGALS exam. An inability to walk on heels or on tiptoes is a good screening maneuver for the ankle and foot (commonly involved in Juvenile Idiopathic Arthritis). Antalgic gait specifically with heel or toe-walking may indicate localized causes of pain (e.g. Sever’s disease, enthesitis of the ankle with heel-walking; Morton’s Neuroma with tiptoe walking). Note that habitual toe walking is common and normal in young children up to 3 years old."], "imgs": []}, {"sec": "Spine PLUS Assessment – Patient Standing", "name": "Inspect from behind patient, from the side of patient, and from the front of patient (Spine, muscles, lower limbs)", "phase": "inspect", "tags": [], "pg": 329, "say": ["I will inspect the muscles and bones first standing to the back and rotating around the side to the front. Please stand with both arms relaxed at the sides."], "do": ["• Standing behind the patient, inspect muscle bulk and symmetry (e.g. of shoulders, paraspinal muscles, gluteal muscles, hamstrings, calves). Look at alignment of spine (e.g. spine itself, shoulder height, level of scapula angles, asymmetric skin folds). Look for equal level of iliac crests; valgus/varus knee deformities; popliteal fossae for swelling; and hind foot for deformities or swelling.", "• Moving to face the patient’s side, inspect spine alignment, limb alignment (elbow extension, knee extension).", "• Moving to face the patient’s front, inspect muscle bulk and symmetry (e.g. of shoulders, pectoralis, quadriceps). Inspect the patient’s feet for deformities (e.g. high arches, flat feet, hallux valgus).", "I note normal muscle bulk, symmetry and alignment throughout the patient’s spine, upper and lower limb."], "why": ["• Back: ↑ thoracic kyphosis may indicate ankylosing spondylitis or vertebral fractures (e.g. osteoporosis); ↑ lumbar lordosis may indicate a hip flexion contracture; ↓ lumbar lordosis may indicate ankylosing spondylitis. Scoliosis may be detected particularly looking at symmetry, shoulder height and skin folds.", "• Knees: Varus and Valgus Knee deformities can be an important cause of knee pain, while a swollen popliteal fossa may indicate a Baker’s Cyst or Knee effusion.", "• Looking at the Ankle and Foot, standing behind the patient may elicit a “Too Many Toes” Sign (>2 toes visible – suggesting severe pes planus or posterior tibialis dysfunction). Inspection may also reveal abnormal arches e.g. splaying of toes (collapse of transverse arch), pes planus (flat feet – collapse of longitudinal arch), or pes cavus (high longitudinal arch) A positive test should prompt a full assessment in the areas of concern identified, e.g. if concern for Scoliosis identified, should conduct a full assessment of the back (Chapter 29 – Back Exam)."], "imgs": []}, {"sec": "Spine PLUS Assessment – Patient Standing", "name": "Active ROM: Lateral Flexion of Neck", "phase": "rom", "tags": [], "pg": 329, "say": ["I will now assess range of motion in the neck. Could you please tilt the head to each side, to bring the ear towards the shoulder? Please let me know if you feel any pain, and if so, where."], "do": ["Watch the patient’s active range of motion and monitor for signs of pain. Monitor if patient is elevating their shoulders to touch the ear to the shoulder (e.g. to minimize movement of their neck)"], "report": ["The patient is able to touch their ear to their shoulder, with 30 degrees lateral flexion, which is normal."], "why": ["This movement assesses cervical spine lateral flexion (often first movement affected in cervical spine disorders). A positive test should prompt a full assessment of the back (Chapter 29 – Back Exam)."], "imgs": []}, {"sec": "Spine PLUS Assessment – Patient Standing", "name": "Active ROM: Lumbar Spine Movement", "phase": "rom", "tags": [], "pg": 329, "say": ["Can you bend forward to touch the toes? Please let me know if you feel any pain, and if so, where."], "do": ["Assess at patient’s side for spine movement through this range of motion. Look at the lumbar spine for transition from lumbar lordosis to kyphosis. This can also be done by placing 2 fingers on the lumbar spine during the motion, where your fingers should move apart on flexion, and come back together on extension."], "report": ["The patient has a normal range of motion throughout their spine, able to touch their toes without pain, with normal lumbar spine transition to kyphosis when bending forward."], "why": ["This movement assesses flexion and extension of the thoracolumbar spine. It is an important activity of daily living. A positive test should prompt a full assessment of the back (Chapter 29 – Back Exam)."], "imgs": []}, {"sec": "Spine PLUS Assessment – Patient Standing", "name": "Assess Temporomandibular joint ROM (Pediatrics)", "phase": "rom", "tags": ["peds"], "pg": 329, "say": ["Can you open the mouth and place your own 3 fingers in the mouth vertically? (clinician may model)"], "do": ["Ask patient to open mouth and insert their own 3 fingers in mouth vertically (e.g. D2 finger touching top incisors, D4 finger touching bottom incisors). Assess Temporomandibular joint range of motion. Look for deviation of the jaw and micrognathia. Listen for clicks."], "report": ["The patient has a normal temporomandibular joint range of motion and is able to put their own 3 fingers in their mouth."], "why": ["This maneuver screens for temporomandibular joint (TMJ) range of motion, deviation of jaw movement, and micrognathia. These are common sites of involvement in Juvenile Idiopathic Arthritis."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Active ROM: Hands behind head", "phase": "rom", "tags": [], "pg": 330, "say": ["I will now assess arm range of motion. Could you place both hands behind the head with elbows back?"], "do": ["Watch patient’s active range of motion and monitor for signs of pain."], "report": ["The patient is able to put their hands behind their head without limitation."], "why": ["This movement sequence assesses shoulder abduction (often first movement affected in rotator cuff disorders), and external rotation (often first movement affected in glenohumeral problems). It also assesses elbow flexion, sternoclavicular (SC) and acromioclavicular (AC) joint movement. This is a functionally important movement (e.g. for eating, washing, grooming). A positive test should prompt a full assessment of the upper limb, with attention paid to areas of decreased ROM or pain. For example, if shoulder abduction is limited with pain in shoulder, this should prompt a full assessment of the shoulder (Chapter 23 – Shoulder Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Active ROM: Back of hands and wrists", "phase": "rom", "tags": [], "pg": 330, "say": ["Now, please bring the elbows down to their sides (elbow extension) with palms up. Then, turn both hands over with palms down and fingers outstretched."], "do": ["Watch patient’s active range of motion and monitor for signs of pain."], "report": ["The patent is able to lower their arms, pronate and supinate their hands without limitation."], "why": ["This movement sequence assesses elbow extension (often first movement affected in elbow problems), supination and pronation with composite elbow, radioulnar and wrist movements. A positive test should prompt a full assessment of the upper limb, with attention paid to areas of decreased ROM or pain. For example, if elbow extension was limited with pain at elbow, this should prompt a full assessment of the elbow (Chapter 24 – Elbow Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Observe Dorsum of Hands and Wrists", "phase": null, "tags": [], "pg": 330, "say": ["Please continue to hold the hands out with palms down and with fingers outstretched."], "do": ["Inspect the wrists, hands and fingers for swelling and deformity, and skin and nail changes."], "report": ["The patient’s wrists, hands and fingers are normal on inspection with no signs of swelling, erythema, atrophy, deformity or skin changes."], "why": ["As detailed in Chapter 25 – Hand and Wrist Exam, inspection can provide diverse diagnostic info:", "• Swelling suggests inflammation (e.g. inflammatory arthritis, tenosynovitis, etc.); patterns of joint swelling can provide clues (e.g. DIPs spared in Rheumatoid Arthritis, vs. can be affected in Psoriatic Arthritis)", "• Deformities can suggest Inflammatory arthritis (e.g. radial deviation of wrist, ulnar deviation of fingers, etc.) or Osteoarthritis (e.g. squaring of wrist, Bouchard’s and Heberden’s Nodes)", "• Skin and Nail Changes can suggest Psoriatic arthritis (e.g. dactylitis, onycholysis, nail fold hemorrhages), Vasculitis (e.g. splinter hemorrhages, peri-ungal infarcts), or Gout (e.g. gouty tophi of hands) A positive test should prompt full assessment of hand and wrist (Chapter 25 – Hand and Wrist Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Squeeze MCP Joints", "phase": null, "tags": [], "pg": 330, "say": ["I will now assess the MCP joints in the hands. Please let me know if you feel any pain, and if so, where."], "do": ["Gently grasp across MCPs with one hand and squeeze. Ask patient if this is painful."], "report": ["MCP squeeze test is negative."], "why": ["The MCP squeeze test producing pain suggests inflammatory arthritis. A positive test should prompt full assessment of hand and wrist (Chapter 25 – Hand and Wrist Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Observe Palms of Wrists and Hands", "phase": null, "tags": [], "pg": 330, "say": ["Please turn both hands over and hold them out with palms up and with fingers outstretched."], "do": ["Inspect the palms for muscle atrophy, tendon thickening, and other changes."], "report": ["The patient’s palms are normal on inspection with no signs of swelling, erythema, atrophy, deformity or skin changes."], "why": ["As detailed in Chapter 25 – Hand and Wrist Exam, inspection can provide diverse diagnostic info:", "• Palmar erythema can suggest diverse systemic conditions (e.g. portal hypertension, chronic liver disease, rheumatoid arthritis, pregnancy, thyrotoxicosis, etc.).", "• Atrophy can suggest important nerve injuries (e.g. thenar wasting in median nerve injury from Carpal Tunnel Syndrome, hypothenar wasting and interossei muscle wasting in ulnar nerve injury, etc.).", "• Dupuytren’s Contractures can be idiopathic but also suggest diverse systemic conditions (e.g. diabetes, alcohol use, liver disease, liver cirrhosis). A positive test should prompt full assessment of hand and wrist (Chapter 25 – Hand and Wrist Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Assess Hand ROM", "phase": "rom", "tags": [], "pg": 330, "say": ["With the palms still up and fingers outstretched, please make a fist and then extend all the fingers."], "do": ["Observe patient’s active range of motion and monitor for signs of pain."], "report": ["The patient has a normal grip function and range of motion with their fingers."], "why": ["This test assesses active ROM across MCPs, PIPs and DIPs, important for daily activities. A positive test should prompt full assessment of hand and wrist (Chapter 25 – Hand and Wrist Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Assess Fine Precision Pinch", "phase": null, "tags": [], "pg": 331, "say": ["With the palms still up and fingers outstretched, please touch each finger to the thumb, one at a time."], "do": ["Observe patient’s fine precision pinch, active range of motion and monitor for signs of pain."], "report": ["The patient has normal opposition and range of motion in their hands with no signs of pain."], "why": ["Opposition (touching thumb to each finger) tests the joints of the hand, coordination and concentration. It is also important for daily activities e.g. dressing. A positive test should prompt full assessment of hand and wrist (Chapter 25 – Hand and Wrist Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Assess Grip Strength", "phase": null, "tags": [], "pg": 331, "say": ["With the palms still up and fingers outstretched, please squeeze my fingers"], "do": ["Place your 4 fingers in each hand of the patient. Ask the patient to squeeze your fingers. Assess strength."], "report": ["The patient’s grip strength is normal."], "why": ["Grip strength assesses power across the MCPs, PIPs and DIPs. This is important for daily activities. A positive test should prompt full assessment of hand and wrist (Chapter 25 – Hand and Wrist Exam)."], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Assess Wrist Extension and Flexion (Pediatric)", "phase": null, "tags": ["peds"], "pg": 331, "say": ["Please place the hands together palm-to-palm (Prayer sign – clinician may model). Now, please place the hands together back-to-back (clinician may model)."], "do": ["Assess finger joint extension; wrist extension and flexion; elbow flexion; and coordination of finger joints."], "report": ["The patient has normal wrist flexion and extension with normal coordination and no deformities seen."], "why": ["These tests are part of the pGALS exam. They can assess for hypermobility with wrist extension and flexion, extension of small joints of fingers, and elbow flexion. They may also reveal Swan Neck Deformities (PIP hyperextension, DIP flexion) and Boutonniere’s Deformities (PIP flexion, DIP hyperextension),"], "imgs": []}, {"sec": "Arms Assessment – Patient may be Standing or Sitting", "name": "Assess Shoulder Abduction, Wrist/Elbow Extension, Neck Extension (Peds)", "phase": null, "tags": ["peds"], "pg": 331, "say": ["Please reach up and touch the sky. Now, tilt the head back to look upwards at the ceiling."], "do": ["Assess neck extension; shoulder abduction; elbow extension; and wrist extension. Look for asymmetry and reduced range of motion."], "report": ["The patient has normal neck extension, shoulder abduction, elbow extension and wrist extension, with no signs of asymmetry on exam."], "why": ["These tests are part of the pGALS exam. They can assess for hypermobility. Asymmetry on exam (e.g. reduced shoulder abduction on the left) would be important to investigate further as a potential sign of pathology."], "imgs": []}, {"sec": "Legs Assessment – Patient Supine", "name": "Passive ROM – Knee Flexion and Hip Flexion", "phase": "rom", "tags": [], "pg": 331, "say": ["I will examine the hips and knees for range of motion. Let me know if you feel any pain, and if so, where."], "do": ["Clinician places one hand on the knee to feel for crepitus, while stabilizing the lower leg with other hand. Passively flex the knee and the hip. Assess for Bony End-Feel vs. Soft End-Feel, observe the passive range of motion you can elicit, and monitor for signs of pain."], "report": ["The patient has a Hip Flexion of about 120 degrees and Knee Flexion of 135 degrees which is normal, with normal end-feel and no pain."], "why": ["If patient passive ROM is limited, it is reasonable to expect limited active ROM. Knee flexion and hip flexion are important for daily activities e.g. walking. Normal knee flexion is 135 degrees. Normal hip flexion is 120 degrees. A positive test should prompt a full assessment of the lower limb, with attention paid to areas of decreased ROM or pain. For example, if knee flexion is limited with bony-end feel, this should prompt a full assessment of the knee (Chapter 26 – Knee Exam)."], "imgs": []}, {"sec": "Legs Assessment – Patient Supine", "name": "Passive ROM – Hip Internal Rotation", "phase": "rom", "tags": [], "pg": 331, "say": ["I will continue to examine the hips for range of motion. Let me know if you feel any pain, and if so, where."], "do": ["Continuing to assess passive range of motion with one hand on the knee, and stabilize lower leg with other hand. Bring hip and knee to 90 degrees of flexion. Bring the foot outwards with femur as axis of rotation to internally rotate hip. Assess for Bony End-Feel vs. Soft End-Feel, observe the passive range of motion you can elicit, and monitor for signs of pain."], "report": ["The patient has a normal Hip Internal Rotation of about 40 degrees, with normal end-feel and no pain."], "why": ["If patient passive ROM is limited, it is reasonable to expect limited active ROM. Normal hip internal rotation is 35-40 degrees and is usually the first movement affected by hip problems. A positive test should prompt full assessment of the hip (Chapter 27 – Hip Exam)"], "imgs": []}, {"sec": "Legs Assessment – Patient Supine", "name": "Palpate Knee Temperature", "phase": "palpate", "tags": [], "pg": 331, "say": ["I will palpate each knee for temperature."], "do": ["Palpate above and below knee with the back of your hand. Then palpate the knee itself."], "report": ["The knee is cooler than above and below the joint, which is normal."], "why": ["Knee joint temperature should be cooler than above and below. Warmth may be a sign of Inflammatory Arthritis, Septic Arthritis, etc. A positive test should prompt full assessment of the knee (Chapter 26 – Knee Exam)"], "imgs": []}, {"sec": "Legs Assessment – Patient Supine", "name": "Assess for Knee Effusion", "phase": null, "tags": [], "pg": 332, "say": ["I will palpate each knee for swelling. Bilateral Knee Effusion4"], "do": ["• Fluid Wave Test or Bulge Sign: Sweep your hand up the medial aspect of the knee to empty the medial fossa. Then sweep down the lateral aspect, looking for a bulge forming in the medial fossa.", "• Patella Tap: Apply pressure with one hand just above the patella and sweep down until you reach the upper pole of the patella. This pushes fluid into the suprapatellar pouch behind the patella. Keep pressure applied. With other hand, use 1-2 fingers to push the patella down, and assess whether it taps the femur and bounces back up."], "report": ["There is no knee effusion palpated with fluid wave or patella tap. Bilateral Knee Effusion4"], "why": ["The Fluid Wave Test/Bulge Sign is useful for smaller knee effusions (may be false negative in larger effusion), whereas the Patella Tap is useful for moderate-large knee effusions (may be false negative in smaller effusion). A positive test should prompt full assessment of the knee (Chapter 26 – Knee Exam)"], "imgs": ["gals-194.webp"]}, {"sec": "Legs Assessment – Patient Supine", "name": "Inspect Ankles and Feet", "phase": "inspect", "tags": [], "pg": 332, "say": ["I will inspect the ankles and feet for swelling or deformities."], "do": ["Inspect the ankles and feet for swelling or deformities.", "Inspecting for deformities can reveal common problems like Hallux Valgus (subluxation of 1st MTP, commonly accompanied by Bunion = bony prominence on medial side of 1st MTP), Hammer Toes (irreversible flexion of PIPs), Claw Toes (irreversible flexion of PIPs and DIPs), or Mallet Toes (irreversible flexion of DIPs). When inspecting for swelling, the location of swelling can provide important clues, for example:", "• Loss of normal depressions anterior to malleoli → Suggests True Ankle Swelling", "• Swelling posterior to lateral malleolus → Suggests Peroneal Tenosynovitis", "• Swelling posterior to medial malleolus → Suggests Posterior Tibial Tenosynovitis", "• Swelling at back of heel → Suggests Retrocalcaneal Bursitis or Retroachilleal Bursitis", "• Swelling of the forefoot → Can be seen in Inflammatory Arthritis Positive findings on inspection should prompt full assessment of ankle and foot (Ch 28 – Ankle/Foot Exam)"], "report": ["I note no swelling or deformities of the patient’s ankles and feet."], "imgs": []}, {"sec": "Legs Assessment – Patient Supine", "name": "Squeeze MTP Joints", "phase": null, "tags": [], "pg": 332, "say": ["I will now assess the MTP joints in each foot. Please let me know if you feel any pain, and if so, where."], "do": ["Gently grasp across MTPs with one hand and squeeze and ask patient if this is painful."], "report": ["MTP squeeze test is negative."], "why": ["The MTP squeeze test producing pain suggests inflammatory arthritis. A positive test should prompt full assessment of ankle and foot (Chapter 28 – Ankle/Foot Exam)"], "imgs": []}, {"sec": "Legs Assessment – Patient Supine", "name": "Inspect Soles for Calluses", "phase": "inspect", "tags": [], "pg": 332, "say": ["I will now inspect the soles of each foot for calluses."], "do": ["Inspect for calluses (rough, thickened area of skin)."], "report": ["I note no calluses on the patient’s feet."], "why": ["Calluses may indicate pressures from an abnormal gait or stance. Positive findings on inspection should prompt full assessment of ankle and foot (Chapter 28 – Ankle/Foot Exam)"], "imgs": []}]}, "shoulder": {"title": "Shoulder", "pg": [252, 262], "notes": [], "steps": [{"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 255, "do": ["• Swelling (Especially of Joints): Sternoclavicular, Acromioclavicular, and Glenohumeral joints (bulge at deltopectoral groove can occur in very large effusions)", "• Erythema", "• Atrophy: Pectoralis Major; Deltoid (Squaring of Shoulder); Supraspinatus and Infraspinatus; and Trapezius", "• Deformities:", "◦ Observe for Normal Alignment: Observing laterally, look for the ear lobe to be aligned through the head of the humerus and the greater trochanter", "◦ Step Deformity of the Clavicle → Suggests Prior Fracture", "◦ Step Deformity of Acromioclavicular Joint → Suggests AC Ligament Disruption", "◦ Asymmetrical Height of Shoulders → Suggests Scoliosis or Sprengel’s Deformity (High-riding Scapula)", "▪ Note: Slight asymmetry of shoulder heights can be normal; most people tend to have their dominant shoulder slightly lower than their non-dominant shoulder.", "◦ Shoulder Elevation, Depression, Protraction or Retraction → Suggests Scapular Deformity", "◦ Winging of Scapula: Ask patient to “do a push up against the wall” → Winging of scapula suggests Injury of Long Thoracic nerve and associated paralysis of serratus anterior muscle, or weakness of the scapulothoracic muscles (rhomboids, trapezius)"], "imgs": []}, {"sec": "General Assessment", "name": "Palpation", "phase": "palpate", "tags": [], "pg": 256, "do": ["• Key Idea: The shoulder has the greatest range of motion of any joint in the body. The only bony connection between the shoulder girdle and trunk is via the clavicle at the acromioclavicular joint. The important structural supports come from soft tissues (bursae, tendons, ligaments, and muscles). Shoulder pain is commonly due to a disease of these soft tissues.", "• Approach: Palpate bones, soft-tissue structures.", "• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy", "• Palpate Anteriorly: Sternoclavicular (SC) Joint, Clavicle, Coracoid Process, Acromioclavicular (AC) Joint, Acromion, Biceps Muscle (both Long head and Short head of biceps), Deltoid Muscle", "• Palpate Posteriorly: Trapezius, Supraspinatus Muscle, Infraspinatus Muscle, Triceps Muscle, Spine and medial border of Scapula", "• Palpate Rotator Cuff Insertion on Greater Tuberosity of Humerus: Extend arm backwards to bring humerus out from under acromion.", "• Palpate for Crepitus during shoulder movement."], "why": ["Palpation can be very helpful to determine source of pain. Palpate for tenderness and swelling in a systematic manner, to assess for potential fractures and other abnormalities. Step-deformity, localized tenderness and swelling of the clavicle may indicate clavicular fracture. Tenderness at the biceps tendon has a Sensitivity of 57% and a Specificity of 72% for Bicipital Tendonitis."], "imgs": ["shoulder-125.webp", "shoulder-126.webp"]}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 256, "do": ["• Approach: Perform Active ROM, and then Passive ROM if Active ROM is limited. These can be integrated with examiner guiding the shoulder beyond patient’s active ROM.", "• Active ROM:", "◦ Screening Test – Apley Scratch Test: Have patient touch the tip of the opposite scapula (involves internal rotation and adduction) → Quick screen for shoulder ROM and subscapularis function", "◦ Shoulder Flexion (Normal: 180°): Patient brings arms forwards all the way to the top", "◦ Shoulder Extension (Normal: 60°): Patient moves arms backwards", "◦ Shoulder Abduction (Normal: 180°):", "▪ Painful Arc: Tends to occur between 60-120° during abduction; a positive painful arc mildly increases the probability of rotator cuff disease, while a negative painful arc moderately reduces the probability of rotator cuff disease (LR+ 3.7, LR-", "0.36).", "▪ Scapulothoracic Rhythm – <30°:", "Glenohumeral (GH) joint; 30-180°: 2:1 GH to Scapulothoracic joint", "• If humerus and scapula move together as one complex → Suggests Adhesive Capsulitis", "◦ Shoulder Adduction: Patient crosses arms in front of body", "◦ Shoulder External Rotation (Normal: 45-90°): With arms relaxed at sides and elbows flexed to 90°, rotate forearms away from body.", "◦ Shoulder Internal Rotation (Normal: Up to 120°): With arms relaxed at sides and elbows flexed to 90°, rotate forearms towards body and behind the back", "• Passive ROM (perform if Active ROM limited):", "◦ Crepitus: With hand over patient shoulder, move arm around to detect grinding/catching/cracking", "◦ Adhesive Capsulitis: With passive ROM, this results in global restriction in all fields of movement."], "imgs": ["shoulder-127.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 257, "do": ["• Standing Approach: With arms at side and elbows flexed to 90°", "◦ Flexion: Clinician counter-supports placing one hand behind patient shoulder; with other hand, clinician pushes upper arm (just above elbow) posteriorly; patient resists motion.", "◦ Extension: Clinician counter-supports placing one hand in front of patient shoulder; with other hand, clinician pushes upper arm (just above elbow) anteriorly; patient resists motion.", "◦ External Rotation: Clinician stabilizes elbow with one hand; with other hand at wrist, push forearm inwards (medially); patient resists motion → Tests Infraspinatus and Teres Minor of Rotator Cuff", "◦ Internal Rotation: Clinician stabilizes elbow with one hand; with other hand at wrist, push forearm outwards (laterally); patient resists motion→ Tests Subscapularis of Rotator Cuff", "• Sitting Approach: With arms abducted from sides at approximately 20°", "◦ Abduction: Clinician hands just above patient elbows, and presses inwards; patient resists motion → Tests Supraspinatus of Rotator Cuff, as well as Deltoid and Trapezius muscles.", "◦ Adduction: Clinician hands on inside of arms just above elbows, push outwards, patient resists motion.", "• Reporting: For each muscle group tested, assess per the Medical Research Council Power Grading. If it is all 5/5, you can say “Power was 5/5 bilaterally in both upper and lower limbs”, and report specific deficits. NOTE: This scale is detailed in Chapter 31 – Screening Neurological Examination"], "imgs": []}, {"sec": "Rotator Cuff and Impingement Tests", "name": "Drop Arm Test", "phase": null, "tags": [], "pg": 257, "say": ["I will assess the rotator cuff."], "do": ["• Method 1: Patient abducts arms overhead, and actively brings arms back to side.", "• Method 2: With patient arm abducted to 90 degrees, clinician “chops down” on arm.", "• With either method 1 or 2, look for a sudden drop of the arm to one side."], "report": ["The drop arm test is negative."], "why": ["A positive drop arm test raises concern for a Complete Tear of Supraspinatus (most common site of rotator cuff tear). A negative drop arm test mildly reduces the probability of rotator cuff disease (LR- 0.82)."], "imgs": []}, {"sec": "Rotator Cuff and Impingement Tests", "name": "Painful Arc", "phase": null, "tags": [], "pg": 257, "say": ["I will continue to assess the rotator cuff. Please let me know if you feel any pain, and if so, where."], "do": ["Have patient actively abduct their arms, and look for signs of pain (typically between 60-120°) – commonly at lateral aspect or tip of the shoulder"], "report": ["No signs of a painful arc on arm abduction."], "why": ["A positive painful arc mildly increases the probability of rotator cuff disease, while a negative painful arc moderately reduces the probability of rotator cuff disease (LR+ 3.7, LR- 0.36). A painful arc suggests External Subacromial Impingement (mechanical encroachment of bursa/rotator cuff tendons on subacromial space between humeral head and acromial arch)"], "imgs": []}, {"sec": "Rotator Cuff and Impingement Tests", "name": "Empty Can Test", "phase": null, "tags": [], "pg": 257, "say": ["I will continue to assess the rotator cuff. Let me know if you feel pain, and if so, where."], "do": ["• Abduct arm to 90° at the side then bring forward 30° with elbows extended and thumbs pointed down (“empty a can”)", "• Clinician applies downward pressure on arms, patient actively resists.", "• Look for signs of pain at tip of shoulder."], "report": ["No pain or weakness elicited – Empty Can Test is negative."], "why": ["The Empty Can test is used to assess for rotator cuff disease, where a positive test suggests External Subacromial Impingement (mechanical encroachment of bursa/rotator cuff tendons on subacromial space between humeral head and acromial arch). As per a JAMA Rational Clinical Exam article, the Empty Can test does not significantly alter the post-test probability of rotator cuff disease. A related test called the Full Can test (performed with arm in 45 degrees external rotation position with thumb pointed up instead of arm in full internal rotation with thumb pointed down) mildly increases the probability of rotator cuff disease (LR+", "2.4, LR- 0.37)."], "imgs": ["shoulder-128.webp"]}, {"sec": "Rotator Cuff and Impingement Tests", "name": "Lift Off Test", "phase": null, "tags": [], "pg": 257, "say": ["I will continue to assess the rotator cuff."], "do": ["Have patient put their arm behind their back palm out at the level of the belt line. Have the patient push out against your hand, keeping the wrist straight. Look for signs of pain in the anterolateral shoulder or weakness."], "report": ["No pain or weakness elicited – negative Lift Off test."], "why": ["The Lift off test is used to assess for rotator cuff disease, specifically subscapularis tendon tears. A positive Lift off test mildly increases the probability of rotator cuff disease (LR+ 1.4-1.5, LR- 0.63-0.85)."], "imgs": []}, {"sec": "Rotator Cuff and Impingement Tests", "name": "HawkinsKennedy Test", "phase": null, "tags": [], "pg": 258, "say": ["I will to assess the rotator cuff. Please let me know if you feel any pain, and if so, where."], "do": ["• Shoulder flexed forward to 90°, elbow flexed 90°, with forearm parallel to floor", "• Clinician passively rotates forearm clockwise to cause internal rotation at the shoulder.", "• Look for signs of pain at shoulder."], "report": ["No pain elicited – Hawkins-Kennedy Test is negative."], "why": ["A positive Hawkins Kennedy test mildly increases the probability of rotator cuff disease (LR+ 1.5, LR- 0.51); when Hawkins and Neer tests are both negative, this moderately decreases the probability of rotator cuff disease (LR- 0.43). A positive test suggests External Subacromial Impingement."], "imgs": ["shoulder-129.webp"]}, {"sec": "Rotator Cuff and Impingement Tests", "name": "Neer’s Test", "phase": null, "tags": [], "pg": 258, "say": ["I will continue to assess the rotator cuff. Please let me know if you feel any pain, and if so, where."], "do": ["• Patient’s elbow in full extension; stabilize the shoulder by placing hand on posterior shoulder.", "• Clinician passively lifts the arm to the ear (“Neer’s to the Ear”). Look for signs of pain. If pain is present, assess whether it is anterior or posterior shoulder pain."], "report": ["No pain elicited – Neer’s Test is negative."], "why": ["Neer’s Test’s is used to assess for rotator cuff disease, where a positive test with anterior pain suggests External Subacromial Impingement (mechanical encroachment of bursa or rotator cuff tendons on subacromial space between humeral head and acromial arch), whereas a positive test with posterior pain suggests Internal Posterosuperior Glenoid Impingement (encroachment of rotator cuff tendons between humeral head and glenoid rim). When Hawkins and Neer tests are both negative, this moderately decreases the probability of rotator cuff disease (LR- 0.43)."], "imgs": ["shoulder-130.webp"]}, {"sec": "Acromioclavicular (AC) Joint Tests", "name": "Scarf Test", "phase": "rom", "tags": [], "pg": 258, "say": ["I will assess the Acromioclavicular joint. Let me know if you feel pain, and if so, where."], "do": ["• Patient places their hand on the opposite shoulder. Tell patient to allow hand to slide over shoulder during the test.", "• Clinician applies a posterior force on the patient’s elbow in direction of the forearm to push the arm into the body while stabilizing the ipsilateral shoulder.", "• Look for signs of pain in the area of the acromioclavicular joint."], "report": ["No pain elicited around acromioclavicular joint – Scarf Test is negative."], "why": ["Pain elicited around acromioclavicular joint during Scarf’s test indicates acromioclavicular joint pathology, for example in Osteoarthritis (OA)."], "imgs": ["shoulder-131.webp"]}, {"sec": "Labral Tests", "name": "O’Brien’s Test", "phase": null, "tags": [], "pg": 258, "say": ["I will assess the labrum. Let me know if you feel pain and if so, where."], "do": ["• Patient in sitting or standing position with arm in 90 degrees of flexion and 10- 15 degrees of adduction.", "• Patient internally rotates shoulder so that thumb points to the floor.", "• Clinician stabilizes the shoulder by placing hand posteriorly and with other hand applies downward force on lower arm as the patient resists with an upward force.", "• The procedure is repeated with the shoulder in neutral position with thumb pointed to the ceiling.", "• Look for pain or click deep in the shoulder joint."], "report": ["No pain or clicking in either position – O’Brien’s test is negative."], "why": ["The O’Brien test assesses for tears of the labrum and is a two-part test. A positive test occurs when pain or clicking is produced deep in the shoulder with the first position but not in the second position. Superficial pain can indicate AC joint involvement. Studies show O’Brien’s test has a specificity ranging from 28-73% and a sensitivity ranging from 63-94%."], "imgs": ["shoulder-132.webp"]}, {"sec": "Stability Tests", "name": "Sulcus Sign", "phase": null, "tags": [], "pg": 259, "say": ["I will assess the shoulder for signs of instability."], "do": ["• Both shoulders at rest. Clinician stabilizes contralateral shoulder and grasps arm just above elbow.", "• Apply a downward pressure on the arm at the elbow. Look for Sulcus at the tip of shoulder."], "report": ["No sulcus seen on downward pressure of the arm – Sulcus Sign is negative."], "why": ["Sulcus Sign’s Diagnostic Value is in Ruling in Inferior Shoulder Instability, with a Sensitivity of 31% and a Specificity of 89%."], "imgs": []}, {"sec": "Stability Tests", "name": "Anterior and Posterior Instability", "phase": null, "tags": [], "pg": 259, "say": ["I will continue to assess the shoulder for signs of instability."], "do": ["• With both shoulders at rest position, clinician grasps one shoulder at the head of humerus and stabilizes by placing the other hand over the top of the shoulder.", "• Clinician attempts to move the head of the humerus backwards and forwards in the glenohumeral joint (can be challenging if significant soft tissue present). Look for excessive movement.", "• Note: Each shoulder should be assessed separately."], "report": ["No excess movement forwards or backwards to indicate instability anteriorly or posteriorly."], "why": ["Excessive movement forwards indicates anterior instability, while excessive movement backwards indicates posterior instability. Anterior shoulder dislocation can cause axillary neuropathy (axillary nerve is a branch of brachial plexus)"], "imgs": []}, {"sec": "Biceps Tests", "name": "Speed’s Test", "phase": null, "tags": [], "pg": 259, "say": ["I will assess the biceps tendon. Let me know if you feel pain, and if so, where."], "do": ["• Patient’s elbow extended, arm supinated and shoulder forward flexed at 45°.", "• Clinician applies a downward pressure on the forearm. Look for signs of pain at the biceps tendon."], "report": ["No pain elicited at biceps tendon – Speed’s Test is negative."], "why": ["Speed’s Test’s Diagnostic Value is in Ruling Out Bicipital Tendonitis i.e. inflammation of long head of biceps tendon as it travels in intertubercular groove beneath transverse humeral ligament. Speed's test has a Sensitivity of 71% and a Specificity of 49% for bicipital tendonitis."], "imgs": ["shoulder-133.webp"]}, {"sec": "Biceps Tests", "name": "Yergason’s Test", "phase": null, "tags": [], "pg": 259, "say": ["I will continue to assess the biceps tendon. Let me know if you feel pain, and if so, where."], "do": ["• Patient’s arm at side, elbow flexed to 90° and hand in neutral position", "• Grasp patient elbow, and forearm with other hand (just proximal to wrist)", "• Attempt to pronate the forearm with patient resisting by trying to supinate.", "• Look for signs of pain at the biceps tendon."], "report": ["No pain elicited at biceps tendon – Yergason’s Test is negative."], "why": ["A positive Yergason’s test is suggestive of Bicipital Tendonitis, along with Speed’s Test. Yergason's test has a Sensitivity of 64-68% and a Specificity of 30-61% for bicipital tendonitis."], "imgs": ["shoulder-134.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "AC Joint Distraction Test", "phase": null, "tags": ["extra"], "pg": 259, "say": ["I will continue to assess the Acromioclavicular Joint. Let me know if you feel pain, and if so, where."], "do": ["• Patient adducts their arm behind their back, with dorsum of their hand resting on opposite buttock.", "• Clinician stabilizes contralateral shoulder and applies additional adduction force (push on patient’s arm)", "• Look for signs of pain in the area of the acromioclavicular joint."], "report": ["No pain elicited around acromioclavicular joint – AC Joint Distraction Test is negative."], "why": ["Pain elicited around acromioclavicular joint during AC Joint Distraction test suggests acromioclavicular joint pathology, for example in Osteoarthritis (OA)."], "imgs": ["shoulder-135.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Apprehension Test, Anterior Relocation Test and Anterior Release Sign", "phase": null, "tags": ["extra"], "pg": 260, "say": ["I will continue to assess the shoulder for signs of instability with moving the shoulder forward. Let me know if you feel any pain, and if so, where."], "do": ["• While patient supine, passively abduct and externally rotate the arm at 90°.", "• Apprehension Test: Clinician holds forearm with one hand, pulling humerus anteriorly with other hand. Look for signs of apprehension or pain (positive Apprehension Test).", "• Relocation Test: Now reposition hand to push humerus posteriorly. Look for signs of relaxation or relief (positive Relocation Test).", "• Anterior Release Sign: Now suddenly remove the hand that was pushing humerus posteriorly in relocation test. Look for signs of renewed apprehension or pain (positive anterior release sign)."], "report": ["No signs of recurrent anterior subluxation of the shoulder with apprehension testing."], "why": ["• The likelihood of anterior shoulder instability is moderately increased by positive anterior relocation test (LR+ 6.5, LR- 0.18) and positive anterior release sign (LR+ 8.3, LR- 0.09).", "• Apprehension Test, Anterior Relocation Test, and Anterior Release Signs suggest recurrent anterior subluxation. Anterior Relocation test and Anterior release help rule in Anterior Shoulder Instability. Anterior shoulder dislocation can cause axillary neuropathy (axillary nerve – branch of brachial plexus).", "• A positive apprehension test with anterior shoulder pain suggests External Subacromial Impingement (mechanical encroachment of bursa/rotator cuff tendons on subacromial space between humeral head and acromial arch).", "• A positive apprehension test with posterior shoulder pain suggests Internal Posterosuperior Glenoid Impingement (encroachment of rotator cuff tendons between humeral head and glenoid rim). A negative anterior relocation and release test suggests primary impingement (structural narrowing of subacromial space causing pain and dysfunction e.g. AC joint arthropathy, subacromial bursitis), while a positive anterior relocation and release test suggests secondary impingement (functional narrowing in specific positions re. excessive anterior translation of humeral head)"], "imgs": ["shoulder-136.webp"]}]}, "elbow": {"title": "Elbow", "pg": [263, 270], "notes": [], "steps": [{"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 266, "do": ["• Approach: Ensure adequate and respectful exposure. Olecranon Bursitis2", "• Swelling:", "◦ Fullness of Para-Olecranon Groove, with elbow in slightly flexed position → Suggests Joint Swelling", "◦ Focal swelling on Posterior Aspect of Olecranon → Suggests Olecranon Bursitis", "• Erythema", "• Atrophy: Inspect the Biceps, Triceps, Brachioradialis, Wrist Flexors (attached to medial epicondyle) and Wrist Extensors (attached to lateral epicondyle)", "• Deformities:", "◦ Carrying Angle (Normal 5-10° in men, 10-20° in women): Angle of forearm with humerus when patient stands with arms at side, elbows extended, and palms facing forwards.", "◦ Inability to fully extend the elbow → Suggests Flexion contractures", "• Skin Changes or Scars:", "◦ Rheumatoid Nodules: Rubbery nodules overlying olecranon", "◦ Gouty Tophi: Hard nodules overlying olecranon"], "imgs": ["elbow-137.webp", "elbow-138.webp"]}, {"sec": "General Assessment", "name": "Palpation", "phase": "palpate", "tags": [], "pg": 267, "do": ["• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy", "• Palpate Posteriorly:", "◦ Triceps", "◦ Olecranon process", "◦ Olecranon bursa", "• Palpate Medially:", "◦ Medial triceps border", "◦ Epitrochlear Lymph Nodes (above medial epicondyle)", "◦ Medial epicondyle", "◦ Common flexor tendon (attached to medial epicondyle)", "▪ Tenderness at medial epicondyle & common flexor tendon → Medial epicondylitis (Golfer’s Elbow)", "• Palpate Anteriorly:", "◦ Bicep", "◦ Biceps Tendon (in antecubital fossa)", "◦ Brachial pulse (medial to biceps tendon)", "• Palpate Laterally:", "◦ Lateral epicondyle", "◦ Palpate for Elbow Effusion: Palpate lateral para-olecranon for effusion between lateral epicondyle and olecranon", "◦ Common extensor tendon (attached to lateral epicondyle)", "▪ Tenderness at lateral epicondyle & common extensor tendons → Lateral epicondylitis (Tennis Elbow)", "◦ Radial head (should slip under thumb with elbow flexion to 90° and clinician’s thumb just distal to lateral epicondyle, with pronation and supination of forearm)", "▪ Pediatrics: Pulled Elbow Syndrome – Radial Head Subluxation: Radial head is slipped out of normal position. Common in children under 5 years old because of relative strength of annular ligament."], "why": ["Palpation can be very helpful to determine source of pain. Palpate for tenderness and swelling in a systematic manner, to assess for potential fractures and other abnormalities. Gout can present in the elbow as well, albeit more rarely."], "imgs": ["elbow-139.webp", "elbow-140.webp", "elbow-141.webp", "elbow-142.webp"]}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 267, "do": ["• Approach: Perform Active ROM, and then Passive ROM if Active ROM is limited. These can be integrated with examiner guiding the elbow beyond patient’s active ROM.", "• Screening Test – Crepitus: With hand over elbow, move elbow joint passively", "• Flexion (140° ± 10°)", "• Extension (Full extension 0°, up to 10° hyperextension normal esp. in women) → inability to fully extend elbow is abnormal, may suggest elbow joint effusion or prior trauma (e.g. fracture)", "• Pronation (75-90°) & Supination (80-90°): With arms at sides, elbows flexed and thumbs up, turn palms down (pronation), and then turn palms up (supination)"], "imgs": ["elbow-143.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 268, "do": ["• Elbow Flexion with Forearm Supination: Patient makes a boxer pose; brace shoulder, grasp the forearm and apply an extensor force; patient resists motion.", "• Elbow Extension with Forearm Supination: Patient makes a boxer pose; brace shoulder, grasp the forearm and apply a flexor force; patient resists motion.", "• Forearm Pronation with Elbow Flexed to 90 degrees: Elbow flexed to 90°, palms up. Brace forearm with wrist in neutral position and apply supination force; patient resists motion.", "• Forearm Supination with Elbow Flexed to 90 degrees, Arms at Side: Elbow flexed to 90°, palms down. Brace forearm with wrist in neutral position and apply pronation force; patient resists motion.", "• Reporting: For each muscle group tested, assess per the Medical Research Council Power Grading. If it is all 5/5, you can say “Power was 5/5 bilaterally in both upper and lower limbs”, and report specific deficits. NOTE: This scale is detailed in Chapter 31 – Screening Neurological Examination"], "imgs": []}, {"sec": "Special Tests", "name": "Elbow Stability Anteroposterior stability", "phase": "special", "tags": [], "pg": 268, "say": ["I will assess the elbow for signs of instability."], "do": ["Support and stabilize elbow flexed at 30°. Grasp forearm with other hand.", "• MCL/UCL Stability: Apply a valgus (outward) force against forearm. Assess for excess laxity with valgus force.", "• LCL/RCL Stability: Apply a varus (inward) force against forearm. Assess for excess laxity with varus force.", "• Anteroposterior Stability: Now flex elbow to 90 degrees. While stabilizing forearm with one hand, push and pull humerus with other hand. There should be no movement."], "report": ["No excess laxity with either a valgus or varus force applied – no signs of MCL or LCL instability."], "why": ["Excess laxity with a valgus force indicates a Medial (Ulnar) Collateral Ligament injury, while excess laxity with a varus force indicates a Lateral (Radial) Collateral Ligament injury. Movement anteriorly or posteriorly of humerus with elbow flexed to 90 degrees indicates antero-posterior instability."], "imgs": []}, {"sec": "Special Tests", "name": "Lateral Epicondylitis (Tennis Elbow) Test", "phase": "special", "tags": [], "pg": 268, "say": ["I will assess for signs of tennis elbow. Please let me know if you feel any pain, and if so, where."], "do": ["Palpate for tenderness at lateral epicondyle and along the common extensor tendon", "• Extend patient’s elbow with wrist extended/cocked backwards.", "• Apply a force at the wrist while the patient resists to maintain wrist extension. Look for signs of pain at lateral epicondyle or common extensor tendon.", "• Patient then relaxes wrist and keeps elbow extended. Examiner pushes wrist into flexion to stretch the common extensor tendon, without patient resistance. Look for signs of pain at lateral epicondyle or common extensor tendon."], "report": ["No tenderness at lateral epicondyle or common extensor tendon – lateral epicondylitis test is negative."], "why": ["Tenderness at lateral epicondyle, tenderness at common extensor tendon, or pain at lateral epicondyle with active resistance or passive wrist flexion is suggestive of tennis elbow (lateral epicondylitis)."], "imgs": []}, {"sec": "Special Tests", "name": "Medial Epicondylitis (Golfer’s Elbow) Test", "phase": "special", "tags": [], "pg": 268, "say": ["I will assess for signs of golfer’s elbow. Please let me know if you feel any pain, and if so, where."], "do": ["Palpate for tenderness at medial epicondyle. Elbow extended with wrist flexion.", "• Extend patient’s elbow with wrist flexed (fingers pointing down)", "• Apply a force at the wrist while the patient resists to maintain wrist flexion. Look for signs of pain at the medial epicondyle or common flexor tendon.", "• Patient relaxes wrist and keeps elbow extended. Examiner pushes wrist into extension to stretch common flexor tendon, without resistance. Look for signs of pain at medial epicondyle or common flexor tendon."], "report": ["No tenderness at medial epicondyle or common flexor tendon – medial epicondylitis test is negative."], "why": ["Tenderness at medial epicondyle, tenderness at common flexor tendon, or pain at medial epicondyle with active resistance of wrist extension is suggestive of golfer’s elbow (medial epicondylitis). The Medial (ulnar) Collateral ligament is strongly attached to Medial Epicondyle, where an excess flexion injury or posterior elbow dislocation can cause avulsion fracture of the medial epicondyle."], "imgs": []}, {"sec": "Special Tests", "name": "Tinel’s Sign", "phase": "special", "tags": [], "pg": 269, "say": ["I will examine the Cubital Tunnel in the elbow by gently tapping on an area on the inside of the elbow for 30 seconds. Let me know if you feel any pins and needles during the test, and if so, where."], "do": ["With patient elbow flexed at 90°, tap over ulnar nerve in the groove between the olecranon process and medial epicondyle for 30 seconds. Look for pain or paresthesia (pins and needles) radiating to 4th/5th fingers."], "report": ["No pain or paresthesias over ulnar nerve sensory distribution in hand – Tinel’s Sign negative."], "why": ["Pain or paresthesias over ulnar nerve sensory distribution in hand (4th/5th fingers) is indicative of Cubital Tunnel Syndrome – caused by irritation or entrapment of the ulnar nerve in the cubital tunnel (groove between medial epicondyle and olecranon)."], "imgs": ["elbow-144.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Elbow Flexion Test", "phase": null, "tags": ["extra"], "pg": 269, "say": ["I will continue to examine the Cubital Tunnel in the elbow with movement of the arms. Please let me know if you feel any pins and needles during the test, and if so, where."], "do": ["Patient maximally flexes elbow for 60 seconds with wrists extended (to avoid compressing median nerve at wrist which can confound a positive test with Carpal Tunnel Syndrome). Look for paresthesias radiating to 4th/5th fingers."], "report": ["No paresthesias developed over ulnar nerve distribution in hand – Elbow Flexion Test negative."], "why": ["Paresthesias over ulnar nerve sensory distribution in hand (4th/5th fingers) is indicative of Cubital Tunnel Syndrome – caused by irritation or entrapment of the ulnar nerve in the cubital tunnel (groove between medial epicondyle and olecranon)."], "imgs": ["elbow-145.webp"]}]}, "hand": {"title": "Hand & wrist", "pg": [271, 282], "notes": [], "steps": [{"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 277, "do": ["• Approach: Offer a pillow for patient to rest their hands on during the exam. Ensure adequate exposure, at least to the level of the elbow.", "• Swelling", "• Erythema: Palmar erythema → associated with Portal hypertension, chronic liver disease, Pregnancy, Rheumatoid arthritis, Thyrotoxicosis, etc.", "• Atrophy:", "◦ Thenar muscle wasting → Suggests Median nerve injury e.g. in severe carpal tunnel syndrome", "◦ Hypothenar muscle wasting→ Suggest Ulnar nerve injury", "◦ Interossei muscle wasting → Suggests Disuse atrophy (e.g. severe arthritis) and/or Ulnar nerve injury", "◦ Dupuytren’s Contracture (See Diagram to right): Caused by thickening and puckering of palmar fascia) → non-specific sign often idiopathic, can be associated with Diabetes, Alcohol Use, Liver disease, or Liver cirrhosis.", "• Deformities:", "◦ Osteoarthritis (OA) – look for Osteophyte development at specific locations:", "▪ Squaring of the wrist – Bony prominence of 1st Carpometacarpal (CMC) Joint – an increased square wrist ratio increases the likelihood of suspected carpal tunnel syndrome (LR+ 2.7, LR-", "0.5)", "▪ Bouchard’s Nodes – Bony enlargement of Proximal Interphalangeal (PIP) Joints", "▪ Heberden’s Nodes – Bony enlargement of Distal Interphalangeal (DIP) Joints", "◦ Rheumatoid Arthritis (RA):", "▪ Joint swelling – Metacarpo- phalangeal (MCPs) and PIPs; DIPs are spared in Rheumatoid Arthritis", "▪ Prominent ulnar head – dorsal subluxation if radioulnar ligament is disrupted", "▪ Radial deviation of wrist", "▪ Ulnar deviation of fingers and subluxation at the MCPs", "▪ Swan Neck Deformities (PIP hyperextension, DIP flexion – looks like a swan): Screen for Swan Neck Deformities with Prayer Sign where the patient put their palms together with wrists extended", "▪ Boutonniere’s Deformities (PIP flexion, DIP hyperextension – looks like pushing on a button)", "▪ Hitchhiker Thumb (MCP flexion, IP hyperextension of thumb)", "◦ Psoriatic Arthritis:", "▪ Joint swelling – Any joint can be involved, including the DIPs", "▪ Dactylitis (sausage digits) can be seen, as well as characteristic skin changes below.", "• Scars and Skin Changes:", "◦ Psoriatic: Psoriasis; Psoriasis Nail Changes (Pitting; Onycholysis = lifting off nail bed; Nail fold hemorrhages which can be asymmetrical)", "◦ Gout: Gouty tophi", "◦ Vasculitis: Splinter hemorrhages (look at nail beds), Peri-ungal infarcts", "◦ Scars: For example, from a prior median nerve release procedure (for Carpal Tunnel Syndrome)"], "imgs": ["hand-146.webp", "hand-147.webp", "hand-148.webp"]}, {"sec": "General Assessment", "name": "Palpation, including palpation for effusions at wrist, MCPs and IPs", "phase": "palpate", "tags": [], "pg": 278, "do": ["• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy", "• Check for warmth: Sweep with back of hand down forearm to the fingers.", "◦ Warmth: Consider Inflammation such as septic arthritis and crystalline arthritis (e.g. Gout, Pseudo- gout), or other Inflammatory Arthritis causes", "• Palpate wrist:", "◦ Ulnar head, ulnar styloid", "◦ Triangular Fibrocartilaginous Complex (TFCC) found between ulnar head and carpal bone", "◦ Distal radius, radial styloid", "◦ Wrist Effusion: Palpate radiocarpal joint space using your thumbs.", "• Press in with your thumbs to check for effusions (tense or boggy sensation)", "• Slide thumbs across radial joint line to check for synovitis or effusion.", "• Try to ballot fluid between your thumbs.", "• Palpate hand:", "◦ Anatomical Snuffbox:", "• Floor of Snuffbox: Scaphoid bone → tenderness may indicate a scaphoid fracture (concern for Avascular Necrosis here due to precarious blood supply)", "• Tendons of Snuffbox: Abductor pollicis longus and extensor pollicis brevis → can be swollen and tender in DeQuervain’s tenosynovitis.", "◦ Carpal Bones (Left hand shown):", "▪ Palpate proximal carpal bones moving from hallux to D5:", "• Scaphoid (Hallux) → Lunate → Triquetrum → Pisiform", "▪ Palpate distal carpal bones moving from hallux to D5", "• Trapezium (Hallux, distal row) → Trapezoid (distal) → Capitate (distal) → Hamate (distal)", "◦ Flexor Tendonitis:", "▪ Ask patient to supinate hand. Palpate flexor tendons in patient’s palm for tenderness and nodules.", "▪ Clinician lines their fingertips along flexor tendon in palm and thumb under the patient’s hand. Apply pressure with fingertips on the flexor tendon, while passively flexing and extending each patient finger. Check for tenderness, crepitus and triggering.", "• Palpate fingers:", "◦ Metacarpals:", "▪ Screen for MCP synovitis with MCP squeeze: Grasp across MCPs with one hand and squeeze, and ask patient if this is painful", "▪ MCP Effusion:", "• Have patient flex fingers at MCPs, where joint line is 1cm distal to tip of knuckle.", "• Use 4-finger technique to palpate – clinician’s middle fingers support underside of joint, tips of thumbs palpate joint line on dorsal side (roughly at 10 o’clock and 2 o’clock)", "• Check for tenderness or fullness, and try to ballot fluid between your thumbs.", "• Slide thumbs across the joint line to check for synovitis or effusion (indistinct on palpation)", "◦ PIP and DIP Effusion:", "▪ Palpate using 4 finger technique – clinician’s thumb and index of one hand on dorsal side (12 o’clock) and volar side (6 o’clock). Clinician uses thumb and index of their other hand to palpate the sides of the joint (at 9 o’clock and 3 o’clock).", "▪ Check for tenderness or fullness and try to ballot fluid between your fingers."], "why": ["Palpation can be very helpful to determine source of pain. Palpate for tenderness and swelling in a systematic manner, to assess for potential fractures and other abnormalities. In particular, note that tenderness on palpation of the anatomical snuffbox may suggest scaphoid fracture. These fractures commonly undetectable on initial X-ray, and thus may be missed. If initial X-ray is negative, immobilize the wrist and repeat X-ray in 14-21 days."], "imgs": ["hand-149.webp", "hand-150.webp"]}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 279, "do": ["• Quick Screen: Make a fist with thumb out, then extend all fingers", "• Wrist Range of Motion:", "◦ Flexion (70-90°) and Extension (70-90°)", "◦ Radial Deviation (20°) and Ulnar Deviation (30°)", "◦ Supination (Palms up) and Pronation (Palms down)", "◦ Circumduction (circular movement – combination of flexion, extension, abduction and adduction)", "◦ Tuck Sign: During wrist or finger extension, see dorsal wrist bulge → suggests Extensor tenosynovitis.", "• Thumb Range of Motion:", "◦ Opposition (touching thumb to tip of each finger)", "◦ Adduction and Abduction (perpendicular to plane of hand)", "◦ Flexion and Extension (thumb movement in plane of hand)", "• MCP Range of Motion: Extension (10-20°), Flexion (90-100°), Abduction and Adduction", "• PIPs (100-120°) and DIPs (0-80°) Flexion → These perform finger tuck."], "imgs": ["hand-151.webp", "hand-152.webp", "hand-153.webp", "hand-154.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 279, "do": ["• Approach: Resisted Isometric Testing i.e. patient resists force applied by clinician", "• Grip Strength: Assess power across MCPs, PIPs and DIPs by squeezing your fingers", "• Wrist Extension (Radial Nerve): Patient adopts elbow flexion with pronation; brace elbow, and apply downward force on dorsal surface of hand; patient resists motion.", "• Wrist Flexion (Median Nerve): Patient adopts elbow flexion with pronation; brace elbow, apply upward force on palmar surface of hand; patient resists motion.", "• Flexion at MCPs (D2 + D3 – Median Nerve; D4 + D5 – Ulnar Nerve): Patient adopts elbow flexion with pronation; brace wrist and apply a downward force on the DIPs grouped together; patient resists motion.", "• Dorsal Interossei (Ulnar Nerve): Abduct fingers, patient resists motion.", "• Palmar Interossei (Ulnar Nerve): Adduct fingers, patient resists motion.", "• Thumb – Thumb Abduction, Flexion, Opposition (Median Nerve); Thumb Extension (Radial Nerve)", "◦ The likelihood of suspected carpal tunnel syndrome is mildly increased by weakened thumb abduction (LR+ 1.8, LR- 0.5).", "• Reporting: For each muscle group tested, assess per the Medical Research Council Power Grading. If it is all 5/5, you can say “Power was 5/5 bilaterally in both upper and lower limbs”, and report specific deficits. NOTE: This scale is detailed in Chapter 31 – Screening Neurological Examination"], "imgs": []}, {"sec": "General Assessment", "name": "Neurological & Vascular Assessment Sensory, Motor – Pulses– Cap Refill Time", "phase": null, "tags": [], "pg": 279, "do": ["• Reflexes: Biceps (C5 & C6), Triceps (C7 & C8), Brachioradialis (C5 & C6)", "• Sensory and Motor Assessment:", "◦ Median nerve: Motor (“Okay” sign) and Sensory (Autonomous zone = palmar pad D2 distal phalanx)", "◦ Radial nerve: Motor (“Thumbs Up”) and Sensory (Autonomous zone = dorsal 1st web space)", "◦ Ulnar nerve: Motor (Finger abduction) and Sensory (Autonomous zone = palmar pad D5 distal phalanx)", "• Vascular Assessment – includes Peripheral Pulses and Capillary Refill Time (see Chapter 8 – Peripheral Vascular Exam – MF1)"], "imgs": []}, {"sec": "Special Tests", "name": "Wrist Stability", "phase": "special", "tags": [], "pg": 280, "say": ["I will assess the wrist for stability."], "do": ["Stabilize the forearm and grasp the hand; Gently try to sublux the wrist up and down."], "report": ["No subluxation of wrist evident with gentle force."], "why": ["If wrist subluxes up and down, this is indicative of wrist instability"], "imgs": []}, {"sec": "Special Tests", "name": "Piano Key Sign", "phase": "special", "tags": [], "pg": 280, "say": ["I will continue to assess the wrist for stability."], "do": ["Hold patient’s hand and press and release the ulnar head. Look for ulnar head to depress, then come back up (like a piano key)."], "report": ["Piano key sign is negative."], "why": ["Positive piano key sign indicates disruption of the distal radioulnar ligament – this can occur in rheumatoid arthritis due to chronic inflammation."], "imgs": []}, {"sec": "Special Tests", "name": "Tinel’s Sign", "phase": "special", "tags": [], "pg": 280, "say": ["I will examine the Carpal Tunnel in the wrist by gently tapping on an area of the wrist for 30 seconds. Please let me know if you feel any burning or pins and needles (paresthesias) during the test, and if so, where."], "do": ["• Patient’s wrist in neutral position.", "• Tap over the median nerve just proximal to the wrist on the palmar surface for 30 seconds.", "• Assess for signs of burning or paresthesias over D1-D3 or radial half of D4 (median nerve distribution)"], "report": ["No burning or paresthesias elicited – Tinel’s Sign is negative for Carpal Tunnel Syndrome."], "why": ["A positive Tinel’s Sign mildly increases the likelihood of Carpal Tunnel Syndrome (LR+ 1.5, LR-", "0.82). The Carpal tunnel is formed by the Flexor Retinaculum and the Carpal bones of the wrist. 9 tendons (4 for each of D2-D5, 1 for the Thumb) run in the Carpal tunnel along with the median nerve. The ulnar nerve and ulnar artery run separately along the palmar carpal ligament. Carpal Tunnel syndrome is caused by pathology ↑ pressure within the Carpal tunnel (e.g. from arthritis, effusion, fasciitis, etc.)"], "imgs": ["hand-155.webp"]}, {"sec": "Special Tests", "name": "Phalen’s Sign", "phase": "special", "tags": [], "pg": 280, "say": ["I will continue to examine the Carpal Tunnel in the wrist by bringing the hands together with palms down for 60 seconds. Please let me know if you feel any burning or pins and needles (paresthesias) during the test, and if so, where."], "do": ["• Patient holds wrists in complete flexion by pushing their dorsal surfaces of hands together for 60 seconds.", "• Assess for signs of burning or paresthesias over D1-D3 or radial half of D4 (median nerve distribution)"], "report": ["No burning or paresthesias elicited – Phalen’s Sign is negative for Carpal Tunnel Syndrome."], "why": ["A positive Phalen’s Sign mildly increases the likelihood of Carpal Tunnel Syndrome (LR+ 1.3, LR-", "0.74)."], "imgs": ["hand-156.webp"]}, {"sec": "Special Tests", "name": "Finkelstein’s Test", "phase": "special", "tags": [], "pg": 280, "say": ["I will assess for DeQuervain’s Tenosynovitis. Please let me know if you feel any pain during the test, and if so, where."], "do": ["• Patient makes a fist with their thumb in.", "• Patient places their forearm on a table, with hand just off to the edge.", "• Patient actively ulnar deviates the hand.", "• Assess for signs of sharp pain along radial aspect of wrist (a +ve test result)"], "report": ["No sharp pain elicited along radial aspect of the wrist – Finkelstein’s Test is negative for DeQuervain’s Tenosynovitis."], "why": ["• A positive Finkelstein’s Test is suggestive of DeQuervain’s Tenosynovitis. This is caused by inflammation of the tendon sheaths of the abductor pollicis longus and extensor pollicis brevis (which are components of the anatomical snuffbox).", "• The Finkelstein’s Test involves the patient actively deviating their hand. An alternate test, called Eichhoff’s Test, is similar with the clinician passively deviating the hand instead of active deviation by the patient."], "imgs": ["hand-157.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Metacarpophalangeal (MCP) Joint Stability", "phase": null, "tags": ["extra"], "pg": 281, "say": ["I will assess the hand for stability."], "do": ["• Ask patient to flex their knuckles (MCPs)", "• Try to sublux the proximal phalanx anteriorly and posteriorly (like knee anterior and posterior drawer test)", "• Look for significant movement (small amount of movement normal)", "• Next, apply a varus and valgus stress to move each finger to the sides (should be little to no movement)"], "report": ["MCP joints are stable."], "why": ["Significant movement with anterior/posterior force, any movement with valgus/varus force, indicates MCP Joint instability."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Interphalangeal (IP) Joint Stability", "phase": null, "tags": ["extra"], "pg": 281, "say": ["I will continue to assess the hand for stability."], "do": ["• Stabilize phalanx proximal to the joint (e.g. proximal phalanx if testing PIP)", "• Grasp phalanx distal to joint (e.g. intermediate phalanx if testing PIP)", "• Apply varus and valgus stresses to the joint, assess for collateral stability."], "report": ["IP joints are stable."], "why": ["If significant movement with varus or valgus forces, this indicates IP Joint instability."], "imgs": []}]}, "back": {"title": "Back & spine", "pg": [316, 328], "notes": [], "steps": [{"sec": "General Assessment", "name": "Gait Assessment Gen - Trendelenburg", "phase": null, "tags": [], "pg": 320, "do": ["• Components of Gait Cycle:", "◦ Stance phase (60% of gait cycle): initial contact (heel strike) → mid-stance → pre-swing (toe-off)", "◦ Swing phase (40% of gait cycle): initial swing → mid-swing → terminal swing", "◦ Note: Former terminology in brackets re. heel-strike and toe-off.", "• Quality of Gait: Smoothness of movement (legs, arm swing, pelvic tilt), symmetry, normal stride length, ability to turn quickly, symmetry.", "• Abnormal Gaits to Assess for: Antalgic Gait (shortened stance phase on affected side, typically indicates pain with weight-bearing); and Trendelenburg Gait (weak hip abductors); bilateral weak hip abductors produce a Waddling Gait).", "• Transition from Sitting to Standing: Ask patient to rise from a chair; helpful to identify source of pain"], "imgs": []}, {"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 320, "do": ["• Approach: Ensure adequate but respectful exposure during your examination", "• Swelling", "• Erythema", "• Atrophy: Sternocleidomastoid, Shoulder Girdle, Chest Wall, Intercostals, Paraspinals, Gluteal, Calf Muscles – likelihood of lumbosacral radiculopathy in patients with sciatica is increased with ipsilateral calf muscle wasting (LR+ 5.2, LR- 0.8)", "• Deformities:", "◦ Normal Curvatures of the Spine:", "▪ Cervical Lordosis", "▪ Thoracic Kyphosis – ↑ in Ankylosing Spondylitis (AS) and in vertebral fractures (e.g. osteoporosis)", "▪ Lumbar Lordosis – ↑ in flexion contracture of hip; Flattened e.g. in Ankylosing Spondylitis (AS)", "▪ Sacrococcygeal Kyphosis", "◦ Scoliosis: Look for asymmetric shoulder height, abnormal curvature in frontal plane", "▪ Adam’s Forward Bend Test (see Special Tests below)", "• Scars or Skin Changes: Inspect for sinus or hair tufts → Suggests concern for Spina Bifida"], "imgs": []}, {"sec": "General Assessment", "name": "Palpation", "phase": "palpate", "tags": [], "pg": 320, "do": ["• Approach: Palpate bones and soft-tissue structures for tenderness – helpful to determine source of pain. Palpate systematically e.g. begin at Occiput, palpate inferiorly and stabilize the patient.", "• Canadian C-Spine Rule: Palpate for midline C-Spine tenderness.", "• NEXUS C-Spine Criteria: Palpate for midline spinal tenderness.", "• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy"], "imgs": []}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 321, "do": ["• Approach: Usually performed as active ROM (patient does it). Clinician may assist for Thoracolumbar rotation by holding both shoulders and rotating beyond patient active ROM.", "• Cervical Spine (Among regions of spine, the Cervical spine has greatest range and variety of movement):", "◦ Flexion (Look Down): Normal 80-90°; Chin should touch chest", "◦ Extension (Look Up): Normal 70°; Chin should pass the level of the ears", "◦ Lateral Flexion: Normal 20-45°; Ear should touch the shoulder (be sure patient isn’t elevating shoulders to do so)", "◦ Rotation (Look Side to Side): Normal is up to 90° to each side –likelihood of cervical radiculopathy in patients with arm/neck pain is increased with <60° rotation of neck to involved side (LR+ 1.7, LR- 0.2).", "• Thoracolumbar Spine (Thoracic Spine primarily Rotatory movements, restricting flexion, extension, and lateral flexion; Lumbar Spine primarily Flexion, Extension, and Lateral Flexion, with restricted rotation):", "◦ Chest Expansion: See Bilateral Chest Expansion below", "◦ Flexion: Ask patient to stand and keep their knees straight and end forward to touch the floor by sliding their hands down the anterior surfaces of each leg. Normally expect to see lumbar lordosis transition to kyphosis with Thoracolumbar flexion.", "▪ Measurement – Modified Schober’s Test: See Modified Schober’s Test below", "◦ Extension: Ask patient to stand and keep legs straight with lower body supported against a stable structure behind (e.g. exam table) and lean backwards without bending knees.", "▪ In a Facet Arthropathy, Extension becomes limited", "◦ Lateral Flexion: Ask patient to stand with back against the wall and with their hands at their sides with fingers straight. Ask patient to bend to either side, sliding their fingers down the side of their leg.", "◦ Rotation: Ask patient to sit (so pelvis is anchored) and give themselves a hug (arms crossed across chest). Ask patient to twist to either side. Clinician may apply over-pressure to fully assess range, while observing for pain."], "imgs": ["back-183.webp", "back-184.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 322, "do": ["• Approach: The back-examination’s power assessment is considered to be part of the neurological examination. When examining the back, you’ll be asked to examine the power of the major flexors and extensors of the lower limb –Hip, Knee, and Ankle/Foot, NOT the posterior muscles of the back. This is to discern whether there is any spinal cord compression, etc. going on along with a chief complaint such as back pain which would trigger you to perform the back MSK examination."], "why": ["In the upper limbs, likelihood of suspected cervical radiculopathy in patients with neck/arm pain is increased by weakness of any arm muscle (LR+ 1.9, LR- 0.4). Specifically, weakness of elbow flexion increases the likelihood of C5 radiculopathy (LR+ 5.3); weakness of wrist extension increases the likelihood of C6 radiculopathy (LR+ 2.3); weakness of elbow extension increases the likelihood of C7 radiculopathy (LR+ 4.0, LR- 0.4); and weakness of finger flexion increases the likelihood of C8 radiculopathy (LR+ 3.8). In the lower limbs, the likelihood of suspected lumbosacral radiculopathy in patients with sciatica is increased by weak ankle dorsiflexion (LR+ 4.9, LR- 0.5). Specifically, weakness of knee extension increases the likelihood of L3-L4 radiculopathy (LR+ 3.7, LR- 0.7); weakness of hallux extension increases the likelihood of L5 radiculopathy (LR+ 1.6); and normal strength of ankle plantarflexion decreases the likelihood of S1 radiculopathy (LR- 0.7)."], "imgs": []}, {"sec": "General Assessment", "name": "Neurological & Vascular Assessment Tone, Power, Deep Tendon Reflexes – Peripheral Pulses – Capillary Refill Time", "phase": "power", "tags": [], "pg": 322, "do": ["• How Do I Perform This Assessment? See Screening Neurological Examination for full details in Chapter", "31. Brief overview is included here for reference.", "• Inspection: Inspection begins in waiting room or as patient enters the exam room. Observe their gait and posture, abnormal limb position, weakness, muscle atrophy, fasciculations, involuntary movements, and lack of coordination.", "• Assess Tone:", "◦ With patient relaxed and supine, support and passively move the limb across joints (Hip, Knee, Ankle)", "◦ Assess for hypotonia (↓ tone in lower motor neuron lesions e.g. nerve root, peripheral nerve)", "◦ Assess for hypertonia (↑ tone in upper motor neuron lesions)", "▪ Spasticity: Variable resistance, often worse at extremes of ROM e.g. in Cerebral Palsy or Stroke", "▪ Cogwheeling Rigidity: Intermittent ↑ resistance and tremor e.g. in Parkinson’s Disease", "▪ Lead-Pipe Rigidity: (↑ resistance throughout range of motion e.g. in Parkinson’s Disease, or Neuroleptic Malignant Syndrome (NMS)", "◦ Assess for ankle clonus (upper motor neuron lesion)", "• Assess Power: Assess with MRC Description resisted isometric force. 5 Movement of body part against gravity with full resistance Report with MRC Power 4 Movement of body part against gravity with some resistance Grading Scale (out of 5)", "• 4+ and 4-: Graduations of 4/5 strength re how much", "◦ Hip Flexion (L1-L3) examiner had to lower resistance", "◦ Hip Extension (S1-S2) 3 Movement of body part against gravity only", "◦ Knee Extension (L2-L4) 2 Movement of body part with gravity eliminated", "◦ Knee Flexion (L5-S2) 1 Muscle contraction, but with no joint movement", "◦ Ankle Dorsiflexion (L4-L5) 0 No muscle contraction", "◦ Ankle Plantarflexion (S1- S2)", "◦ Great Toe Dorsiflexion (L5-S1)", "• Assess Reflexes (Diminished/Absent → suggests Reflex Grade Description Lower Motor Neuron Lesion; Hyperactive/Sustained → suggests Upper Motor Neuron Lesion) 0 Absent", "◦ Patellar Reflex (L2-L4 – Mainly L4) 1+ Diminished (reinforcement", "◦ Achilles Reflex (S1-S2 – Mainly S1) needed to elicit e.g. patient", "◦ Plantar Response (If plantars upgoing, this clenches teeth, locks fingers) indicates an Upper Motor Neuron lesion). 2+ Normal", "• Assess Dermatomes: Assess with both Posterior 3+ Hyperactive without clonus Columns (Cotton Ball) and Spinothalamic Tract 4+ Hyperactive with clonus (Sharp/Dull pin testing differentiation). Map out area of altered sensation to determine spinal level. The following are particular sites to examine for a back exam (i.e. testing Lumbar and Sacral spinal levels:", "◦ Groin (L1); Just Inferior to Groin (L2)", "◦ Medial Aspect of Knee (L3); Lateral Aspect of Knee (L4)", "◦ Dorsum of Foot (L5); Lateral Border of Foot (S1)", "• Vascular Assessment – includes Peripheral Pulses and Capillary Refill Time (see Chapter 8 – Peripheral Vascular Exam – MF1) MRC Description 5 Movement of body part against gravity with full resistance"], "imgs": []}, {"sec": "General Assessment", "name": "4", "phase": null, "tags": [], "pg": 322, "do": ["Movement of body part against gravity with some resistance", "• 4+ and 4-: Graduations of 4/5 strength re how much examiner had to lower resistance 3 Movement of body part against gravity only 2 Movement of body part with gravity eliminated 1 Muscle contraction, but with no joint movement 0 No muscle contraction Reflex Grade Description 0 Absent needed to elicit e.g. patient clenches teeth, locks fingers) 2+ Normal 3+ Hyperactive without clonus 4+ Hyperactive with clonus"], "imgs": []}, {"sec": "Special Tests", "name": "Adam’s Forward Bend Test Peds", "phase": "special", "tags": ["peds"], "pg": 323, "say": ["I will inspect for scoliosis. Please stand with feet together and knees straight. I will stand behind you and watch the back’s movements with bending."], "do": ["• Patient stands with knees in full extension. Clinician stands behind patient.", "• Patient bends forward keeping knees in full extension.", "• Clinician observes for asymmetry with a prominent rib hump."], "report": ["I note no asymmetry on forward bending – Adam’s Forward Bend Test is negative."], "why": ["Adam’s Forward Bend Test’s diagnostic value is to rule out thoracic spine curvature re Scoliosis. Note that a diagnosis of scoliosis is defined objectively by a Cobb Angle >10% on Anteroposterior (AP) Xray. A positive Adam’s Forward Bend Test has a Sensitivity of 92% and a Specificity of 60% for scoliosis."], "imgs": ["back-185.webp"]}, {"sec": "Special Tests", "name": "Occiput-Wall Distance", "phase": "special", "tags": [], "pg": 323, "say": ["I will assess for kyphosis in the neck using a measuring tape. Please stand with the back to the wall."], "do": ["• Patient stands with back to wall, nose and ear at same level (controls for neck hyperextension)", "• Observe distance from occiput to wall; in this position, distance should be 0 cm (Normal: 0-4cm)"], "report": ["Occiput-Wall distance is less than 4.0 cm, with no abnormal cervical or thoracic kyphosis."], "why": ["Occiput-Wall distance > 4.0 cm’s diagnostic value is to rule in thoracic vertebral fracture. It is increased in abnormal cervical or thoracic kyphosis, for example in Ankylosing Spondylitis (tends to begin in the neck in females, vs the lower spine in males) or Thoracic vertebral compression fractures (e.g. in Osteoporosis). An abnormal occiput-wall distance has a Sensitivity of 41% and a Specificity of 92% for thoracic vertebral fracture."], "imgs": []}, {"sec": "Special Tests", "name": "Bilateral Chest Expansion", "phase": "special", "tags": [], "pg": 323, "say": ["If you can sit up and turn to the side of the exam table, I will palpate the back for chest expansion with breathing."], "do": ["5. Place hands at 10th rib, press together.", "6. Ask patient to breathe out fully, then position hands.", "7. Have patient take a deep breath.", "8. Hands should move equidistant on each side with ≥4cm deviation bilaterally Alternative Method: Measure horizontally with measuring tape around patient at level of the xiphisternum."], "more": ["Note: takes longer, can comment that you would measure only if there was time in an OSCE scenario."], "report": ["The chest shows chest expansion of 4 cm with bilateral symmetry, a normal value."], "why": ["Bilateral ↓ expansion can occur in asthma and COPD (Ch 5 – Resp Exam – MF1), as well as Thoracic Scoliosis and Ankylosing Spondylitis (from costovertebral fusion); unilateral ↓ expansion seen in pleural effusion, pneumothorax, etc. on the affected side."], "imgs": ["back-186.webp"]}, {"sec": "Special Tests", "name": "Rib-Pelvis Distance", "phase": "special", "tags": [], "pg": 324, "say": ["I will palpate the distance between the ribs and pelvis for signs of kyphosis in the lower back."], "do": ["• With patient standing and clinician’s fingers outstretched, place your hand in patient’s side between lower rib and the iliac crest (located at mid-axillary line). The distance is usually about 4 fingerbreadths (some variation is expected as fingers vary)", "• Abnormal if the distance is 2 finger breadths or less."], "report": ["The rib-pelvis distance is 4 finger breadths."], "why": ["A Rib-Pelvis distance of > 2 finger breadth’s diagnostic value is to rule out lumbar vertebral fractures. A Rib-Pelvis distance of ≤ 2 finger breadths has a Sensitivity of 87% and a Specificity of 47% for Lumbar Vertebral Fractures. The Rib-pelvis distance is decreased in lumbar kyphosis e.g. in Ankylosing Spondylitis or Lumbar vertebral compression fractures (e.g. in Osteoporosis)"], "imgs": []}, {"sec": "Special Tests", "name": "Modified Schober’s Test", "phase": "special", "tags": [], "pg": 324, "say": ["I will assess for reduced flexion in the low back using a measuring tape. Please stand and keep the knees straight."], "setup": ["With patient standing, using your measuring tape mark the midline between the Dimples of Venus, and mark 10 cm above and 5 cm below this point (total of 15 cm distance while standing)."], "do": ["Have patient bend forward trying to touch the floor while keeping their knees straight. Measure the distance between your two points –should now be > 5cm longer (i.e. ≥20 cm)."], "report": ["There is an increase of greater than 5 cm in the distance between the two measured points – the Modified Schober’s Test is negative."], "why": ["An increase in the distance of < 5cm indicates a restricted lumbar flexion, which can occur in conditions such as ankylosing spondylitis (which tends to begin in the lumbar region in men)."], "imgs": ["back-187.webp"]}, {"sec": "Special Tests", "name": "Straight Leg Raise and Lasegue’s Sign", "phase": "special", "tags": [], "pg": 324, "say": ["I will examine for sciatica nerve pain by moving the leg away from the exam table while it is relaxed. Let me know if you feel any pain during the test, and if so, where."], "do": ["• Patient lying supine with knees extended. Clinician raises the SYMPTOMATIC straightened leg.", "• Observe for pain radiating down the back of the raised leg into foot, (usually at 30-70° of leg raise). This suggests Sciatic Nerve Root Irritation. Pain that is only in the low back or hamstring is NOT a positive straight leg raise (could be due to Hamstring muscle strain e.g. due to tight musculature).", "• If the pain on straight leg raise is consistent with sciatic nerve root irritation, slowly lower the leg until the pain stops and then dorsiflex the ankle. Return of pain is a Positive Lasegue’s Sign."], "report": ["No pain elicited on straight leg raise – Straight Leg Raise test is negative."], "why": ["Straight Leg Raise test’s diagnostic value is to rule out lumbar disc herniation, via testing for irritation of the Sciatic Nerve Roots (L4, L5, S1, S2) by manipulating the symptomatic leg i.e. Sciatica. A positive straight leg raise test has a Sensitivity of 91% and a Specificity of 32% for lumbar disc herniation (sciatica). Further, the likelihood of lumbosacral radiculopathy in patients with sciatica is moderately decreased with a negative straight leg raise test (LR+ 1.3, LR- 0.3)."], "imgs": ["back-188.webp"]}, {"sec": "Special Tests", "name": "Crossed Straight Leg Raise", "phase": "special", "tags": [], "pg": 324, "say": ["I will continue to examine for sciatica nerve pain now by moving the opposite leg away from the exam table while it is relaxed. Let me know if you feel any pain during the test, and if so, where."], "do": ["• Patient lying supine with knees extended. Clinician raises the ASYMPTOMATIC straightened leg.", "• Observe for pain radiating down the back of the symptomatic leg into foot (symptomatic leg still on exam table) This suggests Sciatic Nerve Root Irritation."], "report": ["No pain elicited on crossed straight leg raise – Crossed Straight Leg Raise test is negative."], "why": ["Crossed Straight Leg Raise test’s diagnostic value is to rule in lumbar disc herniation. A positive crossed straight leg raise test has a Sensitivity of 32% and a Specificity of 98% for lumbar disc herniation (sciatica). Further, the likelihood of lumbosacral radiculopathy in patients with sciatica is mildly increased with a positive crossed straight leg raise test (LR+ 3.4, LR- 0.8)."], "imgs": ["back-189.webp"]}, {"sec": "Special Tests", "name": "Femoral Nerve Stretch", "phase": "special", "tags": [], "pg": 325, "say": ["I will examine for femoral nerve pain by moving the leg away from the exam table. I will ask you to lie on the stomach for this test with the legs relaxed. Let me know if you feel pain during the test, and if so, where."], "do": ["• Patient lying prone with knees extended. Clinician passively flexes the knee and extend the hip lifting thigh off the exam table.", "• Observe for pain radiating down the anterior thigh (Note: Femoral nerve is in the anterior compartment)."], "report": ["No pain elicited on femoral nerve stretch – Femoral Nerve Stretch test is negative."], "why": ["Femoral Nerve Stretch test’s diagnostic value is to rule in mid-lumbar nerve impingement, via testing for irritation of the Femoral Nerve Roots (L2, L3, L4). A positive femoral nerve stretch test has a Sensitivity of 50% and a Specificity of 100% for mid-lumbar nerve impingement."], "imgs": ["back-190.webp"]}, {"sec": "Special Tests", "name": "FABER Test", "phase": "special", "tags": [], "pg": 325, "say": ["I will rest the foot on the opposite knee and apply pressure to the inside of the knee to look for signs of Hip or Sacroiliac Joint pain when moving the hip. Please let me know if you feel pain, and if so, where."], "do": ["• Patient lying supine, Flex, Abduct, and Externally Rotate one hip (placing heel on opposite knee, making a figure-of-4).", "• Push down on knee; press on opposite hemipelvis to stabilize.", "• Observe for pain in lower back or buttock Assess: No pain elicited with FABER test."], "why": ["FABER (Flexion, Abduction, External Rotation) test with inability to achieve FABER position or eliciting pain in the anterior/lateral of the hip or groin pain suggests a Hip Joint Pathology (can cause pain in healthy patients due to stretch); pain elicited in lower back/gluteal region suggests a Sacroiliac Joint Pathology."], "imgs": ["back-191.webp"]}, {"sec": "Special Tests", "name": "Gaenslen’s Test", "phase": "special", "tags": [], "pg": 325, "say": ["I will continue to assess for Sacroiliac Joint pain when you bring one knee towards the chest while letting the other leg be relaxed off the exam table. Please let me know if you feel pain, and if so, where."], "do": ["• Patient lying supine with one leg hanging off the exam table (the thigh must be off the exam table)", "• Clinician asks patient to bring the other knee (still on the exam table) to their chest using their hands.", "• Observe for pain in the lower back or buttock."], "report": ["No pain elicited on flexion of knee to chest using hands – Gaenslen’s test is negative."], "why": ["Gaenslen’s test eliciting pain in the back or buttocks suggests Sacroiliac Joint pathology."], "imgs": ["back-192.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Spurling Test", "phase": null, "tags": ["extra"], "pg": 325, "say": ["I will now perform a test for radicular pain in the neck by applying a pressure to the top of the head. Please tilt the head to one side and back. Please let me know if you feel pain or pins and needles during the test, and if so, where."], "do": ["• Review any contraindications to performing Spurling Test (See When Not to Check)", "• Patient sitting up, laterally flexes and then extends the neck to affected side. After each neck motion, ask if this causes pain or paresthesias (tingling).", "• If patient neck in lateral flexion and neck extended without causing their symptoms, apply axial pressure on spine, and ask if this reproduces their pain or paresthesias."], "report": ["Spurling’s test is negative for cervical radiculopathy."], "why": ["The Spurling test is a provocative test, where a positive spurling test in patients with neck/arm pain increases the likelihood of suspected cervical radiculopathy (LR+ 4.5, LR- 0.6). When Not to Check: Avoid in patients suspected of having cervical instability – this includes structural (e.g. trauma, cervical spondylosis with myelopathy), infectious (osteomyelitis or other infectious process), inflammatory (e.g. rheumatoid arthritis), or malignant (e.g. metastatic bone disease)."], "imgs": ["back-193.webp"]}]}, "hip": {"title": "Hip", "pg": [295, 304], "notes": [], "steps": [{"sec": "General Assessment", "name": "Gait Assessment Gen - Trendelenburg", "phase": null, "tags": [], "pg": 298, "do": ["• Components of Gait Cycle:", "◦ Stance phase (60% of gait cycle): initial contact (heel strike) → mid-stance → pre-swing (toe-off)", "◦ Swing phase (40% of gait cycle): initial swing → mid-swing → terminal swing", "◦ Note: Former terminology in brackets re. heel-strike and toe-off.", "• Quality of Gait: Smoothness of movement (legs, arm swing, pelvic tilt), symmetry, normal stride length, ability to turn quickly, symmetry.", "• Abnormal Gaits to Assess for:", "◦ Antalgic Gait: Stance phase shortened on affected side, usually indicating pain on weight-bearing", "▪ Why: Patient is trying to reduce the time spent weight-bearing on the affected limb", "▪ Absence of limp moderately decreases probability of Hip Osteoarthritis (LR- 0.35)", "◦ Trendelenburg Gait:", "▪ Unilateral: During stance phase, if hip abductors weak on standing side, pelvis will drop to opposite side. The trunk may compensate by lurching towards side of weakened abductor muscles, with a truncal tilt present. If uncompensated, there is no truncal tilt present.", "• Hip abductor weakness mildly increases probability of Hip Osteoarthritis (LR+ 4.5, LR- 0.62)", "▪ Bilateral: Produces a waddling gait.", "▪ Why: Leaning on the affected side to align the centre of gravity allows for minimizing torque."], "imgs": []}, {"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 298, "do": ["• Approach: Ensure adequate but respectful exposure during your exam (particularly for hip exam).", "• Swelling: Unlikely to see effusion, but a massive joint swelling may present as a prominence in groin.", "• Erythema", "• Atrophy: Pelvic Girdle – medial & anterior to pubic symphysis; Gluteal Muscles – posterior aspect – role in Hip extension; Hamstrings – posterior aspect of thighs – roles in Hip extension and knee flexion; Quadriceps – anterior aspect of thighs – roles in Hip flexion and knee extension; Lower Back", "• Deformity:", "◦ Posture: Scoliosis; Exaggerated Lumbar Lordosis (may suggest a flexion contracture of hip)", "◦ Pelvic Tilt: Can inspect or palpate level of iliac crests (may suggest either a hip adduction deformity on the higher side, or a hip abduction deformity on the lower side)", "◦ External or Internal Rotation of Hip at Rest: Look at the feet (may suggest a rotational deformity of hip, or an external rotation may suggest a hip fracture)", "◦ Trendelenburg Sign: Have patient stand on one leg at a time – if unsupported side drops → weakness of the hip abductors on the standing side (relates to the Trendelenburg Gait)", "• Skin Changes and Scarring: Look for Rashes, and Scars from surgeries (on lateral aspect of hip)"], "imgs": []}, {"sec": "General Assessment", "name": "Palpation", "phase": "palpate", "tags": [], "pg": 299, "do": ["• Approach: Important landmarks include the Pubic Symphysis, the ASIS, AIIS and the Iliac Crests.", "• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy", "• Palpation Order: Easiest to palpate in an ordered sequence, usually from anterior to posterior", "◦ Anterior structures – Along a line from Pubic Symphysis to ASIS: With patient supine, begin with the medial anterior Pubic Symphysis (if indicated and with patient consent) → Inguinal Ligament → Femoral Pulse → Anterior Inferior Iliac Spine (AIIS) → Anterior Superior Iliac Spine (ASIS) → Iliac Crest", "▪ Note: Pubic symphysis angle acute in males, vs. obtuse in females", "◦ Posterior structures – Beginning at the Iliac Crests:", "▪ Ask patient to change position to to lateral decubitus position to palpate the posterior Iliac Crest (bony prominence) → Dimples of Venus at Posterior Superior Iliac Spine (PSIS, symmetrical sagittal indents located at S2) → SI Joint (a palpable depression superior to PSIS)", "▪ Ask patient to flex leg to 90 degrees to palpate the Ischial Tuberosity (lateral to PSIS)", "▪ Ask patient to return leg to neutral position to palpate Greater Trochanters (Bony prominence of proximal lateral femur) and Iliotibial Band"], "why": ["Palpation may be helpful to assess pain source. Ask patient to localize pain, palpate accordingly.", "• Tenderness at Ischial tuberosity may indicate Ischio-gluteal bursitis", "• Tenderness at Greater Trochanter may indicate Trochanteric bursitis", "• Tenderness at distal 1/3rd of Iliotibial Band can indicate Iliotibial band syndrome", "• Tenderness at inguinal ligament mildly increases probability of Hip Osteoarthritis (LR+ 2.4, LR- 0.53)"], "imgs": ["hip-164.webp"]}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 299, "do": ["• Approach: Perform Active ROM, and then Passive ROM if Active ROM is limited (assess end-feel i.e. Bony End-Feel i.e. Bony pathology vs. Soft End-Feel i.e. Soft-tissue pathology)", "• Flexion (120°): Knee to Chest", "• Extension (20°): Have patient lying prone. If patient lying on side, stabilize hemipelvis with one hand", "• Abduction (45°): Moving leg laterally away from midline", "• Adduction (30°): With other leg abducted out of the way, adduct leg medially as far as possible without having to lift it over other leg (which will flex the hip being tested)", "• Internal Rotation (35-40°): Flex hip and knee to 90°, stabilize knee with one hand. Bring foot outwards with femur as axis of rotation – Internal rotation usually 1st movement limited in hip joint pathology", "• External Rotation (45°): Same position as Internal Rotation, except patient brings lower leg inwards"], "why": ["Assessing passive range of motion if active range of motion is limited helps distinguish between ROM limitations caused by pain, tendon rupture, etc. and those caused by structural limitation. Asymmetry with passive range of motion may indicate arthritis (bony end-feel), joint effusion (e.g. septic arthritis with soft end-feel), or internal derangements such as Femoroacetabular impingement or fracture (bony end- feel). Specifically examining for osteoarthritis, the likelihood of hip osteoarthritis increases mildly with decreased range of movement (LR+ 2.9, LR- 0.34), decreased hip extension (LR+ 2.4, LR- 0.35), decreased hip abduction (LR+ 1.6, LR -0.26), decreased hip adduction (LR+ 4.2, LR- 0.25), decreased hip internal rotation (LR+ 3.2, LR- 0.43) and decreased hip external rotation (LR+ 2.1, LR- 0.37). The likelihood of hip osteoarthritis increases moderately with groin pain on hip abduction or adduction (LR+ 5.7, LR- 0.71), and increases mildly with hip pain on active hip abduction (LR+ 1.5, LR- 0.43-0.59) and active hip internal rotation (LR+ 1.4, LR- 0.31-0.45)"], "imgs": ["hip-165.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 300, "do": ["• Approach: Resisted Isometric Testing i.e. patient resists force applied by clinician.", "• Sitting Up Approach:", "◦ Flexion Strength: Examiner braces hip, pushes down on quadriceps; patient resists motion.", "◦ Extension Strength: Examiner braces hip, pushes up on hamstrings; patient resists motion.", "◦ Abduction: Examiner braces hip, pushes on lateral aspect of thigh; patient resists motion.", "◦ Adduction: Examiner braces hip and pushes out on medial aspect of thigh; patient resists motion.", "• Supine Approach: Similar to above, with slight setup differences.", "◦ Flexion, Extension: With patient lying supine, have the patient’s hip and knees flexed to 90°.", "◦ Abduction and Adduction: With patient lying supine, have the patient’s hips and knees extended to be flat on exam table, and slightly abducted.", "• Reporting: For each muscle group tested, assess per the Medical Research Council Power Grading. If it is all 5/5, you can say “Power was 5/5 bilaterally in both upper and lower limbs”, and report specific deficits. NOTE: This scale is detailed in Chapter 31 – Screening Neurological Examination"], "imgs": []}, {"sec": "Special Tests", "name": "Thomas Test", "phase": "special", "tags": [], "pg": 300, "say": ["I will support the low back while asking you to use both hands to pull the knee towards the chest to assess for a hip contracture."], "do": ["• Patient supine. Clinician places one hand under lumbar spine. Patient places hands on knee and pulls knee towards their chest.", "• Observe if contralateral thigh rises off exam table. Repeat on other side."], "report": ["I note no movement of the contralateral thigh off the exam table – Thomas Test is negative."], "why": ["Positive when contralateral thigh rises above bed, indicating Contralateral Hip Contracture. To maintain posture, patients with a contralateral hip contracture may compensate by arching the lumbar spine (↑ lordosis). The Thomas Test aims to reverse lumbar lordosis to make hip contracture more apparent on testing."], "imgs": ["hip-166.webp"]}, {"sec": "Special Tests", "name": "Ober Test", "phase": "special", "tags": [], "pg": 300, "say": ["I will move the leg backwards to assess for a tight Iliotibial band. Please turn on your side to face away from me, and keep the legs relaxed."], "do": ["• Patient in decubitus position upper leg extended backwards and knee bent. Clinician braces upper leg and extends it backwards.", "• Release the upper leg. Assess whether the knee touches the exam table."], "report": ["The knee of upper leg touched exam table on release – Ober Test is negative."], "why": ["Positive when upper leg’s knee does not touch exam table, indicating a Tight Iliotibial Band."], "imgs": ["hip-167.webp"]}, {"sec": "Special Tests", "name": "FABER Test", "phase": "special", "tags": [], "pg": 300, "say": ["I will rest the foot on the opposite knee and apply pressure to the inside of the knee to look for signs of Hip or Sacroiliac Joint pain when moving the hip. Please let me know if you feel pain, and if so, where."], "do": ["• Patient lying supine, Flex, Abduct, and Externally Rotate one hip (placing heel on opposite knee, making a figure-of-4).", "• Push down on knee; press on opposite hemipelvis to stabilize.", "• Observe for pain in lower back or buttock Assess: No pain elicited with FABER test."], "why": ["FABER (Flexion, Abduction, External Rotation) test with inability to achieve FABER position or eliciting pain in the anterior/lateral of the hip or groin pain suggests a Hip Joint Pathology (can cause pain in healthy patients due to stretch); pain elicited in lower back/gluteal region suggests a Sacroiliac Joint Pathology."], "imgs": ["hip-168.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Barlow & Ortolani Maneuvers (Neonate) Also seen in Ch 17 – Newborn Exam – MF3", "phase": null, "tags": ["extra", "peds"], "pg": 301, "say": ["I will check the baby’s hip joints for stability, which we check for every newborn."], "do": ["Infant supine on examination table with diaper off.", "• Barlow Maneuver: Stabilize infant’s pelvis with one hand and grasp abducted and flexed thigh with other hand. Hip flexed to 90 degrees. Adduct the hip with an additional posterior force on the anterior hip. A positive test is felt as a clunk.", "• Ortolani Maneuver: If a clunk is felt on Barlow Maneuver, Abduct the hip with an additional anterior force on the posterior thigh. A positive test is the reduction of the dislocation (may also be felt as a clunk). Repeat with contralateral hip."], "report": ["The hip joints are stable on each side – Barlow and Ortolani screen is negative for Developmental Dysplasia of the Hip, which is reassuring."], "why": ["Part of Newborn Screening Exam that requires referral to a pediatric orthopedic surgeon and correction. Risk factors include ligamentous laxity, female, positive FMHx, breech presentation, primiparous parent, oligohydramnios & postnatal infant position. Sensitivity of test is lowered in an agitated, crying infant."], "imgs": ["hip-169.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "FADIR Test", "phase": null, "tags": ["extra"], "pg": 301, "say": ["I will flex the knee and hip, then rotate the hip inwards to check for Femoral Acetabular Impingement."], "do": ["• Patient supine and both knees extended/relaxed. Passively move hip to 90° flexion and knee to 90° flexion.", "• Clinician adducts and internally rotates the hip. Ask patient if it reproduces their hip pain symptoms."], "report": ["FADIR is negative as it did not reproduce the patient’s pain."], "why": ["The FADIR test is used to assess for Femoroacetabular Impingement (FAI). A negative FADIR test moderately decreases the probability of FAI (LR+ 1.1, LR- 0.4). There are three kinds of FAI: Cam (abnormal femur); Pincer (over-coverage of femoral head by acetabulum); and Mixed (combination of Cam + Pincer). Note that FAI may present as groin pain as well."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Leg Length Discrepancy", "phase": null, "tags": ["extra"], "pg": 301, "say": ["I will use a measuring tape to measure the length of each leg to look for signs of true or apparent leg length discrepancies. Please keep the legs straight."], "do": ["• Palpate for ASIS and medial malleolus on each side, and measure distance between them –true leg length.", "• Palpate the Umbilicus and medial malleolus, and measure distance between them – apparent leg length."], "report": ["No true or apparent leg length discrepancies detected."], "why": ["A true leg length discrepancy occurs when discrepancy arises below level of hip (e.g. Genu Valgus or Genu Varus). In contrast, an apparent leg length discrepancy is where the true leg lengths are equal, but the apparent leg lengths are different, e.g. when discrepancy arises at level of hip – for example, Trauma (acquired), Pelvic Tilt, Adduction/Abduction deformities of hips, or Congenital Dysplasia of hip."], "imgs": ["hip-170.webp"]}]}, "knee": {"title": "Knee", "pg": [283, 294], "notes": [], "steps": [{"sec": "General Assessment", "name": "Gait Assessment", "phase": null, "tags": [], "pg": 288, "do": ["• Components of Gait Cycle:", "◦ Stance phase (60% of gait cycle): initial contact (heel strike) → mid-stance → pre-swing (toe-off)", "◦ Swing phase (40% of gait cycle): initial swing → mid-swing → terminal swing", "◦ Note: Former terminology in brackets re. heel-strike and toe-off.", "• Quality of Gait: Smoothness of movement (legs, arm swing, pelvic tilt), symmetry, normal stride length, ability to turn quickly", "• Abnormal Gaits to Assess for: Antalgic Gait (shortened stance phase on affected side, typically indicates pain with weight-bearing)"], "why": ["Gait assessment is included as part of all lower limb assessments (Back, Hip, Knee, Ankle). The likelihood of a clinically significant knee fracture (i.e. requiring ortho consult, splinting, surgery) is mildly increased by inability to weight bear (i.e. unable to take 4 steps) both immediately and in Emergency Department (LR+ 3.6, LR- 0.6)."], "imgs": []}, {"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 288, "do": ["• Approach: Ensure adequate but respectful exposure during your exam, with patient in standing position (if possible – more apparent deformities/mal-alignments, and can easily see all sides of knee).", "• Swelling: Inspect all sides, including Popliteal Fossa for Baker’s Cysts (only seen in large effusions)", "• Erythema", "• Atrophy: Inspect Calves; Quadriceps; Hamstrings", "• Deformity:", "◦ Genu Varum (Bow-Legged)", "◦ Genu Valgum (Knock-Kneed)", "◦ Genu Recurvatum (Hyperextension)", "◦ Genu Procurvatum (Flexion deformity, always abnormal)", "• Skin Changes and Scarring Supine Position:", "• Diffuse Swelling (e.g. knee effusion): Loss of parapatellar grooves/fossae; swelling to supra-patellar area", "• Localized Swelling: Can indicate potential bursitis, tendon, or ligament pathology"], "why": ["In a patient with chronic knee pain, the likelihood of osteoarthritis is greatly increased by bony enlargement (LR+ 11.8, LR- 0.5), and mildly increased by varus deformity (LR+ 3.4, LR- 0.8)."], "imgs": ["knee-158.webp"]}, {"sec": "General Assessment", "name": "Palpation, including assessment for knee effusion", "phase": "palpate", "tags": [], "pg": 288, "do": ["• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy", "• Ottawa Knee Rule: Specifically palpate patella and fibular head for tenderness. With Knee Extended (Right Knee shown in diagram):", "• Temperature: Sweep with back of hand – Patella should be cooler than thigh above and tibia below.", "• Patella Palpation: Feel undersides by tilting patella to each side, feel with fingers or thumb", "• Palpating Anteriorly, From Superior to Inferior: Quadriceps most superior→ Quadriceps Tendon → Patella → Patellar Ligament → Tibial Tuberosity most inferior", "• Palpating Popliteal Fossa Posteriorly: Check popliteal pulse and for swelling", "• Palpating 4 Bursae:", "◦ Pre-Patellar Bursa (in front of patella)", "◦ Superficial Infra-Patellar Bursa (inferior to patella, overlying patellar ligament and under skin)", "◦ Deep Infra-Patellar Bursa (behind patellar ligament)", "◦ Anserine Bursa (Anteromedial aspect of knee, near medial tibial plateau, deep to Sartorius, Gracilis and Semitendinosus Tendons) With Knee Flexed to 90°:", "• Palpate Joint Line:", "◦ Medial & Lateral Joint Line; Medial Collateral Ligament (MCL)", "◦ Medial & Lateral Tibial Plateaus; Femoral Condyles", "• Adopt Figure of 4 Position (Heel resting on contralateral knee):", "◦ Palpate Lateral Collateral Ligament (LCL), felt as cord on lateral knee aspect. Can feel hard as bone."], "imgs": ["knee-159.webp"]}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 289, "do": ["• Approach: Perform Active ROM, and then Passive ROM if Active ROM is limited", "• Flexion (135°): Assess patellar crepitus during flexion-extension by placing 1 hand on patella", "• Extension (180° – >10° hyper-extension past 180° is abnormal hypermobility)", "• Internal Rotation (30°): Flex knee to 90°, point toes in", "• External Rotation (20°): Flex knee to 90°, point toes out", "• Patellar Movement: Push medially and laterally on patella; assess for hypermobility, pain or apprehension from dislocation.", "• Patellar Compression test: With clinician hand just proximal to patella, press down and push patella distally, then ask patient to contract quadriceps – pain may indicate pain in patellofemoral compartment e.g. in patellofemoral osteoarthritis."], "why": ["Assessing passive range of motion if active range of motion is limited helps distinguish between ROM limitations caused by pain, tendon rupture etc. and those caused by structural limitation. Asymmetry with passive range of motion may indicate arthritis (bony end-feel), joint effusion (e.g. septic arthritis with soft end-feel), or internal derangements such as meniscal tear or fracture. The likelihood of clinically significant knee fracture is mildly increased by limited knee flexion <60º (LR+ 4.7, LR- 0.6) or limited knee flexion <90º (LR+ 2.9, LR- 0.5). The likelihood of meniscal injury is mildly increased by blocked full extension (LR+ 3.2, LR- 0.7), and pain on forced extension (LR+ 1.6, LR- 0.7)."], "imgs": ["knee-160.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 289, "do": ["• Approach: Resisted Isometric Testing i.e. patient resists force applied by clinician", "• Sitting Approach: With knee flexed to 45-90° over side of exam table.", "◦ Knee Extension: Examiner braces knee & pushes leg towards exam table, patient resists motion.", "◦ Knee Flexion: Examiner braces knee & pulls leg away from exam table, patient resists motion.", "◦ Note: Strength of internal and external tibial rotation usually not tested.", "• Reporting: For each muscle group tested, assess per the Medical Research Council Power Grading. If it is all 5/5, you can say “Power was 5/5 bilaterally in both upper and lower limbs”, and report specific deficits. NOTE: This scale is detailed in Chapter 31 – Screening Neurological Examination"], "imgs": []}, {"sec": "Ligament Testing", "name": "Anterior Drawer Test & Posterior Drawer Test", "phase": null, "tags": [], "pg": 290, "say": ["I will examine for ligament tears in the knee by applying pressure to the lower leg in 2 different directions. Please bend the knee to 90°, with the foot relaxed on the exam table."], "do": ["• Patient supine, knee at 90° flexion. Stabilize tibia, grasping proximal tibia with thumbs on either side of joint line.", "• Anterior Drawer: Apply anterior force to pull tibia forward.", "• Posterior Drawer: Apply posterior force to push tibia backward. Look for excess displacement of tibia.", "• Compare to other side."], "report": ["No excess displacement of tibia seen – both anterior and posterior drawer tests are negative."], "why": ["A positive drawer test may increase the likelihood of anterior cruciate ligament (ACL) tear (LR+", "3.8-13.6, LR- 0.3-0.4). Some studies have shown that the LR+ may or may not be statistically significant. The Lachman Test (below) has consistently been found to have a higher LR+ for ACL tear across studies. A positive posterior drawer test greatly increases the likelihood of a suspected posterior cruciate ligament (PCL) tear (LR+ 97.8, LR- 0.1)."], "imgs": ["knee-161.webp"]}, {"sec": "Ligament Testing", "name": "Lachman Test", "phase": null, "tags": [], "pg": 290, "say": ["I will continue to examine for ligament tears in the knee."], "do": ["• Patient supine. Stabilize femur with one hand and grasp upper tibia with other hand with knee at 30 degrees flexion.", "• Try to pull tibia forward. Assess for excess anterior movement of the tibia (or no discrete end point)"], "report": ["No significant anterior movement of tibia seen – Lachman test is negative."], "why": ["A positive Lachman Test greatly increases the likelihood of a suspected anterior cruciate ligament (ACL) tear (LR+ 19.5-42, LR- 0.1-0.2). Studies have found it to consistently have a better LR+ and LR- than the anterior drawer test (above)."], "imgs": []}, {"sec": "Ligament Testing", "name": "MCL Stress Test & LCL Stress Test", "phase": null, "tags": [], "pg": 290, "say": ["I will continue to examine for ligament tears in the knee."], "do": ["Patient supine. Knee at 0° initially and then 30° flexion, foot on table. Stabilize knee posteriorly with one hand. Stabilize lower leg with other hand.", "• MCL stress test: Apply valgus force to lower leg with knee stabilized (push medially on knee, pull laterally on lower leg). Look for ↑ laxity and pain at MCL.", "• LCL stress test: Apply a varus force to lower leg with knee stabilized (pull laterally on knee, push medially on lower leg). Look for ↑ laxity and pain at LCL."], "report": ["I note no increased laxity or pain in the MCL or LCL – both MCL and LCL stress tests are negative."], "why": ["A positive medial collateral stress test moderately increases the likelihood of a suspected medial collateral ligament tear (LR+ 7.7, LR- 0.2). A positive lateral collateral stress test greatly increases the likelihood of a suspected lateral collateral ligament tear (LR+ 16.2)."], "imgs": []}, {"sec": "Meniscal Testing", "name": "McMurray’s Test", "phase": null, "tags": [], "pg": 290, "say": ["I will examine for meniscal tears in the knee by supporting the leg and applying a pressure with the foot facing in and then facing out. Please keep the leg relaxed and let me know if you feel any pain during the test."], "do": ["• Patient supine with leg relaxed. Clinician stands to side of patient to be tested (e.g. on the patient’s left side to test their left knee).", "• With one hand, grasp the patient’s heel. Your hand grasping the patient’s heel will support the limb and provide required movement through the range of motion in McMurray’s test .", "• With your other hand, grasp the patient’s knee, palpating the joint line with your thumb on one side of the joint line, and index finger on the other side of the joint line.", "• To evaluate for a medial meniscus tear, move the patient’s hip and knee into flexion, then externally rotate and extend the knee.", "• To evaluate for a lateral meniscus tear, move the patient’s hip and knee into flexion, then internally rotate and extend the knee", "• These two motions can be done smoothly and in sequence, or each meniscus can be tested by separate discrete maneuvers. If pain is elicited, or a palpable or audible click occurs, this indicates a meniscal tear."], "report": ["I note no pain elicited or palpable or audible clicks – McMurray’s test is negative for a meniscal tear."], "imgs": []}, {"sec": "Meniscal Testing", "name": "Apley’s Compression Test", "phase": null, "tags": [], "pg": 291, "say": ["I will continue to examine for meniscal tears in the knee by supporting the leg with the knee bent and applying a pressure with the foot facing in and then facing out. I will ask you to lie on the stomach for this test with the legs relaxed. Please let me know if you feel any pain during the test."], "do": ["• Patient prone, knee flexed to 90 degrees, clinician stabilizes femur with one hand, grasps heel with other hand.", "• Grasp patient’s heel and apply downward pressure through heel while rotating lower leg internally and externally. Apply a valgus force/tilt (medial) for medial meniscus, and a varus force/tilt (lateral) for lateral meniscus. If pain is elicited, or a popping/clicking noise occurs, this raises concern for a possible tear of the respective meniscus."], "report": ["I note no pain elicited or palpable or audible clicks – Apley’s compression test is negative."], "why": ["Apley’s test is a two-part test to assess medial or lateral knee pain. Apley’s Compression Test has a Sensitivity of 61% and Specificity of 70% for meniscal tear. With a meniscal tear, patient will tend to localize pain either as a medial or lateral meniscus issue. You are trying to elicit pain or “clunk” sensation by trapping meniscus between femur and tibia."], "imgs": ["knee-162.webp"]}, {"sec": "Meniscal Testing", "name": "Apley’s Distraction Test", "phase": null, "tags": [], "pg": 291, "say": ["I will examine for collateral ligaments tears in the knee pulling up on your lower leg while twisting the foot. I will ask you to lie on your stomach for this test with the legs relaxed. Please let me know if you feel any pain during the test."], "do": ["• Patient prone, knee flexed to 90 degrees", "• Clinician grasps the leg proximal to the ankle and applies traction to the tibia towards the ceiling, then applies internal and external rotation of the tibia while tractioning.", "• If pain is elicited along either joint line, there may be a tear of the collateral ligament on that side"], "report": ["I note no pain elicited – Apley’s distraction test is negative Why check: Apley’s test is a two-part test to assess medial or lateral knee pain. Apley’s distraction test can help identify injury to the collateral ligaments."], "imgs": ["knee-163.webp"]}, {"sec": "Special tests seen in practice (not routine)", "name": "Additional Tests to Palpate for Knee Effusion", "phase": "palpate", "tags": ["extra"], "pg": 291, "do": ["• Fluid Ballottement Test: With leg extended, grasp knee just above the patella with 1 hand. With other hand, grasp the medial and lateral parapatellar fossae. With hand just above patella, apply and release pressure, while feeling for ballotable fluid in other hand. If ballotable fluid, this indicates an effusion.", "• Patellar Tap (useful for moderate-large effusions): Apply pressure with one hand just above the patella and sweep down until you reach the upper pole of the patella. This pushes fluid into the suprapatellar pouch behind patella. Keep pressure applied. With other hand, use 1-2 fingers to push the patella down, and assess whether it taps the femur and bounces back up. If patella taps the femur, then bounces back up, this indicates an effusion (may be false negative in smaller effusions)"], "why": ["As mentioned above, the Fluid Wave Test or Bulge Sign is most useful for smaller effusions and routinely used in clinical practice. Two additional approaches to palpation for knee effusions are the Fluid Ballottement and Patellar Tap tests."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Pivot Shift Test", "phase": null, "tags": ["extra"], "pg": 292, "say": ["I will continue to examine for ligament tears in the knee."], "do": ["• Patient supine with hips and knees extended, relaxed. Brace patient’s ankle while keeping knee in extension. Internally rotate ankle/foot to internally rotate tibia and apply a valgus force (push medially on the fibula).", "• Slowly flex the patient’s knee; a positive test occurs if tibia subluxes posteriorly (a pivot shift) which may be seen as anterior knee reducing or felt as a clunk (typically 45 degrees flexion)."], "report": ["The pivot shift test is negative for ACL Tear."], "why": ["The Pivot Shift Test is used to assess for ACL Tears. To be diagnostic, it requires the patient to have an intact Iliotibial Band and MCL, and ability to extend knee to almost full extension (e.g. difficult to perform in presence of comorbid meniscal tear). A positive pivot shift test moderately increases the likelihood of suspected ACL tear (LR+ 8.8, LR- 0.7)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Clarke Test (Or Patellofemoral Grinding Test)", "phase": null, "tags": ["extra"], "pg": 292, "say": ["I will examine the knee for a functional pain called Patellofemoral Pain Syndrome (PFPS)."], "do": ["• Patient supine, knees supported by pad to create 10-20 degrees of knee flexion, articulating patella in patellofemoral joint. Clinician presses on superior border of patella, applying force distally.", "• Ask patient to contract quadriceps muscle. Ask the patient whether pain is reproduced during test."], "report": ["Clarke’s Test is negative as it did not reproduce the patient’s pain."], "why": ["The Clarke Test is used to assess for Patellofemoral Pain Syndrome (PFPS). A positive Clarke test mildly increases the likelihood of suspected PFPS (LR+ 1.18, LR- 0.7-0.91)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Patellar Apprehension/ Displacement Test", "phase": null, "tags": ["extra"], "pg": 292, "say": ["I will continue to examine the knee for a functional pain called Patellofemoral Pain Syndrome (PFPS)."], "do": ["• Patient supine, relaxed with knee in full extension. Clinician presses on medial patella to displace laterally for a lateral patellar guide, grasping ankle on same side with other hand.", "• Perform slow combined flexion of knee and hip, keeping lateral pressure applied on patella for lateral patellar tracking. Ask patient whether their pain is reproduced and watch for signs of apprehension."], "report": ["Patellar Apprehension Test is negative; it did not cause apprehension or reproduce patient’s pain."], "why": ["Assess for PFPS. An alternative method is Patellar Displacement Test – patella displaced medially to assess pain improving through passive ROM. The evidence for Patellar Apprehension test suggests it is not clinically significant for detecting PFPS (LR+ 0.9-2.3, LR- 0.8-1.0)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Patellar Tilt Test", "phase": null, "tags": ["extra"], "pg": 292, "say": ["I will continue to examine the knee for a functional pain called Patellofemoral Pain Syndrome (PFPS)."], "do": ["• Patient supine, relaxed with knee in full extension. Observe for resting tilt of patella with medial side more anterior than lateral side. Clinician applies pressure on anteromedial patellar border in posterior direction, and also applies pressure on lateral patellar border in anterior direction.", "• Assess whether patella corrects tilt to neutral at minimum (Normal tilt 15 degrees medio-laterally)."], "report": ["The patient has a normal tilt on the Patellar Tilt Test."], "why": ["The Patellar Tilt Test is used to assess for Patellofemoral Pain Syndrome (PFPS). If tilt does not correct with pressure to neutral position, this indicates excessive lateral tightness. A positive patellar tilt test moderately increases the likelihood of suspected PFPS (LR+ 5.4, LR- 0.6)."], "imgs": []}, {"sec": "Special tests seen in practice (not routine)", "name": "Functional Trendelenburg Test", "phase": null, "tags": ["extra"], "pg": 292, "say": ["I will examine the hip for weak hip abductors, which can cause anterior knee pain."], "do": ["• Patient stands on affected leg in single leg stance; can hold onto an item for support if balance concern.", "• Patient does a shallow “squat” with knee flexed to 20 to 30 degrees. If knee moves into valgus, the test is positive. You may also see the contralateral pelvis drop (as seen in Trendelenburg Gait)"], "report": ["The patient was able to flex their knee in a single-leg stance without the knee moving into Valgus – the Functional Trendelenburg test is negative."], "why": ["The Functional Trendelenburg Test is typically used to assess for weakness in the hip abductor muscles (Gluteus Medius and Gluteus Minimus), which can contribute in a kinetic chain to anterior knee pain such as Patellofemoral Pain Syndrome (PFPS). It can also occur with congenital hip dislocation, as well as arthritis (both rheumatoid and osteo-arthritis)."], "imgs": []}]}, "ankle": {"title": "Ankle & foot", "pg": [305, 315], "notes": [], "steps": [{"sec": "General Assessment", "name": "Gait Assessment Gen - Trendelenburg", "phase": null, "tags": [], "pg": 311, "do": ["• Components of Gait Cycle:", "◦ Stance phase (60% of gait cycle): initial contact (heel strike) → mid-stance → pre-swing (toe-off)", "◦ Swing phase (40% of gait cycle): initial swing → mid-swing → terminal swing", "◦ Note: Former terminology in brackets re. heel-strike and toe-off.", "• Quality of Gait: Smoothness of movement (legs, arm swing, pelvic tilt), symmetry, normal stride length, ability to turn quickly", "• Abnormal Gaits to Assess for: Antalgic Gait (shortened stance phase on affected side, typically indicates pain with weight-bearing)", "• Additional Step in Ankle/Foot Exam to assess gait: Ask patient to walk on: (1) toes; (2) heels – assess dorsiflexion strength; (3) Tandem gait (walking in a line with one foot in front of the other)"], "why": ["Gait assessment is included as part of all lower limb assessments (Back, Hip, Knee, Ankle). The likelihood of clinically significant ankle fracture (i.e. bone fragment >3mm, may require plaster immobilization) is increased by inability to weight bear (i.e. unable to take 4 steps) immediately after the injury (LR+ 2.6, LR- 0.5) and in the ED (LR+ 2.5, LR- 0.3). This is a part of the Ottawa Ankle Rule."], "imgs": []}, {"sec": "General Assessment", "name": "Inspection (SEADS)", "phase": "inspect", "tags": [], "pg": 311, "do": ["• Key idea: Feet should be inspected both on weight bearing and non-weight bearing positions. Inspect with adequate exposure, at least up to the knee. With Patient Standing (Weightbearing), comment on:", "• Splaying of the toes → suggests collapse of transverse arch", "• Pes planus “flat feet” → suggests collapse of longitudinal arch", "• Pes cavus → suggests high longitudinal arch", "◦ Note: Arches physiologically create space for soft tissues to act as a shock absorber to ↓ wear and tear, maintain foot orientation, prevent over-eversion, etc.", "• Hindfoot valgus (Normal: 5-10°)", "• “Too Many Toes” Sign: examiner stands behind patient with patient’s feet together. “Too Many Toes” sign is positive when >2 toes visible → suggests severe pes planus, or posterior tibialis dysfunction With Patient Non-Weightbearing, comment on:", "• Swelling:", "◦ Loss of normal depressions anterior to malleoli → Suggests True Ankle Swelling", "◦ Swelling posterior to lateral malleolus → Suggests Peroneal Tenosynovitis", "◦ Swelling posterior to medial malleolus → Suggests Posterior Tibial Tenosynovitis", "◦ Swelling at back of heel → Suggests Retrocalcaneal Bursitis or Retroachilleal Bursitis", "◦ Swelling of the forefoot → Can be seen in Inflammatory Arthritis", "• Erythema", "• Atrophy", "• Deformities:", "◦ Hallux valgus, bunions or bunionettes", "◦ Mallet Toes → Irreversible flexion of DIPs", "◦ Hammer Toes → Irreversible flexion of PIPs", "◦ Claw Toes → Irreversible flexion of both PIPs and DIPs", "• Skin Changes or Scars:", "◦ Callous formation → Abnormal stance or gait", "◦ Inspect sole of the foot as well", "• Additional Step: Footwear Inspection: Most patients wear out central or outer corners of heel of shoe", "◦ Medial heel of shoe worn out → pronation of the foot", "◦ Medial forefoot of shoe worn out → over-pronation of foot", "◦ Lateral forefoot of shoe worn out → over-supination of foot"], "imgs": ["ankle-171.webp", "ankle-172.webp"]}, {"sec": "General Assessment", "name": "Palpation, including assessment for ankle and MTP effusions", "phase": "palpate", "tags": [], "pg": 312, "do": ["• Commenting on: TESTCA – Tenderness, Effusions, Swelling, Temperature, Crepitus, & Atrophy", "• Note: In a screening exam, palpate all areas. In clinical encounters, depending on where the patient complains of pain, may focus palpation on area causing patient’s symptoms.", "• Ottawa Ankle Rule: Palpate posterior edge/tip of lateral malleolus, posterior edge/tip of medial malleolus, base of 5th metatarsal, and navicular bone", "• Palpate Laterally:", "◦ Fibula", "◦ Lateral Malleolus and Lateral Malleolar Bursa", "◦ Lateral Ligaments (Posterior and Anterior Talofibular, Calcaneofibular)", "◦ Peroneal Tendons", "• Palpate Anteriorly:", "◦ Shin (Tibia)", "◦ Tibiotalar joint", "▪ True Ankle Joint: Cup hands around ankle. Palpate tibiotalar joint space anteriorly for fullness. Try to ballot fluid between your thumbs.", "◦ Extensor Tendons", "◦ Tarsal Bones: includes 5 bones of midfoot (cuboid, medial/intermediate/lateral cuneiforms, and navicular) and 2 bones of hindfoot (talus and calcaneus)", "◦ Metatarsal Bones", "▪ MTP Joint Swelling: Palpate 1-2 cm proximal to the web-space with four-finger technique (tips of your thumbs on top of joint, while fingers stabilize joint underneath).", "▪ MTP Squeeze: Grasp across forefoot/ MTPs with one hand and squeeze. Pain suggests synovitis (Inflammatory Arthritis) Podagra (Gout of 1st MTP)3 or Intermetatarsal Bursitis", "◦ PIP and DIP joints: Palpate with two fingers of one hand stabilizing at sides of joint, while the index finger and thumb of other hand palpate from top and bottom.", "• Palpate Medially:", "◦ Medial Malleolus", "◦ Deltoid Ligament", "◦ Posterior Tibialis (pulse)", "• Palpate Posteriorly:", "◦ Gastrocnemius Muscle", "◦ Musculotendinous Junction", "◦ Achilles Tendon and Enthesis", "◦ Calcaneus", "• Palpate Sole:", "◦ Plantar Fasciitis:", "▪ Apply pressure to medial calcaneus tuberosity (insertion of plantar fascia), checking for tenderness", "▪ Tense plantar fascia by passive dorsiflexion of toes and assess for signs of pain", "◦ Painful Heel Pad Syndrome: Palpate the centre of the heel, and assess for signs of pain Podagra (Gout of 1st MTP)3"], "why": ["Palpation can be very helpful to determine source of pain. Palpate for tenderness and swelling in a systematic manner, to assess for potential fractures and other abnormalities. The likelihood of clinically significant ankle fracture (i.e. bone fragment >3mm, may require plaster immobilization) is increased by tenderness over posterior medial malleolus (LR+ 4.8, LR- 0.6), and by tenderness over posterior lateral malleolus (LR+ 2.4, LR- 0.4). The likelihood of clinically significant midfoot fracture is increased by tenderness at base of 5th metatarsal (LR+ 2.9, LR- 0.1), and decreased by tenderness at navicular bone (LR+ 0.4). These are all a part of the Ottawa Ankle Rule. The likelihood of a suspected Achilles tendon rupture is moderately increased by a palpable gap in the Achilles tendon (LR+ 6.8, LR-", "0.3). Gout classically presents with initial flare the first metatarsophalangeal joint (known as podagra) or knee, but may also present in other MTP joints, ankle, and midfoot."], "imgs": ["ankle-173.webp", "ankle-174.webp", "ankle-175.webp", "ankle-176.webp", "ankle-177.webp", "ankle-178.webp"]}, {"sec": "General Assessment", "name": "Range of Motion (ROM)", "phase": "rom", "tags": [], "pg": 313, "do": ["• Approach: Perform Active ROM, and then Passive ROM if Active ROM is limited. These can be integrated with examiner guiding the ankle/foot beyond patient’s active ROM.", "• Setup: Have knee flexed to relax calves, and foot in a neutral position (90 degrees flexion).", "• Tibiotalar Joint (True Ankle): Ankle Dorsiflexion (15-25°); Ankle Plantarflexion (40-50°)", "• Subtalar Joint (between talus and calcaneum): Ankle Inversion (Up to 30°); Ankle Eversion (Up to 20°)", "• Midtarsal Joint: Stabilize heel with one hand while grasping and manipulating the mid and forefoot with your other hand - Inversion (30°); Eversion (20°); Adduction; Abduction", "• Toes: Flexion; Extension"], "why": ["Assessing passive range of motion if active range of motion is limited helps distinguish between ROM limitations caused by pain, tendon rupture etc. and those caused by structural limitation. Asymmetry with passive range of motion may indicate arthritis (bony end-feel), joint effusion (e.g. septic arthritis or gout with soft end-feel), or internal derangements such as fracture."], "imgs": ["ankle-179.webp"]}, {"sec": "General Assessment", "name": "Power Assessment", "phase": "power", "tags": [], "pg": 313, "do": ["• Approach: Resisted Isometric Testing i.e. patient resists force applied by clinician.", "• Assess: Ankle Dorsiflexion and Plantarflexion; Ankle Inversion and Eversion; Toe Flexion and Extension"], "report": ["For each muscle group tested, assess per the Medical Research Council Power Grading. If it is all 5/5, you can say “Power was 5/5 bilaterally in both upper and lower limbs” and report specific deficits. NOTE: This scale is detailed in Chapter 31 – Screening Neurological Examination"], "imgs": []}, {"sec": "Special Tests", "name": "Stability Testing", "phase": "special", "tags": [], "pg": 313, "say": ["I will examine the ankle for signs of instability by applying pressure to the ankle in different directions. Please let me know if you feel pain during the test."], "do": ["Stabilize lower leg with one hand anteriorly, and grasp the hindfoot.", "• Apply eversion force and check for excessive movement", "• Apply inversion force and check for excessive movement", "• Anterior Drawer Test: Flex foot to 20 degrees plantarflexion, stabilize lower leg with one hand anteriorly and grasp the calcaneus. Pull heel forward and check for excessive movement."], "report": ["I note no excess movement with ankle joint stability testing – Deltoid Ligament, Lateral Ligaments, and Anterior Talofibular Ligaments are stable."], "why": ["• Excess movement with foot eversion suggests a Deltoid Ligament Tear. The Deltoid ligament is strongly attached to Medial Malleolus, where over-eversion injury can cause avulsion fracture of medial malleolus.", "• Excess movement with foot inversion suggests Lateral Ligament Tear (e.g. calcaneofibular ligament tear).", "• Excess movement (Normal: less than 5mm) with anterior drawer test suggests an Anterior Talofibular Ligament (ATFL) Tear – ATFL most common ligament involved in ankle sprain from over-inversion injury."], "imgs": ["ankle-180.webp"]}, {"sec": "Special Tests", "name": "Tinel’s Sign", "phase": "special", "tags": [], "pg": 313, "say": ["I will examine the Tarsal Tunnel in the ankle by gently tapping an area on the inside of the ankle for 30 seconds. Let me know if you feel pins and needles in the foot during the test."], "do": ["Locate the tarsal tunnel area, located just posterior to the medial malleolus. Tap over tarsal tunnel for 30 seconds. Paresthesias radiating to first three toes indicates a possible tarsal tunnel syndrome."], "report": ["No paresthesia reported, and Tinel’s Test is negative."], "why": ["If paresthesia radiating to first three toes reported → possible tarsal tunnel syndrome."], "imgs": ["ankle-181.webp"]}, {"sec": "Special Tests", "name": "Thompson CalfSqueeze Test", "phase": "special", "tags": [], "pg": 314, "say": ["I will examine the Achilles Tendon for tears by squeezing the calf muscle. I will ask you to lie on the stomach for this test with the legs relaxed. Please let me know if you feel pain."], "setup": ["Patient prone with foot hanging off exam table or kneeling in a chair with foot hanging off chair."], "do": ["Squeeze calf, looking for normal foot plantarflexion."], "report": ["Calf-Squeeze produces normal foot plantarflexion – Thompson Calf-Squeeze test is negative."], "why": ["The likelihood of suspected Achilles Tendon Rupture is significantly increased with positive Thompson Calf Squeeze Test (LR+ 13.5), and significantly decreased with a negative Thompson Calf-Squeeze Test (LR- 0.05). A positive test is where the foot fails to plantarflex with calf squeeze."], "imgs": ["ankle-182.webp"]}]}}};